INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, 'EN el principio crió Dios los cielos y la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, 'Y la tierra estaba desordenada y vacía, y las tinieblas estaban sobre la haz del abismo, y el Espíritu de Dios se movía sobre la haz de las aguas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, 'Y dijo Dios: Sea la luz: y fué la luz.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, 'Y vió Dios que la luz era buena: y apartó Dios la luz de las tinieblas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, 'Y llamó Dios á la luz Día, y á las tinieblas llamó Noche: y fué la tarde y la mañana un día.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, 'Y dijo Dios: Haya expansión en medio de las aguas, y separe las aguas de las aguas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, 'E hizo Dios la expansión, y apartó las aguas que estaban debajo de la expansión, de las aguas que estaban sobre la expansión: y fué así.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, 'Y llamó Dios á la expansión Cielos: y fué la tarde y la mañana el día segundo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, 'Y dijo Dios: Júntense las aguas que están debajo de los cielos en un lugar, y descúbrase la seca: y fué así.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, 'Y llamó Dios á la seca Tierra, y á la reunión de las aguas llamó Mares: y vió Dios que era bueno.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, 'Y dijo Dios: Produzca la tierra hierba verde, hierba que dé simiente; árbol de fruto que dé fruto según su género, que su simiente esté en él, sobre la tierra: y fué así.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, 'Y produjo la tierra hierba verde, hierba que da simiente según su naturaleza, y árbol que da fruto, cuya simiente está en él, según su género: y vió Dios que era bueno.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, 'Y fué la tarde y la mañana el día tercero.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, 'Y dijo Dios: Sean lumbreras en la expansión de los cielos para apartar el día y la noche: y sean por señales, y para las estaciones, y para días y años;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, 'Y sean por lumbreras en la expansión de los cielos para alumbrar sobre la tierra: y fué así.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, 'E hizo Dios las dos grandes lumbreras; la lumbrera mayor para que señorease en el día, y la lumbrera menor para que señorease en la noche: hizo también las estrellas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, 'Y púsolas Dios en la expansión de los cielos, para alumbrar sobre la tierra,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, 'Y para señorear en el día y en la noche, y para apartar la luz y las tinieblas: y vió Dios que era bueno.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, 'Y fué la tarde y la mañana el día cuarto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, 'Y dijo Dios: Produzcan las aguas reptil de ánima viviente, y aves que vuelen sobre la tierra, en la abierta expansión de los cielos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, 'Y crió Dios las grandes ballenas, y toda cosa viva que anda arrastrando, que las aguas produjeron según su género, y toda ave alada según su especie: y vió Dios que era bueno.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, 'Y Dios los bendijo diciendo: Fructificad y multiplicad, y henchid las aguas en los mares, y las aves se multipliquen en la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, 'Y fué la tarde y la mañana el día quinto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, 'Y dijo Dios: Produzca la tierra seres vivientes según su género, bestias y serpientes y animales de la tierra según su especie: y fué así.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, 'E hizo Dios animales de la tierra según su género, y ganado según su género, y todo animal que anda arrastrando sobre la tierra según su especie: y vió Dios que era bueno.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, 'Y dijo Dios: Hagamos al hombre á nuestra imagen, conforme á nuestra semejanza; y señoree en los peces de la mar, y en las aves de los cielos, y en las bestias, y en toda la tierra, y en todo animal que anda arrastrando sobre la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, 'Y crió Dios al hombre á su imagen, á imagen de Dios lo crió; varón y hembra los crió.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, 'Y los bendijo Dios; y díjoles Dios: Fructificad y multiplicad, y henchid la tierra, y sojuzgadla, y señoread en los peces de la mar, y en las aves de los cielos, y en todas las bestias que se mueven sobre la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, 'Y dijo Dios: He aquí que os he dado toda hierba que da simiente, que está sobre la haz de toda la tierra; y todo árbol en que hay fruto de árbol que da simiente, seros ha para comer.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, 'Y á toda bestia de la tierra, y á todas las aves de los cielos, y á todo lo que se mueve sobre la tierra, en que hay vida, toda hierba verde les será para comer: y fué así.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, 'Y vió Dios todo lo que había hecho, y he aquí que era bueno en gran manera. Y fué la tarde y la mañana el día sexto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, 'Y FUERON acabados los cielos y la tierra, y todo su ornamento.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, 'Y acabó Dios en el día séptimo su obra que hizo, y reposó el día séptimo de toda su obra que había hecho.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, 'Y bendijo Dios al día séptimo, y santificólo, porque en él reposó de toda su obra que había Dios criado y hecho.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, 'Estos son los orígenes de los cielos y de la tierra cuando fueron criados, el día que Jehová Dios hizo la tierra y los cielos,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, 'Y toda planta del campo antes que fuese en la tierra, y toda hierba del campo antes que naciese: porque aun no había Jehová Dios hecho llover sobre la tierra, ni había hombre para que labrase la tierra;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, 'Mas subía de la tierra un vapor, que regaba toda la faz de la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, 'Formó, pues, Jehová Dios al hombre del polvo de la tierra, y alentó en su nariz soplo de vida; y fué el hombre en alma viviente.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'Y había Jehová Dios plantado un huerto en Edén al oriente, y puso allí al hombre que había formado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'Y había Jehová Dios hecho nacer de la tierra todo árbol delicioso á la vista, y bueno para comer: también el árbol de vida en medio del huerto, y el árbol de ciencia del bien y del mal.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, 'Y salía de Edén un río para regar el huerto, y de allí se repartía en cuatro ramales.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, 'El nombre del uno era Pisón: éste es el que cerca toda la tierra de Havilah, donde hay oro:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, 'Y el oro de aquella tierra es bueno: hay allí también bdelio y piedra cornerina.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, 'El nombre del segundo río es Gihón: éste es el que rodea toda la tierra de Etiopía.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, 'Y el nombre del tercer río es Hiddekel: éste es el que va delante de Asiria. Y el cuarto río es el Eufrates.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'Tomó, pues, Jehová Dios al hombre, y le puso en el huerto de Edén, para que lo labrara y lo guardase.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, 'Y mandó Jehová Dios al hombre, diciendo: De todo árbol del huerto comerás;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, 'Mas del árbol de ciencia del bien y del mal no comerás de él; porque el día que de él comieres, morirás.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'Y dijo Jehová Dios: No es bueno que el hombre esté solo; haréle ayuda idónea para él.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, 'Formó, pues, Jehová Dios de la tierra toda bestia del campo, y toda ave de los cielos, y trájolas á Adam, para que viese cómo les había de llamar; y todo lo que Adam llamó á los animales vivientes, ese es su nombre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'Y puso Adam nombres á toda bestia y ave de los cielos y á todo animal del campo: mas para Adam no halló ayuda que estuviese idónea para él.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, 'Y Jehová Dios hizo caer sueño sobre Adam, y se quedó dormido: entonces tomó una de sus costillas, y cerró la carne en su lugar;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'Y de la costilla que Jehová Dios tomó del hombre, hizo una mujer, y trájola al hombre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'Y dijo Adam: Esto es ahora hueso de mis huesos, y carne de mi carne: ésta será llamada Varona, porque del varón fué tomada.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, 'Por tanto, dejará el hombre á su padre y á su madre, y allegarse ha á su mujer, y serán una sola carne.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'Y estaban ambos desnudos, Adam y su mujer, y no se avergonzaban.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, 'EMPERO la serpiente era astuta, más que todos los animales del campo que Jehová Dios había hecho; la cual dijo á la mujer: ¿Conque Dios os ha dicho: No comáis de todo árbol del huerto?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, 'Y la mujer respondió á la serpiente: Del fruto de los árboles del huerto comemos;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, 'Mas del fruto del árbol que está en medio del huerto dijo Dios: No comeréis de él, ni le tocaréis, porque no muráis.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, 'Entonces la serpiente dijo á la mujer: No moriréis;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, 'Mas sabe Dios que el día que comiereis de él, serán abiertos vuestros ojos, y seréis como dioses sabiendo el bien y el mal.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, 'Y vió la mujer que el árbol era bueno para comer, y que era agradable á los ojos, y árbol codiciable para alcanzar la sabiduría; y tomó de su fruto, y comió; y dió también á su marido, el cual comió así como ella.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, 'Y fueron abiertos los ojos de entrambos, y conocieron que estaban desnudos: entonces cosieron hojas de higuera, y se hicieron delantales.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, 'Y oyeron la voz de Jehová Dios que se paseaba en el huerto al aire del día: y escondióse el hombre y su mujer de la presencia de Jehová Dios entre los árboles del huerto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, 'Y llamó Jehová Dios al hombre, y le dijo: ¿Dónde estás tú?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, 'Y él respondió: Oí tu voz en el huerto, y tuve miedo, porque estaba desnudo; y escondíme.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'Y díjole: ¿Quién te enseñó que estabas desnudo? ¿Has comido del árbol de que yo te mandé no comieses?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'Y el hombre respondió: La mujer que me diste por compañera me dió del árbol, y yo comí.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'Entonces Jehová Dios dijo á la mujer: ¿Qué es lo que has hecho? Y dijo la mujer: La serpiente me engañó, y comí.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'Y Jehová Dios dijo á la serpiente: Por cuanto esto hiciste, maldita serás entre todas las bestias y entre todos los animales del campo; sobre tu pecho andarás, y polvo comerás todos los días de tu vida:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, 'Y enemistad pondré entre ti y la mujer, y entre tu simiente y la simiente suya; ésta te herirá en la cabeza, y tú le herirás en el calcañar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, 'A la mujer dijo: Multiplicaré en gran manera tus dolores y tus preñeces; con dolor parirás los hijos; y á tu marido será tu deseo, y él se enseñoreará de ti.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, 'Y al hombre dijo: Por cuanto obedeciste á la voz de tu mujer, y comiste del árbol de que te mandé diciendo, No comerás de él; maldita será la tierra por amor de ti; con dolor comerás de ella todos los días de tu vida;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, 'Espinos y cardos te producirá, y comerás hierba del campo;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, 'En el sudor de tu rostro comerás el pan hasta que vuelvas á la tierra; porque de ella fuiste tomado: pues polvo eres, y al polvo serás tornado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'Y llamó el hombre el nombre de su mujer, Eva; por cuanto ella era madre de todos los vivientes.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, 'Y Jehová Dios hizo al hombre y á su mujer túnicas de pieles, y vistiólos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'Y dijo Jehová Dios: He aquí el hombre es como uno de Nos sabiendo el bien y el mal: ahora, pues, porque no alargue su mano, y tome también del árbol de la vida, y coma, y viva para siempre:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'Y sacólo Jehová del huerto de Edén, para que labrase la tierra de que fué tomado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, 'Echó, pues, fuera al hombre, y puso al oriente del huerto de Edén querubines, y una espada encendida que se revolvía á todos lados, para guardar el camino del árbol de la vida.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, 'Y CONOCIÓ Adam á su mujer Eva, la cual concibió y parió á Caín, y dijo: Adquirido he varón por Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, 'Y después parió á su hermano Abel. Y fué Abel pastor de ovejas, y Caín fué labrador de la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, 'Y aconteció andando el tiempo, que Caín trajo del fruto de la tierra una ofrenda á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'Y Abel trajo también de los primogénitos de sus ovejas, y de su grosura. Y miró Jehová con agrado á Abel y á su ofrenda;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'Mas no miró propicio á Caín y á la ofrenda suya. Y ensañóse Caín en gran manera, y decayó su semblante.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, 'Entonces Jehová dijo á Caín: ¿Por qué te has ensañado, y por qué se ha inmutado tu rostro?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, 'Si bien hicieres, ¿no serás ensalzado? y si no hicieres bien, el pecado está á la puerta: con todo esto, á ti será su deseo, y tú te enseñorearás de él.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'Y habló Caín á su hermano Abel: y aconteció que estando ellos en el campo, Caín se levantó contra su hermano Abel, y le mató.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, 'Y Jehová dijo á Caín: ¿Dónde está Abel tu hermano? Y él respondió: No sé; ¿soy yo guarda de mi hermano?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'Y él le dijo: ¿Qué has hecho? La voz de la sangre de tu hermano clama á mí desde la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'Ahora pues, maldito seas tú de la tierra que abrió su boca para recibir la sangre de tu hermano de tu mano:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, 'Cuando labrares la tierra, no te volverá á dar su fuerza: errante y extranjero serás en la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'Y dijo Caín á Jehová: Grande es mi iniquidad para ser perdonada.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, 'He aquí me echas hoy de la faz de la tierra, y de tu presencia me esconderé; y seré errante y extranjero en la tierra; y sucederá que cualquiera que me hallare, me matará.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'Y respondióle Jehová: Cierto que cualquiera que matare á Caín, siete veces será castigado. Entonces Jehová puso señal en Caín, para que no lo hiriese cualquiera que le hallara.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'Y salió Caín de delante de Jehová, y habitó en tierra de Nod, al oriente de Edén.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'Y conoció Caín á su mujer, la cual concibió y parió á Henoch: y edificó una ciudad, y llamó el nombre de la ciudad del nombre de su hijo, Henoch.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'Y á Henoch nació Irad, é Irad engendró á Mehujael, y Mehujael engendró á Methusael, y Methusael engendró á Lamech.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, 'Y tomó para sí Lamech dos mujeres; el nombre de la una fué Ada, y el nombre de la otra Zilla.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'Y Ada parió á Jabal, el cual fué padre de los que habitan en tiendas, y crían ganados.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, 'Y el nombre de su hermano fué Jubal, el cual fué padre de todos los que manejan arpa y órgano.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, 'Y Zilla también parió á Tubal-Caín, acicalador de toda obra de metal y de hierro: y la hermana de Tubal-Caín fué Naama.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'Y dijo Lamech á sus mujeres: Ada y Zilla, oid mi voz; mujeres de Lamech, escuchad mi dicho: que varón mataré por mi herida, y mancebo por mi golpe:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'Si siete veces será vengado Caín, Lamech en verdad setenta veces siete lo será.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, 'Y conoció de nuevo Adam á su mujer, la cual parió un hijo, y llamó su nombre Seth: Porque Dios (dijo ella) me ha sustituído otra simiente en lugar de Abel, á quien mató Caín.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'Y á Seth también le nació un hijo, y llamó su nombre Enós. Entonces los hombres comenzaron á llamarse del nombre de Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, 'ESTE es el libro de las generaciones de Adam. El día en que crió Dios al hombre, á la semejanza de Dios lo hizo;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, 'Varón y hembra los crió; y los bendijo, y llamó el nombre de ellos Adam, el día en que fueron criados.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'Y vivió Adam ciento y treinta años, y engendró un hijo á su semejanza, conforme á su imagen, y llamó su nombre Seth.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'Y fueron los días de Adam, después que engendró á Seth, ochocientos años: y engendró hijos é hijas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'Y fueron todos los días que vivió Adam novecientos y treinta años, y murió.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'Y vivió Seth ciento y cinco años, y engendró á Enós.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'Y vivió Seth, después que engendró á Enós, ochocientos y siete años: y engendró hijos é hijas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'Y fueron todos los días de Seth novecientos y doce años; y murió.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'Y vivió Enós noventa años, y engendró á Cainán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'Y vivió Enós después que engendró á Cainán, ochocientos y quince años: y engendró hijos é hijas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'Y fueron todos los días de Enós novecientos y cinco años; y murió.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'Y vivió Cainán setenta años, y engendró á Mahalaleel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'Y vivió Cainán, después que engendró á Mahalaleel, ochocientos y cuarenta años: y engendró hijos é hijas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'Y fueron todos los días de Cainán novecientos y diez años; y murió.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'Y vivió Mahalaleel sesenta y cinco años, y engendró á Jared.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'Y vivió Mahalaleel, después que engendró á Jared, ochocientos y treinta años: y engendró hijos é hijas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'Y fueron todos los días de Mahalaleel ochocientos noventa y cinco años; y murió.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'Y vivió Jared ciento sesenta y dos años, y engendró á Henoch.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'Y vivió Jared, después que engendró á Henoch, ochocientos años: y engendró hijos é hijas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'Y fueron todos los días de Jared novecientos sesenta y dos años; y murió.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'Y vivió Henoch sesenta y cinco años, y engendró á Mathusalam.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'Y caminó Henoch con Dios, después que engendró á Mathusalam, trescientos años: y engendró hijos é hijas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'Y fueron todos los días de Henoch trescientos sesenta y cinco años.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'Caminó, pues, Henoch con Dios, y desapareció, porque le llevó Dios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'Y vivió Mathusalam ciento ochenta y siete años, y engendró á Lamech.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'Y vivió Mathusalam, después que engendró á Lamech, setecientos ochenta y dos años: y engendró hijos é hijas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'Fueron, pues, todos los días de Mathusalam, novecientos sesenta y nueve años; y murió.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'Y vivió Lamech ciento ochenta y dos años, y engendró un hijo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, 'Y llamó su nombre Noé, diciendo: Este nos aliviará de nuestras obras, y del trabajo de nuestras manos, á causa de la tierra que Jehová maldijo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'Y vivió Lamech, después que engendró á Noé, quinientos noventa y cinco años: y engendró hijos é hijas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'Y fueron todos los días de Lamech setecientos setenta y siete años; y murió.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 32, 'Y siendo Noé de quinientos años, engendró á Sem, Châm, y á Japhet.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, 'Y ACAECIÓ que, cuando comenzaron los hombres á multiplicarse sobre la faz de la tierra, y les nacieron hijas,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, 'Viendo los hijos de Dios que las hijas de los hombres eran hermosas, tomáronse mujeres, escogiendo entre todas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, 'Y dijo Jehová: No contenderá mi espíritu con el hombre para siempre, porque ciertamente él es carne: mas serán sus días ciento y veinte años.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, 'Había gigantes en la tierra en aquellos días, y también después que entraron los hijos de Dios á las hijas de los hombres, y les engendraron hijos: éstos fueron los valientes que desde la antigüedad fueron varones de nombre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'Y vió Jehová que la malicia de los hombres era mucha en la tierra, y que todo designio de los pensamientos del corazón de ellos era de continuo solamente el mal.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, 'Y arrepintióse Jehová de haber hecho hombre en la tierra, y pesóle en su corazón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'Y dijo Jehová: Raeré los hombres que he criado de sobre la faz de la tierra, desde el hombre hasta la bestia, y hasta el reptil y las aves del cielo: porque me arrepiento de haberlos hecho.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, 'Empero Noé halló gracia en los ojos de Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, 'Estas son las generaciones de Noé: Noé, varón justo, perfecto fué en sus generaciones; con Dios caminó Noé.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, 'Y engendró Noé tres hijos: á Sem, á Châm, y á Japhet.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, 'Y corrompióse la tierra delante de Dios, y estaba la tierra llena de violencia.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, 'Y miró Dios la tierra, y he aquí que estaba corrompida; porque toda carne había corrompido su camino sobre la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, 'Y dijo Dios á Noé: El fin de toda carne ha venido delante de mí; porque la tierra está llena de violencia á causa de ellos; y he aquí que yo los destruiré con la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, 'Hazte un arca de madera de Gopher: harás aposentos en el arca, y la embetunarás con brea por dentro y por fuera.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, 'Y de esta manera la harás: de trescientos codos la longitud del arca, de cincuenta codos su anchura, y de treinta codos su altura.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, 'Una ventana harás al arca, y la acabarás á un codo de elevación por la parte de arriba: y pondrás la puerta del arca á su lado; y le harás piso bajo, segundo y tercero.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, 'Y yo, he aquí que yo traigo un diluvio de aguas sobre la tierra, para destruir toda carne en que haya espíritu de vida debajo del cielo; todo lo que hay en la tierra morirá.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, 'Mas estableceré mi pacto contigo, y entrarás en el arca tú, y tus hijos y tu mujer, y las mujeres de tus hijos contigo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, 'Y de todo lo que vive, de toda carne, dos de cada especie meterás en el arca, para que tengan vida contigo; macho y hembra serán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, 'De las aves según su especie, y de las bestias según su especie, de todo reptil de la tierra según su especie, dos de cada especie entrarán contigo para que hayan vida.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, 'Y toma contigo de toda vianda que se come, y allégala á ti; servirá de alimento para ti y para ellos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, 'E hízolo así Noé; hizo conforme á todo lo que Dios le mandó.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'Y JEHOVÁ dijo á Noé: Entra tú y toda tu casa en el arca; porque á ti he visto justo delante de mí en esta generación.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, 'De todo animal limpio te tomarás de siete en siete, macho y su hembra; mas de los animales que no son limpios, dos, macho y su hembra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, 'También de las aves de los cielos de siete en siete, macho y hembra; para guardar en vida la casta sobre la faz de toda la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, 'Porque pasados aún siete días, yo haré llover sobre la tierra cuarenta días y cuarenta noches; y raeré toda sustancia que hice de sobre la faz de la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'E hizo Noé conforme á todo lo que le mandó Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, 'Y siendo Noé de seiscientos años, el diluvio de las aguas fué sobre la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'Y vino Noé, y sus hijos, y su mujer, y las mujeres de sus hijos con él al arca, por las aguas del diluvio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, 'De los animales limpios, y de los animales que no eran limpios, y de las aves, y de todo lo que anda arrastrando sobre la tierra,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, 'De dos en dos entraron á Noé en el arca: macho y hembra, como mandó Dios á Noé.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, 'Y sucedió que al séptimo día las aguas del diluvio fueron sobre la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'El año seiscientos de la vida de Noé, en el mes segundo, á diecisiete días del mes, aquel día fueron rotas todas las fuentes del grande abismo, y las cataratas de los cielos fueron abiertas;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, 'Y hubo lluvia sobre la tierra cuarenta días y cuarenta noches.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, 'En este mismo día entró Noé, y Sem y Châm y Japhet, hijos de Noé, la mujer de Noé, y las tres mujeres de sus hijos con él en el arca;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, 'Ellos, y todos los animales silvestres según sus especies, y todos los animales mansos según sus especies, y todo reptil que anda arrastrando sobre la tierra según su especie, y toda ave según su especie, todo pájaro, toda especie de volátil.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, 'Y vinieron á Noé al arca, de dos en dos de toda carne en que había espíritu de vida.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, 'Y los que vinieron, macho y hembra de toda carne vinieron, como le había mandado Dios: y Jehová le cerró la puerta.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, 'Y fué el diluvio cuarenta días sobre la tierra; y las aguas crecieron, y alzaron el arca, y se elevó sobre la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, 'Y prevalecieron las aguas, y crecieron en gran manera sobre la tierra; y andaba el arca sobre la faz de las aguas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, 'Y las aguas prevalecieron mucho en extremo sobre la tierra; y todos los montes altos que había debajo de todos los cielos, fueron cubiertos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, 'Quince codos en alto prevalecieron las aguas; y fueron cubiertos los montes.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, 'Y murió toda carne que se mueve sobre la tierra, así de aves como de ganados, y de bestias, y de todo reptil que anda arrastrando sobre la tierra, y todo hombre:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, 'Todo lo que tenía aliento de espíritu de vida en sus narices, de todo lo que había en la tierra, murió.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, 'Así fué destruída toda sustancia que vivía sobre la faz de la tierra, desde el hombre hasta la bestia, y los reptiles, y las aves del cielo; y fueron raídos de la tierra; y quedó solamente Noé, y lo que con él estaba en el arca.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, 'Y prevalecieron las aguas sobre la tierra ciento y cincuenta días.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, 'Y ACORDÓSE Dios de Noé, y de todos los animales, y de todas las bestias que estaban con él en el arca; é hizo pasar Dios un viento sobre la tierra, y disminuyeron las aguas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, 'Y se cerraron las fuentes del abismo, y las cataratas de los cielos; y la lluvia de los cielos fué detenida.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, 'Y tornáronse las aguas de sobre la tierra, yendo y volviendo: y decrecieron las aguas al cabo de ciento y cincuenta días.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, 'Y reposó el arca en el mes séptimo, á diecisiete días del mes, sobre los montes de Armenia.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, 'Y las aguas fueron decreciendo hasta el mes décimo: en el décimo, al primero del mes, se descubrieron las cimas de los montes.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, 'Y sucedió que, al cabo de cuarenta días, abrió Noé la ventana del arca que había hecho,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, 'Y envió al cuervo, el cual salió, y estuvo yendo y tornando hasta que las aguas se secaron de sobre la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, 'Envió también de sí á la paloma, para ver si las aguas se habían retirado de sobre la faz de la tierra;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, 'Y no halló la paloma donde sentar la planta de su pie, y volvióse á él al arca, porque las aguas estaban aún sobre la faz de toda la tierra: entonces él extendió su mano, y cogiéndola, hízola entrar consigo en el arca.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, 'Y esperó aún otros siete días, y volvió á enviar la paloma fuera del arca.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, 'Y la paloma volvió á él á la hora de la tarde; y he aquí que traía una hoja de oliva tomada en su pico: y entendió Noé que las aguas se habían retirado de sobre la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, 'Y esperó aún otros siete días, y envió la paloma, la cual no volvió ya más á él.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, 'Y sucedió que en el año seiscientos y uno de Noé, en el mes primero, al primero del mes, las aguas se enjugaron de sobre la tierra; y quitó Noé la cubierta del arca, y miró, y he aquí que la faz de la tierra estaba enjuta.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, 'Y en el mes segundo, á los veintisiete días del mes, se secó la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, 'Y habló Dios á Noé diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, 'Sal del arca tú, y tu mujer, y tus hijos, y las mujeres de tus hijos contigo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, 'Todos los animales que están contigo de toda carne, de aves y de bestias y de todo reptil que anda arrastrando sobre la tierra, sacarás contigo; y vayan por la tierra, y fructifiquen, y multiplíquense sobre la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'Entonces salió Noé, y sus hijos, y su mujer, y las mujeres de sus hijos con él.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, 'Todos los animales, y todo reptil y toda ave, todo lo que se mueve sobre la tierra según sus especies, salieron del arca.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, 'Y edificó Noé un altar á Jehová, y tomó de todo animal limpio y de toda ave limpia, y ofreció holocausto en el altar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'Y percibió Jehová olor de suavidad; y dijo Jehová en su corazón: No tornaré más á maldecir la tierra por causa del hombre; porque el intento del corazón del hombre es malo desde su juventud: ni volveré más á destruir todo viviente, como he hecho.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, 'Todavía serán todos los tiempos de la tierra; la sementera y la siega, y el frío y calor, verano é invierno, y día y noche, no cesarán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, 'Y BENDIJO Dios á Noé y á sus hijos, y díjoles: Fructificad, y multiplicad, y henchid la tierra:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, 'Y vuestro temor y vuestro pavor será sobre todo animal de la tierra, y sobre toda ave de los cielos, en todo lo que se moverá en la tierra, y en todos los peces del mar: en vuestra mano son entregados.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, 'Todo lo que se mueve y vive, os será para mantenimiento: así como las legumbres y hierbas, os lo he dado todo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, 'Empero carne con su vida, que es su sangre, no comeréis.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, 'Porque ciertamente demandaré la sangre de vuestras vidas; de mano de todo animal la demandaré, y de mano del hombre; de mano del varón su hermano demandaré la vida del hombre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, 'El que derramare sangre del hombre, por el hombre su sangre será derramada; porque á imagen de Dios es hecho el hombre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, 'Mas vosotros fructificad, y multiplicaos; procread abundantemente en la tierra, y multiplicaos en ella.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, 'Y habló Dios á Noé y á sus hijos con él, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, 'Yo, he aquí que yo establezco mi pacto con vosotros, y con vuestra simiente después de vosotros;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'Y con toda alma viviente que está con vosotros, de aves, de animales, y de toda bestia de la tierra que está con vosotros; desde todos los que salieron del arca hasta todo animal de la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, 'Estableceré mi pacto con vosotros, y no fenecerá ya más toda carne con aguas de diluvio; ni habrá más diluvio para destruir la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, 'Y dijo Dios: Esta será la señal del pacto que yo establezco entre mí y vosotros y toda alma viviente que está con vosotros, por siglos perpetuos:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, 'Mi arco pondré en las nubes, el cual será por señal de convenio entre mí y la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, 'Y será que cuando haré venir nubes sobre la tierra, se dejará ver entonces mi arco en las nubes.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, 'Y acordarme he del pacto mío, que hay entre mí y vosotros y toda alma viviente de toda carne; y no serán más las aguas por diluvio para destruir toda carne.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, 'Y estará el arco en las nubes, y verlo he para acordarme del pacto perpetuo entre Dios y toda alma viviente, con toda carne que hay sobre la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, 'Dijo, pues, Dios á Noé: Esta será la señal del pacto que he establecido entre mí y toda carne que está sobre la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, 'Y los hijos de Noé que salieron del arca fueron Sem, Châm y Japhet: y Châm es el padre de Canaán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, 'Estos tres son los hijos de Noé; y de ellos fué llena toda la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, 'Y comenzó Noé á labrar la tierra, y plantó una viña:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, 'Y bebió del vino, y se embriagó, y estaba descubierto en medio de su tienda.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'Y Châm, padre de Canaán, vió la desnudez de su padre, y díjolo á sus dos hermanos á la parte de afuera.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'Entonces Sem y Japhet tomaron la ropa, y la pusieron sobre sus propios hombros, y andando hacia atrás, cubrieron la desnudez de su padre, teniendo vueltos sus rostros, y así no vieron la desnudez de su padre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, 'Y despertó Noé de su vino, y supo lo que había hecho con él su hijo el más joven;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, 'Y dijo: Maldito sea Canaán; siervo de siervos será á sus hermanos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, 'Dijo más: Bendito Jehová el Dios de Sem, y séale Canaán siervo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, 'Engrandezca Dios á Japhet, y habite en las tiendas de Sem, y séale Canaán siervo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'Y vivió Noé después del diluvio trescientos y cincuenta años.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'Y fueron todos los días de Noé novecientos y cincuenta años; y murió.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, 'ESTAS son las generaciones de los hijos de Noé: Sem, Châm y Japhet, á los cuales nacieron hijos después del diluvio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'Los hijos de Japhet: Gomer, y Magog, y Madai, y Javán, y Tubal, y Meshech, y Tiras.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, 'Y los hijos de Gomer: Ashkenaz, y Riphat, y Togorma.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, 'Y los hijos de Javán: Elisa, y Tarsis, Kittim, y Dodanim.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, 'Por éstos fueron repartidas las islas de las gentes en sus tierras, cada cual según su lengua, conforme á sus familias en sus naciones.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, 'Los hijos de Châm: Cush, y Mizraim, y Phut, y Canaán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, 'Y los hijos de Cush: Seba, Havila, y Sabta, y Raama, y Sabtecha. Y los hijos de Raama: Sheba y Dedán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'Y Cush engendró á Nimrod: éste comenzó á ser poderoso en la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, 'Este fué vigoroso cazador delante de Jehová; por lo cual se dice: Así como Nimrod, vigoroso cazador delante de Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, 'Y fué la cabecera de su reino Babel, y Erech, y Accad, y Calneh, en la tierra de Shinar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, 'De aquesta tierra salió Assur, y edificó á Nínive, y á Rehoboth, y á Calah,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'Y á Ressen entre Nínive y Calah; la cual es ciudad grande.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, 'Y Mizraim engendró á Ludim, y á Anamim, y á Lehabim, y á Naphtuhim,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'Y á Pathrusim, y á Casluim, de donde salieron los Filisteos, y á Caphtorim.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, 'Y Canaán engendró á Sidón, su primogénito, y á Heth,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'Y al Jebuseo, y al Amorrheo, y al Gergeseo,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'Y al Heveo, y al Araceo, y al Sineo,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'Y al Aradio, y al Samareo, y al Amatheo: y después se derramaron las familias de los Cananeos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'Y fué el término de los Cananeos desde Sidón, viniendo á Gerar hasta Gaza, hasta entrar en Sodoma y Gomorra, Adma, y Zeboim hasta Lasa.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, 'Estos son los hijos de Châm por sus familias, por sus lenguas, en sus tierras, en sus naciones.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, 'También le nacieron hijos á Sem, padre de todos los hijos de Heber, y hermano mayor de Japhet.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, 'Y los hijos de Sem: Elam, y Assur, y Arphaxad, y Lud, y Aram.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, 'Y los hijos de Aram: Uz, y Hul, y Gether, y Mas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, 'Y Arphaxad engendró á Sala, y Sala engendró á Heber.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'Y á Heber nacieron dos hijos: el nombre del uno fué Peleg, porque en sus días fué repartida la tierra; y el nombre de su hermano, Joctán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'Y Joctán engendró á Almodad, y á Sheleph, y Hazarmaveth, y á Jera,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'Y á Hadoram, y á Uzal, y á Dicla,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'Y á Obal, y á Abimael, y á Seba,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'Y á Ophir, y á Havila, y á Jobad: todos estos fueron hijos de Joctán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, 'Y fué su habitación desde Mesa viniendo de Sephar, monte á la parte del oriente.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, 'Estos fueron los hijos de Sem por sus familias, por sus lenguas, en sus tierras, en sus naciones.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, 'Estas son las familias de Noé por sus descendencias, en sus naciones; y de éstos fueron divididas las gentes en la tierra después del diluvio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, 'ERA entonces toda la tierra de una lengua y unas mismas palabras.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, 'Y aconteció que, como se partieron de oriente, hallaron una vega en la tierra de Shinar, y asentaron allí.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, 'Y dijeron los unos á los otros: Vaya, hagamos ladrillo y cozámoslo con fuego. Y fuéles el ladrillo en lugar de piedra, y el betún en lugar de mezcla.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, 'Y dijeron: Vamos, edifiquémonos una ciudad y una torre, cuya cúspide llegue al cielo; y hagámonos un nombre, por si fuéremos esparcidos sobre la faz de toda la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, 'Y descendió Jehová para ver la ciudad y la torre que edificaban los hijos de los hombres.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'Y dijo Jehová: He aquí el pueblo es uno, y todos éstos tienen un lenguaje: y han comenzado á obrar, y nada les retraerá ahora de lo que han pensando hacer.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, 'Ahora pues, descendamos, y confundamos allí sus lenguas, para que ninguno entienda el habla de su compañero.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'Así los esparció Jehová desde allí sobre la faz de toda la tierra, y dejaron de edificar la ciudad.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, 'Por esto fué llamado el nombre de ella Babel, porque allí confundió Jehová el lenguaje de toda la tierra, y desde allí los esparció sobre la faz de toda la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, 'Estas son las generaciones de Sem: Sem, de edad de cien años, engendró á Arphaxad, dos años después del diluvio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'Y vivió Sem, después que engendró á Arphaxad, quinientos años, y engendró hijos é hijas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'Y Arphaxad vivió treinta y cinco años, y engendró á Sala.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'Y vivió Arphaxad, después que engendró á Sala, cuatrocientos y tres años, y engendró hijos é hijas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'Y vivió Sala treinta años, y engendró á Heber.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'Y vivió Sala, después que engendró á Heber, cuatrocientos y tres años, y engendró hijos é hijas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'Y vivió Heber treinta y cuatro años, y engendró á Peleg.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'Y vivió Heber, después que engendró á Peleg, cuatrocientos y treinta años, y engendró hijos é hijas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'Y vivió Peleg treinta años, y engendró á Reu.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'Y vivió Peleg, después que engendró á Reu, doscientos y nueve años, y engendró hijos é hijas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'Y Reu vivió treinta y dos años, y engendró á Serug.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'Y vivió Reu, después que engendró á Serug, doscientos y siete años, y engendró hijos é hijas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'Y vivió Serug treinta años, y engendró á Nachôr.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'Y vivió Serug, después que engendró á Nachôr, doscientos años, y engendró hijos é hijas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'Y vivió Nachôr veintinueve años, y engendró á Thare.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'Y vivió Nachôr, después que engendró á Thare, ciento diecinueve años, y engendró hijos é hijas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'Y vivió Thare setenta años, y engendró á Abram, y á Nachôr, y á Harán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, 'Estas son las generaciones de Thare: Thare engendró á Abram, y á Nachôr, y á Harán; y Harán engendró á Lot.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'Y murió Harán antes que su padre Thare en la tierra de su naturaleza, en Ur de los Caldeos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, 'Y tomaron Abram y Nachôr para sí mujeres: el nombre de la mujer de Abram fué Sarai, y el nombre de la mujer de Nachôr, Milca, hija de Harán, padre de Milca y de Isca.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'Mas Sarai fué estéril, y no tenía hijo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, 'Y tomó Thare á Abram su hijo, y á Lot hijo de Harán, hijo de su hijo, y á Sarai su nuera, mujer de Abram su hijo: y salió con ellos de Ur de los Caldeos, para ir á la tierra de Canaán: y vinieron hasta Harán, y asentaron allí.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'Y fueron los días de Thare doscientos y cinco años; y murió Thare en Harán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, 'EMPERO Jehová había dicho á Abram: Vete de tu tierra y de tu parentela, y de la casa de tu padre, á la tierra que te mostraré;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, 'Y haré de ti una nación grande, y bendecirte he, y engrandeceré tu nombre, y serás bendición:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, 'Y bendeciré á los que te bendijeren, y á los que te maldijeren maldeciré: y serán benditas en ti todas las familias de la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'Y fuése Abram, como Jehová le dijo; y fué con él Lot: y era Abram de edad de setenta y cinco años cuando salió de Harán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'Y tomó Abram á Sarai su mujer, y á Lot hijo de su hermano, y toda su hacienda que habían ganado, y las almas que habían adquirido en Harán, y salieron para ir á tierra de Canaán; y á tierra de Canaán llegaron.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'Y pasó Abram por aquella tierra hasta el lugar de Sichêm, hasta el valle de Moreh: y el Cananeo estaba entonces en la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, 'Y apareció Jehová á Abram, y le dijo: A tu simiente daré esta tierra. Y edificó allí un altar á Jehová, que le había aparecido.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, 'Y pasóse de allí á un monte al oriente de Bethel, y tendió su tienda, teniendo á Bethel al occidente y Hai al oriente: y edificó allí altar á Jehová, é invocó el nombre de Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, 'Y movió Abram de allí, caminando y yendo hacia el Mediodía.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, 'Y hubo hambre en la tierra, y descendió Abram á Egipto para peregrinar allá; porque era grande el hambre en la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, 'Y aconteció que cuando estaba para entrar en Egipto, dijo á Sarai su mujer: He aquí, ahora conozco que eres mujer hermosa de vista;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, 'Y será que cuando te habrán visto los Egipcios, dirán: Su mujer es: y me matarán á mí, y á ti te reservarán la vida.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, 'Ahora pues, di que eres mi hermana, para que yo haya bien por causa tuya, y viva mi alma por amor de ti.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'Y aconteció que, como entró Abram en Egipto, los Egipcios vieron la mujer que era hermosa en gran manera.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'Viéronla también los príncipes de Faraón, y se la alabaron; y fué llevada la mujer á casa de Faraón:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, 'E hizo bien á Abram por causa de ella; y tuvo ovejas, y vacas, y asnos, y siervos, y criadas, y asnas y camellos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, 'Mas Jehová hirió á Faraón y á su casa con grandes plagas, por causa de Sarai mujer de Abram.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'Entonces Faraón llamó á Abram, y le dijo: ¿Qué es esto que has hecho conmigo? ¿Por qué no me declaraste que era tu mujer?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, '¿Por qué dijiste: Es mi hermana? poniéndome en ocasión de tomarla para mí por mujer? Ahora pues, he aquí tu mujer, tómala y vete.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'Entonces Faraón dió orden á sus gentes acerca de Abram; y le acompañaron, y á su mujer con todo lo que tenía.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, 'SUBIÓ, pues, Abram de Egipto hacia el Mediodía, él, y su mujer, con todo lo que tenía, y con él Lot.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, 'Y Abram era riquísimo en ganado, en plata y oro.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, 'Y volvió por sus jornadas de la parte del Mediodía hacia Bethel, hasta el lugar donde había estado antes su tienda entre Bethel y Hai;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, 'Al lugar del altar que había hecho allí antes: é invocó allí Abram el nombre de Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, 'Y asimismo Lot, que andaba con Abram, tenía ovejas, y vacas, y tiendas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, 'Y la tierra no podía darles para que habitasen juntos: porque su hacienda era mucha, y no podían morar en un mismo lugar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, 'Y hubo contienda entre los pastores del ganado de Abram y los pastores del ganado de Lot: y el Cananeo y el Pherezeo habitaban entonces en la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'Entonces Abram dijo á Lot: No haya ahora altercado entre mí y ti, entre mis pastores y los tuyos, porque somos hermanos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, '¿No está toda la tierra delante de ti? Yo te ruego que te apartes de mí. Si fueres á la mano izquierda, yo iré á la derecha: y si tú á la derecha, yo iré á la izquierda.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, 'Y alzó Lot sus ojos, y vió toda la llanura del Jordán, que toda ella era de riego, antes que destruyese Jehová á Sodoma y á Gomorra, como el huerto de Jehová, como la tierra de Egipto entrando en Zoar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'Entonces Lot escogió para sí toda la llanura del Jordán: y partióse Lot de Oriente, y apartáronse el uno del otro.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'Abram asentó en la tierra de Canaán, y Lot asentó en las ciudades de la llanura, y fué poniendo sus tiendas hasta Sodoma.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'Mas los hombres de Sodoma eran malos y pecadores para con Jehová en gran manera.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, 'Y Jehová dijo á Abram, después que Lot se apartó de él: Alza ahora tus ojos, y mira desde el lugar donde estás hacia el Aquilón, y al Mediodía, y al Oriente y al Occidente;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, 'Porque toda la tierra que ves, la daré á ti y á tu simiente para siempre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, 'Y haré tu simiente como el polvo de la tierra: que si alguno podrá contar el polvo de la tierra, también tu simiente será contada.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, 'Levántate, ve por la tierra á lo largo de ella y á su ancho; porque á ti la tengo de dar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, 'Abram, pues, removiendo su tienda, vino y moró en el alcornocal de Mamre, que es en Hebrón, y edificó allí altar á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, 'Y ACONTECIÓ en los días de Amraphel, rey de Shinar, Arioch, rey de Elazar, Chêdorlaomer, rey de Elá, y Tidal, rey de naciones,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'Que éstos hicieron guerra contra Bera, rey de Sodoma, y contra Birsha, rey de Gomorra, y contra Shinab, rey de Adma, y contra Shemeber, rey de Zeboim, y contra el rey de Bela, la cual es Zoar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, 'Todos estos se juntaron en el valle de Siddim, que es el mar salado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, 'Doce años habían servido á Chêdorlaomer, y al décimotercio año se rebelaron.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, 'Y en el año décimocuarto vino Chêdorlaomer, y los reyes que estaban de su parte, y derrotaron á los Raphaitas en Ashteroth-carnaim, á los Zuzitas en Ham, y á los Emitas en Shave-Kiriataim.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'Y á los Horeos en el monte de Seir, hasta la llanura de Parán, que está junto al desierto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, 'Y volvieron, y vinieron á Emmisphat, que es Cades, y devastaron todas las haciendas de los Amalecitas, y también al Amorrheo, que habitaba en Hazezón-tamar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, 'Y salió el rey de Sodoma, y el rey de Gomorra, y el rey de Adma, y el rey de Zeboim, y el rey de Bela, que es Zoar, y ordenaron contra ellos batalla en el valle de Siddim;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, 'Es á saber, contra Chêdorlaomer, rey de Elam, y Tidal, rey de naciones, y Amraphel, rey de Shinar, y Arioch, rey de Elasar; cuatro reyes contra cinco.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, 'Y el valle de Siddim estaba lleno de pozos de betún: y huyeron el rey de Sodoma y el de Gomorra, y cayeron allí; y los demás huyeron al monte.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, 'Y tomaron toda la riqueza de Sodoma y de Gomorra, y todas sus vituallas, y se fueron.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, 'Tomaron también á Lot, hijo del hermano de Abram, que moraba en Sodoma, y su hacienda, y se fueron.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, 'Y vino uno de los que escaparon, y denunciólo á Abram el Hebreo, que habitaba en el valle de Mamre Amorrheo, hermano de Eschôl y hermano de Aner, los cuales estaban confederados con Abram.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'Y oyó Abram que su hermano estaba prisionero, y armó sus criados, los criados de su casa, trescientos dieciocho, y siguiólos hasta Dan.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, 'Y derramóse sobre ellos de noche él y sus siervos, é hiriólos, y fuélos siguiendo hasta Hobah, que está á la izquierda de Damasco.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'Y recobró todos los bienes, y también á Lot su hermano y su hacienda, y también las mujeres y gente.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'Y salió el rey de Sodoma á recibirlo, cuando volvía de la derrota de Chêdorlaomer y de los reyes que con él estaban, al valle de Shave, que es el valle del Rey.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, 'Entonces Melchîsedec, rey de Salem, sacó pan y vino; el cual era sacerdote del Dios alto;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, 'Y bendíjole, y dijo: Bendito sea Abram del Dios alto, poseedor de los cielos y de la tierra;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, 'Y bendito sea el Dios alto, que entregó tus enemigos en tu mano. Y dióle Abram los diezmos de todo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, 'Entonces el rey de Sodoma dijo á Abram: Dame las personas, y toma para ti la hacienda.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'Y respondió Abram al rey de Sodoma: He alzado mi mano á Jehová Dios alto, poseedor de los cielos y de la tierra,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, 'Que desde un hilo hasta la correa de un calzado, nada tomaré de todo lo que es tuyo, porque no digas: Yo enriquecí á Abram:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, 'Sacando solamente lo que comieron los mancebos, y la porción de los varones que fueron conmigo, Aner, Eschôl, y Mamre; los cuales tomarán su parte.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, 'DESPUÉS de estas cosas fué la palabra de Jehová á Abram en visión, diciendo: No temas, Abram; yo soy tu escudo, y tu galardón sobremanera grande.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'Y respondió Abram: Señor Jehová ¿qué me has de dar, siendo así que ando sin hijo, y el mayordomo de mi casa es ese Damasceno Eliezer?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, 'Dijo más Abram: Mira que no me has dado prole, y he aquí que es mi heredero uno nacido en mi casa.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'Y luego la palabra de Jehová fué á él diciendo: No te heredará éste, sino el que saldrá de tus entrañas será el que te herede.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, 'Y sacóle fuera, y dijo: Mira ahora á los cielos, y cuenta las estrellas, si las puedes contar. Y le dijo: Así será tu simiente.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, 'Y creyó á Jehová, y contóselo por justicia.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, 'Y díjole: Yo soy Jehová, que te saqué de Ur de los Caldeos, para darte á heredar esta tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, 'Y él respondió: Señor Jehová, ¿en qué conoceré que la tengo de heredar?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, 'Y le dijo: Apártame una becerra de tres años, y una cabra de tres años, y un carnero de tres años, una tórtola también, y un palomino.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, 'Y tomó él todas estas cosas, y partiólas por la mitad, y puso cada mitad una enfrente de otra; mas no partió las aves.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, 'Y descendían aves sobre los cuerpos muertos, y ojeábalas Abram.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, 'Mas á la caída del sol sobrecogió el sueño á Abram, y he aquí que el pavor de una grande obscuridad cayó sobre él.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, 'Entonces dijo á Abram: Ten por cierto que tu simiente será peregrina en tierra no suya, y servirá á los de allí, y serán por ellos afligidos cuatrocientos años.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, 'Mas también á la gente á quien servirán, juzgaré yo; y después de esto saldrán con grande riqueza.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, 'Y tú vendrás á tus padres en paz, y serás sepultado en buena vejez.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, 'Y en la cuarta generación volverán acá: porque aun no está cumplida la maldad del Amorrheo hasta aquí.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, 'Y sucedió que puesto el sol, y ya obscurecido, dejóse ver un horno humeando, y una antorcha de fuego que pasó por entre los animales divididos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, 'En aquel día hizo Jehová un pacto con Abram diciendo: A tu simiente daré esta tierra desde el río de Egipto hasta el río grande, el río Eufrates;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, 'Los Cineos, y los Ceneceos, y los Cedmoneos,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'Y los Hetheos, y los Pherezeos, y los Raphaitas,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'Y los Amorrheos, y los Cananeos, y los Gergeseos, y los Jebuseos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'Y SARAI, mujer de Abram, no le paría: y ella tenía una sierva egipcia, que se llamaba Agar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, 'Dijo, pues, Sarai á Abram: Ya ves que Jehová me ha hecho estéril: ruégote que entres á mi sierva; quizá tendré hijos de ella. Y atendió Abram al dicho de Sarai.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'Y Sarai, mujer de Abram, tomó á Agar su sierva egipcia, al cabo de diez años que había habitado Abram en la tierra de Canaán, y dióla á Abram su marido por mujer.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, 'Y él cohabitó con Agar, la cual concibió: y cuando vió que había concebido, miraba con desprecio á su señora.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'Entonces Sarai dijo á Abram: Mi afrenta sea sobre ti: yo puse mi sierva en tu seno, y viéndose embarazada, me mira con desprecio; juzgue Jehová entre mí y ti.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'Y respondió Abram á Sarai: He ahí tu sierva en tu mano, haz con ella lo que bien te pareciere. Y como Sarai la afligiese, huyóse de su presencia.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, 'Y hallóla el ángel de Jehová junto á una fuente de agua en el desierto, junto á la fuente que está en el camino del Sur.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, 'Y le dijo: Agar, sierva de Sarai, ¿de dónde vienes tú, y á dónde vas? Y ella respondió: Huyo de delante de Sarai, mi señora.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, 'Y díjole el ángel de Jehová: Vuélvete á tu señora, y ponte sumisa bajo de su mano.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'Díjole también el ángel de Jehová: Multiplicaré tanto tu linaje, que no será contado á causa de la muchedumbre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'Díjole aún el ángel de Jehová: He aquí que has concebido, y parirás un hijo, y llamarás su nombre Ismael, porque oído ha Jehová tu aflicción.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, 'Y él será hombre fiero; su mano contra todos, y las manos de todos contra él, y delante de todos sus hermanos habitará.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'Entonces llamó el nombre de Jehová que con ella hablaba: Tú eres el Dios de la vista; porque dijo: ¿No he visto también aquí al que me ve?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, 'Por lo cual llamó al pozo, Pozo del Viviente que me ve. He aquí está entre Cades y Bered.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, 'Y parió Agar á Abram un hijo, y llamó Abram el nombre de su hijo que le parió Agar, Ismael.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'Y era Abram de edad de ochenta y seis años, cuando parió Agar á Ismael.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, 'Y SIENDO Abram de edad de noventa y nueve años, aparecióle Jehová, y le dijo: Yo soy el Dios Todopoderoso; anda delante de mí, y sé perfecto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, 'Y pondré mi pacto entre mí y ti, y multiplicarte he mucho en gran manera.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'Entonces Abram cayó sobre su rostro, y Dios habló con él diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, 'Yo, he aquí mi pacto contigo: Serás padre de muchedumbre de gentes:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, 'Y no se llamará más tu nombre Abram, sino que será tu nombre Abraham, porque te he puesto por padre de muchedumbre de gentes.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, 'Y multiplicarte he mucho en gran manera, y te pondré en gentes, y reyes saldrán de ti.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, 'Y estableceré mi pacto entre mí y ti, y tu simiente después de ti en sus generaciones, por alianza perpetua, para serte á ti por Dios, y á tu simiente después de ti.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, 'Y te daré á ti, y á tu simiente después de ti, la tierra de tus peregrinaciones, toda la tierra de Canaán en heredad perpetua; y seré el Dios de ellos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, 'Dijo de nuevo Dios á Abraham: Tú empero guardarás mi pacto, tú y tu simiente después de ti por sus generaciones.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, 'Este será mi pacto, que guardaréis entre mí y vosotros y tu simiente después de ti: Será circuncidado todo varón de entre vosotros.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, 'Circuncidaréis, pues, la carne de vuestro prepucio, y será por señal del pacto entre mí y vosotros.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, 'Y de edad de ocho días será circuncidado todo varón entre vosotros por vuestras generaciones: el nacido en casa, y el comprado á dinero de cualquier extranjero, que no fuere de tu simiente.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, 'Debe ser circuncidado el nacido en tu casa, y el comprado por tu dinero: y estará mi pacto en vuestra carne para alianza perpetua.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, 'Y el varón incircunciso que no hubiere circuncidado la carne de su prepucio, aquella persona será borrada de su pueblo; ha violado mi pacto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, 'Dijo también Dios á Abraham: A Sarai tu mujer no la llamarás Sarai, mas Sara será su nombre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, 'Y bendecirla he, y también te daré de ella hijo; sí, la bendeciré, y vendrá á ser madre de naciones; reyes de pueblos serán de ella.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, 'Entonces Abraham cayó sobre su rostro, y rióse, y dijo en su corazón: ¿A hombre de cien años ha de nacer hijo? ¿y Sara, ya de noventa años, ha de parir?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'Y dijo Abraham á Dios: Ojalá Ismael viva delante de ti.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, 'Y respondió Dios: Ciertamente Sara tu mujer te parirá un hijo, y llamarás su nombre Isaac; y confirmaré mi pacto con él por alianza perpetua para su simiente después de él.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, 'Y en cuanto á Ismael, también te he oído: he aquí que le bendeciré, y le haré fructificar y multiplicar mucho en gran manera: doce príncipes engendrará, y ponerlo he por gran gente.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, 'Mas yo estableceré mi pacto con Isaac, al cual te parirá Sara por este tiempo el año siguiente.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, 'Y acabó de hablar con él, y subió Dios de con Abraham.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, 'Entonces tomó Abraham á Ismael su hijo, y á todos los siervos nacidos en su casa, y á todos los comprados por su dinero, á todo varón entre los domésticos de la casa de Abraham, y circuncidó la carne del prepucio de ellos en aquel mismo día, como Dios le había dicho.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'Era Abraham de edad de noventa y nueve años cuando circuncidó la carne de su prepucio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, 'E Ismael su hijo era de trece años, cuando fué circuncidada la carne de su prepucio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, 'En el mismo día fué circuncidado Abraham é Ismael su hijo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, 'Y todos los varones de su casa, el siervo nacido en casa, y el comprado por dinero del extranjero, fueron circuncidados con él.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, 'Y APARECIÓLE Jehová en el valle de Mamre, estando él sentado á la puerta de su tienda en el calor del día.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, 'Y alzó sus ojos y miró, y he aquí tres varones que estaban junto á él: y cuando los vió, salió corriendo de la puerta de su tienda á recibirlos, é inclinóse hacia la tierra,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, 'Y dijo: Señor, si ahora he hallado gracia en tus ojos, ruégote que no pases de tu siervo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, 'Que se traiga ahora un poco de agua, y lavad vuestros pies; y recostaos debajo de un árbol,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, 'Y traeré un bocado de pan, y sustentad vuestro corazón; después pasaréis: porque por eso habéis pasado cerca de vuestro siervo. Y ellos dijeron: Haz así como has dicho.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, 'Entonces Abraham fué de priesa á la tienda á Sara, y le dijo: Toma presto tres medidas de flor de harina, amasa y haz panes cocidos debajo del rescoldo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, 'Y corrió Abraham á las vacas, y tomó un becerro tierno y bueno, y diólo al mozo, y dióse éste priesa á aderezarlo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'Tomó también manteca y leche, y el becerro que había aderezado, y púsolo delante de ellos; y él estaba junto á ellos debajo del árbol; y comieron.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, 'Y le dijeron: ¿Dónde está Sara tu mujer? Y él respondió: Aquí en la tienda.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, 'Entonces dijo: De cierto volveré á ti según el tiempo de la vida, y he aquí, tendrá un hijo Sara tu mujer. Y Sara escuchaba á la puerta de la tienda, que estaba detrás de él.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, 'Y Abraham y Sara eran viejos, entrados en días: á Sara había cesado ya la costumbre de las mujeres.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, 'Rióse, pues, Sara entre sí, diciendo: ¿Después que he envejecido tendré deleite, siendo también mi señor ya viejo?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'Entonces Jehová dijo á Abraham: ¿Por qué se ha reído Sara diciendo: Será cierto que he de parir siendo ya vieja?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, '¿Hay para Dios alguna cosa difícil? Al tiempo señalado volveré á ti, según el tiempo de la vida, y Sara tendrá un hijo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'Entonces Sara negó diciendo: No me reí; porque tuvo miedo. Y él dijo: No es así, sino que te has reído.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, 'Y los varones se levantaron de allí, y miraron hacia Sodoma: y Abraham iba con ellos acompañándolos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'Y Jehová dijo: ¿Encubriré yo á Abraham lo que voy á hacer,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'Habiendo de ser Abraham en una nación grande y fuerte, y habiendo de ser benditas en él todas las gentes de la tierra?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, 'Porque yo lo he conocido, sé que mandará á sus hijos y á su casa después de sí, que guarden el camino de Jehová, haciendo justicia y juicio, para que haga venir Jehová sobre Abraham lo que ha hablado acerca de él.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'Entonces Jehová le dijo: Por cuanto el clamor de Sodoma y Gomorra se aumenta más y más, y el pecado de ellos se ha agravado en extremo,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, 'Descenderé ahora, y veré si han consumado su obra según el clamor que ha venido hasta mí; y si no, saberlo he.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, 'Y apartáronse de allí los varones, y fueron hacia Sodoma: mas Abraham estaba aún delante de Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, 'Y acercóse Abraham y dijo: ¿Destruirás también al justo con el impío?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, 'Quizá hay cincuenta justos dentro de la ciudad: ¿destruirás también y no perdonarás al lugar por cincuenta justos que estén dentro de él?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, 'Lejos de ti el hacer tal, que hagas morir al justo con el impío, y que sea el justo tratado como el impío; nunca tal hagas. El juez de toda la tierra, ¿no ha de hacer lo que es justo?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, 'Entonces respondió Jehová: Si hallare en Sodoma cincuenta justos dentro de la ciudad, perdonaré á todo este lugar por amor de ellos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, 'Y Abraham replicó y dijo: He aquí ahora que he comenzado á hablar á mi Señor, aunque soy polvo y ceniza:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, 'Quizá faltarán de cincuenta justos cinco: ¿destruirás por aquellos cinco toda la ciudad? Y dijo: No la destruiré, si hallare allí cuarenta y cinco.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, 'Y volvió á hablarle, y dijo: Quizá se hallarán allí cuarenta. Y respondió: No lo haré por amor de los cuarenta.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, 'Y dijo: No se enoje ahora mi Señor, si hablare: quizá se hallarán allí treinta. Y respondió: No lo haré si hallare allí treinta.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, 'Y dijo: He aquí ahora que he emprendido el hablar á mi Señor: quizá se hallarán allí veinte. No la destruiré, respondió, por amor de los veinte.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, 'Y volvió á decir: No se enoje ahora mi Señor, si hablare solamente una vez: quizá se hallarán allí diez. No la destruiré, respondió, por amor de los diez.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'Y fuése Jehová, luego que acabó de hablar á Abraham: y Abraham se volvió á su lugar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, 'LLEGARON, pues, los dos ángeles á Sodoma á la caída de la tarde: y Lot estaba sentado á la puerta de Sodoma. Y viéndolos Lot, levantóse á recibirlos, é inclinóse hacia el suelo;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, 'Y dijo: Ahora, pues, mis señores, os ruego que vengáis á casa de vuestro siervo y os hospedéis, y lavaréis vuestros pies: y por la mañana os levantaréis, y seguiréis vuestro camino. Y ellos respondieron: No, que en la plaza nos quedaremos esta noche.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, 'Mas él porfió con ellos mucho, y se vinieron con él, y entraron en su casa; é hízoles banquete, y coció panes sin levadura, y comieron.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, 'Y antes que se acostasen, cercaron la casa los hombres de la ciudad, los varones de Sodoma, todo el pueblo junto, desde el más joven hasta el más viejo;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'Y llamaron á Lot, y le dijeron: ¿Dónde están los varones que vinieron á ti esta noche? sácanoslos, para que los conozcamos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'Entonces Lot salió á ellos á la puerta, y cerró las puertas tras sí,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, 'Y dijo: Os ruego, hermanos míos, que no hagáis tal maldad.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, 'He aquí ahora yo tengo dos hijas que no han conocido varón; os las sacaré afuera, y haced de ellas como bien os pareciere: solamente á estos varones no hagáis nada, pues que vinieron á la sombra de mi tejado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, 'Y ellos respondieron: Quita allá: y añadieron: Vino éste aquí para habitar como un extraño, ¿y habrá de erigirse en juez? Ahora te haremos más mal que á ellos. Y hacían gran violencia al varón, á Lot, y se acercaron para romper las puertas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, 'Entonces los varones alargaron la mano, y metieron á Lot en casa con ellos, y cerraron las puertas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, 'Y á los hombres que estaban á la puerta de la casa desde el menor hasta el mayor, hirieron con ceguera; mas ellos se fatigaban por hallar la puerta.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, 'Y dijeron los varones á Lot: ¿Tienes aquí alguno más? Yernos, y tus hijos y tus hijas, y todo lo que tienes en la ciudad, sáca lo de este lugar:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, 'Porque vamos á destruir este lugar, por cuanto el clamor de ellos ha subido de punto delante de Jehová; por tanto Jehová nos ha enviado para destruirlo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'Entonces salió Lot, y habló á sus yernos, los que habían de tomar sus hijas, y les dijo: Levantaos, salid de este lugar; porque Jehová va á destruir esta ciudad. Mas pareció á sus yernos como que se burlaba.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, 'Y al rayar el alba, los ángeles daban prisa á Lot, diciendo: Levántate, toma tu mujer, y tus dos hijas que se hallan aquí, porque no perezcas en el castigo de la ciudad.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, 'Y deteniéndose él, los varones asieron de su mano, y de la mano de su mujer, y de las manos de sus dos hijas, según la misericordia de Jehová para con él; y le sacaron, y le pusieron fuera de la ciudad.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, 'Y fué que cuando los hubo sacado fuera, dijo: Escapa por tu vida; no mires tras ti, ni pares en toda esta llanura; escapa al monte, no sea que perezcas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'Y Lot les dijo: No, yo os ruego, señores míos;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, 'He aquí ahora ha hallado tu siervo gracia en tus ojos, y has engrandecido tu misericordia que has hecho conmigo dándome la vida; mas yo no podré escapar al monte, no sea caso que me alcance el mal, y muera.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, 'He aquí ahora esta ciudad está cerca para huir allá, la cual es pequeña; escaparé ahora allá, (¿no es ella pequeña?) y vivirá mi alma.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, 'Y le respondió: He aquí he recibido también tu súplica sobre esto, y no destruiré la ciudad de que has hablado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, 'Date priesa, escápate allá; porque nada podré hacer hasta que allí hayas llegado. Por esto fué llamado el nombre de la ciudad, Zoar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'El sol salía sobre la tierra, cuando Lot llegó á Zoar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'Entonces llovió Jehová sobre Sodoma y sobre Gomorra azufre y fuego de parte de Jehová desde los cielos;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, 'Y destruyó las ciudades, y toda aquella llanura, con todos los moradores de aquellas ciudades, y el fruto de la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, 'Entonces la mujer de Lot miró atrás, á espaldas de él, y se volvió estatua de sal.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'Y subió Abraham por la mañana al lugar donde había estado delante de Jehová:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'Y miró hacia Sodoma y Gomorra, y hacia toda la tierra de aquella llanura miró; y he aquí que el humo subía de la tierra como el humo de un horno.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, 'Así fué que, cuando destruyó Dios las ciudades de la llanura, acordóse Dios de Abraham, y envió fuera á Lot de en medio de la destrucción, al asolar las ciudades donde Lot estaba.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, 'Empero Lot subió de Zoar, y asentó en el monte, y sus dos hijas con él; porque tuvo miedo de quedar en Zoar, y se alojó en una cueva él y sus dos hijas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, 'Entonces la mayor dijo á la menor: Nuestro padre es viejo, y no queda varón en la tierra que entre á nosotras conforme á la costumbre de toda la tierra:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, 'Ven, demos á beber vino á nuestro padre, y durmamos con él, y conservaremos de nuestro padre generación.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, 'Y dieron á beber vino á su padre aquella noche: y entró la mayor, y durmió con su padre; mas él no sintió cuándo se acostó ella, ni cuándo se levantó.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, 'El día siguiente dijo la mayor á la menor: He aquí yo dormí la noche pasada con mi padre; démosle á beber vino también esta noche, y entra y duerme con él, para que conservemos de nuestro padre generación.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, 'Y dieron á beber vino á su padre también aquella noche: y levantóse la menor, y durmió con él; pero no echó de ver cuándo se acostó ella, ni cuándo se levantó.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, 'Y concibieron las dos hijas de Lot, de su padre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, 'Y parió la mayor un hijo, y llamó su nombre Moab, el cual es padre de los Moabitas hasta hoy.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, 'La menor también parió un hijo, y llamó su nombre Ben-ammí, el cual es padre de los Ammonitas hasta hoy.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, 'DE allí partió Abraham á la tierra del Mediodía, y asentó entre Cades y Shur, y habitó como forastero en Gerar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'Y dijo Abraham de Sara su mujer: Mi hermana es. Y Abimelech, rey de Gerar, envió y tomó á Sara.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, 'Empero Dios vino á Abimelech en sueños de noche, y le dijo: He aquí muerto eres á causa de la mujer que has tomado, la cual es casada con marido.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'Mas Abimelech no había llegado á ella, y dijo: Señor, ¿matarás también la gente justa?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, '¿No me dijo él: Mi hermana es; y ella también dijo: Es mi hermano? Con sencillez de mi corazón, y con limpieza de mis manos he hecho esto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, 'Y díjole Dios en sueños: Yo también sé que con integridad de tu corazón has hecho esto; y yo también te detuve de pecar contra mí, y así no te permití que la tocases.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, 'Ahora, pues, vuelve la mujer á su marido; porque es profeta, y orará por ti, y vivirás. Y si tú no la volvieres, sabe que de cierto morirás, con todo lo que fuere tuyo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, 'Entonces Abimelech se levantó de mañana, y llamó á todos sus siervos, y dijo todas estas palabras en los oídos de ellos; y temieron los hombres en gran manera.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, 'Después llamó Abimelech á Abraham, y le dijo: ¿Qué nos has hecho? ¿y en qué pequé yo contra ti, que has atraído sobre mí y sobre mi reino tan gran pecado? lo que no debiste hacer has hecho conmigo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'Y dijo más Abimelech á Abraham: ¿Qué viste para que hicieses esto?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'Y Abraham respondió: Porque dije para mí: Cierto no hay temor de Dios en este lugar, y me matarán por causa de mi mujer.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, 'Y á la verdad también es mi hermana, hija de mi padre, mas no hija de mi madre, y toméla por mujer.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, 'Y fué que, cuando Dios me hizo salir errante de la casa de mi padre, yo le dije: Esta es la merced que tú me harás, que en todos los lugares donde llegáremos, digas de mí: Mi hermano es.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'Entonces Abimelech tomó ovejas y vacas, y siervos y siervas, y diólo á Abraham, y devolvióle á Sara su mujer.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, 'Y dijo Abimelech: He aquí mi tierra está delante de ti, habita donde bien te pareciere.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, 'Y á Sara dijo: He aquí he dado mil monedas de plata á tu hermano; mira que él te es por velo de ojos para todos los que están contigo, y para con todos: así fué reprendida.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, 'Entonces Abraham oró á Dios; y Dios sanó á Abimelech y á su mujer, y á sus siervas, y parieron.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'Porque había del todo cerrado Jehová toda matriz de la casa de Abimelech, á causa de Sara mujer de Abraham.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'Y VISITÓ Jehová á Sara, como había dicho, é hizo Jehová con Sara como había hablado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'Y concibió y parió Sara á Abraham un hijo en su vejez, en el tiempo que Dios le había dicho.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'Y llamó Abraham el nombre de su hijo que le nació, que le parió Sara, Isaac.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'Y circuncidó Abraham á su hijo Isaac de ocho días, como Dios le había mandado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'Y era Abraham de cien años, cuando le nació Isaac su hijo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, 'Entonces dijo Sara: Dios me ha hecho reir, y cualquiera que lo oyere, se reirá conmigo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, 'Y añadió: ¿Quién dijera á Abraham que Sara había de dar de mamar á hijos? pues que le he parido un hijo á su vejez.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, 'Y creció el niño, y fué destetado; é hizo Abraham gran banquete el día que fué destetado Isaac.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, 'Y vió Sara al hijo de Agar la Egipcia, el cual había ésta parido á Abraham, que se burlaba.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, 'Por tanto dijo á Abraham: Echa á esta sierva y á su hijo; que el hijo de esta sierva no ha de heredar con mi hijo, con Isaac.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, 'Este dicho pareció grave en gran manera á Abraham á causa de su hijo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, 'Entonces dijo Dios á Abraham: No te parezca grave á causa del muchacho y de tu sierva; en todo lo que te dijere Sara, oye su voz, porque en Isaac te será llamada descendencia.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, 'Y también al hijo de la sierva pondré en gente, porque es tu simiente.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'Entonces Abraham se levantó muy de mañana, y tomó pan, y un odre de agua, y diólo á Agar, poniéndolo sobre su hombro, y entrególe el muchacho, y despidióla. Y ella partió, y andaba errante por el desierto de Beer-seba.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, 'Y faltó el agua del odre, y echó al muchacho debajo de un árbol;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, 'Y fuése y sentóse enfrente, alejándose como un tiro de arco; porque decía: No veré cuando el muchacho morirá: y sentóse enfrente, y alzó su voz y lloró.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, 'Y oyó Dios la voz del muchacho; y el ángel de Dios llamó á Agar desde el cielo, y le dijo: ¿Qué tienes, Agar? No temas; porque Dios ha oído la voz del muchacho en donde está.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, 'Levántate, alza al muchacho, y ásele de tu mano, porque en gran gente lo tengo de poner.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, 'Entonces abrió Dios sus ojos, y vió una fuente de agua; y fué, y llenó el odre de agua, y dió de beber al muchacho.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, 'Y fué Dios con el muchacho; y creció, y habitó en el desierto, y fué tirador de arco.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'Y habitó en el desierto de Parán; y su madre le tomó mujer de la tierra de Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, 'Y aconteció en aquel mismo tiempo que habló Abimelech, y Phicol, príncipe de su ejército, á Abraham diciendo: Dios es contigo en todo cuanto haces:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, 'Ahora pues, júrame aquí por Dios, que no faltarás á mí, ni á mi hijo, ni á mi nieto; sino que conforme á la bondad que yo hice contigo, harás tú conmigo, y con la tierra donde has peregrinado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, 'Y respondió Abraham: Yo juraré.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, 'Y Abraham reconvino á Abimelech á causa de un pozo de agua, que los siervos de Abimelech le habían quitado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'Y respondió Abimelech: No sé quién haya hecho esto, ni tampoco tú me lo hiciste saber, ni yo lo he oído hasta hoy.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'Y tomó Abraham ovejas y vacas, y dió á Abimelech; é hicieron ambos alianza.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'Y puso Abraham siete corderas del rebaño aparte.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'Y dijo Abimelech á Abraham: ¿Qué significan esas siete corderas que has puesto aparte?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, 'Y él respondió: Que estas siete corderas tomarás de mi mano, para que me sean en testimonio de que yo cavé este pozo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, 'Por esto llamó á aquel lugar Beer-seba; porque allí juraron ambos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, 'Así hicieron alianza en Beer-seba: y levantóse Abimelech, y Phicol, príncipe de su ejército, y se volvieron á tierra de los Filisteos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, 'Y plantó Abraham un bosque en Beer-seba, é invocó allí el nombre de Jehová Dios eterno.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, 'Y moró Abraham en tierra de los Filisteos muchos días.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, 'Y ACONTECIÓ después de estas cosas, que tentó Dios á Abraham, y le dijo: Abraham. Y él respondió: Heme aquí.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'Y dijo: Toma ahora tu hijo, tu único, Isaac, á quien amas, y vete á tierra de Moriah, y ofrécelo allí en holocausto sobre uno de los montes que yo te diré.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'Y Abraham se levantó muy de mañana, y enalbardó su asno, y tomó consigo dos mozos suyos, y á Isaac su hijo: y cortó leña para el holocausto, y levantóse, y fué al lugar que Dios le dijo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, 'Al tercer día alzó Abraham sus ojos, y vió el lugar de lejos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, 'Entonces dijo Abraham á sus mozos: Esperaos aquí con el asno, y yo y el muchacho iremos hasta allí, y adoraremos, y volveremos á vosotros.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'Y tomó Abraham la leña del holocausto, y púsola sobre Isaac su hijo: y él tomó en su mano el fuego y el cuchillo; y fueron ambos juntos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'Entonces habló Isaac á Abraham su padre, y dijo: Padre mío. Y él respondió: Heme aquí, mi hijo. Y él dijo: He aquí el fuego y la leña; mas ¿dónde está el cordero para el holocausto?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, 'Y respondió Abraham: Dios se proveerá de cordero para el holocausto, hijo mío. E iban juntos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, 'Y como llegaron al lugar que Dios le había dicho, edificó allí Abraham un altar, y compuso la leña, y ató á Isaac su hijo, y púsole en el altar sobre la leña.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, 'Y extendió Abraham su mano, y tomó el cuchillo, para degollar á su hijo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, 'Entonces el ángel de Jehová le dió voces del cielo, y dijo: Abraham, Abraham. Y él respondió: Heme aquí.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, 'Y dijo: No extiendas tu mano sobre el muchacho, ni le hagas nada; que ya conozco que temes á Dios, pues que no me rehusaste tu hijo, tu único.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, 'Entonces alzó Abraham sus ojos, y miró, y he aquí un carnero á sus espaldas trabado en un zarzal por sus cuernos: y fué Abraham, y tomó el carnero, y ofrecióle en holocausto en lugar de su hijo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, 'Y llamó Abraham el nombre de aquel lugar, Jehová proveerá. Por tanto se dice hoy: En el monte de Jehová será provisto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'Y llamó el ángel de Jehová á Abraham segunda vez desde el cielo,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, 'Y dijo: Por mí mismo he jurado, dice Jehová, que por cuanto has hecho esto, y no me has rehusado tu hijo, tu único;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, 'Bendiciendo te bendeciré, y multiplicando multiplicaré tu simiente como las estrellas del cielo, y como la arena que está á la orilla del mar; y tu simiente poseerá las puertas de sus enemigos:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, 'En tu simiente serán benditas todas las gentes de la tierra, por cuanto obedeciste á mi voz.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, 'Y tornóse Abraham á sus mozos, y levantáronse y se fueron juntos á Beer-seba; y habitó Abraham en Beer-seba.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, 'Y aconteció después de estas cosas, que fué dada nueva á Abraham, diciendo: He aquí que también Milca ha parido hijos á Nachôr tu hermano:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, 'A Huz su primogénito, y á Buz su hermano, y á Kemuel padre de Aram,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, 'Y á Chêsed, y á Hazo, y á Pildas, y á Jidlaph, y á Bethuel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, 'Y Bethuel engendró á Rebeca. Estos ocho parió Milca á Nachôr, hermano de Abraham.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'Y su concubina, que se llamaba Reúma, parió también á Teba, y á Gaham, y á Taas, y á Maachâ.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, 'Y FUÉ la vida de Sara ciento veintisiete años: tantos fueron los años de la vida de Sara.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'Y murió Sara en Kiriath-arba, que es Hebrón, en la tierra de Canaán: y vino Abraham á hacer el duelo á Sara, y á llorarla.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, 'Y levantóse Abraham de delante de su muerto, y habló á los hijos de Heth, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, 'Peregrino y advenedizo soy entre vosotros; dadme heredad de sepultura con vosotros, y sepultaré mi muerto de delante de mí.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'Y respondieron los hijos de Heth á Abraham, y dijéronle:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, 'Oyenos, señor mío, eres un príncipe de Dios entre nosotros; en lo mejor de nuestras sepulturas sepulta á tu muerto; ninguno de nosotros te impedirá su sepultura, para que entierres tu muerto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, 'Y Abraham se levantó, é inclinóse al pueblo de aquella tierra, á los hijos de Heth;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, 'Y habló con ellos, diciendo: Si tenéis voluntad que yo sepulte mi muerto de delante de mí, oidme, é interceded por mí con Ephrón, hijo de Zohar,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, 'Para que me dé la cueva de Macpela, que tiene al cabo de su heredad: que por su justo precio me la dé, para posesión de sepultura en medio de vosotros.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, 'Este Ephrón hallábase entre los hijos de Heth: y respondió Ephrón Hetheo á Abraham, en oídos de los hijos de Heth, de todos los que entraban por la puerta de su ciudad, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, 'No, señor mío, óyeme: te doy la heredad, y te doy también la cueva que está en ella; delante de los hijos de mi pueblo te la doy; sepulta tu muerto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, 'Y Abraham se inclinó delante del pueblo de la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, 'Y respondió á Ephrón en oídos del pueblo de la tierra, diciendo: Antes, si te place, ruégote que me oigas; yo daré el precio de la heredad, tómalo de mí, y sepultaré en ella mi muerto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'Y respondió Ephrón á Abraham, diciéndole:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, 'Señor mío, escúchame: la tierra vale cuatrocientos siclos de plata: ¿qué es esto entre mí y ti? entierra pues tu muerto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'Entonces Abraham se convino con Ephrón, y pesó Abraham á Ephrón el dinero que dijo, oyéndolo los hijos de Heth, cuatrocientos siclos de plata, de buena ley entre mercaderes.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'Y quedó la heredad de Ephrón que estaba en Macpela enfrente de Mamre, la heredad y la cueva que estaba en ella, y todos los árboles que había en la heredad, y en todo su término al derredor,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, 'Por de Abraham en posesión, á vista de los hijos de Heth, y de todos los que entraban por la puerta de la ciudad.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, 'Y después de esto sepultó Abraham á Sara su mujer en la cueva de la heredad de Macpela enfrente de Mamre, que es Hebrón en la tierra de Canaán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, 'Y quedó la heredad y la cueva que en ella había, por de Abraham, en posesión de sepultura adquirida de los hijos de Heth.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, 'Y ABRAHAM era viejo, y bien entrado en días; y Jehová había bendecido á Abraham en todo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, 'Y dijo Abraham á un criado suyo, el más viejo de su casa, que era el que gobernaba en todo lo que tenía: Pon ahora tu mano debajo de mi muslo,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, 'Y te juramentaré por Jehová, Dios de los cielos y Dios de la tierra, que no has de tomar mujer para mi hijo de las hijas de los Cananeos, entre los cuales yo habito;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, 'Sino que irás á mi tierra y á mi parentela, y tomarás mujer para mi hijo Isaac.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, 'Y el criado le respondió: Quizá la mujer no querrá venir en pos de mí á esta tierra: ¿volveré, pues, tu hijo á la tierra de donde saliste?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, 'Y Abraham le dijo: Guárdate que no vuelvas á mi hijo allá.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, 'Jehová, Dios de los cielos, que me tomó de la casa de mi padre y de la tierra de mi parentela, y me habló y me juró, diciendo: A tu simiente daré esta tierra; él enviará su ángel delante de ti, y tú tomarás de allá mujer para mi hijo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, 'Y si la mujer no quisiere venir en pos de ti, serás libre de este mi juramento; solamente que no vuelvas allá á mi hijo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, 'Entonces el criado puso su mano debajo del muslo de Abraham su señor, y juróle sobre este negocio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, 'Y el criado tomó diez camellos de los camellos de su señor, y fuése, pues tenía á su disposición todos los bienes de su señor: y puesto en camino, llegó á Mesopotamia, á la ciudad de Nachôr.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, 'E hizo arrodillar los camellos fuera de la ciudad, junto á un pozo de agua, á la hora de la tarde, á la hora en que salen las mozas por agua.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, 'Y dijo: Jehová, Dios de mi señor Abraham, dame, te ruego, el tener hoy buen encuentro, y haz misericordia con mi señor Abraham.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, 'He aquí yo estoy junto á la fuente de agua, y las hijas de los varones de esta ciudad salen por agua:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, 'Sea, pues, que la moza á quien yo dijere: Baja tu cántaro, te ruego, para que yo beba; y ella respondiere: Bebe, y también daré de beber á tus camellos: que sea ésta la que tú has destinado para tu siervo Isaac; y en esto conoceré que habrás hecho misericordia con mi señor.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, 'Y aconteció que antes que él acabase de hablar, he aquí Rebeca, que había nacido á Bethuel, hijo de Milca, mujer de Nachôr hermano de Abraham, la cual salía con su cántaro sobre su hombro.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, 'Y la moza era de muy hermoso aspecto, virgen, á la que varón no había conocido; la cual descendió á la fuente, y llenó su cántaro, y se volvía.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, 'Entonces el criado corrió hacia ella, y dijo: Ruégote que me des á beber un poco de agua de tu cántaro.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, 'Y ella respondió: Bebe, señor mío: y dióse prisa á bajar su cántaro sobre su mano, y le dió á beber.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, 'Y cuando acabó de darle á beber, dijo: También para tus camellos sacaré agua, hasta que acaben de beber.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, 'Y dióse prisa, y vació su cántaro en la pila, y corrió otra vez al pozo para sacar agua, y sacó para todos sus camellos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, 'Y el hombre estaba maravillado de ella, callando, para saber si Jehová había prosperado ó no su viaje.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, 'Y fué que como los camellos acabaron de beber, presentóle el hombre un pendiente de oro que pesaba medio siclo, y dos brazaletes que pesaban diez:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, 'Y dijo: ¿De quién eres hija? Ruégote me digas, ¿hay lugar en casa de tu padre donde posemos?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, 'Y ella respondió: Soy hija de Bethuel, hijo de Milca, el cual parió ella á Nachôr.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, 'Y añadió: También hay en nuestra casa paja y mucho forraje, y lugar para posar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, 'El hombre entonces se inclinó, y adoró á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, 'Y dijo: Bendito sea Jehová, Dios de mi amo Abraham, que no apartó su misericordia y su verdad de mi amo, guiándome Jehová en el camino á casa de los hermanos de mi amo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, 'Y la moza corrió, é hizo saber en casa de su madre estas cosas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'Y Rebeca tenía un hermano que se llamaba Labán, el cual corrió afuera al hombre, á la fuente;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'Y fué que como vió el pendiente y los brazaletes en las manos de su hermana, que decía, Así me habló aquel hombre; vino á él: y he aquí que estaba junto á los camellos á la fuente.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, 'Y díjole: Ven, bendito de Jehová; ¿por qué estás fuera? yo he limpiado la casa, y el lugar para los camellos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, 'Entonces el hombre vino á casa, y Labán desató los camellos; y dióles paja y forraje, y agua para lavar los piés de él, y los piés de los hombres que con él venían.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, 'Y pusiéronle delante qué comer; mas él dijo: No comeré hasta que haya dicho mi mensaje. Y él le dijo: Habla.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, 'Entonces dijo: Yo soy criado de Abraham;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, 'Y Jehová ha bendecido mucho á mi amo, y él se ha engrandecido: y le ha dado ovejas y vacas, plata y oro, siervos y siervas, camellos y asnos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'Y Sara, mujer de mi amo, parió en su vejez un hijo á mi señor, quien le ha dado todo cuanto tiene.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'Y mi amo me hizo jurar, diciendo: No tomarás mujer para mi hijo de las hijas de los Cananeos, en cuya tierra habito;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, 'Sino que irás á la casa de mi padre, y á mi parentela, y tomarás mujer para mi hijo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, 'Y yo dije: Quizás la mujer no querrá seguirme.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, 'Entonces él me respondió: Jehová, en cuya presencia he andado, enviará su ángel contigo, y prosperará tu camino; y tomarás mujer para mi hijo de mi linaje y de la casa de mi padre:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, 'Entonces serás libre de mi juramento, cuando hubieres llegado á mi linaje; y si no te la dieren, serás libre de mi juramento.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, 'Llegué, pues, hoy á la fuente, y dije: Jehová, Dios de mi señor Abraham, si tú prosperas ahora mi camino por el cual ando;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, 'He aquí yo estoy junto á la fuente de agua; sea, pues, que la doncella que saliere por agua, á la cual dijere: Dame á beber, te ruego, un poco de agua de tu cántaro;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, 'Y ella me respondiere, Bebe tú, y también para tus camellos sacaré agua: ésta sea la mujer que destinó Jehová para el hijo de mi señor.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, 'Y antes que acabase de hablar en mi corazón, he aquí Rebeca, que salía con su cántaro sobre su hombro; y descendió á la fuente, y sacó agua; y le dije: Ruégote que me des á beber.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, 'Y prestamente bajó su cántaro de encima de sí, y dijo: Bebe, y también á tus camellos daré á beber. Y bebí, y dió también de beber á mis camellos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, 'Entonces preguntéle, y dije: ¿De quién eres hija? Y ella respondió: Hija de Bethuel, hijo de Nachôr, que le parió Milca. Entonces púsele un pendiente sobre su nariz, y brazaletes sobre sus manos:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, 'E inclinéme, y adoré á Jehová, y bendije á Jehová, Dios de mi señor Abraham, que me había guiado por camino de verdad para tomar la hija del hermano de mi señor para su hijo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'Ahora pues, si vosotros hacéis misericordia y verdad con mi señor, declarádmelo; y si no, declarádmelo; y echaré á la diestra ó á la siniestra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'Entonces Labán y Bethuel respondieron y dijeron: De Jehová ha salido esto; no podemos hablarte malo ni bueno.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, 'He ahí Rebeca delante de ti; tómala y vete, y sea mujer del hijo de tu señor, como lo ha dicho Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'Y fué, que como el criado de Abraham oyó sus palabras, inclinóse á tierra á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, 'Y sacó el criado vasos de plata, y vasos de oro y vestidos, y dió á Rebeca: también dió cosas preciosas á su hermano y á su madre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, 'Y comieron y bebieron él y los varones que venían con él, y durmieron; y levantándose de mañana, dijo: Enviadme á mi señor.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'Entonces respondió su hermano y su madre: Espere la moza con nosotros á lo menos diez días, y después irá.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, 'Y él les dijo: No me detengáis, pues que Jehová ha prosperado mi camino; despachadme para que me vaya á mi señor.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, 'Ellos respondieron entonces: Llamemos la moza y preguntémosle.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, 'Y llamaron á Rebeca, y dijéronle: ¿Irás tú con este varón? Y ella respondió: Sí, iré.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, 'Entonces dejaron ir á Rebeca su hermana, y á su nodriza, y al criado de Abraham y á sus hombres.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, 'Y bendijeron á Rebeca, y dijéronle: Nuestra hermana eres; seas en millares de millares, y tu generación posea la puerta de sus enemigos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, 'Levantóse entonces Rebeca y sus mozas, y subieron sobre los camellos, y siguieron al hombre; y el criado tomó á Rebeca, y fuése.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, 'Y venía Isaac del pozo del Viviente que me ve; porque él habitaba en la tierra del Mediodía;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'Y había salido Isaac á orar al campo, á la hora de la tarde; y alzando sus ojos miró, y he aquí los camellos que venían.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'Rebeca también alzó sus ojos, y vió á Isaac, y descendió del camello;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, 'Porque había preguntado al criado: ¿Quién es este varón que viene por el campo hacia nosotros? Y el siervo había respondido: Este es mi señor. Ella entonces tomó el velo, y cubrióse.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, 'Entonces el criado contó á Isaac todo lo que había hecho.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'E introdújola Isaac á la tienda de su madre Sara, y tomó á Rebeca por mujer; y amóla: y consolóse Isaac después de la muerte de su madre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, 'Y ABRAHAM tomó otra mujer, cuyo nombre fué Cetura;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, 'La cual le parió á Zimram, y á Joksan, y á Medan, y á Midiam, y á Ishbak, y á Sua.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, 'Y Joksan engendró á Seba, y á Dedán: é hijos de Dedán fueron Assurim, y Letusim, y Leummim.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, 'E hijos de Midiam: Epha, y Epher, y Enech, y Abida, y Eldaa. Todos estos fueron hijos de Cetura.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'Y Abraham dió todo cuanto tenía á Isaac.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'Y á los hijos de sus concubinas dió Abraham dones, y enviólos de junto Isaac su hijo, mientras él vivía, hacia el oriente, á la tierra oriental.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, 'Y estos fueron los días de vida que vivió Abraham: ciento setenta y cinco años.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'Y exhaló el espíritu, y murió Abraham en buena vejez, anciano y lleno de días, y fué unido á su pueblo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, 'Y sepultáronlo Isaac é Ismael sus hijos en la cueva de Macpela, en la heredad de Ephrón, hijo de Zoar Hetheo, que está enfrente de Mamre;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, 'Heredad que compró Abraham de los hijos de Heth; allí fué Abraham sepultado, y Sara su mujer.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'Y sucedió, después de muerto Abraham, que Dios bendijo á Isaac su hijo: y habitó Isaac junto al pozo del Viviente que me ve.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, 'Y estas son las generaciones de Ismael, hijo de Abraham, que le parió Agar Egipcia, sierva de Sara:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'Estos, pues, son los nombres de los hijos de Ismael, por sus nombres, por sus linajes: El primogénito de Ismael, Nabaioth; luego Cedar, y Abdeel, y Mibsam,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'Y Misma, y Duma, y Massa,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'Hadad, y Tema, y Jetur, y Naphis, y Cedema.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, 'Estos son los hijos de Ismael, y estos sus nombres, por sus villas y por sus campamentos; doce príncipes por sus familias.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, 'Y estos fueron los años de la vida de Ismael, ciento treinta y siete años: y exhaló el espíritu Ismael, y murió; y fué unido á su pueblo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, 'Y habitaron desde Havila hasta Shur, que está enfrente de Egipto viniendo á Asiria; y murió en presencia de todos sus hermanos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'Y estas son las generaciones de Isaac, hijo de Abraham. Abraham engendró á Isaac:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'Y era Isaac de cuarenta años cuando tomó por mujer á Rebeca, hija de Bethuel Arameo de Padan-aram, hermana de Labán Arameo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'Y oró Isaac á Jehová por su mujer, que era estéril; y aceptólo Jehová, y concibió Rebeca su mujer.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'Y los hijos se combatían dentro de ella; y dijo: Si es así ¿para qué vivo yo? Y fué á consultar á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'Y respondióle Jehová: Dos gentes hay en tu seno, y dos pueblos serán divididos desde tus entrañas: y el un pueblo será más fuerte que el otro pueblo, y el mayor servirá al menor.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'Y como se cumplieron sus días para parir, he aquí mellizos en su vientre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'Y salió el primero rubio, y todo él velludo como una pelliza; y llamaron su nombre Esaú.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'Y después salió su hermano, trabada su mano al calcañar de Esaú: y fué llamado su nombre Jacob. Y era Isaac de edad de sesenta años cuando ella los parió.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'Y crecieron los niños, y Esaú fué diestro en la caza, hombre del campo: Jacob empero era varón quieto, que habitaba en tiendas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'Y amó Isaac á Esaú, porque comía de su caza; mas Rebeca amaba á Jacob.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, 'Y guisó Jacob un potaje; y volviendo Esaú del campo cansado,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'Dijo á Jacob: Ruégote que me des á comer de eso bermejo, pues estoy muy cansado. Por tanto fué llamado su nombre Edom.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'Y Jacob respondió: Véndeme en este día tu primogenitura.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, 'Entonces dijo Esaú: He aquí yo me voy á morir; ¿para qué, pues, me servirá la primogenitura?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, 'Y dijo Jacob: Júrame lo en este día. Y él le juró, y vendió á Jacob su primogenitura.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, 'Entonces Jacob dió á Esaú pan y del guisado de las lentejas; y él comió y bebió, y levantóse, y fuése. Así menospreció Esaú la primogenitura.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'Y HUBO hambre en la tierra, además de la primera hambre que fué en los días de Abraham: y fuése Isaac á Abimelech rey de los Filisteos, en Gerar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'Y apareciósele Jehová, y díjole: No desciendas á Egipto: habita en la tierra que yo te diré;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'Habita en esta tierra, y seré contigo, y te bendeciré; porque á ti y á tu simiente daré todas estas tierras, y confirmaré el juramento que juré á Abraham tu padre:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'Y multiplicaré tu simiente como las estrellas del cielo, y daré á tu simiente todas estas tierras; y todas las gentes de la tierra serán benditas en tu simiente:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, 'Por cuanto oyó Abraham mi voz, y guardó mi precepto, mis mandamientos, mis estatutos y mis leyes.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'Habitó, pues, Isaac en Gerar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, 'Y los hombres de aquel lugar le preguntaron acerca de su mujer; y él respondió: Es mi hermana; porque tuvo miedo de decir: Es mi mujer; que tal vez, dijo, los hombres del lugar me matarían por causa de Rebeca; porque era de hermoso aspecto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'Y sucedió que, después que él estuvo allí muchos días, Abimelech, rey de los Filisteos, mirando por una ventana, vió á Isaac que jugaba con Rebeca su mujer.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'Y llamó Abimelech á Isaac, y dijo: He aquí ella es de cierto tu mujer: ¿cómo, pues, dijiste: Es mi hermana? E Isaac le respondió: Porque dije: Quizá moriré por causa de ella.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'Y Abimelech dijo: ¿Por qué nos has hecho esto? Por poco hubiera dormido alguno del pueblo con tu mujer, y hubieras traído sobre nosotros el pecado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'Entonces Abimelech mandó á todo el pueblo, diciendo: El que tocare á este hombre ó á su mujer, de cierto morirá.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, 'Y sembró Isaac en aquella tierra, y halló aquel año ciento por uno: y bendíjole Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, 'Y el varón se engrandeció, y fué adelantando y engrandeciéndose, hasta hacerse muy poderoso:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, 'Y tuvo hato de ovejas, y hato de vacas, y grande apero; y los Filisteos le tuvieron envidia.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, 'Y todos los pozos que habían abierto los criados de Abraham su padre en sus días, los Filisteos los habían cegado y llenado de tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, 'Y dijo Abimelech á Isaac: Apártate de nosotros, porque mucho más poderoso que nosotros te has hecho.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, 'E Isaac se fué de allí; y asentó sus tiendas en el valle de Gerar, y habitó allí.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, 'Y volvió á abrir Isaac los pozos de agua que habían abierto en los días de Abraham su padre, y que los Filisteos habían cegado, muerto Abraham; y llamólos por los nombres que su padre los había llamado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, 'Y los siervos de Isaac cavaron en el valle, y hallaron allí un pozo de aguas vivas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'Y los pastores de Gerar riñeron con los pastores de Isaac, diciendo: El agua es nuestra: por eso llamó el nombre del pozo Esek, porque habían altercado con él.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, 'Y abrieron otro pozo, y también riñeron sobre él: y llamó su nombre Sitnah.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, 'Y apartóse de allí, y abrió otro pozo, y no riñeron sobre él: y llamó su nombre Rehoboth, y dijo: Porque ahora nos ha hecho ensanchar Jehová, y fructificaremos en la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, 'Y de allí subió á Beer-seba.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, 'Y apareciósele Jehová aquella noche, y dijo: Yo soy el Dios de Abraham tu padre; no temas, que yo soy contigo, y yo te bendeciré, y multiplicaré tu simiente por amor de Abraham mi siervo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, 'Y edificó allí un altar, é invocó el nombre de Jehová, y tendió allí su tienda: y abrieron allí los siervos de Isaac un pozo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, 'Y Abimelech vino á él desde Gerar, y Ahuzzath, amigo suyo, y Phicol, capitán de su ejército.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'Y díjoles Isaac: ¿Por qué venís á mí, pues que me habéis aborrecido, y me echasteis de entre vosotros?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, 'Y ellos respondieron: Hemos visto que Jehová es contigo; y dijimos: Haya ahora juramento entre nosotros, entre nosotros y ti, y haremos alianza contigo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, 'Que no nos hagas mal, como nosotros no te hemos tocado, y como solamente te hemos hecho bien, y te enviamos en paz: tú ahora, bendito de Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'Entonces él les hizo banquete, y comieron y bebieron.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, 'Y se levantaron de madrugada, y juraron el uno al otro; é Isaac los despidió, y ellos se partieron de él en paz.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, 'Y en aquel día sucedió que vinieron los criados de Isaac, y diéronle nuevas acerca del pozo que habían abierto, y le dijeron: Agua hemos hallado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, 'Y llamólo Seba: por cuya causa el nombre de aquella ciudad es Beer-seba hasta este día.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, 'Y cuando Esaú fué de cuarenta años, tomó por mujer á Judith hija de Beeri Hetheo, y á Basemat hija de Elón Hetheo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, 'Y fueron amargura de espíritu á Isaac y á Rebeca.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, 'Y ACONTECIÓ que cuando hubo Isaac envejecido, y sus ojos se ofuscaron quedando sin vista, llamó á Esaú, su hijo el mayor, y díjole: Mi hijo. Y él respondió: Heme aquí.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'Y él dijo: He aquí ya soy viejo, no sé el día de mi muerte:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, 'Toma, pues, ahora tus armas, tu aljaba y tu arco, y sal al campo, y cógeme caza;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'Y hazme un guisado, como yo gusto, y tráeme lo, y comeré; para que te bendiga mi alma antes que muera.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, 'Y Rebeca estaba oyendo, cuando hablaba Isaac á Esaú su hijo: y fuése Esaú al campo para coger la caza que había de traer.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, 'Entonces Rebeca habló á Jacob su hijo, diciendo: He aquí yo he oído á tu padre que hablaba con Esaú tu hermano, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, 'Tráeme caza, y hazme un guisado, para que coma, y te bendiga delante de Jehová antes que yo muera.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, 'Ahora pues, hijo mío, obedece á mi voz en lo que te mando;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, 'Ve ahora al ganado, y tráeme de allí dos buenos cabritos de las cabras, y haré de ellos viandas para tu padre, como él gusta;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, 'Y tú las llevarás á tu padre, y comerá, para que te bendiga antes de su muerte.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'Y Jacob dijo á Rebeca su madre: He aquí, Esaú mi hermano es hombre velloso, y yo lampiño:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, 'Quizá me tentará mi padre, y me tendrá por burlador, y traeré sobre mí maldición y no bendición.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, 'Y su madre respondió: Hijo mío, sobre mí tu maldición: solamente obedece á mi voz, y ve y tráemelos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, 'Entonces él fué, y tomó, y trájolos á su madre: y su madre hizo guisados, como su padre gustaba.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, 'Y tomó Rebeca los vestidos de Esaú su hijo mayor, los preciosos, que ella tenía en casa, y vistió á Jacob su hijo menor:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, 'E hízole vestir sobre sus manos, y sobre la cerviz donde no tenía vello, las pieles de los cabritos de las cabras;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, 'Y entregó los guisados y el pan que había aderezado, en mano de Jacob su hijo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, 'Y él fué á su padre, y dijo: Padre mío: y él respondió: Heme aquí, ¿quién eres, hijo mío?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, 'Y Jacob dijo á su padre: Yo soy Esaú tu primogénito; he hecho como me dijiste: levántate ahora, y siéntate, y come de mi caza, para que me bendiga tu alma.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'Entonces Isaac dijo á su hijo: ¿Cómo es que la hallaste tan presto, hijo mío? Y él respondió: Porque Jehová tu Dios hizo que se encontrase delante de mí.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'E Isaac dijo á Jacob: Acércate ahora, y te palparé, hijo mío, por si eres mi hijo Esaú, ó no.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'Y llegóse Jacob á su padre Isaac; y él le palpó, y dijo: La voz es la voz de Jacob, mas las manos, las manos de Esaú.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, 'Y no le conoció, porque sus manos eran vellosas como las manos de Esaú: y le bendijo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, 'Y dijo: ¿Eres tú mi hijo Esaú? Y él respondió: Yo soy.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, 'Y dijo: Acércamela, y comeré de la caza de mi hijo, para que te bendiga mi alma; y él se la acercó, y comió: trájole también vino, y bebió.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'Y díjole Isaac su padre: Acércate ahora, y bésame, hijo mío.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, 'Y él se llegó, y le besó; y olió Isaac el olor de sus vestidos, y le bendijo, y dijo: Mira, el olor de mi hijo como el olor del campo que Jehová ha bendecido:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, 'Dios, pues, te dé del rocío del cielo, y de las grosuras de la tierra, y abundancia de trigo y de mosto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, 'Sírvante pueblos, y naciones se inclinen á ti: sé señor de tus hermanos, e inclínense á ti los hijos de tu madre: malditos los que te maldijeren, y benditos los que te bendijeren.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'Y aconteció, luego que hubo Isaac acabado de bendecir á Jacob, y apenas había salido Jacob de delante de Isaac su padre, que Esaú su hermano vino de su caza.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, 'E hizo él también guisados, y trajo á su padre, y díjole: Levántese mi padre, y coma de la caza de su hijo, para que me bendiga tu alma.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, 'Entonces Isaac su padre le dijo: ¿Quién eres tú? Y él dijo: Yo soy tu hijo, tu primogénito, Esaú.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, 'Y estremecióse Isaac con grande estremecimiento, y dijo: ¿Quién es el que vino aquí, que cogió caza, y me trajo, y comí de todo antes que vinieses? Yo le bendije, y será bendito.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'Como Esaú oyó las palabras de su padre, clamó con una muy grande y muy amarga exclamación, y le dijo: Bendíceme también á mí, padre mío.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'Y él dijo: Vino tu hermano con engaño, y tomó tu bendición.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, 'Y él respondió: Bien llamaron su nombre Jacob, que ya me ha engañado dos veces; alzóse con mi primogenitura, y he aquí ahora ha tomado mi bendición. Y dijo: ¿No has guardado bendición para mí?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'Isaac respondió y dijo á Esaú: He aquí yo le he puesto por señor tuyo, y le he dado por siervos á todos sus hermanos: de trigo y de vino le he provisto: ¿qué, pues, te haré á ti ahora, hijo mío?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'Y Esaú respondió á su padre: ¿No tienes más que una sola bendición, padre mío? bendíceme también á mí, padre mío. Y alzó Esaú su voz, y lloró.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, 'Entonces Isaac su padre habló y díjole: He aquí será tu habitación en grosuras de la tierra, y del rocío de los cielos de arriba;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, 'Y por tu espada vivirás, y á tu hermano servirás: y sucederá cuando te enseñorees, que descargarás su yugo de tu cerviz.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, 'Y aborreció Esaú á Jacob por la bendición con que le había bendecido, y dijo en su corazón: Llegarán los días del luto de mi padre, y yo mataré á Jacob mi hermano.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, 'Y fueron dichas á Rebeca las palabras de Esaú su hijo mayor: y ella envió y llamó á Jacob su hijo menor, y díjole: He aquí, Esaú tu hermano se consuela acerca de ti con la idea de matarte.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'Ahora pues, hijo mío, obedece á mi voz; levántate, y húyete á Labán mi hermano, á Harán;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, 'Y mora con él algunos días, hasta que el enojo de tu hermano se mitigue;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, 'Hasta que se aplaque la ira de tu hermano contra ti, y se olvide de lo que le has hecho: yo enviaré entonces, y te traeré de allá: ¿por qué seré privada de vosotros ambos en un día?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'Y dijo Rebeca á Isaac: Fastidio tengo de mi vida, á causa de las hijas de Heth. Si Jacob toma mujer de las hijas de Heth, como éstas, de las hijas de esta tierra, ¿para qué quiero la vida?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'ENTONCES Isaac llamó á Jacob, y bendíjolo, y mandóle diciendo: No tomes mujer de las hijas de Canaán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, 'Levántate, ve á Padan-aram, á casa de Bethuel, padre de tu madre, y toma allí mujer de las hijas de Labán, hermano de tu madre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, 'Y el Dios omnipotente te bendiga, y te haga fructificar, y te multiplique, hasta venir á ser congregación de pueblos;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, 'Y te dé la bendición de Abraham, y á tu simiente contigo, para que heredes la tierra de tus peregrinaciones, que Dios dió á Abraham.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, 'Así envió Isaac á Jacob, el cual fué á Padan-aram, á Labán, hijo de Bethuel Arameo, hermano de Rebeca, madre de Jacob y de Esaú.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'Y vió Esaú cómo Isaac había bendecido á Jacob, y le había enviado á Padan-aram, para tomar para sí mujer de allí; y que cuando le bendijo, le había mandado, diciendo: No tomarás mujer de las hijas de Canaán;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, 'Y que Jacob había obedecido á su padre y á su madre, y se había ido á Padan-aram.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'Vió asimismo Esaú que las hijas de Canaán parecían mal á Isaac su padre;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, 'Y fuése Esaú á Ismael, y tomó para sí por mujer á Mahaleth, hija de Ismael, hijo de Abraham, hermana de Nabaioth, además de sus otras mujeres.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, 'Y salió Jacob de Beer-seba, y fué á Harán;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, 'Y encontró con un lugar, y durmió allí, porque ya el sol se había puesto: y tomó de las piedras de aquel paraje y puso á su cabecera, y acostóse en aquel lugar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, 'Y soñó, y he aquí una escala que estaba apoyada en tierra, y su cabeza tocaba en el cielo: y he aquí ángeles de Dios que subían y descendían por ella.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'Y he aquí, Jehová estaba en lo alto de ella, el cual dijo: Yo soy Jehová, el Dios de Abraham tu padre, y el Dios de Isaac: la tierra en que estás acostado te la daré á ti y á tu simiente.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, 'Y será tu simiente como el polvo de la tierra, y te extenderás al occidente, y al oriente, y al aquilón, y al mediodía; y todas las familias de la tierra serán benditas en ti y en tu simiente.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'Y he aquí, yo soy contigo, y te guardaré por donde quiera que fueres, y te volveré á esta tierra; porque no te dejaré hasta tanto que haya hecho lo que te he dicho.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'Y despertó Jacob de su sueño, y dijo: Ciertamente Jehová está en este lugar, y yo no lo sabía.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, 'Y tuvo miedo, y dijo: ¡Cuán terrible es este lugar! No es otra cosa que casa de Dios, y puerta del cielo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'Y levantóse Jacob de mañana, y tomó la piedra que había puesto de cabecera, y alzóla por título, y derramó aceite encima de ella.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, 'Y llamó el nombre de aquel lugar Beth-el, bien que Luz era el nombre de la ciudad primero.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, 'E hizo Jacob voto, diciendo: Si fuere Dios conmigo, y me guardare en este viaje que voy, y me diere pan para comer y vestido para vestir,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, 'Y si tornare en paz á casa de mi padre, Jehová será mi Dios,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, 'Y esta piedra que he puesto por título, será casa de Dios: y de todo lo que me dieres, el diezmo lo he de apartar para ti.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, 'Y SIGUIÓ Jacob su camino, y fué á la tierra de los orientales.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'Y miró, y vió un pozo en el campo: y he aquí tres rebaños de ovejas que yacían cerca de él; porque de aquel pozo abrevaban los ganados: y había una gran piedra sobre la boca del pozo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'Y juntábanse allí todos los rebaños; y revolvían la piedra de sobre la boca del pozo, y abrevaban las ovejas; y volvían la piedra sobre la boca del pozo á su lugar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'Y díjoles Jacob: Hermanos míos, ¿de dónde sois? Y ellos respondieron: De Harán somos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'Y él les dijo: ¿Conocéis á Labán, hijo de Nachôr? Y ellos dijeron: Sí, le conocemos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, 'Y él les dijo: ¿Tiene paz? Y ellos dijeron: Paz; y he aquí Rachêl su hija viene con el ganado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, 'Y él dijo: He aquí el día es aún grande; no es tiempo todavía de recoger el ganado; abrevad las ovejas, é id á apacentarlas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, 'Y ellos respondieron: No podemos, hasta que se junten todos los ganados, y remuevan la piedra de sobre la boca del pozo, para que abrevemos las ovejas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'Estando aún él hablando con ellos, Rachêl vino con el ganado de su padre, porque ella era la pastora.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'Y sucedió que, como Jacob vió á Rachêl, hija de Labán hermano de su madre, y á las ovejas de Labán el hermano de su madre, llegóse Jacob, y removió la piedra de sobre la boca del pozo, y abrevó el ganado de Labán hermano de su madre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, 'Y Jacob besó á Rachêl, y alzó su voz, y lloró.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, 'Y Jacob dijo á Rachêl como él era hermano de su padre, y como era hijo de Rebeca: y ella corrió, y dió las nuevas á su padre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'Y así que oyó Labán las nuevas de Jacob, hijo de su hermana, corrió á recibirlo, y abrazólo, y besólo, y trájole á su casa: y él contó á Labán todas estas cosas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'Y Labán le dijo: Ciertamente hueso mío y carne mía eres. Y estuvo con él el tiempo de un mes.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, 'Entonces dijo Labán á Jacob: ¿Por ser tú mi hermano, me has de servir de balde? declárame qué será tu salario.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, 'Y Labán tenía dos hijas: el nombre de la mayor era Lea, y el nombre de la menor, Rachêl.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'Y los ojos de Lea eran tiernos, pero Rachêl era de lindo semblante y de hermoso parecer.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'Y Jacob amó á Rachêl, y dijo: Yo te serviré siete años por Rachêl tu hija menor.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'Y Labán respondió: Mejor es que te la dé á ti, que no que la dé á otro hombre: estáte conmigo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'Así sirvió Jacob por Rachêl siete años: y pareciéronle como pocos días, porque la amaba.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, 'Y dijo Jacob á Labán: Dame mi mujer, porque mi tiempo es cumplido, para que cohabite con ella.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, 'Entonces Labán juntó á todos los varones de aquel lugar, é hizo banquete.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, 'Y sucedió que á la noche tomó á Lea su hija, y se la trajo: y él entró á ella.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'Y dió Labán su sierva Zilpa á su hija Lea por criada.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, 'Y venida la mañana, he aquí que era Lea: y él dijo á Labán: ¿Qué es esto que me has hecho? ¿no te he servido por Rachêl? ¿por qué, pues, me has engañado?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, 'Y Labán respondió: No se hace así en nuestro lugar, que se dé la menor antes de la mayor.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, 'Cumple la semana de ésta, y se te dará también la otra, por el servicio que hicieres conmigo otros siete años.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'E hizo Jacob así, y cumplió la semana de aquélla: y él le dió á Rachêl su hija por mujer.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'Y dió Labán á Rachêl su hija por criada á su sierva Bilha.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'Y entró también á Rachêl: y amóla también más que á Lea: y sirvió con él aún otros siete años.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, 'Y vió Jehová que Lea era aborrecida, y abrió su matriz: pero Rachêl era estéril.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'Y concibió Lea, y parió un hijo, y llamó su nombre Rubén, porque dijo: Ya que ha mirado Jehová mi aflicción; ahora por tanto me amará mi marido.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, 'Y concibió otra vez, y parió un hijo, y dijo: Por cuanto oyó Jehová que yo era aborrecida, me ha dado también éste. Y llamó su nombre Simeón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, 'Y concibió otra vez, y parió un hijo, y dijo: Ahora esta vez se unirá mi marido conmigo, porque le he parido tres hijos: por tanto, llamó su nombre Leví.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, 'Y concibió otra vez, y parió un hijo, y dijo: Esta vez alabaré á Jehová: por esto llamó su nombre Judá: y dejó de parir.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'Y VIENDO Rachêl que no daba hijos á Jacob, tuvo envidia de su hermana, y decía á Jacob: Dame hijos, ó si no, me muero.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'Y Jacob se enojaba contra Rachêl, y decía: ¿Soy yo en lugar de Dios, que te impidió el fruto de tu vientre?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'Y ella dijo: He aquí mi sierva Bilha; entra á ella, y parirá sobre mis rodillas, y yo también tendré hijos de ella.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, 'Así le dió á Bilha su sierva por mujer; y Jacob entró á ella.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'Y concibió Bilha, y parió á Jacob un hijo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'Y dijo Rachêl: Juzgóme Dios, y también oyó mi voz, y dióme un hijo. Por tanto llamó su nombre Dan.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'Y concibió otra vez Bilha, la sierva de Rachêl, y parió el hijo segundo á Jacob.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'Y dijo Rachêl: Con luchas de Dios he contendido con mi hermana, y he vencido. Y llamó su nombre Nephtalí.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, 'Y viendo Lea que había dejado de parir, tomó á Zilpa su sierva, y dióla á Jacob por mujer.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'Y Zilpa, sierva de Lea, parió á Jacob un hijo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, 'Y dijo Lea: Vino la ventura. Y llamó su nombre Gad.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'Y Zilpa, la sierva de Lea, parió otro hijo á Jacob.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'Y dijo Lea: Para dicha mía; porque las mujeres me dirán dichosa: y llamó su nombre Aser.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, 'Y fué Rubén en tiempo de la siega de los trigos, y halló mandrágoras en el campo, y trájolas á Lea su madre: y dijo Rachêl á Lea: Ruégote que me des de las mandrágoras de tu hijo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'Y ella respondió: ¿Es poco que hayas tomado mi marido, sino que también te has de llevar las mandrágoras de mi hijo? y dijo Rachêl: Pues dormirá contigo esta noche por las mandrágoras de tu hijo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, 'Y cuando Jacob volvía del campo á la tarde, salió Lea á él, y le dijo: A mí has de entrar, porque á la verdad te he alquilado por las mandrágoras de mi hijo. Y durmió con ella aquella noche.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, 'Y oyó Dios á Lea: y concibió, y parió á Jacob el quinto hijo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'Y dijo Lea: Dios me ha dado mi recompensa, por cuanto dí mi sierva á mi marido: por eso llamó su nombre Issachâr.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'Y concibió Lea otra vez, y parió el sexto hijo á Jacob.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'Y dijo Lea: Dios me ha dado una buena dote: ahora morará conmigo mi marido, porque le he parido seis hijos: y llamó su nombre Zabulón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, 'Y después parió una hija, y llamó su nombre Dina.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, 'Y acordóse Dios de Rachêl, y oyóla Dios, y abrió su matriz.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, 'Y concibió, y parió un hijo: y dijo: Quitado ha Dios mi afrenta:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, 'Y llamó su nombre José, diciendo: Añádame Jehová otro hijo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, 'Y aconteció, cuando Rachêl hubo parido á José, que Jacob dijo á Labán: Envíame, é iré á mi lugar, y á mi tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'Dame mis mujeres y mis hijos, por las cuales he servido contigo, y déjame ir; pues tú sabes los servicios que te he hecho.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'Y Labán le respondió: Halle yo ahora gracia en tus ojos, y quédate; experimentado he que Jehová me ha bendecido por tu causa.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, 'Y dijo: Señálame tu salario, que yo lo daré.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'Y él respondió: Tú sabes cómo te he servido, y cómo ha estado tu ganado conmigo;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'Porque poco tenías antes de mi venida, y ha crecido en gran número; y Jehová te ha bendecido con mi llegada: y ahora ¿cuándo tengo de hacer yo también por mi propia casa?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, 'Y él dijo: ¿Qué te daré? Y respondió Jacob: No me des nada: si hicieres por mí esto, volveré á apacentar tus ovejas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, 'Yo pasaré hoy por todas tus ovejas, poniendo aparte todas las reses manchadas y de color vario, y todas las reses de color oscuro entre las ovejas, y las manchadas y de color vario entre las cabras; y esto será mi salario.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, 'Así responderá por mí mi justicia mañana, cuando me viniere mi salario delante de ti: toda la que no fuere pintada ni manchada en las cabras y de color oscuro en las ovejas mías, se me ha de tener por de hurto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, 'Y dijo Labán: Mira, ojalá fuese como tú dices.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, 'Y apartó aquel día los machos de cabrío rayados y manchados; y todas las cabras manchadas y de color vario, y toda res que tenía en sí algo de blanco, y todas las de color oscuro entre las ovejas, y púsolas en manos de sus hijos;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, 'Y puso tres días de camino entre sí y Jacob: y Jacob apacentaba las otras ovejas de Labán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, 'Y tomóse Jacob varas de álamo verdes, y de avellano, y de castaño, y descortezó en ellas mondaduras blancas, descubriendo así lo blanco de las varas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, 'Y puso las varas que había mondado en las pilas, delante del ganado, en los abrevaderos del agua donde venían á beber las ovejas, las cuales se recalentaban viniendo á beber.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, 'Y concebían las ovejas delante de las varas, y parían borregos listados, pintados y salpicados de diversos colores.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'Y apartaba Jacob los corderos, y poníalos con su rebaño, los listados, y todo lo que era oscuro en el hato de Labán. Y ponía su hato aparte, y no lo ponía con las ovejas de Labán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, 'Y sucedía que cuantas veces se recalentaban las tempranas, Jacob ponía las varas delante de las ovejas en las pilas, para que concibiesen á la vista de las varas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, 'Y cuando venían las ovejas tardías, no las ponía: así eran las tardías para Labán, y las tempranas para Jacob.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, 'Y acreció el varón muy mucho, y tuvo muchas ovejas, y siervas y siervos, y camellos y asnos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, 'Y OÍA él las palabras de los hijos de Labán, que decían: Jacob ha tomado todo lo que era de nuestro padre; y de lo que era de nuestro padre ha adquirido toda esta grandeza.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, 'Miraba también Jacob el semblante de Labán, y veía que no era para con él como ayer y antes de ayer.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, 'También Jehová dijo á Jacob: Vuélvete á la tierra de tus padres, y á tu parentela; que yo seré contigo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, 'Y envió Jacob, y llamó á Rachêl y á Lea al campo á sus ovejas,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, 'Y díjoles: Veo que el semblante de vuestro padre no es para conmigo como ayer y antes de ayer: mas el Dios de mi padre ha sido conmigo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, 'Y vosotras sabéis que con todas mis fuerzas he servido á vuestro padre:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, 'Y vuestro padre me ha engañado, y me ha mudado el salario diez veces: pero Dios no le ha permitido que me hiciese mal.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, 'Si él decía así: Los pintados serán tu salario; entonces todas las ovejas parían pintados: y si decía así: Los listados serán tu salario; entonces todas las ovejas parían listados.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, 'Así quitó Dios el ganado de vuestro padre, y diómelo á mí.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, 'Y sucedió que al tiempo que las ovejas se recalentaban, alcé yo mis ojos y vi en sueños, y he aquí los machos que cubrían á las hembras eran listados, pintados y abigarrados.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, 'Y díjome el ángel de Dios en sueños: Jacob. Y yo dije: Heme aquí.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, 'Y él dijo: Alza ahora tus ojos, y verás todos los machos que cubren á las ovejas listados, pintados y abigarrados; porque yo he visto todo lo que Labán te ha hecho.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, 'Yo soy el Dios de Beth-el, donde tú ungiste el título, y donde me hiciste un voto. Levántate ahora, y sal de esta tierra, y vuélvete á la tierra de tu naturaleza.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'Y respondió Rachêl y Lea, y dijéronle: ¿Tenemos ya parte ni heredad en la casa de nuestro padre?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, '¿No nos tiene ya como por extrañas, pues que nos vendió, y aun se ha comido del todo nuestro precio?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, 'Porque toda la riqueza que Dios ha quitado á nuestro padre, nuestra es y de nuestros hijos: ahora pues, haz todo lo que Dios te ha dicho.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, 'Entonces se levantó Jacob, y subió sus hijos y sus mujeres sobre los camellos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, 'Y puso en camino todo su ganado, y toda su hacienda que había adquirido, el ganado de su ganancia que había obtenido en Padan-aram, para volverse á Isaac su padre en la tierra de Canaán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, 'Y Labán había ido á trasquilar sus ovejas: y Rachêl hurtó los ídolos de su padre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'Y recató Jacob el corazón de Labán Arameo, en no hacerle saber que se huía.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, 'Huyó, pues, con todo lo que tenía; y levantóse, y pasó el río, y puso su rostro al monte de Galaad.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, 'Y fué dicho á Labán al tercero día como Jacob se había huído.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, 'Entonces tomó á sus hermanos consigo, y fué tras él camino de siete días, y alcanzóle en el monte de Galaad.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, 'Y vino Dios á Labán Arameo en sueños aquella noche, y le dijo: Guárdate que no hables á Jacob descomedidamente.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, 'Alcanzó pues Labán á Jacob, y éste había fijado su tienda en el monte: y Labán plantó la con sus hermanos en el monte de Galaad.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, 'Y dijo Labán á Jacob: ¿Qué has hecho, que me hurtaste el corazón, y has traído á mis hijas como prisioneras de guerra?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, '¿Por qué te escondiste para huir, y me hurtaste, y no me diste noticia, para que yo te enviara con alegría y con cantares, con tamborín y vihuela?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, 'Que aun no me dejaste besar mis hijos y mis hijas. Ahora locamente has hecho.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, 'Poder hay en mi mano para haceros mal: mas el Dios de vuestro padre me habló anoche diciendo: Guárdate que no hables á Jacob descomedidamente.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, 'Y ya que te ibas, porque tenías deseo de la casa de tu padre, ¿por qué me hurtaste mis dioses?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'Y Jacob respondió, y dijo á Labán: Porque tuve miedo; pues dije, que quizá me quitarías por fuerza tus hijas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, 'En quien hallares tus dioses, no viva: delante de nuestros hermanos reconoce lo que yo tuviere tuyo, y llévatelo. Jacob no sabía que Rachêl los había hurtado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, 'Y entró Labán en la tienda de Jacob, y en la tienda de Lea, y en la tienda de las dos siervas, y no los halló, y salió de la tienda de Lea, y vino á la tienda de Rachêl.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'Y tomó Rachêl los ídolos, y púsolos en una albarda de un camello, y sentóse sobre ellos: y tentó Labán toda la tienda, y no los halló.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, 'Y ella dijo á su padre: No se enoje mi señor, porque no me puedo levantar delante de ti; pues estoy con la costumbre de las mujeres. Y él buscó, pero no halló los ídolos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, 'Entonces Jacob se enojó, y regañó con Labán; y respondió Jacob y dijo á Labán: ¿Qué prevaricación es la mía? ¿cuál es mi pecado, que con tanto ardor has venido en seguimiento mío?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, 'Pues que has tentado todos mis muebles, ¿qué has hallado de todas las alhajas de tu casa? Ponlo aquí delante de mis hermanos y tuyos, y juzguen entre nosotros ambos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, 'Estos veinte años he estado contigo: tus ovejas y tus cabras nunca abortaron, ni yo comí carnero de tus ovejas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, 'Nunca te traje lo arrebatado por las fieras; yo pagaba el daño; lo hurtado así de día como de noche, de mi mano lo requerías.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, 'De día me consumía el calor, y de noche la helada, y el sueño se huía de mis ojos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, 'Así he estado veinte años en tu casa: catorce años te serví por tus dos hijas, y seis años por tu ganado; y has mudado mi salario diez veces.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, 'Si el Dios de mi padre, el Dios de Abraham, y el temor de Isaac, no fuera conmigo, de cierto me enviarías ahora vacío: vió Dios mi aflicción y el trabajo de mis manos, y reprendióte anoche.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'Y respondió Labán, y dijo á Jacob: Las hijas son hijas mías, y los hijos, hijos míos son, y las ovejas son mis ovejas, y todo lo que tú ves es mío: ¿y qué puedo yo hacer hoy á estas mis hijas, ó á sus hijos que ellas han parido?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, 'Ven pues ahora, y hagamos alianza yo y tú; y sea en testimonio entre mí y entre ti.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, 'Entonces Jacob tomó una piedra, y levantóla por título.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'Y dijo Jacob á sus hermanos: Coged piedras. Y tomaron piedras é hicieron un majano; y comieron allí sobre aquel majano.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'Y llamólo Labán Jegar Sahadutha: y lo llamó Jacob Galaad.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'Porque Labán dijo: Este majano es testigo hoy entre mí y entre ti; por eso fué llamado su nombre Galaad;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, 'Y Mizpa, por cuanto dijo: Atalaye Jehová entre mí y entre ti, cuando nos apartáremos el uno del otro.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, 'Si afligieres mis hijas, ó si tomares otras mujeres además de mis hijas, nadie está con nosotros; mira, Dios es testigo entre mí y entre ti.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'Dijo más Labán á Jacob: He aquí este majano, y he aquí este título, que he erigido entre mí y ti.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, 'Testigo sea este majano, y testigo sea este título, que ni yo pasaré contra ti este majano, ni tú pasarás contra mí este majano ni este título, para mal.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, 'El Dios de Abraham, y el Dios de Nachôr juzgue entre nosotros, el Dios de sus padres. Y Jacob juró por el temor de Isaac su padre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, 'Entonces Jacob inmoló víctimas en el monte, y llamó á sus hermanos á comer pan: y comieron pan, y durmieron aquella noche en el monte.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 55, 'Y levantóse Labán de mañana, y besó sus hijos y sus hijas, y los bendijo; y retrocedió y volvióse á su lugar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, 'Y JACOB se fué su camino, y saliéronle al encuentro ángeles de Dios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, 'Y dijo Jacob cuando los vió: El campo de Dios es este: y llamó el nombre de aquel lugar Mahanaim.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'Y envió Jacob mensajeros delante de sí á Esaú su hermano, á la tierra de Seir, campo de Edom.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, 'Y mandóles diciendo: Así diréis á mi señor Esaú: Así dice tu siervo Jacob: Con Labán he morado, y detenídome hasta ahora;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, 'Y tengo vacas, y asnos, y ovejas, y siervos y siervas; y envío á decirlo á mi señor, por hallar gracia en tus ojos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, 'Y los mensajeros volvieron á Jacob, diciendo: Vinimos á tu hermano Esaú, y él también viene á recibirte, y cuatrocientos hombres con él.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, 'Entonces Jacob tuvo gran temor, y angustióse; y partió el pueblo que tenía consigo, y las ovejas y las vacas y los camellos, en dos cuadrillas;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, 'Y dijo: Si viniere Esaú á la una cuadrilla y la hiriere, la otra cuadrilla escapará.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, 'Y dijo Jacob: Dios de mi padre Abraham, y Dios de mi padre Isaac, Jehová, que me dijiste: Vuélvete á tu tierra y á tu parentela, y yo te haré bien;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, 'Menor soy que todas las misericordias, y que toda la verdad que has usado para con tu siervo; que con mi bordón pasé este Jordán, y ahora estoy sobre dos cuadrillas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, 'Líbrame ahora de la mano de mi hermano, de la mano de Esaú, porque le temo; no venga quizá, y me hiera la madre con los hijos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, 'Y tú has dicho: Yo te haré bien, y pondré tu simiente como la arena del mar, que no se puede contar por la multitud.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, 'Y durmió allí aquella noche, y tomó de lo que le vino á la mano un presente para su hermano Esaú:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, 'Doscientas cabras y veinte machos de cabrío, doscientas ovejas y veinte carneros,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, 'Treinta camellas paridas, con sus hijos, cuarenta vacas y diez novillos, veinte asnas y diez borricos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, 'Y entrególo en mano de sus siervos, cada manada de por sí; y dijo á sus siervos: Pasad delante de mí, y poned espacio entre manada y manada.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, 'Y mandó al primero, diciendo: Si Esaú mi hermano te encontrare, y te preguntare, diciendo: ¿De quién eres? ¿y adónde vas? ¿y para quién es esto que llevas delante de ti?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, 'Entonces dirás: Presente es de tu siervo Jacob, que envía á mi señor Esaú; y he aquí también él viene tras nosotros.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, 'Y mandó también al segundo, y al tercero, y á todos los que iban tras aquellas manadas, diciendo: Conforme á esto hablaréis á Esaú, cuando le hallareis.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, 'Y diréis también: He aquí tu siervo Jacob viene tras nosotros. Porque dijo: Apaciguaré su ira con el presente que va delante de mí, y después veré su rostro: quizá le seré acepto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, 'Y pasó el presente delante de él; y él durmió aquella noche en el campamento.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, 'Y levantóse aquella noche, y tomó sus dos mujeres, y sus dos siervas, y sus once hijos, y pasó el vado de Jaboc.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'Tomólos pues, y pasólos el arroyo, é hizo pasar lo que tenía.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, 'Y quedóse Jacob solo, y luchó con él un varón hasta que rayaba el alba.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, 'Y como vió que no podía con él, tocó en el sitio del encaje de su muslo, y descoyuntóse el muslo de Jacob mientras con él luchaba.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'Y dijo: Déjame, que raya el alba. Y él dijo: No te dejaré, si no me bendices.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, 'Y él le dijo: ¿Cuál es tu nombre? Y él respondió: Jacob.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, 'Y él dijo: No se dirá más tu nombre Jacob, sino Israel: porque has peleado con Dios y con los hombres, y has vencido.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'Entonces Jacob le preguntó, y dijo: Declárame ahora tu nombre. Y él respondió: ¿Por qué preguntas por mi nombre? Y bendíjolo allí.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'Y llamó Jacob el nombre de aquel lugar, Peniel: porque vi á Dios cara á cara, y fué librada mi alma.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'Y salióle el sol pasado que hubo á Peniel; y cojeaba de su anca.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'Por esto no comen los hijos de Israel, hasta hoy día, del tendón que se contrajo, el cual está en el encaje del muslo: porque tocó á Jacob este sitio de su muslo en el tendón que se contrajo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, 'Y ALZANDO Jacob sus ojos miró, y he aquí venía Esaú, y los cuatrocientos hombres con él: entonces repartió él los niños entre Lea y Rachêl y las dos siervas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, 'Y puso las siervas y sus niños delante; luego á Lea y á sus niños; y á Rachêl y á José los postreros.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, 'Y él pasó delante de ellos, é inclinóse á tierra siete veces, hasta que llegó á su hermano.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'Y Esaú corrió á su encuentro, y abrazóle, y echóse sobre su cuello, y le besó; y lloraron.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'Y alzó sus ojos, y vió las mujeres y los niños, y dijo: ¿Qué te tocan éstos? Y él respondió: Son los niños que Dios ha dado á tu siervo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, 'Y se llegaron las siervas, ellas y sus niños, é inclináronse.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'Y llegóse Lea con sus niños, é inclináronse: y después llegó José y Rachêl, y también se inclinaron.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'Y él dijo: ¿Qué te propones con todas estas cuadrillas que he encontrado? Y él respondió: El hallar gracia en los ojos de mi señor.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, 'Y dijo Esaú: Harto tengo yo, hermano mío: sea para ti lo que es tuyo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, 'Y dijo Jacob: No, yo te ruego, si he hallado ahora gracia en tus ojos, toma mi presente de mi mano, pues que así he visto tu rostro, como si hubiera visto el rostro de Dios; y hazme placer.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, 'Toma, te ruego, mi dádiva que te es traída; porque Dios me ha hecho merced, y todo lo que hay aquí es mío. Y porfió con él, y tomóla.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, 'Y dijo: Anda, y vamos; y yo iré delante de ti.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'Y él le dijo: Mi señor sabe que los niños son tiernos, y que tengo ovejas y vacas paridas; y si las fatigan, en un día morirán todas las ovejas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, 'Pase ahora mi señor delante de su siervo, y yo me iré poco á poco al paso de la hacienda que va delante de mí, y al paso de los niños, hasta que llegue á mi señor á Seir.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, 'Y Esaú dijo: Dejaré ahora contigo de la gente que viene conmigo. Y él dijo: ¿Para qué esto? halle yo gracia en los ojos de mi señor.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, 'Así se volvió Esaú aquel día por su camino á Seir.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, 'Y Jacob se partió á Succoth, y edificó allí casa para sí, é hizo cabañas para su ganado: por tanto llamó el nombre de aquel lugar Succoth.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, 'Y vino Jacob sano á la ciudad de Sichêm, que está en la tierra de Canaán, cuando venía de Padan-aram; y acampó delante de la ciudad.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, 'Y compró una parte del campo, donde tendió su tienda, de mano de los hijos de Hamor, padre de Sichêm, por cien piezas de moneda.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, 'Y erigió allí un altar, y llamóle: El Dios de Israel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'Y SALIÓ Dina la hija de Lea, la cual había ésta parido á Jacob, á ver las hijas del país.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'Y vióla Sichêm, hijo de Hamor Heveo, príncipe de aquella tierra, y tomóla, y echóse con ella, y la deshonró.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, 'Mas su alma se apegó á Dina la hija de Lea, y enamoróse de la moza, y habló al corazón de la joven.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, 'Y habló Sichêm á Hamor su padre, diciendo: Tómame por mujer esta moza.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'Y oyó Jacob que había Sichêm amancillado á Dina su hija: y estando sus hijos con su ganado en el campo, calló Jacob hasta que ellos viniesen.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'Y dirigióse Hamor padre de Sichêm á Jacob, para hablar con él.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, 'Y los hijos de Jacob vinieron del campo cuando lo supieron; y se entristecieron los varones, y se ensañaron mucho, porque hizo vileza en Israel echándose con la hija de Jacob, lo que no se debía haber hecho.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'Y Hamor habló con ellos, diciendo: El alma de mi hijo Sichêm se ha apegado á vuestra hija; ruégoos que se la deis por mujer.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, 'Y emparentad con nosotros; dadnos vuestras hijas, y tomad vosotros las nuestras.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'Y habitad con nosotros; porque la tierra estará delante de vosotros; morad y negociad en ella, y tomad en ella posesión.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'Sichêm también dijo á su padre y á sus hermanos: Halle yo gracia en vuestros ojos, y daré lo que me dijereis.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'Aumentad á cargo mío mucho dote y dones, que yo daré cuanto me dijereis, y dadme la moza por mujer.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, 'Y respondieron los hijos de Jacob á Sichêm y á Hamor su padre con engaño; y parlaron, por cuanto había amancillado á Dina su hermana.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, 'Y dijéronles: No podemos hacer esto de dar nuestra hermana á hombre que tiene prepucio; porque entre nosotros es abominación.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, 'Mas con esta condición os haremos placer: si habéis de ser como nosotros, que se circuncide entre vosotros todo varón;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, 'Entonces os daremos nuestras hijas, y tomaremos nosotros las vuestras; y habitaremos con vosotros, y seremos un pueblo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, 'Mas si no nos prestareis oído para circuncidaros, tomaremos nuestra hija, y nos iremos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, 'Y parecieron bien sus palabras á Hamor y á Sichêm, hijo de Hamor.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, 'Y no dilató el mozo hacer aquello, porque la hija de Jacob le había agradado: y él era el más honrado de toda la casa de su padre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'Entonces Hamor y Sichêm su hijo vinieron á la puerta de su ciudad, y hablaron á los varones de su ciudad, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, 'Estos varones son pacíficos con nosotros, y habitarán en el país, y traficarán en él: pues he aquí la tierra es bastante ancha para ellos: nosotros tomaremos sus hijas por mujeres, y les daremos las nuestras.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, 'Mas con esta condición nos harán estos hombres el placer de habitar con nosotros, para que seamos un pueblo: si se circuncidare en nosotros todo varón, así como ellos son circuncidados.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, 'Sus ganados, y su hacienda y todas sus bestias, serán nuestras: solamente convengamos con ellos, y habitarán con nosotros.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, 'Y obedecieron á Hamor y á Sichêm su hijo todos los que salían por la puerta de la ciudad, y circuncidaron á todo varón, á cuantos salían por la puerta de su ciudad.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, 'Y sucedió que al tercer día, cuando sentían ellos el mayor dolor, los dos hijos de Jacob, Simeón y Leví, hermanos de Dina, tomaron cada uno su espada, y vinieron contra la ciudad animosamente, y mataron á todo varón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, 'Y á Hamor y á Sichêm su hijo los mataron á filo de espada: y tomaron á Dina de casa de Sichêm, y saliéronse.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, 'Y los hijos de Jacob vinieron á los muertos, y saquearon la ciudad; por cuanto habían amancillado á su hermana.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'Tomaron sus ovejas y vacas y sus asnos, y lo que había en la ciudad y en el campo,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, 'Y toda su hacienda; se llevaron cautivos á todos sus niños y sus mujeres, y robaron todo lo que había en casa.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'Entonces dijo Jacob á Simeón y á Leví: Habéisme turbado con hacerme abominable á los moradores de aquesta tierra, el Cananeo y el Pherezeo; y teniendo yo pocos hombres, juntarse han contra mí, y me herirán, y seré destruído yo y mi casa.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, 'Y ellos respondieron: ¿Había él de tratar á nuestra hermana como á una ramera?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, 'Y DIJO Dios á Jacob: Levántate, sube á Beth-el, y estáte allí; y haz allí un altar al Dios que te apareció cuando huías de tu hermano Esaú.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'Entonces Jacob dijo á su familia y á todos los que con él estaban: Quitad los dioses ajenos que hay entre vosotros, y limpiaos, y mudad vuestros vestidos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, 'Y levantémonos, y subamos á Beth-el; y haré allí altar al Dios que me respondió en el día de mi angustia, y ha sido conmigo en el camino que he andado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, 'Así dieron á Jacob todos los dioses ajenos que había en poder de ellos, y los zarzillos que estaban en sus orejas; y Jacob los escondió debajo de una encina, que estaba junto á Sichêm.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, 'Y partiéronse, y el terror de Dios fué sobre las ciudades que había en sus alrededores, y no siguieron tras los hijos de Jacob.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'Y llegó Jacob á Luz, que está en tierra de Canaán, (esta es Beth-el) él y todo el pueblo que con él estaba;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, 'Y edificó allí un altar, y llamó al lugar El-Beth-el, porque allí le había aparecido Dios, cuando huía de su hermano.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, 'Entonces murió Débora, ama de Rebeca, y fué sepultada á las raíces de Beth-el, debajo de una encina: y llamóse su nombre Allon-Bacuth.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, 'Y aparecióse otra vez Dios á Jacob, cuando se había vuelto de Padan-aram, y bendíjole.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, 'Y díjole Dios: Tu nombre es Jacob; no se llamará más tu nombre Jacob, sino Israel será tu nombre: y llamó su nombre Israel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, 'Y díjole Dios: Yo soy el Dios Omnipotente: crece y multiplícate; una nación y conjunto de naciones procederá de ti, y reyes saldrán de tus lomos:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'Y la tierra que yo he dado á Abraham y á Isaac, la daré á ti: y á tu simiente después de ti daré la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, 'Y fuése de él Dios, del lugar donde con él había hablado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, 'Y Jacob erigió un título en el lugar donde había hablado con él, un título de piedra, y derramó sobre él libación, y echó sobre él aceite.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, 'Y llamó Jacob el nombre de aquel lugar donde Dios había hablado con él, Beth-el.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, 'Y partieron de Beth-el, y había aún como media legua de tierra para llegar á Ephrata, cuando parió Rachêl, y hubo trabajo en su parto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, 'Y aconteció, que como había trabajo en su parir, díjole la partera: No temas, que también tendrás este hijo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, 'Y acaeció que al salírsele el alma, (pues murió) llamó su nombre Benoni; mas su padre lo llamó Benjamín.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'Así murió Rachêl, y fué sepultada en el camino de Ephrata, la cual es Beth-lehem.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'Y puso Jacob un título sobre su sepultura: este es el título de la sepultura de Rachêl hasta hoy.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, 'Y partió Israel, y tendió su tienda de la otra parte de Migdaleder.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'Y acaeció, morando Israel en aquella tierra, que fué Rubén y durmió con Bilha la concubina de su padre; lo cual llegó á entender Israel. Ahora bien, los hijos de Israel fueron doce:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, 'Los hijos de Lea: Rubén el primogénito de Jacob, y Simeón, y Leví, y Judá, é Issachâr, y Zabulón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 'Los hijos de Rachêl: José, y Benjamín.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 'Y los hijos de Bilha, sierva de Rachêl: Dan, y Nephtalí.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'Y los hijos de Zilpa, sierva de Lea: Gad, y Aser. Estos fueron los hijos de Jacob, que le nacieron en Padan-aram.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'Y vino Jacob á Isaac su padre á Mamre, á la ciudad de Arba, que es Hebrón, donde habitaron Abraham é Isaac.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'Y fueron los días de Isaac ciento ochenta años.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'Y exhaló Isaac el espíritu, y murió, y fué recogido á sus pueblos, viejo y harto de días; y sepultáronlo Esaú y Jacob sus hijos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, 'Y ESTAS son las generaciones de Esaú, el cual es Edom.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'Esaú tomó sus mujeres de las hijas de Canaán: á Ada, hija de Elón Hetheo, y á Aholibama, hija de Ana, hija de Zibeón el Heveo;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, 'Y á Basemath, hija de Ismael, hermana de Navaioth.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'Y Ada parió á Esaú á Eliphaz; y Basemath parió á Reuel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'Y Aholibama parió á Jeús, y á Jaalam, y á Cora: estos son los hijos de Esaú, que le nacieron en la tierra de Canaán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'Y Esaú tomó sus mujeres, y sus hijos, y sus hijas, y todas las personas de su casa, y sus ganados, y todas sus bestias, y toda su hacienda que había adquirido en la tierra de Canaán, y fuése á otra tierra de delante de Jacob su hermano:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, 'Porque la hacienda de ellos era grande, y no podían habitar juntos, ni la tierra de su peregrinación los podía sostener á causa de sus ganados.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, 'Y Esaú habitó en el monte de Seir: Esaú es Edom.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'Estos son los linajes de Esaú, padre de Edom, en el monte de Seir.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'Estos son los nombres de los hijos de Esaú: Eliphaz, hijo de Ada, mujer de Esaú; Reuel, hijo de Basemath, mujer de Esaú.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, 'Y los hijos de Eliphaz fueron Temán, Omar, Zepho, Gatam, y Cenaz.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'Y Timna fué concubina de Eliphaz, hijo de Esaú, la cual le parió á Amalec: estos son los hijos de Ada, mujer de Esaú.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, 'Y los hijos de Reuel fueron Nahath, Zera, Samma, y Mizza: estos son los hijos de Basemath, mujer de Esaú.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, 'Estos fueron los hijos de Aholibama, mujer de Esaú, hija de Ana, que fué hija de Zibeón: ella parió á Esaú á Jeús, Jaalam, y Cora.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'Estos son los duques de los hijos de Esaú. Hijos de Eliphaz, primogénito de Esaú: el duque Temán, el duque Omar, el duque Zepho, el duque Cenaz,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, 'El duque Cora, el duque Gatam, y el duque Amalec: estos son los duques de Eliphaz en la tierra de Edom; estos fueron los hijos de Ada.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, 'Y estos son los hijos de Reuel, hijo de Esaú: el duque Nahath, el duque Zera, el duque Samma, y el duque Mizza: estos son los duques de la línea de Reuel en la tierra de Edom; estos hijos vienen de Basemath, mujer de Esaú.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, 'Y estos son los hijos de Aholibama, mujer de Esaú: el duque Jeús, el duque Jaalam, y el duque Cora: estos fueron los duques que salieron de Aholibama, mujer de Esaú, hija de Ana.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, 'Estos, pues, son los hijos de Esaú, y sus duques: él es Edom.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, 'Y estos son los hijos de Seir Horeo, moradores de aquella tierra: Lotán, Sobal, Zibeón, Ana,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'Disón, Ezer, y Disán: estos son los duques de los Horeos, hijos de Seir en la tierra de Edom.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'Los hijos de Lotán fueron Hori y Hemán; y Timna fué hermana de Lotán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, 'Y los hijos de Sobal fueron Alván, Manahath, Ebal, Sepho, y Onán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, 'Y los hijos de Zibeón fueron Aja, y Ana. Este Ana es el que descubrió los mulos en el desierto, cuando apacentaba los asnos de Zibeón su padre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, 'Los hijos de Ana fueron Disón, y Aholibama, hija de Ana.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, 'Y estos fueron los hijos de Disón: Hemdán, Eshbán, Ithram, y Cherán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, 'Y estos fueron los hijos de Ezer: Bilhán, Zaaván, y Acán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, 'Estos fueron los hijos de Disán: Huz, y Arán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'Y estos fueron los duques de los Horeos: el duque Lotán, el duque Sobal, el duque Zibeón, el duque Ana,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'El duque Disón, el duque Ezer, el duque Disán: estos fueron los duques de los Horeos: por sus ducados en la tierra de Seir.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, 'Y los reyes que reinaron en la tierra de Edom, antes que reinase rey sobre los hijos de Israel, fueron estos:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'Bela, hijo de Beor, reinó en Edom: y el nombre de su ciudad fué Dinaba.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, 'Y murió Bela, y reinó en su lugar Jobab, hijo de Zera, de Bosra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, 'Y murió Jobab, y en su lugar reinó Husam, de tierra de Temán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, 'Y murió Husam, y reinó en su lugar Adad, hijo de Badad, el que hirió á Midián en el campo de Moab: y el nombre de su ciudad fué Avith.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, 'Y murió Adad, y en su lugar reinó Samla, de Masreca.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, 'Y murió Samla, y reinó en su lugar Saúl, de Rehoboth del Río.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, 'Y murió Saúl, y en lugar suyo reinó Baalanán, hijo de Achbor.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, 'Y murió Baalanán, hijo de Achbor, y reinó Adar en lugar suyo: y el nombre de su ciudad fué Pau; y el nombre de su mujer Meetabel, hija de Matred, hija de Mezaab.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'Estos, pues, son los nombres de los duques de Esaú por sus linajes, por sus lugares, y sus nombres: el duque Timna, el duque Alva, el duque Jetheth,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'El duque Aholibama, el duque Ela, el duque Pinón,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'El duque Cenaz, el duque Temán, el duque Mibzar,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'El duque Magdiel, y el duque Hiram. Estos fueron los duques de Edom por sus habitaciones en la tierra de su posesión. Edom es el mismo Esaú, padre de los Idumeos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, 'Y HABITÓ Jacob en la tierra donde peregrinó su padre, en la tierra de Canaán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'Estas fueron las generaciones de Jacob. José, siendo de edad de diez y siete años apacentaba las ovejas con sus hermanos; y el joven estaba con los hijos de Bilha, y con los hijos de Zilpa, mujeres de su padre: y noticiaba José á su padre la mala fama de ellos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, 'Y amaba Israel á José más que á todos sus hijos, porque le había tenido en su vejez: y le hizo una ropa de diversos colores.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'Y viendo sus hermanos que su padre lo amaba más que á todos sus hermanos, aborrecíanle, y no le podían hablar pacíficamente.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, 'Y soñó José un sueño, y contólo á sus hermanos; y ellos vinieron á aborrecerle más todavía.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, 'Y él les dijo: Oíd ahora este sueño que he soñado:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, 'He aquí que atábamos manojos en medio del campo, y he aquí que mi manojo se levantaba, y estaba derecho, y que vuestros manojos estaban alrededor, y se inclinaban al mío.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'Y respondiéronle sus hermanos: ¿Has de reinar tú sobre nosotros, ó te has de enseñorear sobre nosotros? Y le aborrecieron aún más á causa de sus sueños y de sus palabras.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'Y soñó aún otro sueño, y contólo á sus hermanos, diciendo: He aquí que he soñado otro sueño, y he aquí que el sol y la luna y once estrellas se inclinaban á mí.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, 'Y contólo á su padre y á sus hermanos: y su padre le reprendió, y díjole: ¿Qué sueño es este que soñaste? ¿Hemos de venir yo y tu madre, y tus hermanos, á inclinarnos á ti á tierra?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, 'Y sus hermanos le tenían envidia, mas su padre paraba la consideración en ello.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, 'Y fueron sus hermanos á apacentar las ovejas de su padre en Sichêm.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'Y dijo Israel á José: Tus hermanos apacientan las ovejas en Sichêm: ven, y te enviaré á ellos. Y él respondió: Heme aquí.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, 'Y él le dijo: Ve ahora, mira cómo están tus hermanos y cómo están las ovejas, y tráeme la respuesta. Y enviólo del valle de Hebrón, y llegó á Sichêm.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, 'Y hallólo un hombre, andando él perdido por el campo, y preguntóle aquel hombre, diciendo: ¿Qué buscas?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, 'Y él respondió: Busco á mis hermanos: ruégote que me muestres dónde pastan.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, 'Y aquel hombre respondió: Ya se han ido de aquí; y yo les oí decir: Vamos á Dothán. Entonces José fué tras de sus hermanos, y hallólos en Dothán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'Y como ellos lo vieron de lejos, antes que cerca de ellos llegara, proyectaron contra él para matarle.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, 'Y dijeron el uno al otro: He aquí viene el soñador;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, 'Ahora pues, venid, y matémoslo y echémosle en una cisterna, y diremos: Alguna mala bestia le devoró: y veremos qué serán sus sueños.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'Y como Rubén oyó esto, librólo de sus manos, y dijo: No lo matemos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'Y díjoles Rubén: No derraméis sangre; echadlo en esta cisterna que está en el desierto, y no pongáis mano en él; por librarlo así de sus manos, para hacerlo volver á su padre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, 'Y sucedió que, cuando llegó José á sus hermanos, ellos hicieron desnudar á José su ropa, la ropa de colores que tenía sobre sí;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, 'Y tomáronlo, y echáronle en la cisterna; mas la cisterna estaba vacía, no había en ella agua.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, 'Y sentáronse á comer pan: y alzando los ojos miraron, y he aquí una compañía de Ismaelitas que venía de Galaad, y sus camellos traían aromas y bálsamo y mirra, é iban á llevarlo á Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, 'Entonces Judá dijo á sus hermanos: ¿Qué provecho el que matemos á nuestro hermano y encubramos su muerte?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, 'Venid, y vendámosle á los Ismaelitas, y no sea nuestra mano sobre él; que nuestro hermano es nuestra carne. Y sus hermanos acordaron con él.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, 'Y como pasaban los Midianitas mercaderes, sacaron ellos á José de la cisterna, y trajéronle arriba, y le vendieron á los Ismaelitas por veinte piezas de plata. Y llevaron á José á Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, 'Y Rubén volvió á la cisterna, y no halló á José dentro, y rasgó sus vestidos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, 'Y tornó á sus hermanos, y dijo: El mozo no parece; y yo, ¿adónde iré yo?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, 'Entonces tomaron ellos la ropa de José, y degollaron un cabrito de las cabras, y tiñeron la ropa con la sangre;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, 'Y enviaron la ropa de colores y trajéronla á su padre, y dijeron: Esta hemos hallado, reconoce ahora si es ó no la ropa de tu hijo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, 'Y él la conoció, y dijo: La ropa de mi hijo es; alguna mala bestia le devoró; José ha sido despedazado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'Entonces Jacob rasgó sus vestidos, y puso saco sobre sus lomos, y enlutóse por su hijo muchos días.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'Y levantáronse todos sus hijos y todas sus hijas para consolarlo; mas él no quiso tomar consolación, y dijo: Porque yo tengo de descender á mi hijo enlutado hasta la sepultura. Y llorólo su padre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, 'Y los Midianitas lo vendieron en Egipto á Potiphar, eunuco de Faraón, capitán de los de la guardia.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, 'Y ACONTECIÓ en aquel tiempo, que Judá descendió de con sus hermanos, y fuése á un varón Adullamita, que se llamaba Hira.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'Y vió allí Judá la hija de un hombre Cananeo, el cual se llamaba Súa; y tomóla, y entró á ella:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, 'La cual concibió, y parió un hijo; y llamó su nombre Er.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, 'Y concibió otra vez, y parió un hijo, y llamó su nombre Onán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'Y volvió á concebir, y parió un hijo, y llamó su nombre Sela. Y estaba en Chezib cuando lo parió.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'Y Judá tomó mujer para su primogénito Er, la cual se llamaba Thamar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'Y Er, el primogénito de Judá, fué malo á los ojos de Jehová, y quitóle Jehová la vida.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, 'Entonces Judá dijo á Onán: Entra á la mujer de tu hermano, y despósate con ella, y suscita simiente á tu hermano.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'Y sabiendo Onán que la simiente no había de ser suya, sucedía que cuando entraba á la mujer de su hermano vertía en tierra, por no dar simiente á su hermano.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, 'Y desagradó en ojos de Jehová lo que hacía, y también quitó á él la vida.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'Y Judá dijo á Thamar su nuera: Estáte viuda en casa de tu padre, hasta que crezca Sela mi hijo; porque dijo: Que quizá no muera él también como sus hermanos. Y fuése Thamar, y estúvose en casa de su padre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, 'Y pasaron muchos días, y murió la hija de Súa, mujer de Judá; y Judá se consoló, y subía á los trasquiladores de sus ovejas á Timnath, él y su amigo Hira el Adullamita.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, 'Y fué dado aviso á Thamar, diciendo: He aquí tu suegro sube á Timnath á trasquilar sus ovejas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, 'Entonces quitó ella de sobre sí los vestidos de su viudez, y cubrióse con un velo, y arrebozóse, y se puso á la puerta de las aguas que están junto al camino de Timnath; porque veía que había crecido Sela, y ella no era dada á él por mujer.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, 'Y vióla Judá, y túvola por ramera, porque había ella cubierto su rostro.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, 'Y apartóse del camino hacia ella, y díjole: Ea, pues, ahora entraré á ti; porque no sabía que era su nuera; y ella dijo: ¿Qué me has de dar, si entrares á mí?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, 'El respondió: Yo te enviaré del ganado un cabrito de las cabras. Y ella dijo: Hasme de dar prenda hasta que lo envíes.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, 'Entonces él dijo: ¿Qué prenda te daré? Ella respondió: Tu anillo, y tu manto, y tu bordón que tienes en tu mano. Y él se los dió, y entró á ella, la cual concibió de él.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, 'Y levantóse, y fuése: y quitóse el velo de sobre sí, y vistióse las ropas de su viudez.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'Y Judá envió el cabrito de las cabras por mano de su amigo el Adullamita, para que tomase la prenda de mano de la mujer; mas no la halló.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'Y preguntó á los hombres de aquel lugar, diciendo: ¿Dónde está la ramera de las aguas junto al camino? Y ellos le dijeron: No ha estado aquí ramera.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'Entonces él se volvió á Judá, y dijo: No la he hallado; y también los hombres del lugar dijeron: Aquí no ha estado ramera.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'Y Judá dijo: Tómeselo para sí, porque no seamos menospreciados: he aquí yo he enviado este cabrito, y tú no la hallaste.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, 'Y acaeció que al cabo de unos tres meses fué dado aviso á Judá, diciendo: Thamar tu nuera ha fornicado, y aun cierto está preñada de las fornicaciones. Y Judá dijo: Sacadla, y sea quemada.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, 'Y ella, cuando la sacaban, envió á decir á su suegro: Del varón cuyas son estas cosas, estoy preñada: y dijo más: Mira ahora cúyas son estas cosas, el anillo, y el manto, y el bordón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'Entonces Judá los reconoció, y dijo: Más justa es que yo, por cuanto no la he dado á Sela mi hijo. Y nunca más la conoció.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'Y aconteció que al tiempo del parir, he aquí había dos en su vientre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'Y sucedió, cuando paría, que sacó la mano el uno, y la partera tomó y ató á su mano un hilo de grana, diciendo: Este salió primero.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, 'Empero fué que tornando él á meter la mano, he aquí su hermano salió; y ella dijo: ¿Por qué has hecho sobre ti rotura? Y llamó su nombre Phares.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'Y después salió su hermano, el que tenía en su mano el hilo de grana, y llamó su nombre Zara.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, 'Y LLEVADO José á Egipto, comprólo Potiphar, eunuco de Faraón, capitán de los de la guardia, varón Egipcio, de mano de los Ismaelitas que lo habían llevado allá.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'Mas Jehová fué con José, y fué varón prosperado: y estaba en la casa de su señor el Egipcio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'Y vió su señor que Jehová era con él, y que todo lo que él hacía, Jehová lo hacía prosperar en su mano.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, 'Así halló José gracia en sus ojos, y servíale; y él le hizo mayordomo de su casa, y entregó en su poder todo lo que tenía.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, 'Y aconteció que, desde cuando le dió el encargo de su casa, y de todo lo que tenía, Jehová bendijo la casa del Egipcio á causa de José; y la bendición de Jehová fué sobre todo lo que tenía, así en casa como en el campo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, 'Y dejó todo lo que tenía en mano de José; ni con él sabía de nada más que del pan que comía. Y era José de hermoso semblante y bella presencia.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, 'Y aconteció después de esto, que la mujer de su señor puso sus ojos en José, y dijo: Duerme conmigo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'Y él no quiso, y dijo á la mujer de su señor: He aquí que mi señor no sabe conmigo lo que hay en casa, y ha puesto en mi mano todo lo que tiene:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'No hay otro mayor que yo en esta casa, y ninguna cosa me ha reservado sino á ti, por cuanto tú eres su mujer; ¿cómo, pues, haría yo este grande mal, y pecaría contra Dios?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, 'Y fué que hablando ella á José cada día, y no escuchándola él para acostarse al lado de ella, para estar con ella,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, 'Aconteció que entró él un día en casa para hacer su oficio, y no había nadie de los de casa allí en casa:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, 'Y asiólo ella por su ropa, diciendo: Duerme conmigo. Entonces dejóla él su ropa en las manos, y huyó, y salióse fuera.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, 'Y acaeció que cuando vió ella que le había dejado su ropa en sus manos, y había huído fuera,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, 'Llamó á los de casa, y hablóles diciendo: Mirad, nos ha traído un Hebreo, para que hiciese burla de nosotros: vino él á mí para dormir conmigo, y yo dí grandes voces;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, 'Y viendo que yo alzaba la voz y gritaba, dejó junto á mí su ropa, y huyó, y salióse fuera.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, 'Y ella puso junto á sí la ropa de él, hasta que vino su señor á su casa.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, 'Entonces le habló ella semejantes palabras, diciendo: El siervo Hebreo que nos trajiste, vino á mí para deshonrarme;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, 'Y como yo alcé mi voz y grité, él dejó su ropa junto á mí, y huyó fuera.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, 'Y sucedió que como oyó su señor las palabras que su mujer le hablara, diciendo: Así me ha tratado tu siervo; encendióse su furor.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, 'Y tomó su señor á José, y púsole en la casa de la cárcel, donde estaban los presos del rey, y estuvo allí en la casa de la cárcel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, 'Mas Jehová fué con José, y extendió á él su misericordia, y dióle gracia en ojos del principal de la casa de la cárcel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, 'Y el principal de la casa de la cárcel entregó en mano de José todos los presos que había en aquella prisión; todo lo que hacían allí, él lo hacía.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, 'No veía el principal de la cárcel cosa alguna que en su mano estaba; porque Jehová era con él, y lo que él hacía, Jehová lo prosperaba.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'Y ACONTECIÓ después de estas cosas, que el copero del rey de Egipto y el panadero delinquieron contra su señor el rey de Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'Y enojóse Faraón contra sus dos eunucos, contra el principal de los coperos, y contra el principal de los panaderos:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, 'Y púsolos en prisión en la casa del capitán de los de la guardia, en la casa de la cárcel donde José estaba preso.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, 'Y el capitán de los de la guardia dió cargo de ellos á José, y él les servía: y estuvieron días en la prisión.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, 'Y ambos á dos, el copero y el panadero del rey de Egipto, que estaban arrestados en la prisión, vieron un sueño, cada uno su sueño en una misma noche, cada uno conforme á la declaración de su sueño.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'Y vino á ellos José por la mañana, y mirólos, y he aquí que estaban tristes.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, 'Y él preguntó á aquellos eunucos de Faraón, que estaban con él en la prisión de la casa de su señor, diciendo: ¿Por qué parecen hoy mal vuestros semblantes?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, 'Y ellos le dijeron: Hemos tenido un sueño, y no hay quien lo declare. Entonces les dijo José: ¿No son de Dios las declaraciones? Contádmelo ahora.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, 'Entonces el principal de los coperos contó su sueño á José, y díjole: Yo soñaba que veía una vid delante de mí,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'Y en la vid tres sarmientos; y ella como que brotaba, y arrojaba su flor, viniendo á madurar sus racimos de uvas:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, 'Y que la copa de Faraón estaba en mi mano, y tomaba yo las uvas, y las exprimía en la copa de Faraón, y daba yo la copa en mano de Faraón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'Y díjole José: Esta es su declaración: Los tres sarmientos son tres días:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, 'Al cabo de tres días Faraón te hará levantar cabeza, y te restituirá á tu puesto: y darás la copa á Faraón en su mano, como solías cuando eras su copero.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, 'Acuérdate, pues, de mí para contigo cuando tuvieres ese bien, y ruégote que uses conmigo de misericordia, y hagas mención de mí á Faraón, y me saques de esta casa:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, 'Porque hurtado he sido de la tierra de los Hebreos; y tampoco he hecho aquí porqué me hubiesen de poner en la cárcel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, 'Y viendo el principal de los panaderos que había declarado para bien, dijo á José: También yo soñaba que veía tres canastillos blancos sobre mi cabeza;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'Y en el canastillo más alto había de todas las viandas de Faraón, obra de panadero; y que las aves las comían del canastillo de sobre mi cabeza.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'Entonces respondió José, y dijo: Esta es su declaración: Los tres canastillos tres días son;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, 'Al cabo de tres días quitará Faraón tu cabeza de sobre ti, y te hará colgar en la horca, y las aves comerán tu carne de sobre ti.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, 'Y fué el tercero día el día del nacimiento de Faraón, é hizo banquete á todos sus sirvientes: y alzó la cabeza del principal de los coperos, y la cabeza del principal de los panaderos, entre sus servidores.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, 'E hizo volver á su oficio al principal de los coperos; y dió él la copa en mano de Faraón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'Mas hizo ahorcar al principal de los panaderos, como le había declarado José.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, 'Y el principal de los coperos no se acordó de José, sino que le olvidó.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, 'Y ACONTECIÓ que pasados dos años tuvo Faraón un sueño: Parecíale que estaba junto al río;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, 'Y que del río subían siete vacas, hermosas á la vista, y muy gordas, y pacían en el prado:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'Y que otras siete vacas subían tras ellas del río, de fea vista, y enjutas de carne, y se pararon cerca de las vacas hermosas á la orilla del río:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'Y que las vacas de fea vista y enjutas de carne devoraban á las siete vacas hermosas y muy gordas. Y despertó Faraón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, 'Durmióse de nuevo, y soñó la segunda vez: Que siete espigas llenas y hermosas subían de una sola caña:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, 'Y que otras siete espigas menudas y abatidas del Solano, salían después de ellas:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'Y las siete espigas menudas devoraban á las siete espigas gruesas y llenas. Y despertó Faraón, y he aquí que era sueño.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'Y acaeció que á la mañana estaba agitado su espíritu; y envió é hizo llamar á todos los magos de Egipto, y á todos sus sabios: y contóles Faraón sus sueños, mas no había quien á Faraón los declarase.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, 'Entonces el principal de los coperos habló á Faraón, diciendo: Acuérdome hoy de mis faltas:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, 'Faraón se enojó contra sus siervos, y á mí me echó á la prisión de la casa del capitán de los de la guardia, á mí y al principal de los panaderos:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, 'Y yo y él vimos un sueño una misma noche: cada uno soñó conforme á la declaración de su sueño.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, 'Y estaba allí con nosotros un mozo Hebreo, sirviente del capitán de los de la guardia; y se lo contamos, y él nos declaró nuestros sueños, y declaró á cada uno conforme á su sueño.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'Y aconteció que como él nos declaró, así fué: á mí me hizo volver á mi puesto, é hizo colgar al otro.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, 'Entonces Faraón envió y llamó á José; é hiciéronle salir corriendo de la cárcel, y le cortaron el pelo, y mudaron sus vestidos, y vino á Faraón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'Y dijo Faraón á José: Yo he tenido un sueño, y no hay quien lo declare; mas he oído decir de ti, que oyes sueños para declararlos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, 'Y respondió José á Faraón, diciendo: No está en mí; Dios será el que responda paz á Faraón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'Entonces Faraón dijo á José: En mi sueño parecíame que estaba á la orilla del río:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, 'Y que del río subían siete vacas de gruesas carnes y hermosa apariencia, que pacían en el prado:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, 'Y que otras siete vacas subían después de ellas, flacas y de muy fea traza; tan extenuadas, que no he visto otras semejantes en toda la tierra de Egipto en fealdad:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'Y las vacas flacas y feas devoraban á las siete primeras vacas gruesas:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, 'Y entraban en sus entrañas, mas no se conocía que hubiesen entrado en ellas, porque su parecer era aún malo, como de primero. Y yo desperté.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, 'Vi también soñando, que siete espigas subían en una misma caña llenas y hermosas;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'Y que otras siete espigas menudas, marchitas, abatidas del Solano, subían después de ellas:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'Y las espigas menudas devoraban á las siete espigas hermosas: y helo dicho á los magos, mas no hay quien me lo declare.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'Entonces respondió José á Faraón: El sueño de Faraón es uno mismo: Dios ha mostrado á Faraón lo que va á hacer.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, 'Las siete vacas hermosas siete años son; y las espigas hermosas son siete años: el sueño es uno mismo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, 'También las siete vacas flacas y feas que subían tras ellas, son siete años; y las siete espigas menudas y marchitas del Solano, siete años serán de hambre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, 'Esto es lo que respondo á Faraón. Lo que Dios va á hacer, halo mostrado á Faraón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'He aquí vienen siete años de grande hartura en toda la tierra de Egipto:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'Y levantarse han tras ellos siete años de hambre; y toda la hartura será olvidada en la tierra de Egipto; y el hambre consumirá la tierra;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, 'Y aquella abundancia no se echará de ver á causa del hambre siguiente, la cual será gravísima.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'Y el suceder el sueño á Faraón dos veces, significa que la cosa es firme de parte de Dios, y que Dios se apresura á hacerla.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, 'Por tanto, provéase ahora Faraón de un varón prudente y sabio, y póngalo sobre la tierra de Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'Haga esto Faraón, y ponga gobernadores sobre el país, y quinte la tierra de Egipto en los siete años de la hartura;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, 'Y junten toda la provisión de estos buenos años que vienen, y alleguen el trigo bajo la mano de Faraón para mantenimiento de las ciudades; y guárdenlo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'Y esté aquella provisión en depósito para el país, para los siete años del hambre que serán en la tierra de Egipto; y el país no perecerá de hambre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, 'Y el negocio pareció bien á Faraón, y á sus siervos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, 'Y dijo Faraón á sus siervos: ¿Hemos de hallar otro hombre como éste, en quien haya espíritu de Dios?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'Y dijo Faraón á José: Pues que Dios te ha hecho saber todo esto, no hay entendido ni sabio como tú:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, 'Tú serás sobre mi casa, y por tu dicho se gobernará todo mi pueblo: solamente en el trono seré yo mayor que tú.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'Dijo más Faraón á José: He aquí yo te he puesto sobre toda la tierra de Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'Entonces Faraón quitó su anillo de su mano, y púsolo en la mano de José, é hízole vestir de ropas de lino finísimo, y puso un collar de oro en su cuello;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, 'E hízolo subir en su segundo carro, y pregonaron delante de él: Doblad la rodilla: y púsole sobre toda la tierra de Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'Y dijo Faraón á José: Yo Faraón; y sin ti ninguno alzará su mano ni su pie en toda la tierra de Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, 'Y llamó Faraón el nombre de José, Zaphnath-paaneah; y dióle por mujer á Asenath, hija de Potipherah, sacerdote de On. Y salió José por toda la tierra de Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, 'Y era José de edad de treinta años cuando fué presentado delante de Faraón, rey de Egipto: y salió José de delante de Faraón, y transitó por toda la tierra de Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, 'E hizo la tierra en aquellos siete años de hartura á montones.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'Y él juntó todo el mantenimiento de los siete años que fueron en la tierra de Egipto, y guardó mantenimiento en las ciudades, poniendo en cada ciudad el mantenimiento del campo de sus alrededores.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'Y acopió José trigo como arena de la mar, mucho en extremo, hasta no poderse contar, porque no tenía número.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, 'Y nacieron á José dos hijos antes que viniese el primer año del hambre, los cuales le parió Asenath, hija de Potipherah, sacerdote de On.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'Y llamó José el nombre del primogénito Manasés; porque Dios (dijo) me hizo olvidar todo mi trabajo, y toda la casa de mi padre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, 'Y el nombre del segundo llamólo Ephraim; porque Dios (dijo) me hizo fértil en la tierra de mi aflicción.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, 'Y cumpliéronse los siete años de la hartura, que hubo en la tierra de Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'Y comenzaron á venir los siete años del hambre, como José había dicho: y hubo hambre en todos los países, mas en toda la tierra de Egipto había pan.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'Y cuando se sintió el hambre en toda la tierra de Egipto, el pueblo clamó á Faraón por pan. Y dijo Faraón á todos los Egipcios: Id á José, y haced lo que él os dijere.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, 'Y el hambre estaba por toda la extensión del país. Entonces abrió José todo granero donde había, y vendía á los Egipcios; porque había crecido el hambre en la tierra de Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, 'Y toda la tierra venía á Egipto para comprar de José, porque por toda la tierra había crecido el hambre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, 'Y VIENDO Jacob que en Egipto había alimentos, dijo á sus hijos: ¿Por qué os estáis mirando?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'Y dijo: He aquí, yo he oído que hay víveres en Egipto; descended allá, y comprad de allí para nosotros, para que podamos vivir, y no nos muramos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'Y descendieron los diez hermanos de José á comprar trigo á Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'Mas Jacob no envió á Benjamín hermano de José con sus hermanos; porque dijo: No sea acaso que le acontezca algún desastre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'Y vinieron los hijos de Israel á comprar entre los que venían: porque había hambre en la tierra de Canaán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, 'Y José era el señor de la tierra, que vendía á todo el pueblo de la tierra: y llegaron los hermanos de José, é inclináronse á él rostro por tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'Y José como vió á sus hermanos, conociólos; mas hizo que no los conocía, y hablóles ásperamente, y les dijo: ¿De dónde habéis venido? Ellos respondieron: De la tierra de Canaán á comprar alimentos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'José, pues, conoció á sus hermanos; pero ellos no le conocieron.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'Entonces se acordó José de los sueños que había tenido de ellos, y díjoles: Espías sois; por ver lo descubierto del país habéis venido.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, 'Y ellos le respondieron: No, señor mío: mas tus siervos han venido á comprar alimentos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, 'Todos nosotros somos hijos de un varón: somos hombres de verdad: tus siervos nunca fueron espías.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, 'Y él les dijo: No; á ver lo descubierto del país habéis venido.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, 'Y ellos respondieron: Tus siervos somos doce hermanos, hijos de un varón en la tierra de Canaán; y he aquí el menor está hoy con nuestro padre, y otro no parece.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'Y José les dijo: Eso es lo que os he dicho, afirmando que sois espías:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, 'En esto seréis probados: Vive Faraón que no saldréis de aquí, sino cuando vuestro hermano menor aquí viniere.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, 'Enviad uno de vosotros, y traiga á vuestro hermano; y vosotros quedad presos, y vuestras palabras serán probadas, si hay verdad con vosotros: y si no, vive Faraón, que sois espías.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, 'Y juntólos en la cárcel por tres días.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'Y al tercer día díjoles José: Haced esto, y vivid: Yo temo á Dios:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, 'Si sois hombres de verdad, quede preso en la casa de vuestra cárcel uno de vuestros hermanos; y vosotros id, llevad el alimento para el hambre de vuestra casa:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, 'Pero habéis de traerme á vuestro hermano menor, y serán verificadas vuestras palabras, y no moriréis. Y ellos lo hicieron así.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, 'Y decían el uno al otro: Verdaderamente hemos pecado contra nuestro hermano, que vimos la angustia de su alma cuando nos rogaba, y no le oímos: por eso ha venido sobre nosotros esta angustia.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'Entonces Rubén les respondió, diciendo: ¿No os hablé yo y dije: No pequéis contra el mozo; y no escuchasteis? He aquí también su sangre es requerida.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, 'Y ellos no sabían que los entendía José, porque había intérprete entre ellos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'Y apartóse él de ellos, y lloró: después volvió á ellos, y les habló, y tomó de entre ellos á Simeón, y aprisionóle á vista de ellos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, 'Y mandó José que llenaran sus sacos de trigo, y devolviesen el dinero de cada uno de ellos, poniéndolo en su saco, y les diesen comida para el camino: é hízose así con ellos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, 'Y ellos pusieron su trigo sobre sus asnos, y fuéronse de allí.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, 'Y abriendo uno de ellos su saco para dar de comer á su asno en el mesón, vió su dinero que estaba en la boca de su costal.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, 'Y dijo á sus hermanos: Mi dinero se me ha devuelto, y aun helo aquí en mi saco. Sobresaltóseles entonces el corazón, y espantados dijeron el uno al otro: ¿Qué es esto que nos ha hecho Dios?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, 'Y venidos á Jacob su padre en tierra de Canaán, contáronle todo lo que les había acaecido, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, 'Aquel varón, señor de la tierra, nos habló ásperamente, y nos trató como á espías de la tierra:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, 'Y nosotros le dijimos: Somos hombres de verdad, nunca fuimos espías:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, 'Somos doce hermanos, hijos de nuestro padre; uno no parece, y el menor está hoy con nuestro padre en la tierra de Canaán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, 'Y aquel varón, señor de la tierra, nos dijo: En esto conoceré que sois hombres de verdad; dejad conmigo uno de vuestros hermanos, y tomad para el hambre de vuestras casas, y andad,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'Y traedme á vuestro hermano el menor, para que yo sepa que no sois espías, sino hombres de verdad: así os daré á vuestro hermano, y negociaréis en la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, 'Y aconteció que vaciando ellos sus sacos, he aquí que en el saco de cada uno estaba el atado de su dinero: y viendo ellos y su padre los atados de su dinero, tuvieron temor.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, 'Entonces su padre Jacob les dijo: Habéisme privado de mis hijos; José no parece, ni Simeón tampoco, y á Benjamín le llevaréis: contra mí son todas estas cosas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'Y Rubén habló á su padre, diciendo: Harás morir á mis dos hijos, si no te lo volviere; entrégalo en mi mano, que yo lo volveré á ti.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, 'Y él dijo: No descenderá mi hijo con vosotros; que su hermano es muerto, y él solo ha quedado: y si le aconteciere algún desastre en el camino por donde vais, haréis descender mis canas con dolor á la sepultura.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, 'Y EL hambre era grande en la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, 'Y aconteció que como acabaron de comer el trigo que trajeron de Egipto, díjoles su padre: Volved, y comprad para nosotros un poco de alimento.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'Y respondió Judá, diciendo: Aquel varón nos protestó con ánimo resuelto, diciendo: No veréis mi rostro sin vuestro hermano con vosotros.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, 'Si enviares á nuestro hermano con nosotros, descenderemos y te compraremos alimento:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'Pero si no le enviares, no descenderemos: porque aquel varón nos dijo: No veréis mi rostro sin vuestro hermano con vosotros.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, 'Y dijo Israel: ¿Por qué me hicisteis tanto mal, declarando al varón que teníais más hermano?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, 'Y ellos respondieron: Aquel varón nos preguntó expresamente por nosotros, y por nuestra parentela, diciendo: ¿Vive aún vuestro padre? ¿tenéis otro hermano? y declarámosle conforme á estas palabras. ¿Podíamos nosotros saber que había de decir: Haced venir á vuestro hermano?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'Entonces Judá dijo á Israel su padre: Envía al mozo conmigo, y nos levantaremos é iremos, á fin que vivamos y no muramos nosotros, y tú, y nuestros niños.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, 'Yo lo fío; á mí me pedirás cuenta de él: si yo no te lo volviere y lo pusiere delante de ti, seré para ti el culpante todos los días:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, 'Que si no nos hubiéramos detenido, cierto ahora hubiéramos ya vuelto dos veces.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, 'Entonces Israel su padre les respondió: Pues que así es, hacedlo; tomad de lo mejor de la tierra en vuestros vasos, y llevad á aquel varón un presente, un poco de bálsamo, y un poco de miel, aromas y mirra, nueces y almendras.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, 'Y tomad en vuestras manos doblado dinero, y llevad en vuestra mano el dinero vuelto en las bocas de vuestros costales; quizá fué yerro.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, 'Tomad también á vuestro hermano, y levantaos, y volved á aquel varón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'Y el Dios Omnipotente os dé misericordias delante de aquel varón, y os suelte al otro vuestro hermano, y á este Benjamín. Y si he de ser privado de mis hijos, séalo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, 'Entonces tomaron aquellos varones el presente, y tomaron en su mano doblado dinero, y á Benjamín; y se levantaron, y descendieron á Egipto, y presentáronse delante de José.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, 'Y vió José á Benjamín con ellos, y dijo al mayordomo de su casa: Mete en casa á esos hombres, y degüella víctima, y aderéza la; porque estos hombres comerán conmigo al medio día.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, 'E hizo el hombre como José dijo; y metió aquel hombre á los hombres en casa de José.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, 'Y aquellos hombres tuvieron temor, cuando fueron metidos en casa de José, y decían: Por el dinero que fué vuelto en nuestros costales la primera vez nos han metido aquí, para revolver contra nosotros, y dar sobre nosotros, y tomarnos por siervos á nosotros, y á nuestros asnos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, 'Y llegáronse al mayordomo de la casa de José, y le hablaron á la entrada de la casa.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, 'Y dijeron: Ay, señor mío, nosotros en realidad de verdad descendimos al principio á comprar alimentos:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'Y aconteció que como vinimos al mesón y abrimos nuestros costales, he aquí el dinero de cada uno estaba en la boca de su costal, nuestro dinero en su justo peso; y hémoslo vuelto en nuestras manos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, 'Hemos también traído en nuestras manos otro dinero para comprar alimentos: nosotros no sabemos quién haya puesto nuestro dinero en nuestros costales.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, 'Y él respondió: Paz á vosotros, no temáis; vuestro Dios y el Dios de vuestro padre os dió el tesoro en vuestros costales: vuestro dinero vino á mí. Y sacó á Simeón á ellos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'Y metió aquel varón á aquellos hombres en casa de José: y dióles agua, y lavaron sus pies: y dió de comer á sus asnos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, 'Y ellos prepararon el presente entretanto que venía José al medio día, porque habían oído que allí habían de comer pan.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, 'Y vino José á casa, y ellos le trajeron el presente que tenían en su mano dentro de casa, é inclináronse á él hasta tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, 'Entonces les preguntó él cómo estaban, y dijo: ¿Vuestro padre, el anciano que dijisteis, lo pasa bien? ¿vive todavía?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, 'Y ellos respondieron: Bien va á tu siervo nuestro padre; aun vive. Y se inclinaron, é hicieron reverencia.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'Y alzando él sus ojos vió á Benjamín su hermano, hijo de su madre, y dijo: ¿Es éste vuestro hermano menor, de quien me hablasteis? Y dijo: Dios tenga misericordia de ti, hijo mío.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'Entonces José se apresuró, porque se conmovieron sus entrañas á causa de su hermano, y procuró donde llorar: y entróse en su cámara, y lloró allí.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, 'Y lavó su rostro, y salió fuera, y reprimióse, y dijo: Poned pan.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'Y pusieron para él aparte, y separadamente para ellos, y aparte para los Egipcios que con él comían: porque los Egipcios no pueden comer pan con los Hebreos, lo cual es abominación á los Egipcios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, 'Y sentáronse delante de él, el mayor conforme á su mayoría, y el menor conforme á su menoría; y estaban aquellos hombres atónitos mirándose el uno al otro.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, 'Y él tomó viandas de delante de sí para ellos; mas la porción de Benjamín era cinco veces como cualquiera de las de ellos. Y bebieron, y alegráronse con él.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, 'Y MANDÓ José al mayordomo de su casa, diciendo: Hinche los costales de aquestos varones de alimentos, cuanto pudieren llevar, y pon el dinero de cada uno en la boca de su costal:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'Y pondrás mi copa, la copa de plata, en la boca del costal del menor, con el dinero de su trigo. Y él hizo como dijo José.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'Venida la mañana, los hombres fueron despedidos con sus asnos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'Habiendo ellos salido de la ciudad, de la que aun no se habían alejado, dijo José á su mayordomo: Levántate, y sigue á esos hombres; y cuando los alcanzares, diles: ¿Por qué habéis vuelto mal por bien?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, '¿No es ésta en la que bebe mi señor, y por la que suele adivinar? habéis hecho mal en lo que hicisteis.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, 'Y como él los alcanzó, díjoles estas palabras.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'Y ellos le respondieron: ¿Por qué dice mi señor tales cosas? Nunca tal hagan tus siervos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, 'He aquí, el dinero que hallamos en la boca de nuestros costales, te lo volvimos á traer desde la tierra de Canaán; ¿cómo, pues, habíamos de hurtar de casa de tu señor plata ni oro?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, 'Aquel de tus siervos en quien fuere hallada la copa, que muera, y aun nosotros seremos siervos de mi señor.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, 'Y él dijo: También ahora sea conforme á vuestras palabras; aquél en quien se hallare, será mi siervo, y vosotros seréis sin culpa.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, 'Ellos entonces se dieron prisa, y derribando cada uno su costal en tierra, abrió cada cual el costal suyo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, 'Y buscó; desde el mayor comenzó, y acabó en el menor; y la copa fué hallada en el costal de Benjamín.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, 'Entonces ellos rasgaron sus vestidos, y cargó cada uno su asno, y volvieron á la ciudad.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'Y llegó Judá con sus hermanos á casa de José, que aun estaba allí, y postráronse delante de él en tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'Y díjoles José: ¿Qué obra es esta que habéis hecho? ¿no sabéis que un hombre como yo sabe adivinar?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, 'Entonces dijo Judá: ¿Qué diremos á mi señor? ¿qué hablaremos? ¿ó con qué nos justificaremos? Dios ha hallado la maldad de tus siervos: he aquí, nosotros somos siervos de mi señor, nosotros, y también aquél en cuyo poder fué hallada la copa.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, 'Y él respondió: Nunca yo tal haga: el varón en cuyo poder fué hallada la copa, él será mi siervo; vosotros id en paz á vuestro padre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, 'Entonces Judá se llegó á él, y dijo: Ay señor mío, ruégote que hable tu siervo una palabra en oídos de mi señor, y no se encienda tu enojo contra tu siervo, pues que tú eres como Faraón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, 'Mi señor preguntó á sus siervos, diciendo: ¿Tenéis padre ó hermano?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, 'Y nosotros respondimos á mi señor: Tenemos un padre anciano, y un mozo que le nació en su vejez, pequeño aún; y un hermano suyo murió, y él quedó solo de su madre, y su padre lo ama.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, 'Y tú dijiste á tus siervos: Traédmelo, y pondré mis ojos sobre él.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'Y nosotros dijimos á mi señor: El mozo no puede dejar á su padre, porque si le dejare, su padre morirá.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, 'Y dijiste á tus siervos: Si vuestro hermano menor no descendiere con vosotros, no veáis más mi rostro.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, 'Aconteció pues, que como llegamos á mi padre tu siervo, contámosle las palabras de mi señor.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, 'Y dijo nuestro padre: Volved á comprarnos un poco de alimento.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, 'Y nosotros respondimos: No podemos ir: si nuestro hermano fuere con nosotros, iremos; porque no podemos ver el rostro del varón, no estando con nosotros nuestro hermano el menor.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'Entonces tu siervo mi padre nos dijo: Vosotros sabéis que dos me parió mi mujer;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'Y el uno salió de conmigo, y pienso de cierto que fué despedazado, y hasta ahora no le he visto;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, 'Y si tomareis también éste de delante de mí, y le aconteciere algún desastre, haréis descender mis canas con dolor á la sepultura.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, 'Ahora, pues, cuando llegare yo á tu siervo mi padre, y el mozo no fuere conmigo, como su alma está ligada al alma de él,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, 'Sucederá que cuando no vea al mozo, morirá: y tus siervos harán descender las canas de tu siervo nuestro padre con dolor á la sepultura.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, 'Como tu siervo salió por fiador del mozo con mi padre, diciendo: Si no te lo volviere, entonces yo seré culpable para mi padre todos los días;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'Ruégote por tanto que quede ahora tu siervo por el mozo por siervo de mi señor, y que el mozo vaya con sus hermanos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, 'Porque ¿cómo iré yo á mi padre sin el mozo? No podré, por no ver el mal que sobrevendrá á mi padre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, 'NO podía ya José contenerse delante de todos los que estaban al lado suyo, y clamó: Haced salir de conmigo á todos. Y no quedó nadie con él, al darse á conocer José á sus hermanos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'Entonces se dió á llorar á voz en grito; y oyeron los Egipcios, y oyó también la casa de Faraón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, 'Y dijo José á sus hermanos: Yo soy José: ¿vive aún mi padre? Y sus hermanos no pudieron responderle, porque estaban turbados delante de él.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'Entonces dijo José á sus hermanos: Llegaos ahora á mí. Y ellos se llegaron. Y él dijo: Yo soy José vuestro hermano el que vendisteis para Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'Ahora pues, no os entristezcáis, ni os pese de haberme vendido acá; que para preservación de vida me envió Dios delante de vosotros:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, 'Que ya ha habido dos años de hambre en medio de la tierra, y aun quedan cinco años en que ni habrá arada ni siega.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, 'Y Dios me envió delante de vosotros, para que vosotros quedaseis en la tierra, y para daros vida por medio de grande salvamento.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, 'Así pues, no me enviasteis vosotros acá, sino Dios, que me ha puesto por padre de Faraón, y por señor de toda su casa, y por gobernador en toda la tierra de Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, 'Daos priesa, id á mi padre y decidle: Así dice tu hijo José: Dios me ha puesto por señor de todo Egipto; ven á mí, no te detengas:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, 'Y habitarás en la tierra de Gosén, y estarás cerca de mí, tú y tus hijos, y los hijos de tus hijos, tus ganados y tus vacas, y todo lo que tienes.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'Y allí te alimentaré, pues aun quedan cinco años de hambre, porque no perezcas de pobreza tú y tu casa, y todo lo que tienes:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, 'Y he aquí, vuestros ojos ven, y los ojos de mi hermano Benjamín, que mi boca os habla.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, 'Haréis pues saber á mi padre toda mi gloria en Egipto, y todo lo que habéis visto: y daos priesa, y traed á mi padre acá.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, 'Y echóse sobre el cuello de Benjamín su hermano, y lloró; y también Benjamín lloró sobre su cuello.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'Y besó á todos sus hermanos, y lloró sobre ellos: y después sus hermanos hablaron con él.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, 'Y oyóse la noticia en la casa de Faraón, diciendo: Los hermanos de José han venido. Y plugo en los ojos de Faraón y de sus siervos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'Y dijo Faraón á José: Di á tus hermanos: Haced esto: cargad vuestras bestias, é id, volved á la tierra de Canaán;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'Y tomad á vuestro padre y vuestras familias, y venid á mí, que yo os daré lo bueno de la tierra de Egipto y comeréis la grosura de la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, 'Y tú manda: Haced esto: tomaos de la tierra de Egipto carros para vuestros niños y vuestras mujeres; y tomad á vuestro padre, y venid.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'Y no se os dé nada de vuestras alhajas, porque el bien de la tierra de Egipto será vuestro.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, 'E hiciéronlo así los hijos de Israel: y dióles José carros conforme á la orden de Faraón, y suministróles víveres para el camino.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, 'A cada uno de todos ellos dió mudas de vestidos, y á Benjamín dió trescientas piezas de plata, y cinco mudas de vestidos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, 'Y á su padre envió esto: diez asnos cargados de lo mejor de Egipto, y diez asnas cargadas de trigo, y pan y comida, para su padre en el camino.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, 'Y despidió á sus hermanos, y fuéronse. Y él les dijo: No riñáis por el camino.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'Y subieron de Egipto, y llegaron á la tierra de Canaán á Jacob su padre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, 'Y diéronle las nuevas, diciendo: José vive aún; y él es señor en toda la tierra de Egipto. Y su corazón se desmayó; pues no los creía.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, 'Y ellos le contaron todas las palabras de José, que él les había hablado; y viendo él los carros que José enviaba para llevarlo, el espíritu de Jacob su padre revivió.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, 'Entonces dijo Israel: Basta; José mi hijo vive todavía: iré, y le veré antes que yo muera.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'Y PARTIÓSE Israel con todo lo que tenía, y vino á Beer-seba, y ofreció sacrificios al Dios de su padre Isaac.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, 'Y habló Dios á Israel en visiones de noche, y dijo: Jacob, Jacob. Y él respondió: Heme aquí.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, 'Y dijo: Yo soy Dios, el Dios de tu padre; no temas de descender á Egipto, porque yo te pondré allí en gran gente.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, 'Yo descenderé contigo á Egipto, y yo también te haré volver: y José pondrá su mano sobre tus ojos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'Y levantóse Jacob de Beer-seba; y tomaron los hijos de Israel á su padre Jacob, y á sus niños, y á sus mujeres, en los carros que Faraón había enviado para llevarlo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'Y tomaron sus ganados, y su hacienda que había adquirido en la tierra de Canaán, y viniéronse á Egipto, Jacob, y toda su simiente consigo;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'Sus hijos, y los hijos de sus hijos consigo; sus hijas, y las hijas de sus hijos, y á toda su simiente trajo consigo á Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, 'Y estos son los nombres de los hijos de Israel, que entraron en Egipto, Jacob y sus hijos: Rubén, el primogénito de Jacob.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'Y los hijos de Rubén: Hanoch, y Phallu, y Hezrón, y Carmi.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, 'Y los hijos de Simeón: Jemuel, y Jamín, y Ohad, y Jachîn, y Zohar, y Saúl, hijo de la Cananea.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, 'Y los hijos de Leví: Gersón, y Coath, y Merari.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, 'Y los hijos de Judá: Er, y Onán, y Sela, y Phares, y Zara: mas Er y Onán, murieron en la tierra de Canaán. Y los hijos de Phares fueron Hezrón y Hamul.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, 'Y los hijos de Issachâr: Thola, y Phua, y Job, y Simrón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, 'Y los hijos de Zabulón: Sered, y Elón, y Jahleel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, 'Estos fueron los hijos de Lea, los que parió á Jacob en Padan-aram, y además su hija Dina: treinta y tres las almas todas de sus hijos é hijas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'Y los hijos de Gad: Ziphión, y Aggi, y Ezbón, y Suni, y Heri, y Arodi, y Areli.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, 'Y los hijos de Aser: Jimna, é Ishua, é Isui, y Beria, y Sera, hermana de ellos. Los hijos de Beria: Heber, y Malchîel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, 'Estos fueron los hijos de Zilpa, la que Labán dió á su hija Lea, y parió estos á Jacob; todas diez y seis almas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'Y los hijos de Rachêl, mujer de Jacob: José y Benjamín.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'Y nacieron á José en la tierra de Egipto Manasés y Ephraim, los que le parió Asenath, hija de Potipherah, sacerdote de On.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, 'Y los hijos de Benjamín fueron Bela, y Bechêr y Asbel, y Gera, y Naamán, y Ehi, y Ros y Muppim, y Huppim, y Ard.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, 'Estos fueron los hijos de Rachêl, que nacieron á Jacob: en todas, catorce almas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'Y los hijos de Dan: Husim.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, 'Y los hijos de Nephtalí: Jahzeel, y Guni, y Jezer, y Shillem.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, 'Estos fueron los hijos de Bilha, la que dió Labán á Rachêl su hija, y parió estos á Jacob; todas siete almas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'Todas las personas que vinieron con Jacob á Egipto, procedentes de sus lomos, sin las mujeres de los hijos de Jacob, todas las personas fueron sesenta y seis.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'Y los hijos de José, que le nacieron en Egipto, dos personas. Todas las almas de la casa de Jacob, que entraron en Egipto, fueron setenta.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'Y envió á Judá delante de sí á José, para que le viniese á ver á Gosén; y llegaron á la tierra de Gosén.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, 'Y José unció su carro y vino á recibir á Israel su padre á Gosén; y se manifestó á él, y echóse sobre su cuello, y lloró sobre su cuello bastante.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'Entonces Israel dijo á José: Muera yo ahora, ya que he visto tu rostro, pues aun vives.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, 'Y José dijo á sus hermanos, y á la casa de su padre: Subiré y haré saber á Faraón, y diréle: Mis hermanos y la casa de mi padre, que estaban en la tierra de Canaán, han venido á mí;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'Y los hombres son pastores de ovejas, porque son hombres ganaderos: y han traído sus ovejas y sus vacas, y todo lo que tenían.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'Y cuando Faraón os llamare y dijere: ¿cuál es vuestro oficio?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, 'Entonces diréis: Hombres de ganadería han sido tus siervos desde nuestra mocedad hasta ahora, nosotros y nuestros padres; á fin que moréis en la tierra de Gosén, porque los Egipcios abominan todo pastor de ovejas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, 'Y JOSÉ vino, é hizo saber á Faraón, y dijo: Mi padre y mis hermanos, y sus ovejas y sus vacas, con todo lo que tienen, han venido de la tierra de Canaán, y he aquí, están en la tierra de Gosén.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'Y de los postreros de sus hermanos tomó cinco varones, y presentólos delante de Faraón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'Y Faraón dijo á sus hermanos: ¿Cuál es vuestro oficio? Y ellos respondieron á Faraón: Pastores de ovejas son tus siervos, así nosotros como nuestros padres.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'Dijeron además á Faraón: Por morar en esta tierra hemos venido; porque no hay pasto para las ovejas de tus siervos, pues el hambre es grave en la tierra de Canaán: por tanto, te rogamos ahora que habiten tus siervos en la tierra de Gosén.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, 'Entonces Faraón habló á José, diciendo: Tu padre y tus hermanos han venido á ti;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, 'La tierra de Egipto delante de ti está; en lo mejor de la tierra haz habitar á tu padre y á tus hermanos; habiten en la tierra de Gosén; y si entiendes que hay entre ellos hombres eficaces, ponlos por mayorales del ganado mío.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'Y José introdujo á su padre, y presentólo delante de Faraón; y Jacob bendijo á Faraón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'Y dijo Faraón á Jacob: ¿Cuántos son los días de los años de tu vida?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'Y Jacob respondió á Faraón: Los días de los años de mi peregrinación son ciento treinta años; pocos y malos han sido los días de los años de mi vida, y no han llegado á los días de los años de la vida de mis padres en los días de su peregrinación.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'Y Jacob bendijo á Faraón, y salióse de delante de Faraón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'Así José hizo habitar á su padre y á sus hermanos, y dióles posesión en la tierra de Egipto, en lo mejor de la tierra, en la tierra de Rameses como mandó Faraón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'Y alimentaba José á su padre y á sus hermanos, y á toda la casa de su padre, de pan, hasta la boca del niño.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, 'Y no había pan en toda la tierra, y el hambre era muy grave; por lo que desfalleció de hambre la tierra de Egipto y la tierra de Canaán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'Y recogió José todo el dinero que se halló en la tierra de Egipto y en la tierra de Canaán, por los alimentos que de él compraban; y metió José el dinero en casa de Faraón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'Y acabado el dinero de la tierra de Egipto y de la tierra de Canaán, vino todo Egipto á José diciendo: Danos pan: ¿por qué moriremos delante de ti, por haberse acabado el dinero?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'Y José dijo: Dad vuestros ganados, y yo os daré por vuestros ganados, si se ha acabado el dinero.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'Y ellos trajeron sus ganados á José; y José les dió alimentos por caballos, y por el ganado de las ovejas, y por el ganado de las vacas, y por asnos: y sustentólos de pan por todos sus ganados aquel año.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'Y acabado aquel año, vinieron á él el segundo año, y le dijeron: No encubriremos á nuestro señor que el dinero ciertamente se ha acabado; también el ganado es ya de nuestro señor; nada ha quedado delante de nuestro señor sino nuestros cuerpos y nuestra tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, '¿Por qué moriremos delante de tus ojos, así nosotros como nuestra tierra? Cómpranos á nosotros y á nuestra tierra por pan, y seremos nosotros y nuestra tierra siervos de Faraón: y danos simiente para que vivamos y no muramos, y no sea asolada la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, 'Entonces compró José toda la tierra de Egipto para Faraón; pues los Egipcios vendieron cada uno sus tierras, porque se agravó el hambre sobre ellos: y la tierra vino á ser de Faraón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'Y al pueblo hízolo pasar á las ciudades desde el un cabo del término de Egipto hasta el otro cabo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, 'Solamente la tierra de los sacerdotes no compró, por cuanto los sacerdotes tenían ración de Faraón, y ellos comían su ración que Faraón les daba: por eso no vendieron su tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, 'Y José dijo al pueblo: He aquí os he hoy comprado y á vuestra tierra para Faraón: ved aquí simiente, y sembraréis la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'Y será que de los frutos daréis el quinto á Faraón, y las cuatro partes serán vuestras para sembrar las tierras, y para vuestro mantenimiento, y de los que están en vuestras casas, y para que coman vuestros niños.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, 'Y ellos respondieron: La vida nos has dado: hallemos gracia en ojos de mi señor, y seamos siervos de Faraón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'Entonces José lo puso por fuero hasta hoy sobre la tierra de Egipto, señalando para Faraón el quinto; excepto sólo la tierra de los sacerdotes, que no fué de Faraón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, 'Así habitó Israel en la tierra de Egipto, en la tierra de Gosén; y aposesionáronse en ella, y se aumentaron, y multiplicaron en gran manera.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'Y vivió Jacob en la tierra de Egipto diecisiete años: y fueron los días de Jacob, los años de su vida, ciento cuarenta y siete años.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, 'Y llegáronse los días de Israel para morir, y llamó á José su hijo, y le dijo: Si he hallado ahora gracia en tus ojos, ruégote que pongas tu mano debajo de mi muslo, y harás conmigo misericordia y verdad; ruégote que no me entierres en Egipto;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, 'Mas cuando durmiere con mis padres, llevarme has de Egipto, y me sepultarás en el sepulcro de ellos. Y él respondió: Yo haré como tú dices.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, 'Y él dijo: Júramelo. Y él le juró. Entonces Israel se inclinó sobre la cabecera de la cama.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, 'Y SUCEDIÓ después de estas cosas el haberse dicho á José: He aquí tu padre está enfermo. Y él tomó consigo sus dos hijos Manasés y Ephraim.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, 'Y se hizo saber á Jacob, diciendo: He aquí tu hijo José viene á ti. Entonces se esforzó Israel, y sentóse sobre la cama;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'Y dijo á José: El Dios Omnipotente me apareció en Luz en la tierra de Canaán, y me bendijo,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, 'Y díjome: He aquí, yo te haré crecer, y te multiplicaré, y te pondré por estirpe de pueblos: y daré esta tierra á tu simiente después de ti por heredad perpetua.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'Y ahora tus dos hijos Ephraim y Manasés, que te nacieron en la tierra de Egipto, antes que viniese á ti á la tierra de Egipto, míos son; como Rubén y Simeón, serán míos:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, 'Y los que después de ellos has engendrado, serán tuyos; por el nombre de sus hermanos serán llamados en sus heredades.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, 'Porque cuando yo venía de Padan-aram, se me murió Rachêl en la tierra de Canaán, en el camino, como media legua de tierra viniendo á Ephrata; y sepultéla allí en el camino de Ephrata, que es Bethlehem.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, 'Y vió Israel los hijos de José, y dijo: ¿Quiénes son éstos?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'Y respondió José á su padre: Son mis hijos, que Dios me ha dado aquí. Y él dijo: Allégalos ahora á mí, y los bendeciré.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, 'Y los ojos de Israel estaban tan agravados de la vejez, que no podía ver. Hízoles, pues, llegar á él, y él los besó y abrazó.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'Y dijo Israel á José: No pensaba yo ver tu rostro, y he aquí Dios me ha hecho ver también tu simiente.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'Entonces José los sacó de entre sus rodillas, é inclinóse á tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'Y tomólos José á ambos, Ephraim á su diestra, á la siniestra de Israel; y á Manasés á su izquierda, á la derecha de Israel; é hízoles llegar á él.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'Entonces Israel extendió su diestra, y púsola sobre la cabeza de Ephraim, que era el menor, y su siniestra sobre la cabeza de Manasés, colocando así sus manos adrede, aunque Manasés era el primogénito.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, 'Y bendijo á José, y dijo: El Dios en cuya presencia anduvieron mis padres Abraham é Isaac, el Dios que me mantiene desde que yo soy hasta este día,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, 'El Angel que me liberta de todo mal, bendiga á estos mozos: y mi nombre sea llamado en ellos, y el nombre de mis padres Abraham é Isaac: y multipliquen en gran manera en medio de la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'Entonces viendo José que su padre ponía la mano derecha sobre la cabeza de Ephraim, causóle esto disgusto; y asió la mano de su padre, para mudarla de sobre la cabeza de Ephraim á la cabeza de Manasés.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, 'Y dijo José á su padre: No así, padre mío, porque éste es el primogénito; pon tu diestra sobre su cabeza.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, 'Mas su padre no quiso, y dijo: Lo sé, hijo mío, lo sé: también él vendrá á ser un pueblo, y será también acrecentado; pero su hermano menor será más grande que él, y su simiente será plenitud de gentes.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, 'Y bendíjolos aquel día, diciendo: En ti bendecirá Israel, diciendo: Póngate Dios como á Ephraim y como á Manasés. Y puso á Ephraim delante de Manasés.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'Y dijo Israel á José: He aquí, yo muero, mas Dios será con vosotros, y os hará volver á la tierra de vuestros padres.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, 'Y yo te he dado á ti una parte sobre tus hermanos, la cual tomé yo de mano del Amorrheo con mi espada y con mi arco.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, 'Y LLAMÓ Jacob á sus hijos, y dijo: Juntaos, y os declararé lo que os ha de acontecer en los postreros días.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, 'Juntaos y oid, hijos de Jacob; y escuchad á vuestro padre Israel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, 'Rubén, tú eres mi primogénito, mi fortaleza, y el principio de mi vigor; principal en dignidad, principal en poder.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, 'Corriente como las aguas, no seas el principal; por cuanto subiste al lecho de tu padre: entonces te envileciste, subiendo á mi estrado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, 'Simeón y Leví, hermanos: armas de iniquidad sus armas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, 'En su secreto no entre mi alma, ni mi honra se junte en su compañía; que en su furor mataron varón, y en su voluntad arrancaron muro.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, 'Maldito su furor, que fué fiero; y su ira, que fué dura: yo los apartaré en Jacob, y los esparciré en Israel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, 'Judá, alabarte han tus hermanos: tu mano en la cerviz de tus enemigos: los hijos de tu padre se inclinarán á ti.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, 'Cachorro de león Judá: de la presa subiste, hijo mío: encorvóse, echóse como león, así como león viejo; ¿quién lo despertará?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, 'No será quitado el cetro de Judá, y el legislador de entre sus piés, hasta que venga Shiloh; y á él se congregarán los pueblos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, 'Atando á la vid su pollino, y á la cepa el hijo de su asna, lavó en el vino su vestido, y en la sangre de uvas su manto:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'Sus ojos bermejos del vino, y los dientes blancos de la leche.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, 'Zabulón en puertos de mar habitará, y será para puerto de navíos; y su término hasta Sidón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, 'Issachâr, asno huesudo echado entre dos tercios:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, 'Y vió que el descanso era bueno, y que la tierra era deleitosa; y bajó su hombro para llevar, y sirvió en tributo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, 'Dan juzgará á su pueblo, como una de las tribus de Israel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'Será Dan serpiente junto al camino, cerasta junto á la senda, que muerde los talones de los caballos, y hace caer por detrás al cabalgador de ellos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'Tu salud esperé, oh Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, 'Gad, ejército lo acometerá; mas él acometerá al fin.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, 'El pan de Aser será grueso, y él dará deleites al rey.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, 'Nephtalí, sierva dejada, que dará dichos hermosos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, 'Ramo fructífero José, ramo fructífero junto á fuente, cuyos vástagos se extienden sobre el muro.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, 'Y causáronle amargura, y asaeteáronle, y aborreciéronle los archeros:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, 'Mas su arco quedó en fortaleza, y los brazos de sus manos se corroboraron por las manos del Fuerte de Jacob, (de allí el pastor, y la piedra de Israel,)');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, 'Del Dios de tu padre, el cual te ayudará, y del Omnipotente, el cual te bendecirá con bendiciones de los cielos de arriba, con bendiciones del abismo que está abajo, con bendiciones del seno y de la matriz.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, 'Las bendiciones de tu padre fueron mayores que las bendiciones de mis progenitores: hasta el término de los collados eternos serán sobre la cabeza de José, y sobre la mollera del Nazareo de sus hermanos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, 'Benjamín, lobo arrebatador: á la mañana comerá la presa, y á la tarde repartirá los despojos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, 'Todos estos fueron las doce tribus de Israel: y esto fué lo que su padre les dijo, y bendíjolos; á cada uno por su bendición los bendijo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'Mandóles luego, y díjoles: Yo voy á ser reunido con mi pueblo: sepultadme con mis padres en la cueva que está en el campo de Ephrón el Hetheo;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'En la cueva que está en el campo de Macpela, que está delante de Mamre en la tierra de Canaán, la cual compró Abraham con el mismo campo de Ephrón el Hetheo, para heredad de sepultura.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'Allí sepultaron á Abraham y á Sara su mujer; allí sepultaron á Isaac y á Rebeca su mujer; allí también sepulté yo á Lea.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, 'La compra del campo y de la cueva que está en él, fué de los hijos de Heth.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 33, 'Y como acabó Jacob de dar órdenes á sus hijos, encogió sus pies en la cama, y espiró: y fué reunido con sus padres.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, 'ENTONCES se echó José sobre el rostro de su padre, y lloró sobre él, y besólo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, 'Y mandó José á sus médicos familiares que embalsamasen á su padre: y los médicos embalsamaron á Israel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'Y cumpliéronle cuarenta días, porque así cumplían los días de los embalsamados, y lloráronlo los Egipcios setenta días.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, 'Y pasados los días de su luto, habló José á los de la casa de Faraón, diciendo: Si he hallado ahora gracia en vuestros ojos, os ruego que habléis en oídos de Faraón, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, 'Mi padre me conjuró diciendo: He aquí yo muero; en mi sepulcro que yo cavé para mí en la tierra de Canaán, allí me sepultarás; ruego pues que vaya yo ahora, y sepultaré á mi padre, y volveré.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'Y Faraón dijo: Ve, y sepulta á tu padre, como él te conjuró.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, 'Entonces José subió á sepultar á su padre; y subieron con él todos los siervos de Faraón, los ancianos de su casa, y todos los ancianos de la tierra de Egipto,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'Y toda la casa de José, y sus hermanos, y la casa de su padre: solamente dejaron en la tierra de Gosén sus niños, y sus ovejas y sus vacas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'Y subieron también con él carros y gente de á caballo, é hízose un escuadrón muy grande.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, 'Y llegaron hasta la era de Atad, que está á la otra parte del Jordán, y endecharon allí con grande y muy grave lamentación: y José hizo á su padre duelo por siete días.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'Y viendo los moradores de la tierra, los Cananeos, el llanto en la era de Atad, dijeron: Llanto grande es este de los Egipcios: por eso fué llamado su nombre Abelmizraim, que está á la otra parte del Jordán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'Hicieron, pues, sus hijos con él, según les había mandado:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'Pues lleváronlo sus hijos á la tierra de Canaán, y le sepultaron en la cueva del campo de Macpela, la que había comprado Abraham con el mismo campo, para heredad de sepultura, de Ephrón el Hetheo, delante de Mamre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'Y tornóse José á Egipto, él y sus hermanos, y todos los que subieron con él á sepultar á su padre, después que le hubo sepultado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'Y viendo los hermanos de José que su padre era muerto, dijeron: Quizá nos aborrecerá José, y nos dará el pago de todo el mal que le hicimos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'Y enviaron á decir á José: Tu padre mandó antes de su muerte, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, 'Así diréis á José: Ruégote que perdones ahora la maldad de tus hermanos y su pecado, porque mal te trataron: por tanto ahora te rogamos que perdones la maldad de los siervos del Dios de tu padre. Y José lloró mientras hablaban.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'Y vinieron también sus hermanos, y postráronse delante de él, y dijeron: Henos aquí por tus siervos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'Y respondióles José: No temáis: ¿estoy yo en lugar de Dios?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'Vosotros pensasteis mal sobre mí, mas Dios lo encaminó á bien, para hacer lo que vemos hoy, para mantener en vida á mucho pueblo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'Ahora, pues, no tengáis miedo; yo os sustentaré á vosotros y á vuestros hijos. Así los consoló, y les habló al corazón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'Y estuvo José en Egipto, él y la casa de su padre: y vivió José ciento diez años.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'Y vió José los hijos de Ephraim hasta la tercera generación: también los hijos de Machîr, hijo de Manasés, fueron criados sobre las rodillas de José.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'Y José dijo á sus hermanos: Yo me muero; mas Dios ciertamente os visitará, y os hará subir de aquesta tierra á la tierra que juró á Abraham, á Isaac, y á Jacob.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'Y conjuró José á los hijos de Israel, diciendo: Dios ciertamente os visitará, y haréis llevar de aquí mis huesos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, 'Y murió José de edad de ciento diez años; y embalsamáronlo, y fué puesto en un ataúd en Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'ESTOS son los nombres de los hijos de Israel, que entraron en Egipto con Jacob; cada uno entró con su familia.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'Rubén, Simeón, Leví y Judá;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'Issachâr, Zabulón y Benjamín;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'Dan y Nephtalí, Gad y Aser.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'Y todas las almas de los que salieron del muslo de Jacob, fueron setenta. Y José estaba en Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'Y murió José, y todos sus hermanos, y toda aquella generación.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'Y los hijos de Israel crecieron, y multiplicaron, y fueron aumentados y corroborados en extremo; y llenóse la tierra de ellos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, 'Levantóse entretanto un nuevo rey sobre Egipto, que no conocía á José; el cual dijo á su pueblo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, 'He aquí, el pueblo de los hijos de Israel es mayor y más fuerte que nosotros:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'Ahora, pues, seamos sabios para con él, porque no se multiplique, y acontezca que viniendo guerra, él también se junte con nuestros enemigos, y pelee contra nosotros, y se vaya de la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'Entonces pusieron sobre él comisarios de tributos que los molestasen con sus cargas; y edificaron á Faraón las ciudades de los bastimentos, Phithom y Raamses.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'Empero cuanto más los oprimían, tanto más se multiplicaban y crecían: así que estaban ellos fastidiados de los hijos de Israel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'Y los Egipcios hicieron servir á los hijos de Israel con dureza:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'Y amargaron su vida con dura servidumbre, en hacer barro y ladrillo, y en toda labor del campo, y en todo su servicio, al cual los obligaban con rigorismo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'Y habló el rey de Egipto á las parteras de las Hebreas, una de las cuales se llamaba Siphra, y otra Phúa, y díjoles:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, 'Cuando parteareis á las Hebreas, y mirareis los asientos, si fuere hijo, matadlo; y si fuere hija, entonces viva.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'Mas las parteras temieron á Dios, y no hicieron como les mandó el rey de Egipto, sino que reservaban la vida á los niños.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'Y el rey de Egipto hizo llamar á las parteras, y díjoles: Por qué habéis hecho esto, que habéis reservado la vida á los niños?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, 'Y las parteras respondieron á Faraón: Porque las mujeres Hebreas no son como las Egipcias: porque son robustas, y paren antes que la partera venga á ellas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'Y Dios hizo bien á las parteras: y el pueblo se multiplicó, y se corroboraron en gran manera.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'Y por haber las parteras temido á Dios, él les hizo casas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, 'Entonces Faraón mandó á todo su pueblo, diciendo: Echad en el río todo hijo que naciere, y á toda hija reservad la vida.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, 'UN varón de la familia de Leví fué, y tomó por mujer una hija de Leví:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, 'La cual concibió, y parió un hijo: y viéndolo que era hermoso, túvole escondido tres meses.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'Pero no pudiendo ocultarle más tiempo, tomó una arquilla de juncos, y calafateóla con pez y betún, y colocó en ella al niño, y púsolo en un carrizal á la orilla del río:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'Y paróse una hermana suya á lo lejos, para ver lo que le acontecería.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, 'Y la hija de Faraón descendió á lavarse al río, y paseándose sus doncellas por la ribera del río, vió ella la arquilla en el carrizal, y envió una criada suya á que la tomase.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'Y como la abrió, vió al niño; y he aquí que el niño lloraba. Y teniendo compasión de él, dijo: De los niños de los Hebreos es éste.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'Entonces su hermana dijo á la hija de Faraón: ¿Iré á llamarte un ama de las Hebreas, para que te críe este niño?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, 'Y la hija de Faraón respondió: Ve. Entonces fué la doncella, y llamó á la madre del niño;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'A la cual dijo la hija de Faraón: Lleva este niño, y críamelo, y yo te lo pagaré. Y la mujer tomó al niño, y criólo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'Y como creció el niño, ella lo trajo á la hija de Faraón, la cual lo prohijó, y púsole por nombre Moisés, diciendo: Porque de las aguas lo saqué.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, 'Y en aquellos días acaeció que, crecido ya Moisés, salió á sus hermanos, y vió sus cargas: y observó á un Egipcio que hería á uno de los Hebreos, sus hermanos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'Y miró á todas partes, y viendo que no parecía nadie, mató al Egipcio, y escondiólo en la arena.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'Y salió al día siguiente, y viendo á dos Hebreos que reñían, dijo al que hacía la injuria: ¿Por qué hieres á tu prójimo?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, 'Y él respondió: ¿Quién te ha puesto á ti por príncipe y juez sobre nosotros? ¿piensas matarme como mataste al Egipcio? Entonces Moisés tuvo miedo, y dijo: Ciertamente esta cosa es descubierta.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'Y oyendo Faraón este negocio, procuró matar á Moisés: mas Moisés huyó de delante de Faraón, y habitó en la tierra de Madián; y sentóse junto á un pozo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'Tenía el sacerdote de Madián siete hijas, las cuales vinieron á sacar agua, para llenar las pilas y dar de beber á las ovejas de su padre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'Mas los pastores vinieron, y echáronlas: Entonces Moisés se levantó y defendiólas, y abrevó sus ovejas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'Y volviendo ellas á Ragüel su padre, díjoles él: ¿Por qué habéis hoy venido tan presto?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'Y ellas respondieron: Un varón Egipcio nos defendió de mano de los pastores, y también nos sacó el agua, y abrevó las ovejas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, 'Y dijo á sus hijas: ¿Y dónde está? ¿por qué habéis dejado ese hombre? llamadle para que coma pan.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'Y Moisés acordó en morar con aquel varón; y él dió á Moisés á su hija Séphora:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'La cual le parió un hijo, y él le puso por nombre Gersom: porque dijo: Peregrino soy en tierra ajena.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, 'Y aconteció que después de muchos días murió el rey de Egipto, y los hijos de Israel suspiraron á causa de la servidumbre, y clamaron: y subió á Dios el clamor de ellos con motivo de su servidumbre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'Y oyó Dios el gemido de ellos, y acordóse de su pacto con Abraham, Isaac y Jacob.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'Y miró Dios á los hijos de Israel, y reconociólos Dios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'Y APACENTANDO Moisés las ovejas de Jethro su suegro, sacerdote de Madián, llevó las ovejas detrás del desierto, y vino á Horeb, monte de Dios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'Y apareciósele el Angel de Jehová en una llama de fuego en medio de una zarza: y él miró, y vió que la zarza ardía en fuego, y la zarza no se consumía.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'Entonces Moisés dijo: Iré yo ahora, y veré esta grande visión, por qué causa la zarza no se quema.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'Y viendo Jehová que iba á ver, llamólo Dios de en medio de la zarza, y dijo: ¡Moisés, Moisés! Y él respondió: Heme aquí.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, 'Y dijo: No te llegues acá: quita tus zapatos de tus pies, porque el lugar en que tú estás, tierra santa es.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'Y dijo: Yo soy el Dios de tu padre, Dios de Abraham, Dios de Isaac, Dios de Jacob. Entonces Moisés cubrió su rostro, porque tuvo miedo de mirar á Dios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'Y dijo Jehová: Bien he visto la aflicción de mi pueblo que está en Egipto, y he oído su clamor á causa de sus exactores; pues tengo conocidas sus angustias:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'Y he descendido para librarlos de mano de los Egipcios, y sacarlos de aquella tierra á una tierra buena y ancha, á tierra que fluye leche y miel, á los lugares del Cananeo, del Hetheo, del Amorrheo, del Pherezeo, del Heveo, y del Jebuseo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'El clamor, pues, de los hijos de Israel ha venido delante de mí, y también he visto la opresión con que los Egipcios los oprimen.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'Ven por tanto ahora, y enviarte he á Faraón, para que saques á mi pueblo, los hijos de Israel, de Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, 'Entonces Moisés respondió á Dios: ¿Quién soy yo, para que vaya á Faraón, y saque de Egipto á los hijos de Israel?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, 'Y él le respondió: Ve, porque yo seré contigo; y esto te será por señal de que yo te he enviado: luego que hubieres sacado este pueblo de Egipto, serviréis á Dios sobre este monte.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'Y dijo Moisés á Dios: He aquí que llego yo á los hijos de Israel, y les digo, El Dios de vuestros padres me ha enviado á vosotros; si ellos me preguntaren: ¿Cuál es su nombre? ¿qué les responderé?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, 'Y respondió Dios á Moisés: YO SOY EL QUE SOY. Y dijo: Así dirás á los hijos de Israel: YO SOY me ha enviado á vosotros.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'Y dijo más Dios á Moisés: Así dirás á los hijos de Israel: Jehová, el Dios de vuestros padres, el Dios de Abraham, Dios de Isaac y Dios de Jacob, me ha enviado á vosotros. Este es mi nombre para siempre, este es mi memorial por todos los siglos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, 'Ve, y junta los ancianos de Israel, y diles: Jehová, el Dios de vuestros padres, el Dios de Abraham, de Isaac, y de Jacob, me apareció, diciendo: De cierto os he visitado, y visto lo que se os hace en Egipto;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'Y he dicho: Yo os sacaré de la aflicción de Egipto á la tierra del Cananeo, y del Hetheo, y del Amorrheo, y del Pherezeo, y del Heveo, y del Jebuseo, á una tierra que fluye leche y miel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'Y oirán tu voz; é irás tú, y los ancianos de Israel, al rey de Egipto, y le diréis: Jehová, el Dios de los Hebreos, nos ha encontrado; por tanto nosotros iremos ahora camino de tres días por el desierto, para que sacrifiquemos á Jehová nuestro Dios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'Mas yo sé que el rey de Egipto no os dejará ir sino por mano fuerte.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'Empero yo extenderé mi mano, y heriré á Egipto con todas mis maravillas que haré en él, y entonces os dejará ir.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'Y yo daré á este pueblo gracia en los ojos de los Egipcios, para que cuando os partiereis, no salgáis vacíos:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'Sino que demandará cada mujer á su vecina y á su huéspeda vasos de plata, vasos de oro, y vestidos: los cuales pondréis sobre vuestros hijos y vuestras hijas; y despojaréis á Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'ENTONCES Moisés respondió, y dijo: He aquí que ellos no me creerán, ni oirán mi voz; porque dirán: No te ha aparecido Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, 'Y Jehová dijo: ¿Qué es eso que tienes en tu mano? Y él respondió: Una vara.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, 'Y él le dijo: Échala en tierra. Y él la echó en tierra, y tornóse una culebra: y Moisés huía de ella.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'Entonces dijo Jehová á Moisés: Extiende tu mano, y tómala por la cola. Y él extendió su mano, y tomóla, y tornóse vara en su mano.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, 'Por esto creerán que se te ha aparecido Jehová, el Dios de tus padres, el Dios de Abraham, Dios de Isaac y Dios de Jacob.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'Y díjole más Jehová: Mete ahora tu mano en tu seno. Y él metió la mano en su seno; y como la sacó, he aquí que su mano estaba leprosa como la nieve.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, 'Y dijo: Vuelve á meter tu mano en tu seno: y él volvió á meter su mano en su seno; y volviéndola á sacar del seno, he aquí que se había vuelto como la otra carne.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, 'Sí aconteciere, que no te creyeren, ni obedecieren á la voz de la primera señal, creerán á la voz de la postrera.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, 'Y si aun no creyeren á estas dos señales, ni oyeren tu voz, tomarás de las aguas del río, y derrámalas en tierra; y volverse han aquellas aguas que tomarás del río, se volverán sangre en la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, 'Entonces dijo Moisés á Jehová: ¡Ay Señor! yo no soy hombre de palabras de ayer ni de anteayer, ni aun desde que tú hablas á tu siervo; porque soy tardo en el habla y torpe de lengua.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, 'Y Jehová le respondió: ¿Quién dió la boca al hombre? ¿ó quién hizo al mudo y al sordo, al que ve y al ciego? ¿no soy yo Jehová?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, 'Ahora pues, ve, que yo seré en tu boca, y te enseñaré lo que hayas de hablar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, 'Y él dijo: ¡Ay Señor! envía por mano del que has de enviar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, 'Entonces Jehová se enojó contra Moisés, y dijo: ¿No conozco yo á tu hermano Aarón, Levita, y que él hablará? Y aun he aquí que él te saldrá á recibir, y en viéndote, se alegrará en su corazón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, 'Tú hablarás á él, y pondrás en su boca las palabras, y yo seré en tu boca y en la suya, y os enseñaré lo que hayáis de hacer.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, 'Y él hablará por ti al pueblo; y él te será á ti en lugar de boca, y tú serás para él en lugar de Dios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'Y tomarás esta vara en tu mano, con la cual harás las señales.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, 'Así se fué Moisés, y volviendo á su suegro Jethro, díjole: Iré ahora, y volveré á mis hermanos que están en Egipto, para ver si aun viven. Y Jethro dijo á Moisés: Ve en paz.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, 'Dijo también Jehová á Moisés en Madián: Ve, y vuélvete á Egipto, porque han muerto todos los que procuraban tu muerte.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'Entonces Moisés tomó su mujer y sus hijos, y púsolos sobre un asno, y volvióse á tierra de Egipto: tomó también Moisés la vara de Dios en su mano.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'Y dijo Jehová á Moisés: Cuando hubiereis vuelto á Egipto, mira que hagas delante de Faraón todas las maravillas que he puesto en tu mano: yo empero endureceré su corazón, de modo que no dejará ir al pueblo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, 'Y dirás á Faraón: Jehová ha dicho así: Israel es mi hijo, mi primogénito.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, 'Ya te he dicho que dejes ir á mi hijo, para que me sirva, mas no has querido dejarlo ir: he aquí yo voy á matar á tu hijo, tu primogénito.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'Y aconteció en el camino, que en una posada le salió al encuentro Jehová, y quiso matarlo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'Entonces Séphora cogió un afilado pedernal, y cortó el prepucio de su hijo, y echólo á sus pies, diciendo: A la verdad tú me eres un esposo de sangre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, 'Así le dejó luego ir. Y ella dijo: Esposo de sangre, á causa de la circuncisión.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, 'Y Jehová dijo á Aarón: Ve á recibir á Moisés al desierto. Y él fué, y encontrólo en el monte de Dios, y besóle.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'Entonces contó Moisés á Aarón todas las palabras de Jehová que le enviaba, y todas las señales que le había dado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, 'Y fueron Moisés y Aarón, y juntaron todos los ancianos de los hijos de Israel:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, 'Y habló Aarón todas las palabras que Jehová había dicho á Moisés, é hizo las señales delante de los ojos del pueblo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, 'Y el pueblo creyó: y oyendo que Jehová había visitado los hijos de Israel, y que había visto su aflicción, inclináronse y adoraron.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, 'DESPUÉS entraron Moisés y Aarón á Faraón, y le dijeron: Jehová, el Dios de Israel, dice así: Deja ir á mi pueblo á celebrarme fiesta en el desierto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, 'Y Faraón respondió: ¿Quién es Jehová, para que yo oiga su voz y deje ir á Israel? Yo no conozco á Jehová, ni tampoco dejaré ir á Israel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, 'Y ellos dijeron: El Dios de los Hebreos nos ha encontrado: iremos, pues, ahora camino de tres días por el desierto, y sacrificaremos á Jehová nuestro Dios; porque no venga sobre nosotros con pestilencia ó con espada.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'Entonces el rey de Egipto les dijo: Moisés y Aarón, ¿por qué hacéis cesar al pueblo de su obra? idos á vuestros cargos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, 'Dijo también Faraón: He aquí el pueblo de la tierra es ahora mucho, y vosotros les hacéis cesar de sus cargos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'Y mandó Faraón aquel mismo día á los cuadrilleros del pueblo que le tenían á su cargo, y á sus gobernadores, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, 'De aquí adelante no daréis paja al pueblo para hacer ladrillo, como ayer y antes de ayer; vayan ellos y recojan por sí mismos la paja:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'Y habéis de ponerles la tarea del ladrillo que hacían antes, y no les disminuiréis nada; porque están ociosos, y por eso levantan la voz diciendo: Vamos y sacrificaremos á nuestro Dios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, 'Agrávese la servidumbre sobre ellos, para que se ocupen en ella, y no atiendan á palabras de mentira.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, 'Y saliendo los cuadrilleros del pueblo y sus gobernadores, hablaron al pueblo, diciendo: Así ha dicho Faraón: Yo no os doy paja.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, 'Id vosotros, y recoged paja donde la hallareis; que nada se disminuirá de vuestra tarea.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, 'Entonces el pueblo se derramó por toda la tierra de Egipto á coger rastrojo en lugar de paja.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, 'Y los cuadrilleros los apremiaban, diciendo: Acabad vuestra obra, la tarea del día en su día, como cuando se os daba paja.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, 'Y azotaban á los capataces de los hijos de Israel, que los cuadrilleros de Faraón habían puesto sobre ellos, diciendo: ¿Por qué no habéis cumplido vuestra tarea de ladrillo ni ayer ni hoy, como antes?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, 'Y los capataces de los hijos de Israel vinieron á Faraón, y se quejaron á él, diciendo: ¿Por qué lo haces así con tus siervos?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, 'No se da paja á tus siervos, y con todo nos dicen: Haced el ladrillo. Y he aquí tus siervos son azotados, y tu pueblo cae en falta.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, 'Y él respondió: Estáis ociosos, sí, ociosos, y por eso decís: Vamos y sacrifiquemos á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, 'Id pues ahora, y trabajad. No se os dará paja, y habéis de dar la tarea del ladrillo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, 'Entonces los capataces de los hijos de Israel se vieron en aflicción, habiéndoseles dicho: No se disminuirá nada de vuestro ladrillo, de la tarea de cada día.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, 'Y encontrando á Moisés y á Aarón, que estaban á la vista de ellos cuando salían de Faraón,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, 'Dijéronles: Mire Jehová sobre vosotros, y juzgue; pues habéis hecho heder nuestro olor delante de Faraón y de sus siervos, dándoles el cuchillo en las manos para que nos maten.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, 'Entonces Moisés se volvió á Jehová, y dijo: Señor, ¿por qué afliges á este pueblo? ¿para qué me enviaste?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, 'Porque desde que yo vine á Faraón para hablarle en tu nombre, ha afligido á este pueblo; y tú tampoco has librado á tu pueblo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'JEHOVÁ respondió á Moisés: Ahora verás lo que yo haré á Faraón; porque con mano fuerte los ha de dejar ir; y con mano fuerte los ha de echar de su tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, 'Habló todavía Dios á Moisés, y díjole: Yo soy JEHOVÁ;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, 'Y aparecí á Abraham, á Isaac y á Jacob bajo el nombre de Dios Omnipotente, mas en mi nombre JEHOVÁ no me notifiqué á ellos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, 'Y también establecí mi pacto con ellos, de darles la tierra de Canaán, la tierra en que fueron extranjeros, y en la cual peregrinaron.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, 'Y asimismo yo he oído el gemido de los hijos de Israel, á quienes hacen servir los Egipcios, y heme acordado de mi pacto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, 'Por tanto dirás á los hijos de Israel: Yo JEHOVÁ; y yo os sacaré de debajo de las cargas de Egipto, y os libraré de su servidumbre, y os redimiré con brazo extendido, y con juicios grandes:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, 'Y os tomaré por mi pueblo y seré vuestro Dios: y vosotros sabréis que yo soy Jehová vuestro Dios, que os saco de debajo de las cargas de Egipto:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, 'Y os meteré en la tierra, por la cual alcé mi mano que la daría á Abraham, á Isaac y á Jacob: y yo os la daré por heredad. Yo JEHOVÁ.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'De esta manera habló Moisés á los hijos de Israel: mas ellos no escuchaban á Moisés á causa de la congoja de espíritu, y de la dura servidumbre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, 'Y habló Jehová á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, 'Entra, y habla á Faraón rey de Egipto, que deje ir de su tierra á los hijos de Israel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'Y respondió Moisés delante de Jehová, diciendo: He aquí, los hijos de Israel no me escuchan: ¿cómo pues me escuchará Faraón, mayormente siendo yo incircunciso de labios?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, 'Entonces Jehová habló á Moisés y á Aarón, y dióles mandamiento para los hijos de Israel, y para Faraón rey de Egipto, para que sacasen á los hijos de Israel de la tierra de Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, 'Estas son las cabezas de las familias de sus padres. Los hijos de Rubén, el primogénito de Israel: Hanoch y Phallú, Hezrón y Carmi: estas son las familias de Rubén.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, 'Los hijos de Simeón: Jemuel, y Jamín, y Ohad, y Jachîn, y Zoar, y Saúl, hijo de una Cananea: estas son las familias de Simeón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'Y estos son los nombres de los hijos de Leví por sus linajes: Gersón, y Coath, y Merari. Y los años de la vida de Leví fueron ciento treinta y siete años.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, 'Y los hijos de Gersón: Libni, y Shimi, por sus familias.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, 'Y los hijos de Coath: Amram, é Izhar, y Hebrón, y Uzziel. Y los años de la vida de Coath fueron ciento treinta y tres años.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, 'Y los hijos de Merari: Mahali, y Musi: estas son las familias de Leví por sus linajes.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'Y Amram tomó por mujer á Jochêbed su tía; la cual le parió á Aarón y á Moisés. Y los años de la vida de Amram fueron ciento treinta y siete años.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, 'Y los hijos de Izhar: Cora, y Nepheg y Zithri.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, 'Y los hijos de Uzziel: Misael, y Elzaphán y Zithri.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, 'Y tomóse Aarón por mujer á Elisabeth, hija de Aminadab, hermana de Naasón; la cual le parió á Nadab, y á Abiú, y á Eleazar y á Ithamar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, 'Y los hijos de Cora: Assir, y Elcana, y Abiasaph: estas son las familias de los Coritas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, 'Y Eleazar, hijo de Aarón, tomó para sí mujer de las hijas de Phutiel, la cual le parió á Phinees: y estas son las cabezas de los padres de los Levitas por sus familias.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'Este es aquel Aarón y aquel Moisés, á los cuales Jehová dijo: Sacad á los hijos de Israel de la tierra de Egipto por sus escuadrones.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, 'Estos son los que hablaron á Faraón rey de Egipto, para sacar de Egipto á los hijos de Israel. Moisés y Aarón fueron estos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'Cuando Jehová habló á Moisés en la tierra de Egipto,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'Entonces Jehová habló á Moisés, diciendo: Yo soy JEHOVÁ; di á Faraón rey de Egipto todas las cosas que yo te digo á ti.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'Y Moisés respondió delante de Jehová: He aquí, yo soy incircunciso de labios, ¿cómo pues me ha de oir Faraón?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'Y JEHOVÁ dijo á Moisés: Mira, yo te he constituído dios para Faraón, y tu hermano Aarón será tu profeta.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'Tú dirás todas las cosas que yo te mandaré, y Aarón tu hermano hablará á Faraón, para que deje ir de su tierra á los hijos de Israel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'Y yo endureceré el corazón de Faraón, y multiplicaré en la tierra de Egipto mis señales y mis maravillas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'Y Faraón no os oirá; mas yo pondré mi mano sobre Egipto, y sacaré á mis ejércitos, mi pueblo, los hijos de Israel, de la tierra de Egipto, con grandes juicios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'Y sabrán los Egipcios que yo soy Jehová, cuando extenderé mi mano sobre Egipto, y sacaré los hijos de Israel de en medio de ellos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'E hizo Moisés y Aarón como Jehová les mandó: hiciéronlo así.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'Y era Moisés de edad de ochenta años, y Aarón de edad de ochenta y tres, cuando hablaron á Faraón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'Y habló Jehová á Moisés y á Aarón, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, 'Si Faraón os respondiere diciendo, Mostrad milagro; dirás á Aarón: Toma tu vara, y échala delante de Faraón, para que se torne culebra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, 'Vinieron, pues, Moisés y Aarón á Faraón, é hicieron como Jehová lo había mandado: y echó Aarón su vara delante de Faraón y de sus siervos, y tornóse culebra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, 'Entonces llamó también Faraón sabios y encantadores; é hicieron también lo mismo los encantadores de Egipto con sus encantamientos;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, 'Pues echó cada uno su vara, las cuales se volvieron culebras: mas la vara de Aarón devoró las varas de ellos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, 'Y el corazón de Faraón se endureció, y no los escuchó; como Jehová lo había dicho.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, 'Entonces Jehová dijo á Moisés: El corazón de Faraón está agravado, que no quiere dejar ir al pueblo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, 'Ve por la mañana á Faraón, he aquí que él sale á las aguas; y tú ponte á la orilla del río delante de él, y toma en tu mano la vara que se volvió culebra,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, 'Y dile: Jehová el Dios de los Hebreos me ha enviado á ti, diciendo: Deja ir á mi pueblo, para que me sirvan en el desierto; y he aquí que hasta ahora no has querido oir.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'Así ha dicho Jehová: En esto conocerás que yo soy Jehová: he aquí, yo heriré con la vara que tengo en mi mano el agua que está en el río, y se convertirá en sangre:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, 'Y los peces que hay en el río morirán, y hederá el río, y tendrán asco los Egipcios de beber el agua del río.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'Y Jehová dijo á Moisés: Di á Aarón: Toma tu vara, y extiende tu mano sobre las aguas de Egipto, sobre sus ríos, sobre sus arroyos y sobre sus estanques, y sobre todos sus depósitos de aguas, para que se conviertan en sangre, y haya sangre por toda la región de Egipto, así en los vasos de madera como en los de piedra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'Y Moisés y Aarón hicieron como Jehová lo mandó; y alzando la vara hirió las aguas que había en el río, en presencia de Faraón y de sus siervos; y todas las aguas que había en el río se convirtieron en sangre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, 'Asimismo los peces que había en el río murieron; y el río se corrompió, que los Egipcios no podían beber de él: y hubo sangre por toda la tierra de Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'Y los encantadores de Egipto hicieron lo mismo con sus encantamientos: y el corazón de Faraón se endureció, y no los escuchó; como Jehová lo había dicho.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'Y tornando Faraón volvióse á su casa, y no puso su corazón aun en esto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'Y en todo Egipto hicieron pozos alrededor del río para beber, porque no podían beber de las aguas del río.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, 'Y cumpliéronse siete días después que Jehová hirió el río.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'ENTONCES Jehová dijo á Moisés: Entra á Faraón, y dile: Jehová ha dicho así: Deja ir á mi pueblo, para que me sirvan.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, 'Y si no lo quisieres dejar ir, he aquí yo heriré con ranas todos tus términos:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, 'Y el río criará ranas, las cuales subirán, y entrarán en tu casa, y en la cámara de tu cama, y sobre tu cama, y en las casas de tus siervos, y en tu pueblo, y en tus hornos, y en tus artesas:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, 'Y las ranas subirán sobre ti, y sobre tu pueblo, y sobre todos tus siervos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'Y Jehová dijo á Moisés: Di á Aarón: Extiende tu mano con tu vara sobre los ríos, arroyos, y estanques, para que haga venir ranas sobre la tierra de Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, 'Entonces Aarón extendió su mano sobre las aguas de Egipto, y subieron ranas que cubrieron la tierra de Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, 'Y los encantadores hicieron lo mismo con sus encantamientos, é hicieron venir ranas sobre la tierra de Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'Entonces Faraón llamó á Moisés y á Aarón, y díjoles: Orad á Jehová que quite las ranas de mí y de mi pueblo; y dejaré ir al pueblo, para que sacrifique á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'Y dijo Moisés á Faraón: Gloríate sobre mí: ¿cuándo oraré por ti, y por tus siervos, y por tu pueblo, para que las ranas sean quitadas de ti, y de tus casas, y que solamente se queden en el río?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, 'Y él dijo: Mañana. Y Moisés respondió: Se hará conforme á tu palabra, para que conozcas que no hay como Jehová nuestro Dios:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, 'Y las ranas se irán de ti, y de tus casas, y de tus siervos, y de tu pueblo, y solamente se quedarán en el río.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'Entonces salieron Moisés y Aarón de con Faraón, y clamó Moisés á Jehová sobre el negocio de las ranas que había puesto á Faraón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'E hizo Jehová conforme á la palabra de Moisés, y murieron las ranas de las casas, de los cortijos, y de los campos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, 'Y las juntaron en montones, y apestaban la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, 'Y viendo Faraón que le habían dado reposo, agravó su corazón, y no los escuchó; como Jehová lo había dicho.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, 'Entonces Jehová dijo á Moisés: Di á Aarón: Extiende tu vara, y hiere el polvo de la tierra, para que se vuelva piojos por todo el país de Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, 'Y ellos lo hicieron así; y Aarón extendió su mano con su vara, é hirió el polvo de la tierra, el cual se volvió piojos, así en los hombres como en las bestias: todo el polvo de la tierra se volvió piojos en todo el país de Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, 'Y los encantadores hicieron así también, para sacar piojos con sus encantamientos; mas no pudieron. Y había piojos así en los hombres como en las bestias.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, 'Entonces los magos dijeron á Faraón: Dedo de Dios es este. Mas el corazón de Faraón se endureció, y no los escuchó; como Jehová lo había dicho.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, 'Y Jehová dijo á Moisés: Levántate de mañana y ponte delante de Faraón, he aquí él sale á las aguas; y dile: Jehová ha dicho así: Deja ir á mi pueblo, para que me sirva.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, 'Porque si no dejares ir á mi pueblo, he aquí yo enviaré sobre ti, y sobre tus siervos, y sobre tu pueblo, y sobre tus casas toda suerte de moscas; y las casas de los Egipcios se henchirán de toda suerte de moscas, y asimismo la tierra donde ellos estuvieren.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, 'Y aquel día yo apartaré la tierra de Gosén, en la cual mi pueblo habita, para que ninguna suerte de moscas haya en ella; á fin de que sepas que yo soy Jehová en medio de la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, 'Y yo pondré redención entre mi pueblo y el tuyo. Mañana será esta señal.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, 'Y Jehová lo hizo así: que vino toda suerte de moscas molestísimas sobre la casa de Faraón, y sobre las casas de sus siervos, y sobre todo el país de Egipto; y la tierra fué corrompida á causa de ellas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, 'Entonces Faraón llamó á Moisés y á Aarón, y díjoles: Andad, sacrificad á vuestro Dios en la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, 'Y Moisés respondió: No conviene que hagamos así, porque sacrificaríamos á Jehová nuestro Dios la abominación de los Egipcios. He aquí, si sacrificáramos la abominación de los Egipcios delante de ellos, ¿no nos apedrearían?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, 'Camino de tres días iremos por el desierto, y sacrificaremos á Jehová nuestro Dios, como él nos dirá.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'Y dijo Faraón: Yo os dejaré ir para que sacrifiquéis á Jehová vuestro Dios en el desierto, con tal que no vayáis más lejos: orad por mí.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 29, 'Y respondió Moisés: He aquí, en saliendo yo de contigo, rogaré á Jehová que las diversas suertes de moscas se vayan de Faraón, y de sus siervos, y de su pueblo mañana; con tal que Faraón no falte más, no dejando ir al pueblo á sacrificar á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 30, 'Entonces Moisés salió de con Faraón, y oró á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 31, 'Y Jehová hizo conforme á la palabra de Moisés; y quitó todas aquellas moscas de Faraón, y de sus siervos, y de su pueblo, sin que quedara una.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 32, 'Mas Faraón agravó aún esta vez su corazón, y no dejó ir al pueblo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, 'ENTONCES Jehová dijo á Moisés: Entra á Faraón, y dile: Jehová, el Dios de los Hebreos, dice así: Deja ir á mi pueblo, para que me sirvan;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, 'Porque si no lo quieres dejar ir, y los detuvieres aún,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'He aquí la mano de Jehová será sobre tus ganados que están en el campo, caballos, asnos, camellos, vacas y ovejas, con pestilencia gravísima:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'Y Jehová hará separación entre los ganados de Israel y los de Egipto, de modo que nada muera de todo lo de los hijos de Israel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'Y Jehová señaló tiempo, diciendo: Mañana hará Jehová esta cosa en la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, 'Y el día siguiente Jehová hizo aquello, y murió todo el ganado de Egipto; mas del ganado de los hijos de Israel no murió uno.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'Entonces Faraón envió, y he aquí que del ganado de los hijos de Israel no había muerto uno. Mas el corazón de Faraón se agravó, y no dejó ir al pueblo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, 'Y Jehová dijo á Moisés y á Aarón: Tomad puñados de ceniza de un horno, y espárzala Moisés hacia el cielo delante de Faraón:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, 'Y vendrá á ser polvo sobre toda la tierra de Egipto, el cual originará sarpullido que cause tumores apostemados en los hombres y en las bestias, por todo el país de Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, 'Y tomaron la ceniza del horno, y pusiéronse delante de Faraón, y esparcióla Moisés hacia el cielo; y vino un sarpullido que causaba tumores apostemados así en los hombres como en las bestias.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, 'Y los magos no podían estar delante de Moisés á causa de los tumores, porque hubo sarpullido en los magos y en todos los Egipcios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, 'Y Jehová endureció el corazón de Faraón, y no los oyó; como Jehová lo había dicho á Moisés.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, 'Entonces Jehová dijo á Moisés: Levántate de mañana, y ponte delante de Faraón, y dile: Jehová, el Dios de los Hebreos, dice así: Deja ir á mi pueblo, para que me sirva.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, 'Porque yo enviaré esta vez todas mis plagas á tu corazón, sobre tus siervos, y sobre tu pueblo, para que entiendas que no hay otro como yo en toda la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, 'Porque ahora yo extenderé mi mano para herirte á ti y á tu pueblo de pestilencia, y serás quitado de la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, 'Y á la verdad yo te he puesto para declarar en ti mi potencia, y que mi Nombre sea contado en toda la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, '¿Todavía te ensalzas tú contra mi pueblo, para no dejarlos ir?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, 'He aquí que mañana á estas horas yo haré llover granizo muy grave, cual nunca fué en Egipto, desde el día que se fundó hasta ahora.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, 'Envía, pues, á recoger tu ganado, y todo lo que tienes en el campo; porque todo hombre ó animal que se hallare en el campo, y no fuere recogido á casa, el granizo descenderá sobre él, y morirá.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'De los siervos de Faraón el que temió la palabra de Jehová, hizo huir sus criados y su ganado á casa:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'Mas el que no puso en su corazón la palabra de Jehová, dejó sus criados y sus ganados en el campo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'Y Jehová dijo á Moisés: Extiende tu mano hacia el cielo, para que venga granizo en toda la tierra de Egipto sobre los hombres, y sobre las bestias, y sobre toda la hierba del campo en el país de Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'Y Moisés extendió su vara hacia el cielo, y Jehová hizo tronar y granizar, y el fuego discurría por la tierra; y llovió Jehová granizo sobre la tierra de Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, 'Hubo pues granizo, y fuego mezclado con el granizo, tan grande, cual nunca hubo en toda la tierra de Egipto desde que fué habitada.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, 'Y aquel granizo hirió en toda la tierra de Egipto todo lo que estaba en el campo, así hombres como bestias; asimismo hirió el granizo toda la hierba del campo, y desgajó todos los árboles del país.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, 'Solamente en la tierra de Gosén, donde los hijos de Israel estaban, no hubo granizo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, 'Entonces Faraón envió á llamar á Moisés y á Aarón, y les dijo: He pecado esta vez: Jehová es justo, y yo y mi pueblo impíos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'Orad á Jehová: y cesen los truenos de Dios y el granizo; y yo os dejaré ir, y no os detendréis más.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, 'Y respondióle Moisés: En saliendo yo de la ciudad extenderé mis manos á Jehová, y los truenos cesarán, y no habrá más granizo; para que sepas que de Jehová es la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, 'Mas yo sé que ni tú ni tus siervos temeréis todavía la presencia del Dios Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, 'El lino, pues, y la cebada fueron heridos; porque la cebada estaba ya espigada, y el lino en caña.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, 'Mas el trigo y el centeno no fueron heridos; porque eran tardíos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'Y salido Moisés de con Faraón de la ciudad, extendió sus manos á Jehová, y cesaron los truenos y el granizo; y la lluvia no cayó más sobre la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, 'Y viendo Faraón que la lluvia había cesado y el granizo y los truenos, perseveró en pecar, y agravó su corazón, él y sus siervos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, 'Y el corazón de Faraón se endureció, y no dejó ir á los hijos de Israel; como Jehová lo había dicho por medio de Moisés.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, 'Y JEHOVÁ dijo á Moisés: Entra á Faraón; porque yo he agravado su corazón, y el corazón de sus siervos, para dar entre ellos estas mis señales;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, 'Y para que cuentes á tus hijos y á tus nietos las cosas que yo hice en Egipto, y mis señales que dí entre ellos; y para que sepáis que yo soy Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'Entonces vinieron Moisés y Aarón á Faraón, y le dijeron: Jehová, el Dios de los Hebreos, ha dicho así: ¿Hasta cuándo no querrás humillarte delante de mí? Deja ir á mi pueblo para que me sirvan.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, 'Y si aun rehusas dejarlo ir, he aquí que yo traeré mañana langosta en tus términos,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, 'La cual cubrirá la faz de la tierra, de modo que no pueda verse la tierra; y ella comerá lo que quedó salvo, lo que os ha quedado del granizo; comerá asimismo todo árbol que os produce fruto en el campo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, 'Y llenarse han tus casas, y las casas de todos tus siervos, y las casas de todos los Egipcios, cual nunca vieron tus padres ni tus abuelos, desde que ellos fueron sobre la tierra hasta hoy. Y volvióse, y salió de con Faraón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, 'Entonces los siervos de Faraón le dijeron: ¿Hasta cuándo nos ha de ser éste por lazo? Deja ir á estos hombres, para que sirvan á Jehová su Dios; ¿aun no sabes que Egipto está destruído?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, 'Y Moisés y Aarón volvieron á ser llamados á Faraón, el cual les dijo: Andad, servid á Jehová vuestro Dios. ¿Quién y quién son los que han de ir?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, 'Y Moisés respondió: Hemos de ir con nuestros niños y con nuestros viejos, con nuestros hijos y con nuestras hijas: con nuestras ovejas y con nuestras vacas hemos de ir; porque tenemos solemnidad de Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, 'Y él les dijo: Así sea Jehová con vosotros como yo os dejaré ir á vosotros y á vuestros niños: mirad como el mal está delante de vuestro rostro.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'No será así: id ahora vosotros los varones, y servid á Jehová: pues esto es lo que vosotros demandasteis. Y echáronlos de delante de Faraón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, 'Entonces Jehová dijo á Moisés: Extiende tu mano sobre la tierra de Egipto para langosta, á fin de que suba sobre el país de Egipto, y consuma todo lo que el granizo dejó.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'Y extendió Moisés su vara sobre la tierra de Egipto, y Jehová trajo un viento oriental sobre el país todo aquel día y toda aquella noche; y á la mañana el viento oriental trajo la langosta:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, 'Y subió la langosta sobre toda la tierra de Egipto, y asentóse en todos los términos de Egipto, en gran manera grave: antes de ella no hubo langosta semejante, ni después de ella vendrá otra tal;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, 'Y cubrió la faz de todo el país, y oscurecióse la tierra; y consumió toda la hierba de la tierra, y todo el fruto de los árboles que había dejado el granizo; que no quedó cosa verde en árboles ni en hierba del campo, por toda la tierra de Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, 'Entonces Faraón hizo llamar apriesa á Moisés y á Aarón, y dijo: He pecado contra Jehová vuestro Dios, y contra vosotros.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, 'Mas ruego ahora que perdones mi pecado solamente esta vez, y que oréis á Jehová vuestro Dios que quite de mí solamente esta muerte.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, 'Y salió de con Faraón, y oró á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, 'Y Jehová volvió un viento occidental fortísimo, y quitó la langosta, y arrojóla en el mar Bermejo: ni una langosta quedó en todo el término de Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, 'Mas Jehová endureció el corazón de Faraón; y no envió los hijos de Israel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, 'Y Jehová dijo á Moisés: Extiende tu mano hacia el cielo, para que haya tinieblas sobre la tierra de Egipto, tales que cualquiera las palpe.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'Y extendió Moisés su mano hacia el cielo, y hubo densas tinieblas tres días por toda la tierra de Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, 'Ninguno vió á su prójimo, ni nadie se levantó de su lugar en tres días; mas todos los hijos de Israel tenían luz en sus habitaciones.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, 'Entonces Faraón hizo llamar á Moisés, y dijo: Id, servid á Jehová; solamente queden vuestras ovejas y vuestras vacas: vayan también vuestros niños con vosotros.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, 'Y Moisés respondió: Tú también nos entregarás sacrificios y holocaustos que sacrifiquemos á Jehová nuestro Dios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, 'Nuestros ganados irán también con nosotros; no quedará ni una uña; porque de ellos hemos de tomar para servir á Jehová nuestro Dios; y no sabemos con qué hemos de servir á Jehová, hasta que lleguemos allá.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, 'Mas Jehová endureció el corazón de Faraón, y no quiso dejarlos ir.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, 'Y díjole Faraón: Retírate de mí: guárdate que no veas más mi rostro, porque en cualquier día que vieres mi rostro, morirás.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, 'Y Moisés respondió: Bien has dicho; no veré más tu rostro.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, 'Y JEHOVÁ dijo á Moisés: Una plaga traeré aún sobre Faraón, y sobre Egipto; después de la cual él os dejará ir de aquí; y seguramente os echará de aquí del todo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, 'Habla ahora al pueblo, y que cada uno demande á su vecino, y cada una á su vecina, vasos de plata y de oro.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'Y Jehová dió gracia al pueblo en los ojos de los Egipcios. También Moisés era muy gran varón en la tierra de Egipto, á los ojos de los siervos de Faraón, y á los ojos del pueblo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, 'Y dijo Moisés: Jehová ha dicho así: A la media noche yo saldré por medio de Egipto,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'Y morirá todo primogénito en tierra de Egipto, desde el primogénito de Faraón que se sienta en su trono, hasta el primogénito de la sierva que está tras la muela; y todo primogénito de las bestias.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, 'Y habrá gran clamor por toda la tierra de Egipto, cual nunca fué, ni jamás será.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, 'Mas entre todos los hijos de Israel, desde el hombre hasta la bestia, ni un perro moverá su lengua: para que sepáis que hará diferencia Jehová entre los Egipcios y los Israelitas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, 'Y descenderán á mí todos estos tus siervos, é inclinados delante de mí dirán: Sal tú, y todo el pueblo que está bajo de ti; y después de esto yo saldré. Y salióse muy enojado de con Faraón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, 'Y Jehová dijo á Moisés: Faraón no os oirá, para que mis maravillas se multipliquen en la tierra de Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'Y Moisés y Aarón hicieron todos estos prodigios delante de Faraón: mas Jehová había endurecido el corazón de Faraón, y no envió á los hijos de Israel fuera de su país.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, 'Y HABLÓ Jehová á Moisés y á Aarón en la tierra de Egipto, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, 'Este mes os será principio de los meses; será este para vosotros el primero en los meses del año.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, 'Hablad á toda la congregación de Israel, diciendo: En el diez de aqueste mes tómese cada uno un cordero por las familias de los padres, un cordero por familia:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'Mas si la familia fuere pequeña que no baste á comer el cordero, entonces tomará á su vecino inmediato á su casa, y según el número de las personas, cada uno conforme á su comer, echaréis la cuenta sobre el cordero.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, 'El cordero será sin defecto, macho de un año: tomaréislo de las ovejas ó de las cabras:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, 'Y habéis de guardarlo hasta el día catorce de este mes; y lo inmolará toda la congregación del pueblo de Israel entre las dos tardes.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'Y tomarán de la sangre, y pondrán en los dos postes y en el dintel de las casas en que lo han de comer.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, 'Y aquella noche comerán la carne asada al fuego, y panes sin levadura: con hierbas amargas lo comerán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, 'Ninguna cosa comeréis de él cruda, ni cocida en agua, sino asada al fuego; su cabeza con sus pies y sus intestinos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, 'Ninguna cosa dejaréis de él hasta la mañana; y lo que habrá quedado hasta la mañana, habéis de quemarlo en el fuego.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'Y así habéis de comerlo: ceñidos vuestros lomos, vuestros zapatos en vuestros pies, y vuestro bordón en vuestra mano; y lo comeréis apresuradamente: es la Pascua de Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, 'Pues yo pasaré aquella noche por la tierra de Egipto, y heriré á todo primogénito en la tierra de Egipto, así en los hombres como en las bestias: y haré juicios en todos los dioses de Egipto. Yo JEHOVÁ.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'Y la sangre os será por señal en las casas donde vosotros estéis; y veré la sangre, y pasaré de vosotros, y no habrá en vosotros plaga de mortandad, cuando heriré la tierra de Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, 'Y este día os ha de ser en memoria, y habéis de celebrarlo como solemne á Jehová durante vuestras generaciones: por estatuto perpetuo lo celebraréis.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, 'Siete días comeréis panes sin levadura; y así el primer día haréis que no haya levadura en vuestras casas: porque cualquiera que comiere leudado desde el primer día hasta el séptimo, aquella alma será cortada de Israel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, 'El primer día habrá santa convocación, y asimismo en el séptimo día tendréis una santa convocación: ninguna obra se hará en ellos, excepto solamente que aderecéis lo que cada cual hubiere de comer.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, 'Y guardaréis la fiesta de los ázimos, porque en aqueste mismo día saqué vuestros ejércitos de la tierra de Egipto: por tanto guardaréis este día en vuestras generaciones por costumbre perpetua.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, 'En el mes primero, el día catorce del mes por la tarde, comeréis los panes sin levadura, hasta el veintiuno del mes por la tarde.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, 'Por siete días no se hallará levadura en vuestras casas, porque cualquiera que comiere leudado, así extranjero como natural del país, aquella alma será cortada de la congregación de Israel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, 'Ninguna cosa leudada comeréis; en todas vuestras habitaciones comeréis panes sin levadura.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, 'Y Moisés convocó á todos los ancianos de Israel, y díjoles: Sacad, y tomaos corderos por vuestras familias, y sacrificad la pascua.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, 'Y tomad un manojo de hisopo, y mojadle en la sangre que estará en una jofaina, y untad el dintel y los dos postes con la sangre que estará en la jofaina; y ninguno de vosotros salga de las puertas de su casa hasta la mañana.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, 'Porque Jehová pasará hiriendo á los Egipcios; y como verá la sangre en el dintel y en los dos postes, pasará Jehová aquella puerta, y no dejará entrar al heridor en vuestras casas para herir.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, 'Y guardaréis esto por estatuto para vosotros y para vuestros hijos para siempre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, 'Y será, cuando habréis entrado en la tierra que Jehová os dará, como tiene hablado, que guardaréis este rito.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, 'Y cuando os dijeren vuestros hijos: ¿Qué rito es este vuestro?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, 'Vosotros responderéis: Es la víctima de la Pascua de Jehová, el cual pasó las casas de los hijos de Israel en Egipto, cuando hirió á los Egipcios, y libró nuestras casas. Entonces el pueblo se inclinó y adoró.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'Y los hijos de Israel se fueron, é hicieron puntualmente así; como Jehová había mandado á Moisés y á Aarón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, 'Y aconteció que á la medianoche Jehová hirió á todo primogénito en la tierra de Egipto, desde el primogénito de Faraón que se sentaba sobre su trono, hasta el primogénito del cautivo que estaba en la cárcel, y todo primogénito de los animales.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, 'Y levantóse aquella noche Faraón, él y todos sus siervos, y todos los Egipcios; y había un gran clamor en Egipto, porque no había casa donde no hubiese muerto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'E hizo llamar á Moisés y á Aarón de noche, y díjoles: Salid de en medio de mi pueblo vosotros, y los hijos de Israel; é id, servid á Jehová, como habéis dicho.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, 'Tomad también vuestras ovejas y vuestras vacas, como habéis dicho, é idos; y bendecidme también á mí.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, 'Y los Egipcios apremiaban al pueblo, dándose priesa á echarlos de la tierra; porque decían: Todos somos muertos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, 'Y llevó el pueblo su masa antes que se leudase, sus masas envueltas en sus sábanas sobre sus hombros.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, 'E hicieron los hijos de Israel conforme al mandamiento de Moisés, demandando á los Egipcios vasos de plata, y vasos de oro, y vestidos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'Y Jehová dió gracia al pueblo delante de los Egipcios, y prestáronles; y ellos despojaron á los Egipcios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, 'Y partieron los hijos de Israel de Rameses á Succoth, como seiscientos mil hombres de á pie, sin contar los niños.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, 'Y también subió con ellos grande multitud de diversa suerte de gentes; y ovejas, y ganados muy muchos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, 'Y cocieron tortas sin levadura de la masa que habían sacado de Egipto; porque no había leudado, por cuanto echándolos los Egipcios, no habían podido detenerse, ni aun prepararse comida.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, 'El tiempo que los hijos de Israel habitaron en Egipto, fué cuatrocientos treinta años.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, 'Y pasados cuatrocientos treinta años, en el mismo día salieron todos los ejércitos de Jehová de la tierra de Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, 'Es noche de guardar á Jehová, por haberlos sacado en ella de la tierra de Egipto. Esta noche deben guardar á Jehová todos los hijos de Israel en sus generaciones.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'Y Jehová dijo á Moisés y á Aarón: Esta es la ordenanza de la Pascua: Ningún extraño comerá de ella:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, 'Mas todo siervo humano comprado por dinero, comerá de ella después que lo hubieres circuncidado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, 'El extranjero y el asalariado no comerán de ella.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, 'En una casa se comerá, y no llevarás de aquella carne fuera de casa, ni quebraréis hueso suyo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'Toda la congregación de Israel le sacrificará.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, 'Mas si algún extranjero peregrinare contigo, y quisiere hacer la pascua á Jehová, séale circuncidado todo varón, y entonces se llegará á hacerla, y será como el natural de la tierra; pero ningún incircunciso comerá de ella.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, 'La misma ley será para el natural y para el extranjero que peregrinare entre vosotros.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'Así lo hicieron todos los hijos de Israel; como mandó Jehová á Moisés y á Aarón, así lo hicieron.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, 'Y en aquel mismo día sacó Jehová á los hijos de Israel de la tierra de Egipto por sus escuadrones.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, 'Y JEHOVÁ habló á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, 'Santifícame todo primogénito, cualquiera que abre matriz entre los hijos de Israel, así de los hombres como de los animales: mío es.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'Y Moisés dijo al pueblo: Tened memoria de aqueste día, en el cual habéis salido de Egipto, de la casa de servidumbre; pues Jehová os ha sacado de aquí con mano fuerte: por tanto, no comeréis leudado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'Vosotros salís hoy en el mes de Abib.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'Y cuando Jehová te hubiere metido en la tierra del Cananeo, y del Hetheo, y del Amorrheo, y del Hebeo, y del Jebuseo, la cual juró á tus padres que te daría, tierra que destila leche y miel, harás este servicio en aqueste mes.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, 'Siete días comerás por leudar, y el séptimo día será fiesta á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, 'Por los siete días se comerán los panes sin levadura; y no se verá contigo leudado, ni levadura en todo tu término.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, 'Y contarás en aquel día á tu hijo, diciendo: Hácese esto con motivo de lo que Jehová hizo conmigo cuando me sacó de Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, 'Y serte ha como una señal sobre tu mano, y como una memoria delante de tus ojos, para que la ley de Jehová esté en tu boca; por cuanto con mano fuerte te sacó Jehová de Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, 'Por tanto, tú guardarás este rito en su tiempo de año en año.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, 'Y cuando Jehová te hubiere metido en la tierra del Cananeo, como te ha jurado á ti y á tus padres, y cuando te la hubiere dado,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, 'Harás pasar á Jehová todo lo que abriere la matriz, asimismo todo primerizo que abriere la matriz de tus animales: los machos serán de Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, 'Mas todo primogénito de asno redimirás con un cordero; y si no lo redimieres, le degollarás: asimismo redimirás todo humano primogénito de tus hijos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, 'Y cuando mañana te preguntare tu hijo, diciendo: ¿Qué es esto? decirle has: Jehová nos sacó con mano fuerte de Egipto, de casa de servidumbre;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, 'Y endureciéndose Faraón en no dejarnos ir, Jehová mató en la tierra de Egipto á todo primogénito, desde el primogénito humano hasta el primogénito de la bestia: y por esta causa yo sacrifico á Jehová todo primogénito macho, y redimo todo primogénito de mis hijos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, 'Serte ha, pues, como una señal sobre tu mano, y por una memoria delante de tus ojos; ya que Jehová nos sacó de Egipto con mano fuerte.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, 'Y luego que Faraón dejó ir al pueblo, Dios no los llevó por el camino de la tierra de los Filisteos, que estaba cerca; porque dijo Dios: Que quizá no se arrepienta el pueblo cuando vieren la guerra, y se vuelvan á Egipto:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, 'Mas hizo Dios al pueblo que rodease por el camino del desierto del mar Bermejo. Y subieron los hijos de Israel de Egipto armados.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, 'Tomó también consigo Moisés los huesos de José, el cual había juramentado á los hijos de Israel, diciendo: Dios ciertamente os visitará, y haréis subir mis huesos de aquí con vosotros.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, 'Y partidos de Succoth, asentaron campo en Etham, á la entrada del desierto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'Y Jehová iba delante de ellos de día en una columna de nube, para guiarlos por el camino; y de noche en una columna de fuego para alumbrarles; á fin de que anduviesen de día y de noche.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, 'Nunca se partió de delante del pueblo la columna de nube de día, ni de noche la columna de fuego.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, 'Y HABLÓ Jehová á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, 'Habla á los hijos de Israel que den la vuelta, y asienten su campo delante de Pihahiroth, entre Migdol y la mar hacia Baalzephón: delante de él asentaréis el campo, junto á la mar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'Porque Faraón dirá de los hijos de Israel: Encerrados están en la tierra, el desierto los ha encerrado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, 'Y yo endureceré el corazón de Faraón para que los siga; y seré glorificado en Faraón y en todo su ejército; y sabrán los Egipcios que yo soy Jehová. Y ellos lo hicieron así.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, 'Y fué dado aviso al rey de Egipto cómo el pueblo se huía: y el corazón de Faraón y de sus siervos se volvió contra el pueblo, y dijeron: ¿Cómo hemos hecho esto de haber dejado ir á Israel, para que no nos sirva?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'Y unció su carro, y tomó consigo su pueblo;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, 'Y tomó seiscientos carros escogidos, y todos los carros de Egipto, y los capitanes sobre ellos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'Y endureció Jehová el corazón de Faraón rey de Egipto, y siguió á los hijos de Israel; pero los hijos de Israel habían salido con mano poderosa.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'Siguiéndolos, pues, los Egipcios, con toda la caballería y carros de Faraón, su gente de á caballo, y todo su ejército, alcanzáronlos asentando el campo junto á la mar, al lado de Pihahiroth, delante de Baalzephón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, 'Y cuando Faraón se hubo acercado, los hijos de Israel alzaron sus ojos, y he aquí los Egipcios que venían tras ellos; por lo que temieron en gran manera, y clamaron los hijos de Israel á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, 'Y dijeron á Moisés: ¿No había sepulcros en Egipto, que nos has sacado para que muramos en el desierto? ¿Por qué lo has hecho así con nosotros, que nos has sacado de Egipto?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, '¿No es esto lo que te hablamos en Egipto, diciendo: Déjanos servir á los Egipcios? Que mejor nos fuera servir á los Egipcios, que morir nosotros en el desierto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, 'Y Moisés dijo al pueblo: No temáis; estáos quedos, y ved la salud de Jehová, que él hará hoy con vosotros; porque los Egipcios que hoy habéis visto, nunca más para siempre los veréis.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'Jehová peleará por vosotros, y vosotros estaréis quedos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, 'Entonces Jehová dijo á Moisés: ¿Por qué clamas á mí? di á los hijos de Israel que marchen:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, 'Y tú alza tu vara, y extiende tu mano sobre la mar, y divídela; y entren los hijos de Israel por medio de la mar en seco.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, 'Y yo, he aquí yo endureceré el corazón de los Egipcios, para que los sigan: y yo me glorificaré en Faraón, y en todo su ejército, y en sus carros, y en su caballería;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, 'Y sabrán los Egipcios que yo soy Jehová, cuando me glorificaré en Faraón, en sus carros, y en su gente de á caballo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, 'Y el ángel de Dios que iba delante del campo de Israel, se apartó, é iba en pos de ellos; y asimismo la columna de nube que iba delante de ellos, se apartó, y púsose á sus espaldas:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, 'E iba entre el campo de los Egipcios y el campo de Israel; y era nube y tinieblas para aquéllos, y alumbraba á Israel de noche: y en toda aquella noche nunca llegaron los unos á los otros.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'Y extendió Moisés su mano sobre la mar, é hizo Jehová que la mar se retirase por recio viento oriental toda aquella noche; y tornó la mar en seco, y las aguas quedaron divididas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'Entonces los hijos de Israel entraron por medio de la mar en seco, teniendo las aguas como muro á su diestra y á su siniestra:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'Y siguiéndolos los Egipcios, entraron tras ellos hasta el medio de la mar, toda la caballería de Faraón, sus carros, y su gente de á caballo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, 'Y aconteció á la vela de la mañana, que Jehová miró al campo de los Egipcios desde la columna de fuego y nube, y perturbó el campo de los Egipcios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, 'Y quitóles las ruedas de sus carros, y trastornólos gravemente. Entonces los Egipcios dijeron: Huyamos de delante de Israel, porque Jehová pelea por ellos contra los Egipcios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, 'Y Jehová dijo á Moisés: Extiende tu mano sobre la mar, para que las aguas vuelvan sobre los Egipcios, sobre sus carros, y sobre su caballería.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, 'Y Moisés extendió su mano sobre la mar, y la mar se volvió en su fuerza cuando amanecía; y los Egipcios iban hacia ella: y Jehová derribó á los Egipcios en medio de la mar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, 'Y volvieron las aguas, y cubrieron los carros y la caballería, y todo el ejército de Faraón que había entrado tras ellos en la mar; no quedó de ellos ni uno.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, 'Y los hijos de Israel fueron por medio de la mar en seco, teniendo las aguas por muro á su diestra y á su siniestra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, 'Así salvó Jehová aquel día á Israel de mano de los Egipcios; é Israel vió á los Egipcios muertos á la orilla de la mar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'Y vió Israel aquel grande hecho que Jehová ejecutó contra los Egipcios: y el pueblo temió á Jehová, y creyeron á Jehová y á Moisés su siervo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, 'ENTONCES cantó Moisés y los hijos de Israel este cántico á Jehová, y dijeron: Cantaré yo á Jehová, porque se ha magnificado grandemente, echando en la mar al caballo y al que en él subía.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'Jehová es mi fortaleza, y mi canción, y hame sido por salud: éste es mi Dios, y á éste engrandeceré; Dios de mi padre, y á éste ensalzaré.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'Jehová, varón de guerra; Jehová es su nombre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, 'Los carros de Faraón y á su ejército echó en la mar; y sus escogidos príncipes fueron hundidos en el mar Bermejo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, 'Los abismos los cubrieron; como piedra descendieron á los profundos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'Tu diestra, oh Jehová, ha sido magnificada en fortaleza; tu diestra, oh Jehová, ha quebrantado al enemigo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, 'Y con la grandeza de tu poder has trastornado á los que se levantaron contra ti: enviaste tu furor; los tragó como á hojarasca.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, 'Con el soplo de tus narices se amontonaron las aguas; paráronse las corrientes como en un montón; los abismos se cuajaron en medio de la mar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, 'El enemigo dijo: Perseguiré, prenderé, repartiré despojos; mi alma se henchirá de ellos; sacaré mi espada, destruirlos ha mi mano.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, 'Soplaste con tu viento, cubriólos la mar: hundiéronse como plomo en las impetuosas aguas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, '¿Quién como tú, Jehová, entre los dioses? ¿quién como tú, magnífico en santidad, terrible en loores, hacedor de maravillas?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, 'Extendiste tu diestra; la tierra los tragó.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, 'Condujiste en tu misericordia á este pueblo, al cual salvaste; llevástelo con tu fortaleza á la habitación de tu santuario.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, 'Oiránlo los pueblos, y temblarán; apoderarse ha dolor de los moradores de Palestina.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'Entonces los príncipes de Edom se turbarán; á los robustos de Moab los ocupará temblor; abatirse han todos los moradores de Canaán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, 'Caiga sobre ellos temblor y espanto; á la grandeza de tu brazo enmudezcan como una piedra; hasta que haya pasado tu pueblo, oh Jehová, hasta que haya pasado este pueblo que tú rescataste.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, 'Tú los introducirás y los plantarás en el monte de tu heredad, en el lugar de tu morada, que tú has aparejado, oh Jehová; en el santuario del Señor, que han afirmado tus manos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'Jehová reinará por los siglos de los siglos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, 'Porque Faraón entró cabalgando con sus carros y su gente de á caballo en la mar, y Jehová volvió á traer las aguas de la mar sobre ellos; mas los hijos de Israel fueron en seco por medio de la mar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, 'Y María la profetisa, hermana de Aarón, tomó un pandero en su mano, y todas las mujeres salieron en pos de ella con panderos y danzas;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'Y María les respondía: Cantad á Jehová; porque en extremo se ha engrandecido, echando en la mar al caballo, y al que en él subía.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, 'E hizo Moisés que partiese Israel del mar Bermejo, y salieron al desierto de Shur; y anduvieron tres días por el desierto sin hallar agua.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, 'Y llegaron á Mara, y no pudieron beber las aguas de Mara, porque eran amargas; por eso le pusieron el nombre de Mara.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, 'Entonces el pueblo murmuró contra Moisés, y dijo: ¿Qué hemos de beber?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'Y Moisés clamó á Jehová; y Jehová le mostró un árbol, el cual metídolo que hubo dentro de las aguas, las aguas se endulzaron. Allí les dió estatutos y ordenanzas, y allí los probó;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, 'Y dijo: Si oyeres atentamente la voz de Jehová tu Dios, é hicieres lo recto delante de sus ojos, y dieres oído á sus mandamientos, y guardares todos sus estatutos, ninguna enfermedad de las que envié á los Egipcios te enviaré á ti; porque yo soy Jehová tu Sanador.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, 'Y llegaron á Elim, donde había doce fuentes de aguas, y setenta palmas; y asentaron allí junto á las aguas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, 'Y PARTIENDO de Elim toda la congregación de los hijos de Israel, vino al desierto de Sin, que está entre Elim y Sinaí, á los quince días del segundo mes después que salieron de la tierra de Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, 'Y toda la congregación de los hijos de Israel murmuró contra Moisés y Aarón en el desierto;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, 'Y decíanles los hijos de Israel: Ojalá hubiéramos muerto por mano de Jehová en la tierra de Egipto, cuando nos sentábamos á las ollas de las carnes, cuando comíamos pan en hartura; pues nos habéis sacado á este desierto, para matar de hambre á toda esta multitud.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, 'Y Jehová dijo á Moisés: He aquí yo os haré llover pan del cielo; y el pueblo saldrá, y cogerá para cada un día, para que yo le pruebe si anda en mi ley, ó no.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, 'Mas al sexto día aparejarán lo que han de encerrar, que será el doble de lo que solían coger cada día.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'Entonces dijo Moisés y Aarón á todos los hijos de Israel: A la tarde sabréis que Jehová os ha sacado de la tierra de Egipto:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, 'Y á la mañana veréis la gloria de Jehová; porque él ha oído vuestras murmuraciones contra Jehová; que nosotros, ¿qué somos, para que vosotros murmuréis contra nosotros?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'Y dijo Moisés: Jehová os dará á la tarde carne para comer, y á la mañana pan en hartura; por cuanto Jehová ha oído vuestras murmuraciones con que habéis murmurado contra él: que nosotros, ¿qué somos? vuestras murmuraciones no son contra nosotros, sino contra Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'Y dijo Moisés á Aarón: Di á toda la congregación de los hijos de Israel: Acercaos á la presencia de Jehová; que él ha oído vuestras murmuraciones.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, 'Y hablando Aarón á toda la congregación de los hijos de Israel, miraron hacia el desierto, y he aquí la gloria de Jehová, que apareció en la nube.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, 'Y Jehová habló á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, 'Yo he oído las murmuraciones de los hijos de Israel; háblales, diciendo: Entre las dos tardes comeréis carne, y por la mañana os hartaréis de pan, y sabréis que yo soy Jehová vuestro Dios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, 'Y venida la tarde subieron codornices que cubrieron el real; y á la mañana descendió rocío en derredor del real.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'Y como el rocío cesó de descender, he aquí sobre la haz del desierto una cosa menuda, redonda, menuda como una helada sobre la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, 'Y viéndolo los hijos de Israel, se dijeron unos á otros: ¿Qué es esto? porque no sabían qué era. Entonces Moisés les dijo: Es el pan que Jehová os da para comer.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, 'Esto es lo que Jehová ha mandado: cogeréis de él cada uno según pudiere comer; un gomer por cabeza, conforme al número de vuestras personas, tomaréis cada uno para los que están en su tienda.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'Y los hijos de Israel lo hicieron así: y recogieron unos más, otros menos:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'Y medíanlo por gomer, y no sobraba al que había recogido mucho, ni faltaba al que había recogido poco: cada uno recogió conforme á lo que había de comer.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, 'Y díjoles Moisés: Ninguno deje nada de ello para mañana.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, 'Mas ellos no obedecieron á Moisés, sino que algunos dejaron de ello para otro día, y crió gusanos, y pudrióse; y enojóse contra ellos Moisés.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, 'Y recogíanlo cada mañana, cada uno según lo que había de comer: y luego que el sol calentaba, derretíase.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, 'En el sexto día recogieron doblada comida, dos gomeres para cada uno: y todos los príncipes de la congregación vinieron á Moisés, y se lo hicieron saber.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'Y él les dijo: Esto es lo que ha dicho Jehová: Mañana es el santo sábado, el reposo de Jehová: lo que hubiereis de cocer, cocedlo hoy, y lo que hubiereis de cocinar, cocinadlo; y todo lo que os sobrare, guardadlo para mañana.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, 'Y ellos lo guardaron hasta la mañana, según que Moisés había mandado, y no se pudrió, ni hubo en él gusano.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, 'Y dijo Moisés: Comedlo hoy, porque hoy es sábado de Jehová: hoy no hallaréis en el campo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, 'En los seis días lo recogeréis; mas el séptimo día es sábado, en el cual no se hallará.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, 'Y aconteció que algunos del pueblo salieron en el séptimo día á recoger, y no hallaron.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, 'Y Jehová dijo á Moisés: ¿Hasta cuándo no querréis guardar mis mandamientos y mis leyes?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, 'Mirad que Jehová os dió el sábado, y por eso os da en el sexto día pan para dos días. Estése, pues, cada uno en su estancia, y nadie salga de su lugar en el séptimo día.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, 'Así el pueblo reposó el séptimo día.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'Y la casa de Israel lo llamó Maná; y era como simiente de culantro, blanco, y su sabor como de hojuelas con miel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'Y dijo Moisés: Esto es lo que Jehová ha mandado: Henchirás un gomer de él para que se guarde para vuestros descendientes, á fin de que vean el pan que yo os dí á comer en el desierto, cuando yo os saqué de la tierra de Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, 'Y dijo Moisés á Aarón: Toma un vaso, y pon en él un gomer lleno de maná, y ponlo delante de Jehová, para que sea guardado para vuestros descendientes.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, 'Y Aarón lo puso delante del Testimonio para guardarlo, como Jehová lo mandó á Moisés.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'Así comieron los hijos de Israel maná cuarenta años, hasta que entraron en la tierra habitada: maná comieron hasta que llegaron al término de la tierra de Canaán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, 'Y un gomer es la décima parte del epha.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, 'Y TODA la congregación de los hijos de Israel partió del desierto de Sin, por sus jornadas, al mandamiento de Jehová, y asentaron el campo en Rephidim: y no había agua para que el pueblo bebiese.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, 'Y altercó el pueblo con Moisés, y dijeron: Danos agua que bebamos. Y Moisés les dijo: ¿Por qué altercáis conmigo? ¿por qué tentáis á Jehová?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, 'Así que el pueblo tuvo allí sed de agua, y murmuró contra Moisés, y dijo: ¿Por qué nos hiciste subir de Egipto, para matarnos de sed á nosotros, y á nuestros hijos, y á nuestros ganados?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, 'Entonces clamó Moisés á Jehová, diciendo: ¿Qué haré con este pueblo? de aquí á un poco me apedrearán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, 'Y Jehová dijo á Moisés: Pasa delante del pueblo, y toma contigo de los ancianos de Israel; y toma también en tu mano tu vara, con que heriste el río, y ve:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, 'He aquí que yo estoy delante de ti allí sobre la peña en Horeb; y herirás la peña, y saldrán de ella aguas, y beberá el pueblo. Y Moisés lo hizo así en presencia de los ancianos de Israel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'Y llamó el nombre de aquel lugar Massah y Meribah, por la rencilla de los hijos de Israel, y porque tentaron á Jehová, diciendo: ¿Está, pues, Jehová entre nosotros, ó no?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, 'Y vino Amalec, y peleó con Israel en Rephidim.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'Y dijo Moisés á Josué: Escógenos varones, y sal, pelea con Amalec: mañana yo estaré sobre la cumbre del collado, y la vara de Dios en mi mano.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'E hizo Josué como le dijo Moisés, peleando con Amalec; y Moisés y Aarón y Hur subieron á la cumbre del collado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'Y sucedía que cuando alzaba Moisés su mano, Israel prevalecía; mas cuando él bajaba su mano, prevalecía Amalec.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, 'Y las manos de Moisés estaban pesadas; por lo que tomaron una piedra, y pusiéronla debajo de él, y se sentó sobre ella: y Aarón y Hur sustentaban sus manos, el uno de una parte y el otro de otra; así hubo en sus manos firmeza hasta que se puso el sol.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, 'Y Josué deshizo á Amalec y á su pueblo á filo de espada.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, 'Y Jehová dijo á Moisés: Escribe esto para memoria en un libro, y di á Josué que del todo tengo de raer la memoria de Amalec de debajo del cielo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, 'Y Moisés edificó un altar, y llamó su nombre Jehová-nissi;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, 'Y dijo: Por cuanto la mano sobre el trono de Jehová, Jehová tendrá guerra con Amalec de generación en generación.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, 'Y OYÓ Jethro, sacerdote de Madián, suegro de Moisés, todas las cosas que Dios había hecho con Moisés, y con Israel su pueblo, y cómo Jehová había sacado á Israel de Egipto:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, 'Y tomó Jethro, suegro de Moisés, á Séphora la mujer de Moisés, después que él la envió,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'Y á sus dos hijos; el uno se llamaba Gersom, porque dijo, Peregrino he sido en tierra ajena;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, 'Y el otro se llamaba Eliezer, porque dijo, El Dios de mi padre me ayudó, y me libró del cuchillo de Faraón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, 'Y Jethro, el suegro de Moisés, con sus hijos y su mujer, llegó á Moisés en el desierto, donde tenía el campo junto al monte de Dios;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, 'Y dijo á Moisés: Yo tu suegro Jethro vengo á ti, con tu mujer, y sus dos hijos con ella.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'Y Moisés salió á recibir á su suegro, é inclinóse, y besólo: y preguntáronse el uno al otro cómo estaban, y vinieron á la tienda.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, 'Y Moisés contó á su suegro todas las cosas que Jehová había hecho á Faraón y á los Egipcios por amor de Israel, y todo el trabajo que habían pasado en el camino, y cómo los había librado Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'Y alegróse Jethro de todo el bien que Jehová había hecho á Israel, que lo había librado de mano de los Egipcios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, 'Y Jethro dijo: Bendito sea Jehová, que os libró de mano de los Egipcios, y de la mano de Faraón, y que libró al pueblo de la mano de los Egipcios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, 'Ahora conozco que Jehová es grande más que todos los dioses; hasta en lo que se ensoberbecieron contra ellos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, 'Y tomó Jethro, suegro de Moisés, holocaustos y sacrificios para Dios: y vino Aarón y todos los ancianos de Israel á comer pan con el suegro de Moisés delante de Dios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, 'Y aconteció que otro día se sentó Moisés á juzgar al pueblo; y el pueblo estuvo delante de Moisés desde la mañana hasta la tarde.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'Y viendo el suegro de Moisés todo lo que él hacía con el pueblo, dijo: ¿Qué es esto que haces tú con el pueblo? ¿por qué te sientas tú solo, y todo el pueblo está delante de ti desde la mañana hasta la tarde?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, 'Y Moisés respondió á su suegro: Porque el pueblo viene á mí para consultar á Dios:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, 'Cuando tienen negocios, vienen á mí; y yo juzgo entre el uno y el otro, y declaro las ordenanzas de Dios y sus leyes.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, 'Entonces el suegro de Moisés le dijo: No haces bien:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, 'Desfallecerás del todo, tú, y también este pueblo que está contigo; porque el negocio es demasiado pesado para ti; no podrás hacerlo tú solo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, 'Oye ahora mi voz, yo te aconsejaré, y Dios será contigo. Está tú por el pueblo delante de Dios, y somete tú los negocios á Dios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, 'Y enseña á ellos las ordenanzas y las leyes, y muéstrales el camino por donde anden, y lo que han de hacer.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'Además inquiere tú de entre todo el pueblo varones de virtud, temerosos de Dios, varones de verdad, que aborrezcan la avaricia; y constituirás á éstos sobre ellos caporales sobre mil, sobre ciento, sobre cincuenta y sobre diez.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, 'Los cuales juzgarán al pueblo en todo tiempo; y será que todo negocio grave lo traerán á ti, y ellos juzgarán todo negocio pequeño: alivia así la carga de sobre ti, y llevarla han ellos contigo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, 'Si esto hicieres, y Dios te lo mandare, tú podrás persistir, y todo este pueblo se irá también en paz á su lugar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'Y oyó Moisés la voz de su suegro, é hizo todo lo que dijo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'Y escogió Moisés varones de virtud de todo Israel, y púsolos por cabezas sobre el pueblo, caporales sobre mil, sobre ciento, sobre cincuenta, y sobre diez;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, 'Y juzgaban al pueblo en todo tiempo: el negocio arduo traíanlo á Moisés, y ellos juzgaban todo negocio pequeño.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, 'Y despidió Moisés á su suegro, y fuése á su tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, 'AL mes tercero de la salida de los hijos de Israel de la tierra de Egipto, en aquel día vinieron al desierto de Sinaí.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, 'Porque partieron de Rephidim, y llegaron al desierto de Sinaí, y asentaron en el desierto; y acampó allí Israel delante del monte.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, 'Y Moisés subió á Dios; y Jehová lo llamó desde el monte, diciendo: Así dirás á la casa de Jacob, y denunciarás á los hijos de Israel:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, 'Vosotros visteis lo que hice á los Egipcios, y cómo os tomé sobre alas de águilas, y os he traído á mí.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, 'Ahora pues, si diereis oído á mi voz, y guardareis mi pacto, vosotros seréis mi especial tesoro sobre todos los pueblos; porque mía es toda la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, 'Y vosotros seréis mi reino de sacerdotes, y gente santa. Estas son las palabras que dirás á los hijos de Israel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, 'Entonces vino Moisés, y llamó á los ancianos del pueblo, y propuso en presencia de ellos todas estas palabras que Jehová le había mandado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, 'Y todo el pueblo respondió á una, y dijeron: Todo lo que Jehová ha dicho haremos. Y Moisés refirió las palabras del pueblo á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'Y Jehová dijo á Moisés: He aquí, yo vengo á ti en una nube espesa, para que el pueblo oiga mientras yo hablo contigo, y también para que te crean para siempre. Y Moisés denunció las palabras del pueblo á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, 'Y Jehová dijo á Moisés: Ve al pueblo, y santifícalos hoy y mañana, y laven sus vestidos;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, 'Y estén apercibidos para el día tercero, porque al tercer día Jehová descenderá, á ojos de todo el pueblo, sobre el monte de Sinaí.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, 'Y señalarás término al pueblo en derredor, diciendo: Guardaos, no subáis al monte, ni toquéis á su término: cualquiera que tocare el monte, de seguro morirá:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, 'No le tocará mano, mas será apedreado ó asaeteado; sea animal ó sea hombre, no vivirá. En habiendo sonado largamente la bocina, subirán al monte.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'Y descendió Moisés del monte al pueblo, y santificó al pueblo; y lavaron sus vestidos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, 'Y dijo al pueblo: Estad apercibidos para el tercer día; no lleguéis á mujer.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, 'Y aconteció al tercer día cuando vino la mañana, que vinieron truenos y relámpagos, y espesa nube sobre el monte, y sonido de bocina muy fuerte; y estremecióse todo el pueblo que estaba en el real.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'Y Moisés sacó del real al pueblo á recibir á Dios; y pusiéronse á lo bajo del monte.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'Y todo el monte de Sinaí humeaba, porque Jehová había descendido sobre él en fuego: y el humo de él subía como el humo de un horno, y todo el monte se estremeció en gran manera.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, 'Y el sonido de la bocina iba esforzándose en extremo: Moisés hablaba, y Dios le respondía en voz.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'Y descendió Jehová sobre el monte de Sinaí, sobre la cumbre del monte: y llamó Jehová á Moisés á la cumbre del monte, y Moisés subió.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'Y Jehová dijo á Moisés: Desciende, requiere al pueblo que no traspasen el término por ver á Jehová, porque caerá multitud de ellos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, 'Y también los sacerdotes que se llegan á Jehová, se santifiquen, porque Jehová no haga en ellos estrago.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, 'Y Moisés dijo á Jehová: El pueblo no podrá subir al monte de Sinaí, porque tú nos has requerido diciendo: Señala términos al monte, y santifícalo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, 'Y Jehová le dijo: Ve, desciende, y subirás tú, y Aarón contigo: mas los sacerdotes y el pueblo no traspasen el término por subir á Jehová, porque no haga en ellos estrago.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'Entonces Moisés descendió al pueblo, y habló con ellos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, 'Y HABLÓ Dios todas estas palabras, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, 'Yo soy JEHOVÁ tu Dios, que te saqué de la tierra de Egipto, de casa de siervos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, 'No tendrás dioses ajenos delante de mí.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, 'No te harás imagen, ni ninguna semejanza de cosa que esté arriba en el cielo, ni abajo en la tierra, ni en las aguas debajo de la tierra:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, 'No te inclinarás á ellas, ni las honrarás; porque yo soy Jehová tu Dios, fuerte, celoso, que visito la maldad de los padres sobre los hijos, sobre los terceros y sobre los cuartos, á los que me aborrecen,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, 'Y que hago misericordia en millares á los que me aman, y guardan mis mandamientos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, 'No tomarás el nombre de Jehová tu Dios en vano; porque no dará por inocente Jehová al que tomare su nombre en vano.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, 'Acordarte has del día del reposo, para santificarlo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, 'Seis días trabajarás, y harás toda tu obra;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, 'Mas el séptimo día será reposo para Jehová tu Dios: no hagas en él obra alguna, tú, ni tu hijo, ni tu hija, ni tu siervo, ni tu criada ni tu bestia, ni tu extranjero que está dentro de tus puertas:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, 'Porque en seis días hizo Jehová los cielos y la tierra, la mar y todas las cosas que en ellos hay, y reposó en el séptimo día: por tanto Jehová bendijo el día del reposo y lo santificó.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, 'Honra á tu padre y á tu madre, porque tus días se alarguen en la tierra que Jehová tu Dios te da.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, 'No matarás.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, 'No cometerás adulterio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, 'No hurtarás.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, 'No hablarás contra tu prójimo falso testimonio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, 'No codiciarás la casa de tu prójimo, no codiciarás la mujer de tu prójimo, ni su siervo, ni su criada, ni su buey, ni su asno, ni cosa alguna de tu prójimo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, 'Todo el pueblo consideraba las voces, y las llamas, y el sonido de la bocina, y el monte que humeaba: y viéndolo el pueblo, temblaron, y pusiéronse de lejos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'Y dijeron á Moisés: Habla tú con nosotros, que nosotros oiremos; mas no hable Dios con nosotros, porque no muramos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, 'Y Moisés respondió al pueblo: No temáis; que por probaros vino Dios, y porque su temor esté en vuestra presencia para que no pequéis.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, 'Entonces el pueblo se puso de lejos, y Moisés se llegó á la osbcuridad, en la cual estaba Dios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, 'Y Jehová dijo á Moisés: Así dirás á los hijos de Israel: Vosotros habéis visto que he hablado desde el cielo con vosotros.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, 'No hagáis conmigo dioses de plata, ni dioses de oro os haréis.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, 'Altar de tierra harás para mí, y sacrificarás sobre él tus holocaustos y tus pacíficos, tus ovejas y tus vacas: en cualquier lugar donde yo hiciere que esté la memoria de mi nombre, vendré á ti, y te bendeciré.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, 'Y si me hicieres altar de piedras, no las labres de cantería; porque si alzares tu pico sobre él, tú lo profanarás.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, 'Y no subirás por gradas á mi altar, porque tu desnudez no sea junto á él descubierta.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, 'Y ESTOS son los derechos que les propondrás.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, 'Si comprares siervo hebreo, seis años servirá; mas el séptimo saldrá horro de balde.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, 'Si entró solo, solo saldrá: si tenía mujer, saldrá él y su mujer con él.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'Si su amo le hubiere dado mujer, y ella le hubiere parido hijos ó hijas, la mujer y sus hijos serán de su amo, y él saldrá solo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, 'Y si el siervo dijere: Yo amo á mi señor, á mi mujer y á mis hijos, no saldré libre:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, 'Entonces su amo lo hará llegar á los jueces, y harále llegar á la puerta ó al poste; y su amo le horadará la oreja con lesna, y será su siervo para siempre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, 'Y cuando alguno vendiere su hija por sierva, no saldrá como suelen salir los siervos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, 'Si no agradare á su señor, por lo cual no la tomó por esposa, permitirle ha que se rescate, y no la podrá vender á pueblo extraño cuando la desechare.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, 'Mas si la hubiere desposado con su hijo, hará con ella según la costumbre de las hijas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, 'Si le tomare otra, no disminuirá su alimento, ni su vestido, ni el débito conyugal.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, 'Y si ninguna de estas tres cosas hiciere, ella saldrá de gracia sin dinero.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, 'El que hiriere á alguno, haciéndole así morir, él morirá.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'Mas el que no armó asechanzas, sino que Dios lo puso en sus manos, entonces yo te señalaré lugar al cual ha de huir.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, 'Además, si alguno se ensoberbeciere contra su prójimo, y lo matare con alevosía, de mi altar lo quitarás para que muera.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'Y el que hiriere á su padre ó á su madre, morirá.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, 'Asimismo el que robare una persona, y la vendiere, ó se hallare en sus manos, morirá.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, 'Igualmente el que maldijere á su padre ó á su madre, morirá.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, 'Además, si algunos riñeren, y alguno hiriere á su prójimo con piedra ó con el puño, y no muriere, pero cayere en cama;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, 'Si se levantare y anduviere fuera sobre su báculo, entonces será el que le hirió absuelto: solamente le satisfará lo que estuvo parado, y hará que le curen.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'Y si alguno hiriere á su siervo ó á su sierva con palo, y muriere bajo de su mano, será castigado:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'Mas si durare por un día ó dos, no será castigado, porque su dinero es.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, 'Si algunos riñeren, é hiriesen á mujer preñada, y ésta abortare, pero sin haber muerte, será penado conforme á lo que le impusiere el marido de la mujer y juzgaren los árbitros.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, 'Mas si hubiere muerte, entonces pagarás vida por vida,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, 'Ojo por ojo, diente por diente, mano por mano, pie por pie,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, 'Quemadura por quemadura, herida por herida, golpe por golpe.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, 'Y cuando alguno hiriere el ojo de su siervo, ó el ojo de su sierva, y lo entortare, darále libertad por razón de su ojo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, 'Y si sacare el diente de su siervo, ó el diente de su sierva, por su diente le dejará ir libre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, 'Si un buey acorneare hombre ó mujer, y de resultas muriere, el buey será apedreado, y no se comerá su carne; mas el dueño del buey será absuelto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, 'Pero si el buey era acorneador desde ayer y antes de ayer, y á su dueño le fué hecho requerimiento, y no lo hubiere guardado, y matare hombre ó mujer, el buey será apedreado, y también morirá su dueño.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, 'Si le fuere impuesto rescate, entonces dará por el rescate de su persona cuanto le fuere impuesto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, 'Haya acorneado hijo, ó haya acorneado hija, conforme á este juicio se hará con él.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, 'Si el buey acorneare siervo ó sierva, pagará treinta siclos de plata su señor, y el buey será apedreado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, 'Y si alguno abriere hoyo, ó cavare cisterna, y no la cubriere, y cayere allí buey ó asno,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, 'El dueño de la cisterna pagará el dinero, resarciendo á su dueño, y lo que fué muerto será suyo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, 'Y si el buey de alguno hiriere al buey de su prójimo, y éste muriere, entonces venderán el buey vivo, y partirán el dinero de él, y también partirán el muerto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, 'Mas si era notorio que el buey era acorneador de ayer y antes de ayer, y su dueño no lo hubiere guardado, pagará buey por buey, y el muerto será suyo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, 'CUANDO alguno hurtare buey ú oveja, y le degollare ó vendiere, por aquel buey pagará cinco bueyes, y por aquella oveja cuatro ovejas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, 'Si el ladrón fuere hallado forzando una casa, y fuere herido y muriere, el que le hirió no será culpado de su muerte.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, 'Si el sol hubiere sobre él salido, el matador será reo de homicidio: el ladrón habrá de restituir cumplidamente; si no tuviere, será vendido por su hurto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, 'Si fuere hallado con el hurto en la mano, sea buey ó asno ú oveja vivos, pagará el duplo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, 'Si alguno hiciere pacer campo ó viña, y metiere su bestia, y comiere la tierra de otro, de lo mejor de su tierra y de lo mejor de su viña pagará.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, 'Cuando rompiere un fuego, y hallare espinas, y fuere quemado montón, ó haza, ó campo, el que encendió el fuego pagará lo quemado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, 'Cuando alguno diere á su prójimo plata ó alhajas á guardar, y fuere hurtado de la casa de aquel hombre, si el ladrón se hallare, pagará el doble.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, 'Si el ladrón no se hallare, entonces el dueño de la casa será presentado á los jueces, para ver si ha metido su mano en la hacienda de su prójimo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, 'Sobre todo negocio de fraude, sobre buey, sobre asno, sobre oveja, sobre vestido, sobre toda cosa perdida, cuando uno dijere: Esto es mío, la causa de ambos vendrá delante de los jueces; y el que los jueces condenaren, pagará el doble á su prójimo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, 'Si alguno hubiere dado á su prójimo asno, ó buey, ú oveja, ó cualquier otro animal á guardar, y se muriere, ó se perniquebrare, ó fuere llevado sin verlo nadie;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, 'Juramento de Jehová tendrá lugar entre ambos de que no echó su mano á la hacienda de su prójimo: y su dueño lo aceptará, y el otro no pagará.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, 'Mas si le hubiere sido hurtado, resarcirá á su dueño.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, 'Y si le hubiere sido arrebatado por fiera, traerle ha testimonio, y no pagará lo arrebatado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, 'Pero si alguno hubiere tomado prestada bestia de su prójimo, y fuere estropeada ó muerta, ausente su dueño, deberá pagar la.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, 'Si el dueño estaba presente, no la pagará. Si era alquilada, él vendrá por su alquiler.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, 'Y si alguno engañare á alguna doncella que no fuere desposada, y durmiere con ella, deberá dotarla y tomarla por mujer.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'Si su padre no quisiere dársela, él le pesará plata conforme al dote de las vírgenes.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, 'A la hechicera no dejarás que viva.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, 'Cualquiera que tuviere ayuntamiento con bestia, morirá.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, 'El que sacrificare á dioses, excepto á sólo Jehová, será muerto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, 'Y al extranjero no engañarás, ni angustiarás, porque extranjeros fuisteis vosotros en la tierra de Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, 'A ninguna viuda ni huérfano afligiréis.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, 'Que si tú llegas á afligirle, y él á mí clamare, ciertamente oiré yo su clamor;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'Y mi furor se encenderá, y os mataré á cuchillo, y vuestras mujeres serán viudas, y huérfanos vuestros hijos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, 'Si dieres á mi pueblo dinero emprestado, al pobre que está contigo, no te portarás con él como logrero, ni le impondrás usura.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, 'Si tomares en prenda el vestido de tu prójimo, á puestas del sol se lo volverás:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, 'Porque sólo aquello es su cubierta, es aquél el vestido para cubrir sus carnes, en el que ha de dormir: y será que cuando él á mí clamare, yo entonces le oiré, porque soy misericordioso.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, 'No denostarás á los jueces, ni maldecirás al príncipe de tu pueblo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, 'No dilatarás la primicia de tu cosecha, ni de tu licor: me darás el primogénito de tus hijos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, 'Así harás con el de tu buey y de tu oveja: siete días estará con su madre, y al octavo día me lo darás.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 31, 'Y habéis de serme varones santos: y no comeréis carne arrebatada de las fieras en el campo; á los perros la echaréis.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, 'NO admitirás falso rumor. No te concertarás con el impío para ser testigo falso.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, 'No seguirás á los muchos para mal hacer; ni responderás en litigio inclinándote á los más para hacer agravios;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, 'Ni al pobre distinguirás en su causa.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, 'Si encontrares el buey de tu enemigo ó su asno extraviado, vuelve á llevárselo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, 'Si vieres el asno del que te aborrece caído debajo de su carga, ¿le dejarás entonces desamparado? Sin falta ayudarás con él á levantarlo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, 'No pervertirás el derecho de tu mendigo en su pleito.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, 'De palabra de mentira te alejarás, y no matarás al inocente y justo; porque yo no justificaré al impío.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, 'No recibirás presente; porque el presente ciega á los que ven, y pervierte las palabras justas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, 'Y no angustiarás al extranjero: pues vosotros sabéis cómo se halla el alma del extranjero, ya que extranjeros fuisteis en la tierra de Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, 'Seis años sembrarás tu tierra, y allegarás su cosecha:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, 'Mas el séptimo la dejarás vacante y soltarás, para que coman los pobres de tu pueblo; y de lo que quedare comerán las bestias del campo; así harás de tu viña y de tu olivar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, 'Seis días harás tus negocios, y al séptimo día holgarás, á fin que descanse tu buey y tu asno, y tome refrigerio el hijo de tu sierva, y el extranjero.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, 'Y en todo lo que os he dicho seréis avisados. Y nombre de otros dioses no mentaréis, ni se oirá de vuestra boca.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, 'Tres veces en el año me celebraréis fiesta.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, 'La fiesta de los ázimos guardarás: siete días comerás los panes sin levadura, como yo te mandé, en el tiempo del mes de Abib; porque en él saliste de Egipto: y ninguno comparecerá vacío delante de mí:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, 'También la fiesta de la siega, los primeros frutos de tus labores que hubieres sembrado en el campo; y la fiesta de la cosecha á la salida del año, cuando habrás recogido tus labores del campo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, 'Tres veces en el año parecerá todo varón tuyo delante del Señor Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, 'No ofrecerás con pan leudo la sangre de mi sacrificio; ni el sebo de mi víctima quedará de la noche hasta la mañana.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, 'Las primicias de los primeros frutos de tu tierra traerás á la casa de Jehová tu Dios. No guisarás el cabrito con la leche de su madre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, 'He aquí yo envío el Angel delante de ti para que te guarde en el camino, y te introduzca en el lugar que yo he preparado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, 'Guárdate delante de él, y oye su voz; no le seas rebelde; porque él no perdonará vuestra rebelión: porque mi nombre está en él.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, 'Pero si en verdad oyeres su voz, é hicieres todo lo que yo te dijere, seré enemigo á tus enemigos, y afligiré á los que te afligieren.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'Porque mi Angel irá delante de ti, y te introducirá al Amorrheo, y al Hetheo, y al Pherezeo, y al Cananeo, y al Heveo, y al Jebuseo, á los cuales yo haré destruir.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, 'No te inclinarás á sus dioses, ni los servirás, ni harás como ellos hacen; antes los destruirás del todo, y quebrantarás enteramente sus estatuas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, 'Mas á Jehová vuestro Dios serviréis, y él bendecirá tu pan y tus aguas; y yo quitaré toda enfermedad de en medio de ti.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, 'No habrá mujer que aborte, ni estéril en tu tierra; y yo cumpliré el número de tus días.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, 'Yo enviaré mi terror delante de ti, y consternaré á todo pueblo donde tú entrares, y te daré la cerviz de todos tus enemigos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, 'Yo enviaré la avispa delante de ti, que eche fuera al Heveo, y al Cananeo, y al Hetheo, de delante de ti:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, 'No los echaré de delante de ti en un año, porque no quede la tierra desierta, y se aumenten contra ti las bestias del campo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, 'Poco á poco los echaré de delante de ti, hasta que te multipliques y tomes la tierra por heredad.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, 'Y yo pondré tu término desde el mar Bermejo hasta la mar de Palestina, y desde el desierto hasta el río: porque pondré en vuestras manos los moradores de la tierra, y tú los echarás de delante de ti.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, 'No harás alianza con ellos, ni con sus dioses.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, 'En tu tierra no habitarán, no sea que te hagan pecar contra mí sirviendo á sus dioses: porque te será de tropiezo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, 'Y DIJO á Moisés: Sube á Jehová, tú, y Aarón, Nadab, y Abiú, y setenta de los ancianos de Israel; y os inclinaréis desde lejos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'Mas Moisés sólo se llegará á Jehová; y ellos no se lleguen cerca, ni suba con él el pueblo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'Y Moisés vino y contó al pueblo todas las palabras de Jehová, y todos los derechos: y todo el pueblo respondió á una voz, y dijeron: Ejecutaremos todas las palabras que Jehová ha dicho.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'Y Moisés escribió todas las palabras de Jehová, y levantándose de mañana edificó un altar al pie del monte, y doce columnas, según las doce tribus de Israel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, 'Y envió á los mancebos de los hijos de Israel, los cuales ofrecieron holocaustos, y sacrificaron pacíficos á Jehová, becerros.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'Y Moisés tomó la mitad de la sangre, y púsola en tazones, y esparció la otra mitad de la sangre sobre el altar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, 'Y tomó el libro de la alianza, y leyó á oídos del pueblo, el cual dijo: Haremos todas las cosas que Jehová ha dicho, y obedeceremos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'Entonces Moisés tomó la sangre, y roció sobre el pueblo, y dijo: He aquí la sangre de la alianza que Jehová ha hecho con vosotros sobre todas estas cosas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, 'Y subieron Moisés y Aarón, Nadab y Abiú, y setenta de los ancianos de Israel;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'Y vieron al Dios de Israel; y había debajo de sus pies como un embaldosado de zafiro, semejante al cielo cuando está sereno.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, 'Mas no extendió su mano sobre los príncipes de los hijos de Israel: y vieron á Dios, y comieron y bebieron.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, 'Entonces Jehová dijo á Moisés: Sube á mí al monte, y espera allá, y te daré tablas de piedra, y la ley, y mandamientos que he escrito para enseñarlos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'Y levantóse Moisés, y Josué su ministro; y Moisés subió al monte de Dios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, 'Y dijo á los ancianos: Esperadnos aquí hasta que volvamos á vosotros: y he aquí Aarón y Hur están con vosotros: el que tuviere negocios, lléguese á ellos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, 'Entonces Moisés subió al monte, y una nube cubrió el monte.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'Y la gloria de Jehová reposó sobre el monte Sinaí, y la nube lo cubrió por seis días: y al séptimo día llamó á Moisés de en medio de la nube.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'Y el parecer de la gloria de Jehová era como un fuego abrasador en la cumbre del monte, á los ojos de los hijos de Israel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'Y entró Moisés en medio de la nube, y subió al monte: y estuvo Moisés en el monte cuarenta días y cuarenta noches.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, 'Y JEHOVÁ habló á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, 'Di á los hijos de Israel que tomen para mí ofrenda: de todo varón que la diere de su voluntad, de corazón, tomaréis mi ofrenda.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, 'Y esta es la ofrenda que tomaréis de ellos: Oro, y plata, y cobre,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, 'Y jacinto, y púrpura, y carmesí, y lino fino, y pelo de cabras,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, 'Y cueros de carneros teñidos de rojo, y cueros de tejones, y madera de Sittim;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, 'Aceite para la luminaria, especias para el aceite de la unción, y para el sahumerio aromático;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, 'Piedras de onix, y piedras de engastes, para el ephod, y para el racional.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, 'Y hacerme han un santuario, y yo habitaré entre ellos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, 'Conforme á todo lo que yo te mostrare, el diseño del tabernáculo, y el diseño de todos sus vasos, así lo haréis.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, 'Harán también un arca de madera de Sittim, cuya longitud será de dos codos y medio, y su anchura de codo y medio, y su altura de codo y medio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, 'Y la cubrirás de oro puro; por dentro y por fuera la cubrirás; y harás sobre ella una cornisa de oro alrededor.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, 'Y para ella harás de fundición cuatro anillos de oro, que pondrás á sus cuatro esquinas; dos anillos al un lado de ella, y dos anillos al otro lado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, 'Y harás unas varas de madera de Sittim, las cuales cubrirás de oro:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, 'Y meterás las varas por los anillos á los lados del arca, para llevar el arca con ellas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, 'Las varas se estarán en los anillos del arca: no se quitarán de ella.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, 'Y pondrás en el arca el testimonio que yo te daré.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, 'Y harás una cubierta de oro fino, cuya longitud será de dos codos y medio, y su anchura de codo y medio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, 'Harás también dos querubines de oro, labrados á martillo los harás, en los dos cabos de la cubierta.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, 'Harás, pues, un querubín al extremo de un lado, y un querubín al otro extremo del lado opuesto: de la calidad de la cubierta harás los querubines en sus dos extremidades.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'Y los querubines extenderán por encima las alas, cubriendo con sus alas la cubierta: sus caras la una enfrente de la otra, mirando á la cubierta las caras de los querubines.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, 'Y pondrás la cubierta encima del arca, y en el arca pondrás el testimonio que yo te daré.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, 'Y de allí me declararé á ti, y hablaré contigo de sobre la cubierta, de entre los dos querubines que están sobre el arca del testimonio, todo lo que yo te mandaré para los hijos de Israel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, 'Harás asimismo una mesa de madera de Sittim: su longitud será de dos codos, y de un codo su anchura, y su altura de codo y medio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, 'Y la cubrirás de oro puro, y le has de hacer una cornisa de oro alrededor.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, 'Hacerle has también una moldura alrededor, del ancho de una mano, á la cual moldura harás una cornisa de oro en circunferencia.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'Y le harás cuatro anillos de oro, los cuales pondrás á las cuatro esquinas que corresponden á sus cuatro pies.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, 'Los anillos estarán antes de la moldura, por lugares de las varas, para llevar la mesa.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'Y harás las varas de madera de Sittim, y las cubrirás de oro, y con ellas será llevada la mesa.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, 'Harás también sus platos, y sus cucharas, y sus cubiertas, y sus tazones, con que se libará: de oro fino los harás.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, 'Y pondrás sobre la mesa el pan de la proposición delante de mí continuamente.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, 'Harás además un candelero de oro puro; labrado á martillo se hará el candelero: su pie, y su caña, sus copas, sus manzanas, y sus flores, serán de lo mismo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, 'Y saldrán seis brazos de sus lados: tres brazos del candelero del un lado suyo, y tres brazos del candelero del otro su lado:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, 'Tres copas en forma de almendras en el un brazo, una manzana y una flor; y tres copas, figura de almendras, en el otro brazo, una manzana y una flor: así pues, en los seis brazos que salen del candelero:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, 'Y en el candelero cuatro copas en forma de almendras, sus manzanas y sus flores.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, 'Habrá una manzana debajo de los dos brazos de lo mismo, otra manzana debajo de los otros dos brazos de lo mismo, y otra manzana debajo de los otros dos brazos de lo mismo, en conformidad á los seis brazos que salen del candelero.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'Sus manzanas y sus brazos serán de lo mismo, todo ello una pieza labrada á martillo, de oro puro.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, 'Y hacerle has siete candilejas, las cuales encenderás para que alumbren á la parte de su delantera:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'También sus despabiladeras y sus platillos, de oro puro.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, 'De un talento de oro fino lo harás, con todos estos vasos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, 'Y mira, y hazlos conforme á su modelo, que te ha sido mostrado en el monte.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, 'Y HARÁS el tabernáculo de diez cortinas de lino torcido, cárdeno, y púrpura, y carmesí: y harás querubines de obra delicada.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, 'La longitud de la una cortina de veintiocho codos, y la anchura de la misma cortina de cuatro codos: todas las cortinas tendrán una medida.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'Cinco cortinas estarán juntas la una con la otra, y cinco cortinas unidas la una con la otra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, 'Y harás lazadas de cárdeno en la orilla de la una cortina, en el borde, en la juntura: y así harás en la orilla de la postrera cortina en la juntura segunda.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, 'Cincuenta lazadas harás en la una cortina, y cincuenta lazadas harás en el borde de la cortina que está en la segunda juntura: las lazadas estarán contrapuestas la una á la otra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, 'Harás también cincuenta corchetes de oro, con los cuales juntarás las cortinas la una con la otra, y se formará un tabernáculo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, 'Harás asimismo cortinas de pelo de cabras para una cubierta sobre el tabernáculo; once cortinas harás.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'La longitud de la una cortina será de treinta codos, y la anchura de la misma cortina de cuatro codos: una medida tendrán las once cortinas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, 'Y juntarás las cinco cortinas aparte y las otras seis cortinas separadamente; y doblarás la sexta cortina delante de la faz del tabernáculo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, 'Y harás cincuenta lazadas en la orilla de la una cortina, al borde en la juntura, y cincuenta lazadas en la orilla de la segunda cortina en la otra juntura.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, 'Harás asimismo cincuenta corchetes de alambre, los cuales meterás por las lazadas: y juntarás la tienda, para que se haga una sola cubierta.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'Y el sobrante que resulta en las cortinas de la tienda, la mitad de la una cortina que sobra, quedará á las espaldas del tabernáculo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, 'Y un codo de la una parte, y otro codo de la otra que sobra en la longitud de las cortinas de la tienda, cargará sobre los lados del tabernáculo de la una parte y de la otra, para cubrirlo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, 'Harás también á la tienda una cubierta de cueros de carneros, teñidos de rojo, y una cubierta de cueros de tejones encima.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, 'Y harás para el tabernáculo tablas de madera de Sittim, que estén derechas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, 'La longitud de cada tabla será de diez codos, y de codo y medio la anchura de cada tabla.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, 'Dos quicios tendrá cada tabla, trabadas la una con la otra; así harás todas las tablas del tabernáculo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, 'Harás, pues, las tablas del tabernáculo: veinte tablas al lado del mediodía, al austro.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, 'Y harás cuarenta basas de plata debajo de las veinte tablas; dos basas debajo de la una tabla para sus dos quicios, y dos basas debajo de la otra tabla para sus dos quicios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, 'Y al otro lado del tabernáculo, á la parte del aquilón, veinte tablas;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, 'Y sus cuarenta basas de plata: dos basas debajo de la una tabla, y dos basas debajo de la otra tabla.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, 'Y para el lado del tabernáculo, al occidente, harás seis tablas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, 'Harás además dos tablas para las esquinas del tabernáculo en los dos ángulos posteriores;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'Las cuales se unirán por abajo, y asimismo se juntarán por su alto á un gozne: así será de las otras dos que estarán á las dos esquinas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'De suerte que serán ocho tablas, con sus basas de plata, diez y seis basas; dos basas debajo de la una tabla, y dos basas debajo de la otra tabla.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, 'Harás también cinco barras de madera de Sittim, para las tablas del un lado del tabernáculo,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'Y cinco barras para las tablas del otro lado del tabernáculo, y cinco barras para el otro lado del tabernáculo, que está al occidente.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, 'Y la barra del medio pasará por medio de las tablas, del un cabo al otro.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, 'Y cubrirás las tablas de oro, y harás sus anillos de oro para meter por ellos las barras: también cubrirás las barras de oro.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, 'Y alzarás el tabernáculo conforme á su traza que te fué mostrada en el monte.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, 'Y harás también un velo de cárdeno, y púrpura, y carmesí, y de lino torcido: será hecho de primorosa labor, con querubines:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, 'Y has de ponerlo sobre cuatro columnas de madera de Sittim cubiertas de oro; sus capiteles de oro, sobre basas de plata.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, 'Y pondrás el velo debajo de los corchetes, y meterás allí, del velo adentro, el arca del testimonio; y aquel velo os hará separación entre el lugar santo y el santísimo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, 'Y pondrás la cubierta sobre el arca del testimonio en el lugar santísimo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, 'Y pondrás la mesa fuera del velo, y el candelero enfrente de la mesa al lado del tabernáculo al mediodía; y pondrás la mesa al lado del aquilón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, 'Y harás á la puerta del tabernáculo una cortina de cárdeno, y púrpura, y carmesí, y lino torcido, obra de bordador.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, 'Y harás para la cortina cinco columnas de madera de Sittim, las cuales cubrirás de oro, con sus capiteles de oro: y hacerlas has de fundición cinco basas de metal.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, 'HARÁS también altar de madera de Sittim de cinco codos de longitud, y de cinco codos de anchura: será cuadrado el altar, y su altura de tres codos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'Y harás sus cuernos á sus cuatro esquinas; los cuernos serán de lo mismo; y lo cubrirás de metal.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, 'Harás también sus calderas para echar su ceniza; y sus paletas, y sus tazones, y sus garfios, y sus braseros: harás todos sus vasos de metal.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, 'Y le harás un enrejado de metal de obra de malla; y sobre el enrejado harás cuatro anillos de metal á sus cuatro esquinas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, 'Y lo has de poner dentro del cerco del altar abajo; y llegará el enrejado hasta el medio del altar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, 'Harás también varas para el altar, varas de madera de Sittim, las cuales cubrirás de metal.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'Y sus varas se meterán por los anillos: y estarán aquellas varas á ambos lados del altar, cuando hubiere de ser llevado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, 'De tablas lo harás, hueco: de la manera que te fué mostrado en el monte, así lo harás.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, 'Asimismo harás el atrio del tabernáculo: al lado del mediodía, al austro, tendrá el atrio cortinas de lino torcido, de cien codos de longitud cada un lado;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'Sus veinte columnas, y sus veinte basas serán de metal; los capiteles de las columnas y sus molduras, de plata.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, 'Y de la misma manera al lado del aquilón habrá á lo largo cortinas de cien codos de longitud, y sus veinte columnas, con sus veinte basas de metal; los capiteles de sus columnas y sus molduras, de plata.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, 'Y el ancho del atrio del lado occidental tendrá cortinas de cincuenta codos; sus columnas diez, con sus diez basas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'Y en el ancho del atrio por la parte de levante, al oriente, habrá cincuenta codos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, 'Y las cortinas del un lado serán de quince codos; sus columnas tres, con sus tres basas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, 'Al otro lado quince codos de cortinas; sus columnas tres, con sus tres basas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, 'Y á la puerta del atrio habrá un pabellón de veinte codos, de cárdeno, y púrpura, y carmesí, y lino torcido, de obra de bordador: sus columnas cuatro, con sus cuatro basas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, 'Todas las columnas del atrio en derredor serán ceñidas de plata; sus capiteles de plata, y sus basas de metal.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, 'La longitud del atrio será de cien codos, y la anchura cincuenta por un lado y cincuenta por el otro, y la altura de cinco codos: sus cortinas de lino torcido, y sus basas de metal.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, 'Todos los vasos del tabernáculo en todo su servicio, y todos sus clavos, y todos los clavos del atrio, serán de metal.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, 'Y tú mandarás á los hijos de Israel que te traigan aceite puro de olivas, molido, para la luminaria, para hacer arder continuamente las lámparas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, 'En el tabernáculo del testimonio, afuera del velo que está delante del testimonio, las pondrá en orden Aarón y sus hijos, delante de Jehová desde la tarde hasta la mañana, como estatuto perpetuo de los hijos de Israel por sus generaciones.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, 'Y TÚ allega á ti á Aarón tu hermano, y á sus hijos consigo, de entre los hijos de Israel, para que sean mis sacerdotes; á Aarón, Nadab y Abiú, Eleazar é Ithamar, hijos de Aarón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, 'Y harás vestidos sagrados á Aarón tu hermano, para honra y hermosura.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, 'Y tú hablarás á todos los sabios de corazón, á quienes yo he henchido de espíritu de sabiduría, á fin que hagan los vestidos de Aarón, para consagrarle á que me sirva de sacerdote.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, 'Los vestidos que harán son estos: el racional, y el ephod, y el manto, y la túnica labrada, la mitra, y el cinturón. Hagan, pues, los sagrados vestidos á Aarón tu hermano, y á sus hijos, para que sean mis sacerdotes.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, 'Tomarán oro, y cárdeno, y púrpura, y carmesí, y lino torcido.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, 'Y harán el ephod de oro y cárdeno, y púrpura, y carmesí, y lino torcido de obra de bordador.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'Tendrá dos hombreras que se junten á sus dos lados, y se juntará.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, 'Y el artificio de su cinto que está sobre él, será de su misma obra, de lo mismo; de oro, cárdeno, y púrpura, y carmesí, y lino torcido.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, 'Y tomarás dos piedras oniquinas, y grabarás en ellas los nombres de los hijos de Israel:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, 'Los seis de sus nombres en la una piedra, y los otros seis nombres en la otra piedra, conforme al nacimiento de ellos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, 'De obra de escultor en piedra á modo de grabaduras de sello, harás grabar aquellas dos piedras con los nombres de los hijos de Israel; harásles alrededor engastes de oro.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'Y pondrás aquellas dos piedras sobre los hombros del ephod, para piedras de memoria á los hijos de Israel; y Aarón llevará los nombres de ellos delante de Jehová en sus dos hombros por memoria.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, 'Harás pues, engastes de oro,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, 'Y dos cadenillas de oro fino; las cuales harás de hechura de trenza; y fijarás las cadenas de hechura de trenza en los engastes.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, 'Harás asimismo el racional del juicio de primorosa obra, le has de hacer conforme á la obra del ephod, de oro, y cárdeno, y púrpura, y carmesí, y lino torcido.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, 'Será cuadrado y doble, de un palmo de largo y un palmo de ancho:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, 'Y lo llenarás de pedrería con cuatro órdenes de piedras: un orden de una piedra sárdica, un topacio, y un carbunclo; será el primer orden;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, 'El segundo orden, una esmeralda, un zafiro, y un diamante;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, 'El tercer orden, un rubí, un ágata, y una amatista;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, 'Y el cuarto orden, un berilo, un onix, y un jaspe: estarán engastadas en oro en sus encajes.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'Y serán aquellas piedras según los nombres de los hijos de Israel, doce según sus nombres; como grabaduras de sello cada una con su nombre, vendrán á ser según las doce tribus.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, 'Harás también en el racional cadenetas de hechura de trenzas de oro fino.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'Y harás en el racional dos anillos de oro, los cuales dos anillos pondrás á las dos puntas del racional.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'Y pondrás las dos trenzas de oro en los dos anillos á las dos puntas del racional:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, 'Y los dos cabos de las dos trenzas sobre los dos engastes, y las pondrás á los lados del ephod en la parte delantera.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, 'Harás también dos anillos de oro, los cuales pondrás á las dos puntas del racional, en su orilla que está al lado del ephod de la parte de dentro.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, 'Harás asimismo dos anillos de oro, los cuales pondrás á los dos lados del ephod abajo en la parte delantera, delante de su juntura sobre el cinto del ephod.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, 'Y juntarán el racional con sus anillos á los anillos del ephod con un cordón de jacinto, para que esté sobre el cinto del ephod, y no se aparte el racional del ephod.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'Y llevará Aarón los nombres de los hijos de Israel en el racional del juicio sobre su corazón, cuando entrare en el santuario, para memoria delante de Jehová continuamente.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, 'Y pondrás en el racional del juicio Urim y Thummim, para que estén sobre el corazón de Aarón cuando entrare delante de Jehová: y llevará siempre Aarón el juicio de los hijos de Israel sobre su corazón delante de Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, 'Harás el manto del ephod todo de jacinto:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, 'Y en medio de él por arriba habrá una abertura, la cual tendrá un borde alrededor de obra de tejedor, como el cuello de un coselete, para que no se rompa.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, 'Y abajo en sus orillas harás granadas de jacinto, y púrpura, y carmesí, por sus bordes alrededor; y entre ellas campanillas de oro alrededor:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, 'Una campanilla de oro y una granada, campanilla de oro y granada, por las orillas del manto alrededor.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'Y estará sobre Aarón cuando ministrare; y oiráse su sonido cuando él entrare en el santuario delante de Jehová y cuando saliere, porque no muera.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, 'Harás además una plancha de oro fino, y grabarás en ella grabadura de sello, SANTIDAD Á JEHOVÁ.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, 'Y la pondrás con un cordón de jacinto, y estará sobre la mitra; por el frente anterior de la mitra estará.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, 'Y estará sobre la frente de Aarón: y llevará Aarón el pecado de las cosas santas, que los hijos de Israel hubieren consagrado en todas sus santas ofrendas; y sobre su frente estará continuamente para que hayan gracia delante de Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, 'Y bordarás una túnica de lino, y harás una mitra de lino; harás también un cinto de obra de recamador.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, 'Y para los hijos de Aarón harás túnicas; también les harás cintos, y les formarás chapeos (tiaras) para honra y hermosura.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, 'Y con ellos vestirás á Aarón tu hermano, y á sus hijos con él: y los ungirás, y los consagrarás, y santificarás, para que sean mis sacerdotes.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, 'Y les harás pañetes de lino para cubrir la carne vergonzosa; serán desde los lomos hasta los muslos:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'Y estarán sobre Aarón y sobre sus hijos cuando entraren en el tabernáculo del testimonio, ó cuando se llegaren al altar para servir en el santuario, porque no lleven pecado, y mueran. Estatuto perpetuo para él, y para su simiente después de él.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, 'Y ESTO es lo que les harás para consagrarlos, para que sean mis sacerdotes: Toma un becerro de la vacada, y dos carneros sin tacha;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, 'Y panes sin levadura, y tortas sin levadura amasadas con aceite, y hojaldres sin levadura untadas con aceite; las cuales cosas harás de flor de harina de trigo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, 'Y las pondrás en un canastillo, y en el canastillo las ofrecerás, con el becerro y los dos carneros.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, 'Y harás llegar á Aarón y á sus hijos á la puerta del tabernáculo del testimonio, y los lavarás con agua.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, 'Y tomarás las vestiduras, y vestirás á Aarón la túnica y el manto del ephod, y el ephod, y el racional, y le ceñirás con el cinto del ephod;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, 'Y pondrás la mitra sobre su cabeza, y sobre la mitra pondrás la diadema santa.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, 'Y tomarás el aceite de la unción, y derramarás sobre su cabeza, y le ungirás.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, 'Y harás llegar sus hijos, y les vestirás las túnicas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, 'Y les ceñirás el cinto, á Aarón y á sus hijos, y les atarás los chapeos (tiaras), y tendrán el sacerdocio por fuero perpetuo: y henchirás las manos de Aarón y de sus hijos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, 'Y harás llegar el becerro delante del tabernáculo del testimonio, y Aarón y sus hijos pondrán sus manos sobre la cabeza del becerro.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'Y matarás el becerro delante de Jehová á la puerta del tabernáculo del testimonio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, 'Y tomarás de la sangre del becerro, y pondrás sobre los cuernos del altar con tu dedo, y derramarás toda la demás sangre al pie del altar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, 'Tomarás también todo el sebo que cubre los intestinos, y el redaño de sobre el hígado, y los dos riñones, y el sebo que está sobre ellos, y los quemarás sobre el altar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, 'Empero consumirás á fuego fuera del campo la carne del becerro, y su pellejo, y su estiércol: es expiación.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, 'Asimismo tomarás el un carnero, y Aarón y sus hijos pondrán sus manos sobre la cabeza del carnero.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, 'Y matarás el carnero, y tomarás su sangre, y rociarás sobre el altar alrededor.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, 'Y cortarás el carnero en pedazos, y lavarás sus intestinos y sus piernas, y las pondrás sobre sus trozos y sobre su cabeza.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, 'Y quemarás todo el carnero sobre el altar: es holocausto á Jehová, olor grato, es ofrenda quemada á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, 'Tomarás luego el otro carnero, y Aarón y sus hijos pondrán sus manos sobre la cabeza del carnero:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, 'Y matarás el carnero, y tomarás de su sangre, y pondrás sobre la ternilla de la oreja derecha de Aarón, y sobre la ternilla de las orejas de sus hijos, y sobre el dedo pulgar de las manos derechas de ellos, y sobre el dedo pulgar de los pies derechos de ellos, y esparcirás la sangre sobre el altar alrededor.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, 'Y tomarás de la sangre que hay sobre el altar, y del aceite de la unción, y esparcirás sobre Aarón, y sobre sus vestiduras, y sobre sus hijos, y sobre las vestimentas de éstos; y él será santificado, y sus vestiduras, y sus hijos, y las vestimentas de sus hijos con él.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, 'Luego tomarás del carnero el sebo, y la cola, y el sebo que cubre los intestinos, y el redaño del hígado, y los dos riñones, y el sebo que está sobre ellos, y la espaldilla derecha; porque es carnero de consagraciones:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, 'También una torta de pan, y una hojaldre amasada con aceite, y una lasaña del canastillo de los ázimos presentado á Jehová;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, 'Y lo has de poner todo en las manos de Aarón, y en las manos de sus hijos; y lo mecerás agitándolo delante de Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, 'Después lo tomarás de sus manos, y lo harás arder sobre el altar en holocausto, por olor agradable delante de Jehová. Es ofrenda encendida á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, 'Y tomarás el pecho del carnero de las consagraciones, que fué inmolado para la de Aarón, y lo mecerás por ofrenda agitada delante de Jehová; y será porción tuya.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, 'Y apartarás el pecho de la ofrenda mecida, y la espaldilla de la santificación, lo que fué mecido y lo que fué santificado del carnero de las consagraciones de Aarón y de sus hijos:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, 'Y será para Aarón y para sus hijos por estatuto perpetuo de los hijos de Israel, porque es porción elevada; y será tomada de los hijos de Israel de sus sacrificios pacíficos, porción de ellos elevada en ofrenda á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, 'Y las vestimentas santas, que son de Aarón, serán de sus hijos después de él, para ser ungidos con ellas, y para ser con ellas consagrados.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'Por siete días las vestirá el sacerdote de sus hijos, que en su lugar viniere al tabernáculo del testimonio á servir en el santuario.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, 'Y tomarás el carnero de las consagraciones, y cocerás su carne en el lugar del santuario.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'Y Aarón y sus hijos comerán la carne del carnero, y el pan que está en el canastillo, á la puerta del tabernáculo del testimonio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, 'Y comerán aquellas cosas con las cuales se hizo expiación, para henchir sus manos para ser santificados: mas el extranjero no comerá, porque es cosa santa.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'Y si sobrare algo de la carne de las consagraciones y del pan hasta la mañana, quemarás al fuego lo que hubiere sobrado: no se comerá, porque es cosa santa.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, 'Así pues harás á Aarón y á sus hijos, conforme á todas las cosas que yo te he mandado: por siete días los consagrarás.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, 'Y sacrificarás el becerro de la expiación en cada día para las expiaciones; y purificarás el altar en habiendo hecho expiación por él, y lo ungirás para santificarlo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, 'Por siete días expiarás el altar, y lo santificarás, y será un altar santísimo: cualquiera cosa que tocare al altar, será santificada.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, 'Y esto es lo que ofrecerás sobre el altar: dos corderos de un año cada día, sin intermisión.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, 'Ofrecerás el un cordero á la mañana, y el otro cordero ofrecerás á la caída de la tarde:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, 'Además una décima parte de un epha de flor de harina amasada con la cuarta parte de un hin de aceite molido: y la libación será la cuarta parte de un hin de vino con cada cordero.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, 'Y ofrecerás el otro cordero á la caída de la tarde, haciendo conforme á la ofrenda de la mañana, y conforme á su libación, en olor de suavidad; será ofrenda encendida á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, 'Esto será holocausto continuo por vuestras generaciones á la puerta del tabernáculo del testimonio delante de Jehová, en el cual me concertaré con vosotros, para hablaros allí,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, 'Y allí testificaré de mí á los hijos de Israel, y el lugar será santificado con mi gloria.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, 'Y santificaré el tabernáculo del testimonio y el altar: santificaré asimismo á Aarón y á sus hijos, para que sean mis sacerdotes.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, 'Y habitaré entre los hijos de Israel, y seré su Dios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, 'Y conocerán que yo soy Jehová su Dios, que los saqué de la tierra de Egipto, para habitar en medio de ellos: Yo Jehová su Dios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, 'HARÁS asimismo un altar de sahumerio de perfume: de madera de Sittim lo harás.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'Su longitud será de un codo, y su anchura de un codo: será cuadrado: y su altura de dos codos: y sus cuernos serán de lo mismo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, 'Y cubrirlo has de oro puro, su techado, y sus paredes en derredor, y sus cuernos: y le harás en derredor una corona de oro.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, 'Le harás también dos anillos de oro debajo de su corona á sus dos esquinas en ambos lados suyos, para meter los varales con que será llevado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'Y harás los varales de madera de Sittim, y los cubrirás de oro.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, 'Y lo pondrás delante del velo que está junto al arca del testimonio, delante de la cubierta que está sobre el testimonio, donde yo te testificaré de mí.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'Y quemará sobre él Aarón sahumerio de aroma cada mañana: cuando aderezare las lámparas lo quemará.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'Y cuando Aarón encenderá las lámparas al anochecer, quemará el sahumerio: rito perpetuo delante de Jehová por vuestras edades.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, 'No ofreceréis sobre él sahumerio extraño, ni holocausto, ni presente; ni tampoco derramaréis sobre él libación.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'Y sobre sus cuernos hará Aarón expiación una vez en el año con la sangre de la expiación para las reconciliaciones: una vez en el año hará expiación sobre él en vuestras edades: será muy santo á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, 'Y habló Jehová á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, 'Cuando tomares el número de los hijos de Israel conforme á la cuenta de ellos, cada uno dará á Jehová el rescate de su persona, cuando los contares, y no habrá en ellos mortandad por haberlos contado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, 'Esto dará cualquiera que pasare por la cuenta, medio siclo conforme al siclo del santuario. El siclo es de veinte óbolos: la mitad de un siclo será la ofrenda á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, 'Cualquiera que pasare por la cuenta, de veinte años arriba, dará la ofrenda á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, 'Ni el rico aumentará, ni el pobre disminuirá de medio siclo, cuando dieren la ofrenda á Jehová para hacer expiación por vuestras personas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, 'Y tomarás de los hijos de Israel el dinero de las expiaciones, y lo darás para la obra del tabernáculo del testimonio: y será por memoria á los hijos de Israel delante de Jehová, para expiar vuestras personas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, 'Habló más Jehová á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, 'Harás también una fuente de metal, con su basa de metal, para lavar; y la has de poner entre el tabernáculo del testimonio y el altar; y pondrás en ella agua.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'Y de ella se lavarán Aarón y sus hijos sus manos y sus pies:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, 'Cuando entraren en el tabernáculo del testimonio, se han de lavar con agua, y no morirán: y cuando se llegaren al altar para ministrar, para encender á Jehová la ofrenda que se ha de consumir al fuego,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, 'También se lavarán las manos y los pies, y no morirán. Y lo tendrán por estatuto perpetuo él y su simiente por sus generaciones.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, 'Habló más Jehová á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, 'Y tú has de tomar de las principales drogas; de mirra excelente quinientos siclos, y de canela aromática la mitad, esto es, doscientos y cincuenta, y de cálamo aromático doscientos y cincuenta,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, 'Y de casia quinientos, al peso del santuario, y de aceite de olivas un hin:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, 'Y harás de ello el aceite de la santa unción, superior ungüento, obra de perfumador, el cual será el aceite de la unción sagrada.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, 'Con él ungirás el tabernáculo del testimonio, y el arca del testimonio,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, 'Y la mesa, y todos sus vasos, y el candelero, y todos sus vasos, y el altar del perfume,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, 'Y el altar del holocausto, todos sus vasos, y la fuente y su basa.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, 'Así los consagrarás, y serán cosas santísimas: todo lo que tocare en ellos, será santificado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, 'Ungirás también á Aarón y á sus hijos, y los consagrarás para que sean mis sacerdotes.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, 'Y hablarás á los hijos de Israel, diciendo: Este será mi aceite de la santa unción por vuestras edades.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, 'Sobre carne de hombre no será untado, ni haréis otro semejante, conforme á su composición: santo es; por santo habéis de tenerlo vosotros.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, 'Cualquiera que compusiere ungüento semejante, y que pusiere de él sobre extraño, será cortado de sus pueblos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, 'Dijo aún Jehová á Moisés: Tómate aromas, estacte y uña olorosa y gálbano aromático é incienso limpio; de todo en igual peso:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, 'Y harás de ello una confección aromática de obra de perfumador, bien mezclada, pura y santa:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, 'Y molerás alguna de ella pulverizándola, y la pondrás delante del testimonio en el tabernáculo del testimonio, donde yo te testificaré de mí. Os será cosa santísima.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, 'Como la confección que harás, no os haréis otra según su composición: te será cosa sagrada para Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, 'Cualquiera que hiciere otra como ella para olerla, será cortado de sus pueblos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, 'Y HABLÓ Jehová á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, 'Mira, yo he llamado por su nombre á Bezaleel, hijo de Uri, hijo de Hur, de la tribu de Judá;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, 'Y lo he henchido de espíritu de Dios, en sabiduría, y en inteligencia, y en ciencia, y en todo artificio,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, 'Para inventar diseños, para trabajar en oro, y en plata, y en metal,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, 'Y en artificio de piedras para engastar las, y en artificio de madera; para obrar en toda suerte de labor.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, 'Y he aquí que yo he puesto con él á Aholiab, hijo de Ahisamac, de la tribu de Dan: y he puesto sabiduría en el ánimo de todo sabio de corazón, para que hagan todo lo que te he mandado:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, 'El tabernáculo del testimonio, y el arca del testimonio, y la cubierta que está sobre ella, y todos los vasos del tabernáculo;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, 'Y la mesa y sus vasos, y el candelero limpio y todos sus vasos, y el altar del perfume;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, 'Y el altar del holocausto y todos sus vasos, y la fuente y su basa;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, 'Y los vestidos del servicio, y las santas vestiduras para Aarón el sacerdote, y las vestiduras de sus hijos, para que ejerzan el sacerdocio;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'Y el aceite de la unción, y el perfume aromático para el santuario: harán conforme á todo lo que te he mandado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, 'Habló además Jehová á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, 'Y tú hablarás á los hijos de Israel, diciendo: Con todo eso vosotros guardaréis mis sábados: porque es señal entre mí y vosotros por vuestras edades, para que sepáis que yo soy Jehová que os santifico.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, 'Así que guardaréis el sábado, porque santo es á vosotros: el que lo profanare, de cierto morirá; porque cualquiera que hiciere obra alguna en él, aquella alma será cortada de en medio de sus pueblos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, 'Seis días se hará obra, mas el día séptimo es sábado de reposo consagrado á Jehová; cualquiera que hiciere obra el día del sábado, morirá ciertamente.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, 'Guardarán, pues, el sábado los hijos de Israel: celebrándolo por sus edades por pacto perpetuo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, 'Señal es para siempre entre mí y los hijos de Israel; porque en seis días hizo Jehová los cielos y la tierra, y en el séptimo día cesó, y reposó.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, 'Y dió á Moisés, como acabó de hablar con él en el monte de Sinaí, dos tablas del testimonio, tablas de piedra escritas con el dedo de Dios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, 'MAS viendo el pueblo que Moisés tardaba en descender del monte, allegóse entonces á Aarón, y dijéronle: Levántate, haznos dioses que vayan delante de nosotros; porque á este Moisés, aquel varón que nos sacó de la tierra de Egipto, no sabemos qué le haya acontecido.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, 'Y Aarón les dijo: Apartad los zarcillos de oro que están en las orejas de vuestras mujeres, y de vuestros hijos, y de vuestras hijas, y traédmelos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, 'Entonces todo el pueblo apartó los zarcillos de oro que tenían en sus orejas, y trajéronlos á Aarón:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'El cual los tomó de las manos de ellos, y formólo con buril, é hizo de ello un becerro de fundición. Entonces dijeron: Israel, estos son tus dioses, que te sacaron de la tierra de Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'Y viendo esto Aarón, edificó un altar delante del becerro; y pregonó Aarón, y dijo: Mañana será fiesta á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, 'Y el día siguiente madrugaron, y ofrecieron holocaustos, y presentaron pacíficos: y sentóse el pueblo á comer y á beber, y levantáronse á regocijarse.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, 'Entonces Jehová dijo á Moisés: Anda, desciende, porque tu pueblo que sacaste de tierra de Egipto se ha corrompido:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, 'Presto se han apartado del camino que yo les mandé, y se han hecho un becerro de fundición, y lo han adorado, y han sacrificado á él, y han dicho: Israel, estos son tus dioses, que te sacaron de la tierra de Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, 'Dijo más Jehová á Moisés: Yo he visto á este pueblo, que por cierto es pueblo de dura cerviz:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, 'Ahora pues, déjame que se encienda mi furor en ellos, y los consuma: y á ti yo te pondré sobre gran gente.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'Entonces Moisés oró á la faz de Jehová su Dios, y dijo: Oh Jehová, ¿por qué se encenderá tu furor en tu pueblo, que tú sacaste de la tierra de Egipto con gran fortaleza, y con mano fuerte?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, '¿Por qué han de hablar los Egipcios, diciendo: Para mal los sacó, para matarlos en los montes, y para raerlos de sobre la haz de la tierra? Vuélvete del furor de tu ira, y arrepiéntete del mal de tu pueblo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, 'Acuérdate de Abraham, de Isaac, y de Israel, tus siervos, á los cuales has jurado por ti mismo, y dícholes: Yo multiplicaré vuestra simiente como las estrellas del cielo; y daré á vuestra simiente toda esta tierra que he dicho, y la tomarán por heredad para siempre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'Entonces Jehová se arrepintió del mal que dijo que había de hacer á su pueblo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, 'Y volvióse Moisés, y descendió del monte trayendo en su mano las dos tablas del testimonio, las tablas escritas por ambos lados; de una parte y de otra estaban escritas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, 'Y las tablas eran obra de Dios, y la escritura era escritura de Dios grabada sobre las tablas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, 'Y oyendo Josué el clamor del pueblo que gritaba, dijo á Moisés: Alarido de pelea hay en el campo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, 'Y él respondió: No es eco de algazara de fuertes, ni eco de alaridos de flacos: algazara de cantar oigo yo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, 'Y aconteció, que como llegó él al campo, y vió el becerro y las danzas, enardeciósele la ira á Moisés, y arrojó las tablas de sus manos, y quebrólas al pie del monte.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, 'Y tomó el becerro que habían hecho, y quemólo en el fuego, y moliólo hasta reducirlo á polvo, que esparció sobre las aguas, y diólo á beber á los hijos de Israel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, 'Y dijo Moisés á Aarón: ¿Qué te ha hecho este pueblo, que has traído sobre él tan gran pecado?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, 'Y respondió Aarón: No se enoje mi señor; tú conoces el pueblo, que es inclinado á mal.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, 'Porque me dijeron: Haznos dioses que vayan delante de nosotros, que á este Moisés, el varón que nos sacó de tierra de Egipto, no sabemos qué le ha acontecido.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, 'Y yo les respondí: ¿Quién tiene oro? apartadlo. Y diéronmelo, y echélo en el fuego, y salió este becerro.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, 'Y viendo Moisés que el pueblo estaba despojado, porque Aarón lo había despojado para vergüenza entre sus enemigos,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, 'Púsose Moisés á la puerta del real, y dijo: ¿Quién es de Jehová? júntese conmigo. Y juntáronse con él todos los hijos de Leví.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'Y él les dijo: Así ha dicho Jehová, el Dios de Israel: Poned cada uno su espada sobre su muslo: pasad y volved de puerta á puerta por el campo, y matad cada uno á su hermano, y á su amigo, y á su pariente.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'Y los hijos de Leví lo hicieron conforme al dicho de Moisés: y cayeron del pueblo en aquel día como tres mil hombres.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, 'Entonces Moisés dijo: Hoy os habéis consagrado á Jehová, porque cada uno se ha consagrado en su hijo, y en su hermano, para que dé él hoy bendición sobre vosotros.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, 'Y aconteció que el día siguiente dijo Moisés al pueblo: Vosotros habéis cometido un gran pecado: mas yo subiré ahora á Jehová; quizá le aplacaré acerca de vuestro pecado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'Entonces volvió Moisés á Jehová, y dijo: Ruégote, pues este pueblo ha cometido un gran pecado, porque se hicieron dioses de oro,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, 'Que perdones ahora su pecado, y si no, ráeme ahora de tu libro que has escrito.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'Y Jehová respondió á Moisés: Al que pecare contra mí, á éste raeré yo de mi libro.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, 'Ve pues ahora, lleva á este pueblo donde te he dicho: he aquí mi ángel irá delante de ti; que en el día de mi visitación yo visitaré en ellos su pecado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'Y Jehová hirió al pueblo, porque habían hecho el becerro que formó Aarón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, 'Y JEHOVÁ dijo á Moisés: Ve, sube de aquí, tú y el pueblo que sacaste de la tierra de Egipto, á la tierra de la cual juré á Abraham, Isaac, y Jacob, diciendo: A tu simiente la daré:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, 'Y yo enviaré delante de ti el ángel, y echaré fuera al Cananeo y al Amorrheo, y al Hetheo, y al Pherezeo, y al Heveo y al Jebuseo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, '(A la tierra que fluye leche y miel); porque yo no subiré en medio de ti, porque eres pueblo de dura cerviz, no sea que te consuma en el camino.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'Y oyendo el pueblo esta sensible palabra, vistieron luto, y ninguno se puso sus atavíos:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'Pues Jehová dijo á Moisés: Di á los hijos de Israel: Vosotros sois pueblo de dura cerviz: en un momento subiré en medio de ti, y te consumiré: quítate pues ahora tus atavíos, que yo sabré lo que te tengo de hacer.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, 'Entonces los hijos de Israel se despojaron de sus atavíos desde el monte Horeb.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'Y Moisés tomó el tabernáculo, y extendiólo fuera del campo, lejos del campo, y llamólo el Tabernáculo del Testimonio. Y fué, que cualquiera que requería á Jehová, salía al tabernáculo del testimonio, que estaba fuera del campo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'Y sucedía que, cuando salía Moisés al tabernáculo, todo el pueblo se levantaba, y estaba cada cual en pie á la puerta de su tienda, y miraban en pos de Moisés, hasta que él entraba en el tabernáculo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'Y cuando Moisés entraba en el tabernáculo, la columna de nube descendía, y poníase á la puerta del tabernáculo, y Jehová hablaba con Moisés.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, 'Y viendo todo el pueblo la columna de la nube, que estaba á la puerta del tabernáculo, levantábase todo el pueblo, cada uno á la puerta de su tienda, y adoraba.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, 'Y hablaba Jehová á Moisés cara á cara, como habla cualquiera á su compañero. Y volvíase al campo; mas el joven Josué, su criado, hijo de Nun, nunca se apartaba de en medio del tabernáculo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, 'Y dijo Moisés á Jehová: Mira, tú me dices á mí: Saca este pueblo: y tú no me has declarado á quién has de enviar conmigo: sin embargo tú dices: Yo te he conocido por tu nombre, y has hallado también gracia en mis ojos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, 'Ahora, pues, si he hallado gracia en tus ojos, ruégote que me muestres ahora tu camino, para que te conozca, porque halle gracia en tus ojos: y mira que tu pueblo es aquesta gente.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, 'Y él dijo: Mi rostro irá contigo, y te haré descansar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, 'Y él respondió: Si tu rostro no ha de ir conmigo, no nos saques de aquí.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, '¿Y en qué se conocerá aquí que he hallado gracia en tus ojos, yo y tu pueblo, sino en andar tú con nosotros, y que yo y tu pueblo seamos apartados de todos los pueblos que están sobre la faz de la tierra?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'Y Jehová dijo á Moisés: También haré esto que has dicho, por cuanto has hallado gracia en mis ojos, y te he conocido por tu nombre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, 'El entonces dijo: Ruégote que me muestres tu gloria.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'Y respondióle: Yo haré pasar todo mi bien delante de tu rostro, y proclamaré el nombre de Jehová delante de ti; y tendré misericordia del que tendré misericordia, y seré clemente para con el que seré clemente.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'Dijo más: No podrás ver mi rostro: porque no me verá hombre, y vivirá.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'Y dijo aún Jehová: He aquí lugar junto á mí, y tú estarás sobre la peña:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, 'Y será que, cuando pasare mi gloria, yo te pondré en una hendidura de la peña, y te cubriré con mi mano hasta que haya pasado:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'Después apartaré mi mano, y verás mis espaldas; mas no se verá mi rostro.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, 'Y JEHOVÁ dijo á Moisés: Alísate dos tablas de piedra como las primeras, y escribiré sobre esas tablas las palabras que estaban en las tablas primeras que quebraste.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, 'Apercíbete, pues, para mañana, y sube por la mañana al monte de Sinaí, y estáme allí sobre la cumbre del monte.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, 'Y no suba hombre contigo, ni parezca alguno en todo el monte; ni ovejas ni bueyes pazcan delante del monte.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'Y Moisés alisó dos tablas de piedra como las primeras; y levantóse por la mañana, y subió al monte de Sinaí, como le mandó Jehová, y llevó en su mano las dos tablas de piedra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, 'Y Jehová descendió en la nube, y estuvo allí con él, proclamando el nombre de Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'Y pasando Jehová por delante de él, proclamó: Jehová, Jehová, fuerte, misericordioso, y piadoso; tardo para la ira, y grande en benignidad y verdad;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, 'Que guarda la misericordia en millares, que perdona la iniquidad, la rebelión, y el pecado, y que de ningún modo justificará al malvado; que visita la iniquidad de los padres sobre los hijos y sobre los hijos de los hijos, sobre los terceros, y sobre los cuartos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, 'Entonces Moisés, apresurándose, bajó la cabeza hacia el suelo y encorvóse;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, 'Y dijo: Si ahora, Señor, he hallado gracia en tus ojos, vaya ahora el Señor en medio de nosotros; porque este es pueblo de dura cerviz; y perdona nuestra iniquidad y nuestro pecado, y poséenos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, 'Y él dijo: He aquí, yo hago concierto delante de todo tu pueblo: haré maravillas que no han sido hechas en toda la tierra, ni en nación alguna; y verá todo el pueblo en medio del cual estás tú, la obra de Jehová; porque ha de ser cosa terrible la que yo haré contigo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, 'Guarda lo que yo te mando hoy; he aquí que yo echo de delante de tu presencia al Amorrheo, y al Cananeo, y al Hetheo, y al Pherezeo, y al Heveo, y al Jebuseo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, 'Guárdate que no hagas alianza con los moradores de la tierra donde has de entrar, porque no sean por tropezadero en medio de tí:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, 'Mas derribaréis sus altares, y quebraréis sus estatuas, y talaréis sus bosques:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, 'Porque no te has de inclinar á dios ajeno; que Jehová, cuyo nombre es Celoso, Dios celoso es.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, 'Por tanto no harás alianza con los moradores de aquella tierra; porque fornicarán en pos de sus dioses, y sacrificarán á sus dioses, y te llamarán, y comerás de sus sacrificios;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, 'O tomando de sus hijas para tus hijos, y fornicando sus hijas en pos de sus dioses, harán también fornicar á tus hijos en pos de los dioses de ellas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, 'No harás dioses de fundición para ti.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, 'La fiesta de los ázimos guardarás: siete días comerás por leudar, según te he mandado, en el tiempo del mes de Abib; porque en el mes de Abib saliste de Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, 'Todo lo que abre matriz, mío es; y de tu ganado todo primerizo de vaca ó de oveja que fuere macho.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, 'Empero redimirás con cordero el primerizo del asno; y si no lo redimieres, le has de cortar la cabeza. Redimirás todo primogénito de tus hijos, y no serán vistos vacíos delante de mí.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, 'Seis días trabajarás, mas en el séptimo día cesarás: cesarás aun en la arada y en la siega.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, 'Y te harás la fiesta de las semanas á los principios de la siega del trigo: y la fiesta de la cosecha á la vuelta del año.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, 'Tres veces en el año será visto todo varón tuyo delante del Señoreador Jehová, Dios de Israel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, 'Porque yo arrojaré las gentes de tu presencia, y ensancharé tu término: y ninguno codiciará tu tierra, cuando tú subieres para ser visto delante de Jehová tu Dios tres veces en el año.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, 'No ofrecerás con leudo la sangre de mi sacrificio; ni quedará de la noche para la mañana el sacrificio de la fiesta de la pascua.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, 'La primicia de los primeros frutos de tu tierra meterás en la casa de Jehová tu Dios. No cocerás el cabrito en la leche de su madre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, 'Y Jehová dijo á Moisés: Escribe tú estas palabras; porque conforme á estas palabras he hecho la alianza contigo y con Israel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, 'Y él estuvo allí con Jehová cuarenta días y cuarenta noches: no comió pan, ni bebió agua; y escribió en tablas las palabras de la alianza, las diez palabras.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, 'Y aconteció, que descendiendo Moisés del monte Sinaí con las dos tablas del testimonio en su mano, mientras descendía del monte, no sabía él que la tez de su rostro resplandecía, después que hubo con El hablado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'Y miró Aarón y todos los hijos de Israel á Moisés, y he aquí la tez de su rostro era resplandeciente; y tuvieron miedo de llegarse á él.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'Y llamólos Moisés; y Aarón y todos los príncipes de la congregación volvieron á él, y Moisés les habló.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, 'Y después se llegaron todos los hijos de Israel, á los cuales mandó todas las cosas que Jehová le había dicho en el monte de Sinaí.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'Y cuando hubo acabado Moisés de hablar con ellos, puso un velo sobre su rostro.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, 'Y cuando venía Moisés delante de Jehová para hablar con él, quitábase el velo hasta que salía; y saliendo, hablaba con los hijos de Israel lo que le era mandado;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'Y veían los hijos de Israel el rostro de Moisés, que la tez de su rostro era resplandeciente; y volvía Moisés á poner el velo sobre su rostro, hasta que entraba á hablar con El.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, 'Y MOISÉS hizo juntar toda la congregación de los hijos de Israel, y díjoles: Estas son las cosas que Jehová ha mandado que hagáis.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, 'Seis días se hará obra, mas el día séptimo os será santo, sábado de reposo á Jehová: cualquiera que en él hiciere obra, morirá.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, 'No encenderéis fuego en todas vuestras moradas en el día del sábado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'Y habló Moisés á toda la congregación de los hijos de Israel, diciendo: Esto es lo que Jehová ha mandado, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, 'Tomad de entre vosotros ofrenda para Jehová: todo liberal de corazón la traerá á Jehová: oro, plata, metal;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, 'Y cárdeno, y púrpura, y carmesí, y lino fino, y pelo de cabras;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, 'Y cueros rojos de carneros, y cueros de tejones, y madera de Sittim;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, 'Y aceite para la luminaria, y especias aromáticas para el aceite de la unción, y para el perfume aromático;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, 'Y piedras de onix, y demás pedrería, para el ephod, y para el racional.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, 'Y todo sabio de corazón entre vosotros, vendrá y hará todas las cosas que Jehová ha mandado:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, 'El tabernáculo, su tienda, y su cubierta, y sus anillos, y sus tablas, sus barras, sus columnas, y sus basas;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, 'El arca, y sus varas, la cubierta, y el velo de la tienda;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, 'La mesa, y sus varas, y todos sus vasos, y el pan de la proposición.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, 'El candelero de la luminaria, y sus vasos, y sus candilejas, y el aceite para la luminaria;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, 'Y el altar del perfume, y sus varas, y el aceite de la unción, y el perfume aromático, y el pabellón de la puerta, para la entrada del tabernáculo;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, 'El altar del holocausto, y su enrejado de metal, y sus varas, y todos sus vasos, y la fuente con su basa;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, 'Las cortinas del atrio, sus columnas, y sus basas, y el pabellón de la puerta del atrio;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, 'Las estacas del tabernáculo, y las estacas del atrio, y sus cuerdas;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, 'Las vestiduras del servicio para ministrar en el santuario, las sagradas vestiduras de Aarón el sacerdote, y las vestiduras de sus hijos para servir en el sacerdocio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, 'Y salió toda la congregación de los hijos de Israel de delante de Moisés.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, 'Y vino todo varón á quien su corazón estimuló, y todo aquel á quien su espíritu le dió voluntad, y trajeron ofrenda á Jehová para la obra del tabernáculo del testimonio, y para toda su fábrica, y para las sagradas vestiduras.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, 'Y vinieron así hombres como mujeres, todo voluntario de corazón, y trajeron cadenas y zarcillos, sortijas y brazaletes, y toda joya de oro; y cualquiera ofrecía ofrenda de oro á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, 'Todo hombre que se hallaba con jacinto, ó púrpura, ó carmesí, ó lino fino, ó pelo de cabras, ó cueros rojos de carneros, ó cueros de tejones, lo traía.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, 'Cualquiera que ofrecía ofrenda de plata ó de metal, traía á Jehová la ofrenda: y todo el que se hallaba con madera de Sittim, traíala para toda la obra del servicio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, 'Además todas las mujeres sabias de corazón hilaban de sus manos, y traían lo que habían hilado: cárdeno, ó púrpura, ó carmesí, ó lino fino.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, 'Y todas las mujeres cuyo corazón las levantó en sabiduría, hilaron pelos de cabras.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, 'Y los príncipes trajeron piedras de onix, y las piedras de los engastes para el ephod y el racional;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, 'Y la especia aromática y aceite, para la luminaria, y para el aceite de la unción, y para el perfume aromático.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, 'De los hijos de Israel, así hombres como mujeres, todos los que tuvieron corazón voluntario para traer para toda la obra, que Jehová había mandado por medio de Moisés que hiciesen, trajeron ofrenda voluntaria á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, 'Y dijo Moisés á los hijos de Israel: Mirad, Jehová ha nombrado á Bezaleel, hijo de Uri, hijo de Hur, de la tribu de Judá;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, 'Y lo ha henchido de espíritu de Dios, en sabiduría, en inteligencia, y en ciencia, y en todo artificio,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, 'Para proyectar inventos, para trabajar en oro, y en plata, y en metal,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, 'Y en obra de pedrería para engastar, y en obra de madera, para trabajar en toda invención ingeniosa.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, 'Y ha puesto en su corazón el que pueda enseñar, así él como Aholiab, hijo de Ahisamac, de la tribu de Dan:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, 'Y los ha henchido de sabiduría de corazón, para que hagan toda obra de artificio, y de invención, y de recamado en jacinto, y en púrpura, y en carmesí, y en lino fino, y en telar; para que hagan toda labor, é inventen todo diseño.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, 'HIZO, pues, Bezaleel y Aholiab, y todo hombre sabio de corazón, á quien Jehová dió sabiduría é inteligencia para que supiesen hacer toda la obra del servicio del santuario, todas las cosas que había mandado Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'Y Moisés llamó á Bezaleel y á Aholiab, y á todo varón sabio de corazón, en cuyo corazón había dado Jehová sabiduría, y á todo hombre á quien su corazón le movió á llegarse á la obra, para trabajar en ella;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, 'Y tomaron de delante de Moisés toda la ofrenda que los hijos de Israel habían traído para la obra del servicio del santuario, á fin de hacerla. Y ellos le traían aún ofrenda voluntaria cada mañana.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, 'Vinieron, por tanto, todos los maestros que hacían toda la obra del santuario, cada uno de la obra que hacía.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'Y hablaron á Moisés, diciendo: El pueblo trae mucho más de lo que es menester para la atención de hacer la obra que Jehová ha mandado que se haga.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'Entonces Moisés mandó pregonar por el campo, diciendo: Ningún hombre ni mujer haga más obra para ofrecer para el santuario. Y así fué el pueblo impedido de ofrecer;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, 'Pues tenía material abundante para hacer toda la obra, y sobraba.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, 'Y todos los sabios de corazón entre los que hacían la obra, hicieron el tabernáculo de diez cortinas, de lino torcido, y de jacinto, y de púrpura y carmesí; las cuales hicieron de obra prima, con querubines.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, 'La longitud de la una cortina era de veintiocho codos, y la anchura de cuatro codos: todas las cortinas tenían una misma medida.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, 'Y juntó las cinco cortinas la una con la otra: asimismo unió las otras cinco cortinas la una con la otra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, 'E hizo las lazadas de color de jacinto en la orilla de la una cortina, en el borde, á la juntura; y así hizo en la orilla al borde de la segunda cortina, en la juntura.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, 'Cincuenta lazadas hizo en la una cortina, y otras cincuenta en la segunda cortina, en el borde, en la juntura; las unas lazadas enfrente de las otras.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, 'Hizo también cincuenta corchetes de oro, con los cuales juntó las cortinas, la una con la otra; é hízose un tabernáculo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, 'Hizo asimismo cortinas de pelo de cabras para la tienda sobre el tabernáculo, é hízolas en número de once.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, 'La longitud de la una cortina era de treinta codos, y la anchura de cuatro codos: las once cortinas tenían una misma medida.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, 'Y juntó las cinco cortinas de por sí, y las seis cortinas aparte.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, 'Hizo además cincuenta lazadas en la orilla de la postrera cortina en la juntura, y otras cincuenta lazadas en la orilla de la otra cortina en la juntura.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, 'Hizo también cincuenta corchetes de metal para juntar la tienda, de modo que fuese una.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, 'E hizo una cubierta para la tienda de cueros rojos de carneros, y una cubierta encima de cueros de tejones.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, 'Además hizo las tablas para el tabernáculo de madera de Sittim, para estar derechas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, 'La longitud de cada tabla de diez codos, y de codo y medio la anchura.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, 'Cada tabla tenía dos quicios enclavijados el uno delante del otro: así hizo todas las tablas del tabernáculo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, 'Hizo, pues, las tablas para el tabernáculo: veinte tablas al lado del austro, al mediodía.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, 'Hizo también las cuarenta basas de plata debajo de las veinte tablas: dos basas debajo de la una tabla para sus dos quicios, y dos basas debajo de la otra tabla para sus dos quicios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, 'Y para el otro lado del tabernáculo, á la parte del aquilón, hizo veinte tablas,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, 'Con sus cuarenta basas de plata: dos basas debajo de la una tabla, y dos basas debajo de la otra tabla.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, 'Y para el lado occidental del tabernáculo hizo seis tablas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, 'Para las esquinas del tabernáculo en los dos lados hizo dos tablas,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, 'Las cuales se juntaban por abajo, y asimismo por arriba á un gozne: y así hizo á la una y á la otra en las dos esquinas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, 'Eran, pues, ocho tablas, y sus basas de plata dieciséis; dos basas debajo de cada tabla.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, 'Hizo también las barras de madera de Sittim; cinco para las tablas del un lado del tabernáculo,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, 'Y cinco barras para las tablas del otro lado del tabernáculo, y cinco barras para las tablas del lado del tabernáculo á la parte occidental.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, 'E hizo que la barra del medio pasase por medio de las tablas del un cabo al otro.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, 'Y cubrió las tablas de oro, é hizo de oro los anillos de ellas por donde pasasen las barras: cubrió también de oro las barras.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, 'Hizo asimismo el velo de cárdeno, y púrpura, y carmesí, y lino torcido, el cual hizo con querubines de delicada obra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, 'Y para él hizo cuatro columnas de madera de Sittim; y cubriólas de oro, los capiteles de las cuales eran de oro; é hizo para ellas cuatro basas de plata de fundición.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, 'Hizo también el velo para la puerta del tabernáculo, de jacinto, y púrpura, y carmesí, y lino torcido, obra de recamador;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, 'Y sus cinco columnas con sus capiteles: y cubrió las cabezas de ellas y sus molduras de oro: pero sus cinco basas las hizo de metal.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'HIZO también Bezaleel el arca de madera de Sittim: su longitud era de dos codos y medio, y de codo y medio su anchura, y su altura de otro codo y medio:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, 'Y cubrióla de oro puro por de dentro y por de fuera, é hízole una cornisa de oro en derredor.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, 'Hízole además de fundición cuatro anillos de oro á sus cuatro esquinas; en el un lado dos anillos y en el otro lado dos anillos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, 'Hizo también las varas de madera de Sittim, y cubriólas de oro.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, 'Y metió las varas por los anillos á los lados del arca, para llevar el arca.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, 'Hizo asimismo la cubierta de oro puro: su longitud de dos codos y medio, y su anchura de codo y medio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, 'Hizo también los dos querubines de oro, hízolos labrados á martillo, á los dos cabos de la cubierta:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, 'El un querubín de esta parte al un cabo, y el otro querubín de la otra parte al otro cabo de la cubierta: hizo los querubines á sus dos cabos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, 'Y los querubines extendían sus alas por encima, cubriendo con sus alas la cubierta: y sus rostros el uno enfrente del otro, hacia la cubierta los rostros de los querubines.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, 'Hizo también la mesa de madera de Sittim; su longitud de dos codos, y su anchura de un codo, y de codo y medio su altura;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, 'Y cubrióla de oro puro, é hízole una cornisa de oro en derredor.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, 'Hízole también una moldura alrededor, del ancho de una mano, á la cual moldura hizo la cornisa de oro en circunferencia.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, 'Hízole asimismo de fundición cuatro anillos de oro, y púsolos á las cuatro esquinas que correspondían á los cuatro pies de ella.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, 'Delante de la moldura estaban los anillos, por los cuales se metiesen las varas para llevar la mesa.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, 'E hizo las varas de madera de Sittim para llevar la mesa, y cubriólas de oro.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, 'También hizo los vasos que habían de estar sobre la mesa, sus platos, y sus cucharas, y sus cubiertos y sus tazones con que se había de libar, de oro fino.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, 'Hizo asimismo el candelero de oro puro, é hízolo labrado á martillo: su pie y su caña, sus copas, sus manzanas y sus flores eran de lo mismo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, 'De sus lados salían seis brazos; tres brazos del un lado del candelero, y otros tres brazos del otro lado del candelero:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, 'En el un brazo, tres copas figura de almendras, una manzana y una flor; y en el otro brazo tres copas figura de almendras, una manzana y una flor: y así en los seis brazos que salían del candelero.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, 'Y en el candelero había cuatro copas figura de almendras, sus manzanas y sus flores:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, 'Y una manzana debajo de los dos brazos de lo mismo, y otra manzana debajo de los otros dos brazos de lo mismo, y otra manzana debajo de los otros dos brazos de lo mismo, conforme á los seis brazos que salían de él.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, 'Sus manzanas y sus brazos eran de lo mismo; todo era una pieza labrada á martillo, de oro puro.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, 'Hizo asimismo sus siete candilejas, y sus despabiladeras, y sus platillos, de oro puro;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, 'De un talento de oro puro lo hizo, con todos sus vasos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, 'Hizo también el altar del perfume de madera de Sittim: un codo su longitud, y otro codo su anchura, era cuadrado; y su altura de dos codos; y sus cuernos de la misma pieza.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, 'Y cubriólo de oro puro, su mesa y sus paredes alrededor, y sus cuernos: é hízole una corona de oro alrededor.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, 'Hízole también dos anillos de oro debajo de la corona en las dos esquinas á los dos lados, para pasar por ellos las varas con que había de ser conducido.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, 'E hizo las varas de madera de Sittim, y cubriólas de oro.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, 'Hizo asimismo el aceite santo de la unción, y el fino perfume aromático, de obra de perfumador.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, 'IGUALMENTE hizo el altar del holocausto de madera de Sittim: su longitud de cinco codos, y su anchura de otros cinco codos, cuadrado, y de tres codos de altura.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, 'E hízole sus cuernos á sus cuatro esquinas, los cuales eran de la misma pieza, y cubriólo de metal.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, 'Hizo asimismo todos los vasos del altar: calderas, y tenazas, y tazones, y garfios, y palas: todos sus vasos hizo de metal.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, 'E hizo para el altar el enrejado de metal, de hechura de red, que puso en su cerco por debajo hasta el medio del altar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, 'Hizo también cuatro anillos de fundición á los cuatro cabos del enrejado de metal, para meter las varas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, 'E hizo las varas de madera de Sittim, y cubriólas de metal.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, 'Y metió las varas por los anillos á los lados del altar, para llevarlo con ellas: hueco lo hizo, de tablas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, 'También hizo la fuente de metal, con su basa de metal, de los espejos de las que velaban á la puerta del tabernáculo del testimonio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, 'Hizo asimismo el atrio; á la parte austral del mediodía las cortinas del atrio eran de cien codos, de lino torcido:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, 'Sus columnas veinte, con sus veinte basas de metal: los capiteles de las columnas y sus molduras, de plata.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, 'Y á la parte del aquilón cortinas de cien codos: sus columnas veinte, con sus veinte basas de metal; los capiteles de las columnas y sus molduras, de plata.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, 'A la parte del occidente cortinas de cincuenta codos: sus columnas diez, y sus diez basas; los capiteles de las columnas y sus molduras, de plata.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, 'Y á la parte oriental, al levante, cortinas de cincuenta codos:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, 'Al un lado cortinas de quince codos, sus tres columnas, y sus tres basas;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, 'Al otro lado, de la una parte y de la otra de la puerta del atrio, cortinas de á quince codos, sus tres columnas, y sus tres basas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, 'Todas las cortinas del atrio alrededor eran de lino torcido.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, 'Y las basas de las columnas eran de metal; los capiteles de las columnas y sus molduras, de plata; asimismo las cubiertas de las cabezas de ellas, de plata: y todas las columnas del atrio tenían molduras de plata.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, 'Y el pabellón de la puerta del atrio fué de obra de recamado, de jacinto, y púrpura, y carmesí, y lino torcido: la longitud de veinte codos, y la altura en el ancho de cinco codos, conforme á las cortinas del atrio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'Y sus columnas fueron cuatro con sus cuatro basas de metal: y sus capiteles de plata; y las cubiertas de los capiteles de ellas y sus molduras, de plata.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, 'Y todas las estacas del tabernáculo y del atrio alrededor fueron de metal.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, 'Estas son las cuentas del tabernáculo, del tabernáculo del testimonio, lo que fué contado de orden de Moisés por mano de Ithamar, hijo de Aarón sacerdote, para el ministerio de los Levitas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, 'Y Bezaleel, hijo de Uri, hijo de Hur, de la tribu de Judá, hizo todas las cosas que Jehová mandó á Moisés.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, 'Y con él estaba Aholiab, hijo de Ahisamac, de la tribu de Dan, artífice, y diseñador, y recamador en jacinto, y púrpura, y carmesí, y lino fino.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, 'Todo el oro empleado en la obra, en toda la obra del santuario, el cual fué oro de ofrenda, fué veintinueve talentos, y setecientos y treinta siclos, según el siclo del santuario.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, 'Y la plata de los contados de la congregación fué cien talentos, y mil setecientos setenta y cinco siclos, según el siclo del santuario:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, 'Medio por cabeza, medio siclo, según el siclo del santuario, á todos los que pasaron por cuenta de edad de veinte años y arriba, que fueron seiscientos tres mil quinientos cincuenta.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, 'Hubo además cien talentos de plata para hacer de fundición las basas del santuario y las basas del velo: en cien basas cien talentos, á talento por basa.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, 'Y de los mil setecientos setenta y cinco siclos hizo los capiteles de las columnas, y cubrió los capiteles de ellas, y las ciñó.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, 'Y el metal de la ofrenda fué setenta talentos, y dos mil cuatrocientos siclos;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, 'Del cual hizo las basas de la puerta del tabernáculo del testimonio, y el altar de metal, y su enrejado de metal, y todos los vasos del altar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, 'Y las basas del atrio alrededor, y las basas de la puerta del atrio, y todas las estacas del tabernáculo, y todas las estacas del atrio alrededor.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, 'Y DEL jacinto, y púrpura, y carmesí, hicieron las vestimentas del ministerio para ministrar en el santuario, y asimismo hicieron las vestiduras sagradas para Aarón; como Jehová lo había mandado á Moisés.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, 'Hizo también el ephod de oro, de cárdeno y púrpura y carmesí, y lino torcido.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, 'Y extendieron las planchas de oro, y cortaron hilos para tejerlos entre el jacinto, y entre la púrpura, y entre el carmesí, y entre el lino, con delicada obra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, 'Hiciéronle las hombreras que se juntasen; y uníanse en sus dos lados.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, 'Y el cinto del ephod que estaba sobre él, era de lo mismo, conforme á su obra; de oro, jacinto, y púrpura, y carmesí, y lino torcido; como Jehová lo había mandado á Moisés.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, 'Y labraron las piedras oniquinas cercadas de engastes de oro, grabadas de grabadura de sello con los nombres de los hijos de Israel:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, 'Y púsolas sobre las hombreras del ephod, por piedras de memoria á los hijos de Israel; como Jehová lo había á Moisés mandado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, 'Hizo también el racional de primorosa obra, como la obra del ephod, de oro, jacinto, y púrpura, y carmesí, y lino torcido.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, 'Era cuadrado: doblado hicieron el racional: su longitud era de un palmo, y de un palmo su anchura, doblado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, 'Y engastaron en él cuatro órdenes de piedras. El primer orden era un sardio, un topacio, y un carbunclo: este el primer orden.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, 'El segundo orden, una esmeralda, un zafiro, y un diamante.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, 'El tercer orden, un ligurio, un ágata, y un amatista.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, 'Y el cuarto orden, un berilo, un onix, y un jaspe: cercadas y encajadas en sus engastes de oro.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, 'Las cuales piedras eran conforme á los nombres de los hijos de Israel, doce según los nombres de ellos; como grabaduras de sello, cada una con su nombre según las doce tribus.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, 'Hicieron también sobre el racional las cadenas pequeñas de hechura de trenza, de oro puro.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, 'Hicieron asimismo los dos engastes y los dos anillos, de oro; los cuales dos anillos de oro pusieron en los dos cabos del racional.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, 'Y pusieron las dos trenzas de oro en aquellos dos anillos á los cabos del racional.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, 'Y fijaron los dos cabos de las dos trenzas en los dos engastes, que pusieron sobre las hombreras del ephod, en la parte delantera de él.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, 'E hicieron dos anillos de oro, que pusieron en los dos cabos del racional en su orilla, á la parte baja del ephod.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, 'Hicieron además dos anillos de oro, los cuales pusieron en las dos hombreras del ephod, abajo en la parte delantera, delante de su juntura, sobre el cinto del ephod.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, 'Y ataron el racional de sus anillos á los anillos del ephod con un cordón de jacinto, para que estuviese sobre el cinto del mismo ephod, y no se apartase el racional del ephod; como Jehová lo había mandado á Moisés.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, 'Hizo también el manto del ephod de obra de tejedor, todo de jacinto,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, 'Con su abertura en medio de él, como el cuello de un coselete, con un borde en derredor de la abertura, porque no se rompiese.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, 'E hicieron en las orillas del manto las granadas de jacinto, y púrpura, y carmesí, y lino torcido.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, 'Hicieron también las campanillas de oro puro, las cuales campanillas pusieron entre las granadas por las orillas del manto alrededor entre las granadas:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, 'Una campanilla y una granada, una campanilla y una granada alrededor, en las orillas del manto, para ministrar; como Jehová lo mandó á Moisés.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, 'Igualmente hicieron las túnicas de lino fino de obra de tejedor, para Aarón y para sus hijos;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, 'Asimismo la mitra de lino fino, y los adornos de los chapeos (tiaras) de lino fino, y los pañetes de lino, de lino torcido;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, 'También el cinto de lino torcido, y de jacinto, y púrpura, y carmesí, de obra de recamador; como Jehová lo mandó á Moisés.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, 'Hicieron asimismo la plancha de la diadema santa de oro puro, y escribieron en ella de grabadura de sello, el rótulo, SANTIDAD Á JEHOVÁ.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, 'Y pusieron en ella un cordón de jacinto, para colocarla en alto sobre la mitra; como Jehová lo había mandado á Moisés.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, 'Y fué acabada toda la obra del tabernáculo, del tabernáculo del testimonio: é hicieron los hijos de Israel como Jehová lo había mandado á Moisés: así lo hicieron.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, 'Y trajeron el tabernáculo á Moisés, el tabernáculo y todos sus vasos; sus corchetes, sus tablas, sus barras, y sus columnas, y sus basas;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, 'Y la cubierta de pieles rojas de carneros, y la cubierta de pieles de tejones, y el velo del pabellón;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, 'El arca del testimonio, y sus varas, y la cubierta;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, 'La mesa, todos sus vasos, y el pan de la proposición;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, 'El candelero limpio, sus candilejas, las lámparas que debían mantenerse en orden, y todos sus vasos, y el aceite para la luminaria;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, 'Y el altar de oro, y el aceite de la unción, y el perfume aromático, y el pabellón para la puerta del tabernáculo;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, 'El altar de metal, con su enrejado de metal, sus varas, y todos sus vasos; y la fuente, y su basa;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, 'Las cortinas del atrio, y sus columnas, y sus basas, y el pabellón para la puerta del atrio, y sus cuerdas, y sus estacas, y todos los vasos del servicio del tabernáculo, del tabernáculo del testimonio;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, 'Las vestimentas del servicio para ministrar en el santuario, las sagradas vestiduras para Aarón el sacerdote, y las vestiduras de sus hijos, para ministrar en el sacerdocio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, 'En conformidad á todas las cosas que Jehová había mandado á Moisés, así hicieron los hijos de Israel toda la obra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, 'Y vió Moisés toda la obra, y he aquí que la habían hecho como Jehová había mandado; y bendíjolos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, 'Y JEHOVÁ habló á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, 'En el primer día del mes primero harás levantar el tabernáculo, el tabernáculo del testimonio:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, 'Y pondrás en él el arca del testimonio, y la cubrirás con el velo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, 'Y meterás la mesa, y la pondrás en orden: meterás también el candelero, y encenderás sus lámparas:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, 'Y pondrás el altar de oro para el perfume delante del arca del testimonio, y pondrás el pabellón delante de la puerta del tabernáculo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, 'Después pondrás el altar del holocausto delante de la puerta del tabernáculo, del tabernáculo del testimonio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, 'Luego pondrás la fuente entre el tabernáculo del testimonio y el altar; y pondrás agua en ella.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, 'Finalmente pondrás el atrio en derredor, y el pabellón de la puerta del atrio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, 'Y tomarás el aceite de la unción, y ungirás el tabernáculo, y todo lo que está en él; y le santificarás con todos sus vasos, y será santo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, 'Ungirás también el altar del holocausto y todos sus vasos: y santificarás el altar, y será un altar santísimo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, 'Asimismo ungirás la fuente y su basa, y la santificarás.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'Y harás llegar á Aarón y á sus hijos á la puerta del tabernáculo del testimonio, y los lavarás con agua.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'Y harás vestir á Aarón las vestiduras sagradas, y lo ungirás, y lo consagrarás, para que sea mi sacerdote.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, 'Después harás llegar sus hijos, y les vestirás las túnicas:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'Y los ungirás como ungiste á su padre, y serán mis sacerdotes: y será que su unción les servirá por sacerdocio perpetuo por sus generaciones.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'Y Moisés hizo conforme á todo lo que Jehová le mandó; así lo hizo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, 'Y así en el día primero del primer mes, en el segundo año, el tabernáculo fué erigido.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, 'Y Moisés hizo levantar el tabernáculo, y asentó sus basas, y colocó sus tablas, y puso sus barras, é hizo alzar sus columnas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, 'Y extendió la tienda sobre el tabernáculo, y puso la sobrecubierta encima del mismo; como Jehová había mandado á Moisés.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, 'Y tomó y puso el testimonio dentro del arca, y colocó las varas en el arca, y encima la cubierta sobre el arca:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, 'Y metió el arca en el tabernáculo, y puso el velo de la tienda, y cubrió el arca del testimonio; como Jehová había mandado á Moisés.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, 'Y puso la mesa en el tabernáculo del testimonio, al lado septentrional del pabellón, fuera del velo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, 'Y sobre ella puso por orden los panes delante de Jehová, como Jehová había mandado á Moisés.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, 'Y puso el candelero en el tabernáculo del testimonio, enfrente de la mesa, al lado meridional del pabellón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, 'Y encendió las lámparas delante de Jehová; como Jehová había mandado á Moisés.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, 'Puso también el altar de oro en el tabernáculo del testimonio, delante del velo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'Y encendió sobre él el perfume aromático; como Jehová había mandado á Moisés.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, 'Puso asimismo la cortina de la puerta del tabernáculo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, 'Y colocó el altar del holocausto á la puerta del tabernáculo, del tabernáculo del testimonio; y ofreció sobre él holocausto y presente; como Jehová había mandado á Moisés.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, 'Y puso la fuente entre el tabernáculo del testimonio y el altar; y puso en ella agua para lavar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'Y Moisés y Aarón y sus hijos lavaban en ella sus manos y sus pies.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, 'Cuando entraban en el tabernáculo del testimonio, y cuando se llegaban al altar, se lavaban; como Jehová había mandado á Moisés.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'Finalmente erigió el atrio en derredor del tabernáculo y del altar, y puso la cortina de la puerta del atrio. Y así acabó Moisés la obra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, 'Entonces una nube cubrió el tabernáculo del testimonio, y la gloria de Jehová hinchió el tabernáculo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, 'Y no podía Moisés entrar en el tabernáculo del testimonio, porque la nube estaba sobre él, y la gloria de Jehová lo tenía lleno.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, 'Y cuando la nube se alzaba del tabernáculo, los hijos de Israel se movían en todas sus jornadas:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 37, 'Pero si la nube no se alzaba, no se partían hasta el día en que ella se alzaba.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 38, 'Porque la nube de Jehová estaba de día sobre el tabernáculo, y el fuego estaba de noche en él, á vista de toda la casa de Israel, en todas sus jornadas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, 'Y LLAMÓ Jehová á Moisés, y habló con él desde el tabernáculo del testimonio, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, 'Habla á los hijos de Israel, y diles: Cuando alguno de entre vosotros ofreciere ofrenda á Jehová, de ganado vacuno ú ovejuno haréis vuestra ofrenda.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, 'Si su ofrenda fuere holocausto de vacas, macho sin tacha lo ofrecerá: de su voluntad lo ofrecerá á la puerta del tabernáculo del testimonio delante de Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, 'Y pondrá su mano sobre la cabeza del holocausto; y él lo aceptará para expiarle.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, 'Entonces degollará el becerro en la presencia de Jehová; y los sacerdotes, hijos de Aarón, ofrecerán la sangre, y la rociarán alrededor sobre el altar, el cual está á la puerta del tabernáculo del testimonio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, 'Y desollará el holocausto, y lo dividirá en sus piezas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, 'Y los hijos de Aarón sacerdote pondrán fuego sobre el altar, y compondrán la leña sobre el fuego.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, 'Luego los sacerdotes, hijos de Aarón, acomodarán las piezas, la cabeza y el redaño, sobre la leña que está sobre el fuego, que habrá encima del altar:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, 'Y lavará con agua sus intestinos y sus piernas: y el sacerdote hará arder todo sobre el altar: holocausto es, ofrenda encendida de olor suave á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, 'Y si su ofrenda para holocausto fuere de ovejas, de los corderos, ó de las cabras, macho sin defecto lo ofrecerá.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, 'Y ha de degollarlo al lado septentrional del altar delante de Jehová: y los sacerdotes, hijos de Aarón, rociarán su sangre sobre el altar alrededor.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, 'Y lo dividirá en sus piezas, con su cabeza y su redaño; y el sacerdote las acomodará sobre la leña que está sobre el fuego, que habrá encima del altar;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, 'Y lavará sus entrañas y sus piernas con agua; y el sacerdote lo ofrecerá todo, y harálo arder sobre el altar; holocausto es, ofrenda encendida de olor suave á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, 'Y si el holocausto se hubiere de ofrecer á Jehová de aves, presentará su ofrenda de tórtolas, ó de palominos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, 'Y el sacerdote la ofrecerá sobre el altar, y ha de quitarle la cabeza, y hará que arda en el altar; y su sangre será exprimida sobre la pared del altar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, 'Y le ha de quitar el buche y las plumas, lo cual echará junto al altar, hacia el oriente, en el lugar de las cenizas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, 'Y la henderá por sus alas, mas no la dividirá en dos: y el sacerdote la hará arder sobre el altar, sobre la leña que estará en el fuego; holocausto es, ofrenda encendida de olor suave á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, 'Y CUANDO alguna persona ofreciere oblación de presente á Jehová, su ofrenda será flor de harina, sobre la cual echará aceite, y pondrá sobre ella incienso:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, 'Y la traerá á los sacerdotes, hijos de Aarón; y de ello tomará el sacerdote su puño lleno de su flor de harina y de su aceite, con todo su incienso, y lo hará arder sobre el altar: ofrenda encendida para recuerdo, de olor suave á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, 'Y la sobra del presente será de Aarón y de sus hijos: es cosa santísima de las ofrendas que se queman á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, 'Y cuando ofrecieres ofrenda de presente cocida en horno, será de tortas de flor de harina sin levadura, amasadas con aceite, y hojaldres sin levadura untadas con aceite.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, 'Mas si tu presente fuere ofrenda de sartén, será de flor de harina sin levadura, amasada con aceite,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, 'La cual partirás en piezas, y echarás sobre ella aceite: es presente.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, 'Y si tu presente fuere ofrenda cocida en cazuela, haráse de flor de harina con aceite.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, 'Y traerás á Jehová la ofrenda que se hará de estas cosas, y la presentarás al sacerdote, el cual la llegará al altar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, 'Y tomará el sacerdote de aquel presente, en memoria del mismo, y harálo arder sobre el altar; ofrenda encendida, de suave olor á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, 'Y lo restante del presente será de Aarón y de sus hijos: es cosa santísima de las ofrendas que se queman á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, 'Ningún presente que ofreciereis á Jehová, será con levadura: porque de ninguna cosa leuda, ni de ninguna miel, se ha de quemar ofrenda á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, 'En la ofrenda de las primicias las ofreceréis á Jehová: mas no subirán sobre el altar en olor de suavidad.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, 'Y sazonarás toda ofrenda de tu presente con sal; y no harás que falte jamás de tu presente la sal de la alianza de tu Dios: en toda ofrenda tuya ofrecerás sal.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, 'Y si ofrecieres á Jehová presente de primicias, tostarás al fuego las espigas verdes, y el grano desmenuzado ofrecerás por ofrenda de tus primicias.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, 'Y pondrás sobre ella aceite, y pondrás sobre ella incienso: es presente.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, 'Y el sacerdote hará arder, en memoria del don, parte de su grano desmenuzado, y de su aceite con todo su incienso; es ofrenda encendida á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, 'Y SI su ofrenda fuere sacrificio de paces, si hubiere de ofrecerlo de ganado vacuno, sea macho ó hembra, sin defecto lo ofrecerá delante de Jehová:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, 'Y pondrá su mano sobre la cabeza de su ofrenda, y la degollará á la puerta del tabernáculo del testimonio; y los sacerdotes, hijos de Aarón, rociarán su sangre sobre el altar en derredor.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, 'Luego ofrecerá del sacrificio de las paces, por ofrenda encendida á Jehová, el sebo que cubre los intestinos, y todo el sebo que está sobre las entrañas,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, 'Y los dos riñones, y el sebo que está sobre ellos, y sobre los ijares, y con los riñones quitará el redaño que está sobre el hígado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, 'Y los hijos de Aarón harán arder esto en el altar, sobre el holocausto que estará sobre la leña que habrá encima del fuego; es ofrenda de olor suave á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, 'Mas si de ovejas fuere su ofrenda para sacrificio de paces á Jehová, sea macho ó hembra, ofrecerála sin tacha.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, 'Si ofreciere cordero por su ofrenda, ha de ofrecerlo delante de Jehová:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, 'Y pondrá su mano sobre la cabeza de su ofrenda, y después la degollará delante del tabernáculo del testimonio; y los hijos de Aarón rociarán su sangre sobre el altar en derredor.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, 'Y del sacrificio de las paces ofrecerá por ofrenda encendida á Jehová, su sebo, y la cola entera, la cual quitará á raíz del espinazo, y el sebo que cubre los intestinos, y todo el sebo que está sobre las entrañas:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, 'Asimismo los dos riñones, y el sebo que está sobre ellos, y el que está sobre los ijares, y con los riñones quitará el redaño de sobre el hígado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, 'Y el sacerdote hará arder esto sobre el altar; vianda de ofrenda encendida á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, 'Y si fuere cabra su ofrenda ofrecerála delante de Jehová:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, 'Y pondrá su mano sobre la cabeza de ella, y la degollará delante del tabernáculo del testimonio; y los hijos de Aarón rociarán su sangre sobre el altar en derredor.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, 'Después ofrecerá de ella su ofrenda encendida á Jehová; el sebo que cubre los intestinos, y todo el sebo que está sobre las entrañas,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, 'Y los dos riñones, y el sebo que está sobre ellos, y el que está sobre los ijares, y con los riñones quitará el redaño de sobre el hígado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, 'Y el sacerdote hará arder esto sobre el altar; es vianda de ofrenda que se quema en olor de suavidad á Jehová: el sebo todo es de Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, 'Estatuto perpetuo por vuestras edades; en todas vuestras moradas, ningún sebo ni ninguna sangre comeréis.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, 'Y HABLÓ Jehová á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, 'Habla á los hijos de Israel, diciendo: Cuando alguna persona pecare por yerro en alguno de los mandamientos de Jehová sobre cosas que no se han de hacer, y obrare contra alguno de ellos;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, 'Si sacerdote ungido pecare según el pecado del pueblo, ofrecerá á Jehová, por su pecado que habrá cometido, un becerro sin tacha para expiación.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, 'Y traerá el becerro á la puerta del tabernáculo del testimonio delante de Jehová, y pondrá su mano sobre la cabeza del becerro, y lo degollará delante de Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, 'Y el sacerdote ungido tomará de la sangre del becerro, y la traerá al tabernáculo del testimonio;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, 'Y mojará el sacerdote su dedo en la sangre, y rociará de aquella sangre siete veces delante de Jehová, hacia el velo del santuario.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, 'Y pondrá el sacerdote de la sangre sobre los cuernos del altar del perfume aromático, que está en el tabernáculo del testimonio delante de Jehová: y echará toda la sangre del becerro al pie del altar del holocausto, que está á la puerta del tabernáculo del testimonio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, 'Y tomará del becerro para la expiación todo su sebo, el sebo que cubre los intestinos, y todo el sebo que está sobre las entrañas,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, 'Y los dos riñones, y el sebo que está sobre ellos, y el que está sobre los ijares, y con los riñones quitará el redaño de sobre el hígado,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, 'De la manera que se quita del buey del sacrificio de las paces: y el sacerdote lo hará arder sobre el altar del holocausto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, 'Y el cuero del becerro, y toda su carne, con su cabeza, y sus piernas, y sus intestinos, y su estiércol,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, 'En fin, todo el becerro sacará fuera del campo, á un lugar limpio, donde se echan las cenizas, y lo quemará al fuego sobre la leña: en donde se echan las cenizas será quemado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, 'Y si toda la congregación de Israel hubiere errado, y el negocio estuviere oculto á los ojos del pueblo, y hubieren hecho algo contra alguno de los mandamientos de Jehová en cosas que no se han de hacer, y fueren culpables;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, 'Luego que fuere entendido el pecado sobre que delinquieron, la congregación ofrecerá un becerro por expiación, y lo traerán delante del tabernáculo del testimonio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, 'Y los ancianos de la congregación pondrán sus manos sobre la cabeza del becerro delante de Jehová; y en presencia de Jehová degollarán aquel becerro.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, 'Y el sacerdote ungido meterá de la sangre del becerro en el tabernáculo del testimonio:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, 'Y mojará el sacerdote su dedo en la misma sangre, y rociará siete veces delante de Jehová hacia el velo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, 'Y de aquella sangre pondrá sobre los cuernos del altar que está delante de Jehová en el tabernáculo del testimonio, y derramará toda la sangre al pie del altar del holocausto, que está á la puerta del tabernáculo del testimonio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, 'Y le quitará todo el sebo, y harálo arder sobre el altar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, 'Y hará de aquel becerro como hizo con el becerro de la expiación; lo mismo hará de él: así hará el sacerdote expiación por ellos, y obtendrán perdón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, 'Y sacará el becerro fuera del campamento, y lo quemará como quemó el primer becerro; expiación de la congregación.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, 'Y cuando pecare el príncipe, é hiciere por yerro algo contra alguno de todos los mandamientos de Jehová su Dios, sobre cosas que no se han de hacer, y pecare;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, 'Luego que le fuere conocido su pecado en que ha delinquido, presentará por su ofrenda un macho cabrío sin defecto;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, 'Y pondrá su mano sobre la cabeza del macho cabrío, y lo degollará en el lugar donde se degüella el holocausto delante de Jehová; es expiación.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, 'Y tomará el sacerdote con su dedo de la sangre de la expiación, y pondrá sobre los cuernos del altar del holocausto, y derramará la sangre al pie del altar del holocausto:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, 'Y quemará todo su sebo sobre el altar, como el sebo del sacrificio de las paces: así hará el sacerdote por él la expiación de su pecado, y tendrá perdón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, 'Y si alguna persona del común del pueblo pecare por yerro, haciendo algo contra alguno de los mandamientos de Jehová en cosas que no se han de hacer, y delinquiere;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, 'Luego que le fuere conocido su pecado que cometió, traerá por su ofrenda una hembra de las cabras, una cabra sin defecto, por su pecado que habrá cometido:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, 'Y pondrá su mano sobre la cabeza de la expiación, y la degollará en el lugar del holocausto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, 'Luego tomará el sacerdote en su dedo de su sangre, y pondrá sobre los cuernos del altar del holocausto, y derramará toda su sangre al pie del altar:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, 'Y le quitará todo su sebo, de la manera que fué quitado el sebo del sacrificio de las paces; y el sacerdote lo hará arder sobre el altar en olor de suavidad á Jehová: así hará el sacerdote expiación por él, y será perdonado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, 'Y si trajere cordero para su ofrenda por el pecado, hembra sin defecto traerá:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, 'Y pondrá su mano sobre la cabeza de la expiación, y la degollará por expiación en el lugar donde se degüella el holocausto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, 'Después tomará el sacerdote con su dedo de la sangre de la expiación, y pondrá sobre los cuernos del altar del holocausto; y derramará toda la sangre al pie del altar:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, 'Y le quitará todo su sebo, como fué quitado el sebo del sacrificio de las paces, y harálo el sacerdote arder en el altar sobre la ofrenda encendida á Jehová: y le hará el sacerdote expiación de su pecado que habrá cometido, y será perdonado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, 'Y CUANDO alguna persona pecare, que hubiere oído la voz del que juró, y él fuere testigo que vió, ó supo, si no lo denunciare, él llevará su pecado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, 'Asimismo la persona que hubiere tocado en cualquiera cosa inmunda, sea cuerpo muerto de bestia inmunda, ó cuerpo muerto de animal inmundo, ó cuerpo muerto de reptil inmundo, bien que no lo supiere, será inmunda y habrá delinquido:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, 'O si tocare á hombre inmundo en cualquiera inmundicia suya de que es inmundo, y no lo echare de ver; si después llega á saberlo, será culpable.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, 'También la persona que jurare, pronunciando con sus labios hacer mal ó bien, en cualesquiera cosas que el hombre profiere con juramento, y él no lo conociere; si después lo entiende, será culpado en una de estas cosas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, 'Y será que cuando pecare en alguna de estas cosas, confesará aquello en que pecó:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, 'Y para su expiación traerá á Jehová por su pecado que ha cometido, una hembra de los rebaños, una cordera ó una cabra como ofrenda de expiación; y el sacerdote hará expiación por él de su pecado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, 'Y si no le alcanzare para un cordero, traerá en expiación por su pecado que cometió, dos tórtolas ó dos palominos á Jehová; el uno para expiación, y el otro para holocausto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, 'Y ha de traerlos al sacerdote, el cual ofrecerá primero el que es para expiación, y desunirá su cabeza de su cuello, mas no la apartará del todo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, 'Y rociará de la sangre de la expiación sobre la pared del altar; y lo que sobrare de la sangre lo exprimirá al pie del altar; es expiación.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, 'Y del otro hará holocausto conforme al rito; y hará por él el sacerdote expiación de su pecado que cometió, y será perdonado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, 'Mas si su posibilidad no alcanzare para dos tórtolas, ó dos palominos, el que pecó traerá por su ofrenda la décima parte de un epha de flor de harina por expiación. No pondrá sobre ella aceite, ni sobre ella pondrá incienso, porque es expiación.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, 'Traerála, pues, al sacerdote, y el sacerdote tomará de ella su puño lleno, en memoria suya, y la hará arder en el altar sobre las ofrendas encendidas á Jehová: es expiación.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, 'Y hará el sacerdote expiación por él de su pecado que cometió en alguna de estas cosas, y será perdonado; y el sobrante será del sacerdote, como el presente de vianda.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, 'Habló más Jehová á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, 'Cuando alguna persona cometiere falta, y pecare por yerro en las cosas santificadas á Jehová, traerá su expiación á Jehová, un carnero sin tacha de los rebaños, conforme á tu estimación, en siclos de plata del siclo del santuario, en ofrenda por el pecado:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, 'Y pagará aquello de las cosas santas en que hubiere pecado, y añadirá á ello el quinto, y lo dará al sacerdote: y el sacerdote hará expiación por él con el carnero del sacrificio por el pecado, y será perdonado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, 'Finalmente, si una persona pecare, ó hiciere alguna de todas aquellas cosas que por mandamiento de Jehová no se han de hacer, aun sin hacerlo á sabiendas, es culpable, y llevará su pecado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, 'Traerá, pues, al sacerdote por expiación, según tú lo estimes, un carnero sin tacha de los rebaños: y el sacerdote hará expiación por él de su yerro que cometió por ignorancia, y será perdonado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, 'Es infracción, y ciertamente delinquió contra Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, 'Y HABLÓ Jehová á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, 'Cuando una persona pecare, é hiciere prevaricación contra Jehová, y negare á su prójimo lo encomendado, ó dejado en su mano, ó bien robare, ó calumniare á su prójimo;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, 'O sea que hallando lo perdido, después lo negare, y jurare en falso, en alguna de todas aquellas cosas en que suele pecar el hombre:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, 'Entonces será que, puesto habrá pecado y ofendido, restituirá aquello que robó, ó por el daño de la calumnia, ó el depósito que se le encomendó, ó lo perdido que halló,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, 'O todo aquello sobre que hubiere jurado falsamente; lo restituirá, pues, por entero, y añadirá á ello la quinta parte, que ha de pagar á aquel á quien pertenece en el día de su expiación.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, 'Y por su expiación traerá á Jehová un carnero sin tacha de los rebaños, conforme á tu estimación, al sacerdote para la expiación:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, 'Y el sacerdote hará expiación por él delante de Jehová, y obtendrá perdón de cualquiera de todas las cosas en que suele ofender.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, 'Habló aún Jehová á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, 'Manda á Aarón y á sus hijos diciendo: Esta es la ley del holocausto: (es holocausto, porque se quema sobre el altar toda la noche hasta la mañana, y el fuego del altar arderá en él:)');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, 'El sacerdote se pondrá su vestimenta de lino, y se vestirá pañetes de lino sobre su carne; y cuando el fuego hubiere consumido el holocausto, apartará él las cenizas de sobre el altar, y pondrálas junto al altar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, 'Después se desnudará de sus vestimentas, y se pondrá otras vestiduras, y sacará las cenizas fuera del real al lugar limpio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, 'Y el fuego encendido sobre el altar no ha de apagarse, sino que el sacerdote pondrá en él leña cada mañana, y acomodará sobre él el holocausto, y quemará sobre él los sebos de las paces.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, 'El fuego ha de arder continuamente en el altar; no se apagará.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, 'Y esta es la ley del presente: Han de ofrecerlo los hijos de Aarón delante de Jehová, delante del altar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, 'Y tomará de él un puñado de la flor de harina del presente, y de su aceite, y todo el incienso que está sobre el presente, y harálo arder sobre el altar por memoria, en olor suavísimo á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, 'Y el sobrante de ella lo comerán Aarón y sus hijos: sin levadura se comerá en el lugar santo; en el atrio del tabernáculo del testimonio lo comerán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, 'No se cocerá con levadura: helo dado á ellos por su porción de mis ofrendas encendidas; es cosa santísima, como la expiación por el pecado, y como la expiación por la culpa.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, 'Todos los varones de los hijos de Aarón comerán de ella. Estatuto perpetuo será para vuestras generaciones tocante á las ofrendas encendidas de Jehová: toda cosa que tocare en ellas será santificada.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, 'Y habló Jehová á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, 'Esta es la ofrenda de Aarón y de sus hijos, que ofrecerán á Jehová el día que serán ungidos: la décima parte de un epha de flor de harina, presente perpetuo, la mitad á la mañana y la mitad á la tarde.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, 'En sartén se aderezará con aceite; frita la traerás, y los pedazos cocidos del presente ofrecerás á Jehová en olor de suavidad.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, 'Y el sacerdote que en lugar de Aarón fuere ungido de entre sus hijos, hará la ofrenda; estatuto perpetuo de Jehová: toda ella será quemada.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, 'Y todo presente de sacerdote será enteramente quemado; no se comerá.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 24, 'Y habló Jehová á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 25, 'Habla á Aarón y á sus hijos, diciendo: Esta es la ley de la expiación: en el lugar donde será degollado el holocausto, será degollada la expiación por el pecado delante de Jehová: es cosa santísima.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 26, 'El sacerdote que la ofreciere por expiación, la comerá: en el lugar santo será comida, en el atrio del tabernáculo del testimonio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 27, 'Todo lo que en su carne tocare, será santificado; y si cayere de su sangre sobre el vestido, lavarás aquello sobre que cayere, en el lugar santo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 28, 'Y la vasija de barro en que fuere cocida, será quebrada: y si fuere cocida en vasija de metal, será fregada y lavada con agua.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 29, 'Todo varón de entre los sacerdotes la comerá: es cosa santísima.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 30, 'Mas no se comerá de expiación alguna, de cuya sangre se metiere en el tabernáculo del testimonio para reconciliar en el santuario: al fuego será quemada.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, 'ASIMISMO esta es la ley de la expiación de la culpa: es cosa muy santa.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, 'En el lugar donde degollaren el holocausto, degollarán la víctima por la culpa; y rociará su sangre en derredor sobre el altar:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, 'Y de ella ofrecerá todo su sebo, la cola, y el sebo que cubre los intestinos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, 'Y los dos riñones, y el sebo que está sobre ellos, y el que está sobre los ijares; y con los riñones quitará el redaño de sobre el hígado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, 'Y el sacerdote lo hará arder sobre el altar; ofrenda encendida á Jehová: es expiación de la culpa.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, 'Todo varón de entre los sacerdotes la comerá: será comida en el lugar santo: es cosa muy santa.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, 'Como la expiación por el pecado, así es la expiación de la culpa: una misma ley tendrán: será del sacerdote que habrá hecho la reconciliación con ella.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, 'Y el sacerdote que ofreciere holocausto de alguno, el cuero del holocausto que ofreciere, será para él.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, 'Asimismo todo presente que se cociere en horno, y todo el que fuere aderezado en sartén, ó en cazuela, será del sacerdote que lo ofreciere.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, 'Y todo presente amasado con aceite, y seco, será de todos los hijos de Aarón, tanto al uno como al otro.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, 'Y esta es la ley del sacrificio de las paces, que se ofrecerá á Jehová:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, 'Si se ofreciere en hacimiento de gracias, ofrecerá por sacrificio de hacimiento de gracias tortas sin levadura amasadas con aceite, y hojaldres sin levadura untadas con aceite, y flor de harina frita en tortas amasadas con aceite.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, 'Con tortas de pan leudo ofrecerá su ofrenda en el sacrificio de hacimientos de gracias de sus paces.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, 'Y de toda la ofrenda presentará una parte por ofrenda elevada á Jehová, y será del sacerdote que rociare la sangre de los pacíficos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, 'Y la carne del sacrificio de sus pacíficos en hacimiento de gracias, se comerá en el día que fuere ofrecida: no dejarán de ella nada para otro día.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, 'Mas si el sacrificio de su ofrenda fuere voto, ó voluntario, el día que ofreciere su sacrificio será comido; y lo que de él quedare, comerse ha el día siguiente:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, 'Y lo que quedare para el tercer día de la carne del sacrificio, será quemado en el fuego.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, 'Y si se comiere de la carne del sacrificio de sus paces el tercer día, el que lo ofreciere no será acepto, ni le será imputado; abominación será, y la persona que de él comiere llevará su pecado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, 'Y la carne que tocare á alguna cosa inmunda, no se comerá; al fuego será quemada; mas cualquiera limpio comerá de aquesta carne.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, 'Y la persona que comiere la carne del sacrificio de paces, el cual es de Jehová, estando inmunda, aquella persona será cortada de sus pueblos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, 'Además, la persona que tocare alguna cosa inmunda, en inmundicia de hombre, ó en animal inmundo, ó en cualquiera abominación inmunda, y comiere la carne del sacrificio de las paces, el cual es de Jehová, aquella persona será cortada de sus pueblos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, 'Habló aún Jehová á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, 'Habla á los hijos de Israel, diciendo: Ningún sebo de buey, ni de cordero, ni de cabra, comeréis.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, 'El sebo de animal mortecino, y el sebo del que fué arrebatado de fieras, se aparejará para cualquiera otro uso, mas no lo comeréis.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, 'Porque cualquiera que comiere sebo de animal, del cual se ofrece á Jehová ofrenda encendida, la persona que lo comiere, será cortada de sus pueblos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, 'Además, ninguna sangre comeréis en todas vuestras habitaciones, así de aves como de bestias.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, 'Cualquiera persona que comiere alguna sangre, la tal persona será cortada de sus pueblos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, 'Habló más Jehová á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, 'Habla á los hijos de Israel, diciendo: El que ofreciere sacrificio de sus paces á Jehová, traerá su ofrenda del sacrificio de sus paces á Jehová;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, 'Sus manos traerán las ofrendas que se han de quemar á Jehová: traerá el sebo con el pecho: el pecho para que éste sea agitado, como sacrificio agitado delante de Jehová;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, 'Y el sebo lo hará arder el sacerdote en el altar; mas el pecho será de Aarón y de sus hijos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, 'Y daréis al sacerdote para ser elevada en ofrenda, la espaldilla derecha de los sacrificios de vuestras paces.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, 'El que de los hijos de Aarón ofreciere la sangre de las paces, y el sebo, de él será en porción la espaldilla derecha;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, 'Porque he tomado de los hijos de Israel, de los sacrificios de sus paces, el pecho que se agita, y la espaldilla elevada en ofrenda, y lo he dado á Aarón el sacerdote y á sus hijos, por estatuto perpetuo de los hijos de Israel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, 'Esta es por la unción de Aarón y la unción de sus hijos, la parte de ellos en las ofrendas encendidas á Jehová, desde el día que él los allegó para ser sacerdotes de Jehová:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, 'Lo cual mandó Jehová que les diesen, desde el día que él los ungió de entre los hijos de Israel, por estatuto perpetuo en sus generaciones.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, 'Esta es la ley del holocausto, del presente, de la expiación por el pecado, y de la culpa, y de las consagraciones, y del sacrificio de las paces:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, 'La cual intimó Jehová á Moisés, en el monte de Sinaí, el día que mandó á los hijos de Israel que ofreciesen sus ofrendas á Jehová en el desierto de Sinaí.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, 'Y HABLÓ Jehová á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, 'Toma á Aarón y á sus hijos con él, y las vestimentas, y el aceite de la unción, y el becerro de la expiación, y los dos carneros, y el canastillo de los ázimos;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, 'Y reune toda la congregación á la puerta del tabernáculo del testimonio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, 'Hizo, pues, Moisés como Jehová le mandó, y juntóse la congregación á la puerta del tabernáculo del testimonio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, 'Y dijo Moisés á la congregación: Esto es lo que Jehová ha mandado hacer.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, 'Entonces Moisés hizo llegar á Aarón y á sus hijos, y lavólos con agua.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, 'Y puso sobre él la túnica, y ciñólo con el cinto; vistióle después el manto, y puso sobre él el ephod, y ciñólo con el cinto del ephod, y ajustólo con él.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, 'Púsole luego encima el racional, y en él puso el Urim y Thummim.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, 'Después puso la mitra sobre su cabeza; y sobre la mitra en su frente delantero puso la plancha de oro, la diadema santa; como Jehová había mandado á Moisés.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, 'Y tomó Moisés el aceite de la unción, y ungió el tabernáculo, y todas las cosas que estaban en él, y santificólas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, 'Y roció de él sobre el altar siete veces, y ungió el altar y todos sus vasos, y la fuente y su basa, para santificarlos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, 'Y derramó del aceite de la unción sobre la cabeza de Aarón, y ungiólo para santificarlo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, 'Después Moisés hizo llegar los hijos de Aarón, y vistióles las túnicas, y ciñólos con cintos, y ajustóles los chapeos (tiaras), como Jehová lo había mandado á Moisés.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, 'Hizo luego llegar el becerro de la expiación, y Aarón y sus hijos pusieron sus manos sobre la cabeza del becerro de la expiación.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, 'Y degollólo; y Moisés tomó la sangre, y puso con su dedo sobre los cuernos del altar alrededor, y purificó el altar; y echó la demás sangre al pie del altar, y santificólo para reconciliar sobre él.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, 'Después tomó todo el sebo que estaba sobre los intestinos, y el redaño del hígado, y los dos riñones, y el sebo de ellos, é hízolo Moisés arder sobre el altar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, 'Mas el becerro, y su cuero, y su carne, y su estiércol, quemólo al fuego fuera del real; como Jehová lo había mandado á Moisés.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, 'Después hizo llegar el carnero del holocausto, y Aarón y sus hijos pusieron sus manos sobre la cabeza del carnero:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, 'Y degollólo; y roció Moisés la sangre sobre el altar en derredor.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, 'Y cortó el carnero en trozos; y Moisés hizo arder la cabeza, y los trozos, y el sebo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, 'Lavó luego con agua los intestinos y piernas, y quemó Moisés todo el carnero sobre el altar: holocausto en olor de suavidad, ofrenda encendida á Jehová; como lo había Jehová mandado á Moisés.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, 'Después hizo llegar el otro carnero, el carnero de las consagraciones, y Aarón y sus hijos pusieron sus manos sobre la cabeza del carnero:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, 'Y degollólo; y tomó Moisés de su sangre, y puso sobre la ternilla de la oreja derecha de Aarón, y sobre el dedo pulgar de su mano derecha, y sobre el dedo pulgar de su pie derecho.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, 'Hizo llegar luego los hijos de Aarón, y puso Moisés de la sangre sobre la ternilla de sus orejas derechas, y sobre los pulgares de sus manos derechas, y sobre los pulgares de sus pies derechos: y roció Moisés la sangre sobre el altar en derredor;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, 'Y después tomó el sebo, y la cola, y todo el sebo que estaba sobre los intestinos, y el redaño del hígado, y los dos riñones, y el sebo de ellos, y la espaldilla derecha;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, 'Y del canastillo de los ázimos, que estaba delante de Jehová, tomó una torta sin levadura, y una torta de pan de aceite, y una lasaña, y púsolo con el sebo y con la espaldilla derecha;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, 'Y púsolo todo en las manos de Aarón, y en las manos de sus hijos, é hízolo mecer: ofrenda agitada delante de Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, 'Después tomó aquellas cosas Moisés de las manos de ellos, é hízolas arder en el altar sobre el holocausto: las consagraciones en olor de suavidad, ofrenda encendida á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, 'Y tomó Moisés el pecho, y meciólo, ofrenda agitada delante de Jehová: del carnero de las consagraciones aquélla fué la parte de Moisés; como Jehová lo había mandado á Moisés.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, 'Luego tomó Moisés del aceite de la unción, y de la sangre que estaba sobre el altar, y roció sobre Aarón, y sobre sus vestiduras, sobre sus hijos, y sobre las vestiduras de sus hijos con él; y santificó á Aarón, y sus vestiduras, y á sus hijos, y las vestiduras de sus hijos con él.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, 'Y dijo Moisés á Aarón y á sus hijos: Comed la carne á la puerta del tabernáculo del testimonio; y comedla allí con el pan que está en el canastillo de las consagraciones, según yo he mandado, diciendo: Aarón y sus hijos la comerán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, 'Y lo que sobrare de la carne y del pan, habéis de quemarlo al fuego.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, 'De la puerta del tabernáculo del testimonio no saldréis en siete días, hasta el día que se cumplieren los días de vuestras consagraciones: porque por siete días seréis consagrados.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, 'De la manera que hoy se ha hecho, mandó hacer Jehová para expiaros.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, 'A la puerta, pues, del tabernáculo del testimonio estaréis día y noche por siete días, y guardaréis la ordenanza delante de Jehová, para que no muráis; porque así me ha sido mandado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, 'Y Aarón y sus hijos hicieron todas las cosas que mandó Jehová por medio de Moisés.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, 'Y FUÉ en el día octavo, que Moisés llamó á Aarón y á sus hijos, y á los ancianos de Israel;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, 'Y dijo á Aarón: Toma de la vacada un becerro para expiación, y un carnero para holocausto, sin defecto, y ofrécelos delante de Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, 'Y á los hijos de Israel hablarás, diciendo: Tomad un macho cabrío para expiación, y un becerro y un cordero de un año, sin tacha, para holocausto;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, 'Asimismo un buey y un carnero para sacrificio de paces, que inmoléis delante de Jehová; y un presente amasado con aceite: porque Jehová se aparecerá hoy á vosotros.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, 'Y llevaron lo que mandó Moisés delante del tabernáculo del testimonio, y llegóse toda la congregación, y pusiéronse delante de Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, 'Entonces Moisés dijo: Esto es lo que mandó Jehová; hacedlo, y la gloria de Jehová se os aparecerá.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, 'Y dijo Moisés á Aarón: Llégate al altar, y haz tu expiación, y tu holocausto, y haz la reconciliación por ti y por el pueblo: haz también la ofrenda del pueblo, y haz la reconciliación por ellos; como ha mandado Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, 'Entonces llegóse Aarón al altar; y degolló su becerro de la expiación que era por él.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, 'Y los hijos de Aarón le trajeron la sangre; y él mojó su dedo en la sangre, y puso sobre los cuernos del altar, y derramó la demás sangre al pie del altar;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, 'Y el sebo y riñones y redaño del hígado, de la expiación, hízolos arder sobre el altar; como Jehová lo había mandado á Moisés.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, 'Mas la carne y el cuero los quemó al fuego fuera del real.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, 'Degolló asimismo el holocausto, y los hijos de Aarón le presentaron la sangre, la cual roció él alrededor sobre el altar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, 'Presentáronle después el holocausto, á trozos, y la cabeza; é hízolos quemar sobre el altar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, 'Luego lavó los intestinos y las piernas, y quemólos sobre el holocausto en el altar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, 'Ofreció también la ofrenda del pueblo, y tomó el macho cabrío que era para la expiación del pueblo, y degollólo, y lo ofreció por el pecado como el primero.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, 'Y ofreció el holocausto, é hizo según el rito.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, 'Ofreció asimismo el presente, é hinchió de él su mano, y lo hizo quemar sobre el altar, además del holocausto de la mañana.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, 'Degolló también el buey y el carnero en sacrificio de paces, que era del pueblo: y los hijos de Aarón le presentaron la sangre (la cual roció él sobre el altar alrededor),');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, 'Y los sebos del buey; y del carnero la cola con lo que cubre las entrañas, y los riñones, y el redaño del hígado:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, 'Y pusieron los sebos sobre los pechos, y él quemó los sebos sobre el altar:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, 'Empero los pechos, con la espaldilla derecha, meciólos Aarón por ofrenda agitada delante de Jehová; como Jehová lo había mandado á Moisés.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, 'Después alzó Aarón sus manos hacia el pueblo y bendíjolos: y descendió de hacer la expiación, y el holocausto, y el sacrificio de las paces.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, 'Y entraron Moisés y Aarón en el tabernáculo del testimonio; y salieron, y bendijeron al pueblo: y la gloria de Jehová se apareció á todo el pueblo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, 'Y salió fuego de delante de Jehová, y consumió el holocausto y los sebos sobre el altar; y viéndolo todo el pueblo, alabaron, y cayeron sobre sus rostros.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, 'Y LOS hijos de Aarón, Nadab y Abiú, tomaron cada uno su incensario, y pusieron fuego en ellos, sobre el cual pusieron perfume, y ofrecieron delante de Jehová fuego extraño, que él nunca les mandó.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, 'Y salió fuego de delante de Jehová que los quemó, y murieron delante de Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, 'Entonces dijo Moisés á Aarón: Esto es lo que habló Jehová, diciendo: En mis allegados me santificaré, y en presencia de todo el pueblo seré glorificado. Y Aarón calló.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, 'Y llamó Moisés á Misael, y á Elzaphán, hijos de Uzziel, tío de Aarón, y díjoles: Llegaos y sacad á vuestros hermanos de delante del santuario fuera del campo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, 'Y ellos llegaron, y sacáronlos con sus túnicas fuera del campo, como dijo Moisés.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, 'Entonces Moisés dijo á Aarón, y á Eleazar y á Ithamar, sus hijos: No descubráis vuestras cabezas, ni rasguéis vuestros vestidos, porque no muráis, ni se levante la ira sobre toda la congregación: empero vuestros hermanos, toda la casa de Israel, lamentarán el incendio que Jehová ha hecho.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, 'Ni saldréis de la puerta del tabernáculo del testimonio, porque moriréis; por cuanto el aceite de la unción de Jehová está sobre vosotros. Y ellos hicieron conforme al dicho de Moisés.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, 'Y Jehová habló á Aarón, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, 'Tú, y tus hijos contigo, no beberéis vino ni sidra, cuando hubiereis de entrar en el tabernáculo del testimonio, porque no muráis: estatuto perpetuo por vuestras generaciones;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, 'Y para poder discernir entre lo santo y lo profano, y entre lo inmundo y lo limpio;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, 'Y para enseñar á los hijos de Israel todos los estatutos que Jehová les ha dicho por medio de Moisés.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, 'Y Moisés dijo á Aarón, y á Eleazar y á Ithamar, sus hijos que habían quedado: Tomad el presente que queda de las ofrendas encendidas á Jehová, y comedlo sin levadura junto al altar, porque es cosa muy santa.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, 'Habéis, pues, de comerlo en el lugar santo: porque esto es fuero para ti, y fuero para tus hijos, de las ofrendas encendidas á Jehová, pues que así me ha sido mandado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, 'Comeréis asimismo en lugar limpio, tú y tus hijos y tus hijas contigo, el pecho de la mecida, y la espaldilla elevada, porque por fuero para ti, y fuero para tus hijos, son dados de los sacrificios de las paces de los hijos de Israel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, 'Con las ofrendas de los sebos que se han de encender, traerán la espaldilla que se ha de elevar, y el pecho que será mecido, para que lo mezas por ofrenda agitada delante de Jehová: y será por fuero perpetuo tuyo, y de tus hijos contigo, como Jehová lo ha mandado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, 'Y Moisés demandó el macho cabrío de la expiación, y hallóse que era quemado: y enojóse contra Eleazar é Ithamar, los hijos de Aarón que habían quedado, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, '¿Por qué no comisteis la expiación en el lugar santo? porque es muy santa, y dióla él á vosotros para llevar la iniquidad de la congregación, para que sean reconciliados delante de Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, 'Veis que su sangre no fué metida dentro del santuario: habíais de comerla en el lugar santo, como yo mandé.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, 'Y respondió Aarón á Moisés: He aquí hoy han ofrecido su expiación y su holocausto delante de Jehová: pero me han acontecido estas cosas: pues si comiera yo hoy de la expiación, ¿hubiera sido acepto á Jehová?');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, 'Y cuando Moisés oyó esto, dióse por satisfecho.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, 'Y HABLÓ Jehová á Moisés y á Aarón, diciéndoles:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, 'Hablad á los hijos de Israel, diciendo: Estos son los animales que comeréis de todos los animales que están sobre la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, 'De entre los animales, todo el de pezuña, y que tiene las pezuñas hendidas, y que rumia, éste comeréis.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, 'Estos empero no comeréis de los que rumian, y de los que tienen pezuña: el camello, porque rumia mas no tiene pezuña hendida, habéis de tenerlo por inmundo;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, 'También el conejo, porque rumia, mas no tiene pezuña, tendréislo por inmundo;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, 'Asimismo la liebre, porque rumia, mas no tiene pezuña, tendréisla por inmunda;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, 'También el puerco, porque tiene pezuñas, y es de pezuñas hendidas, mas no rumia, tendréislo por inmundo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, 'De la carne de ellos no comeréis, ni tocaréis su cuerpo muerto: tendréislos por inmundos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, 'Esto comeréis de todas las cosas que están en las aguas: todas las cosas que tienen aletas y escamas en las aguas de la mar, y en los ríos, aquellas comeréis;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, 'Mas todas las cosas que no tienen aletas ni escamas en la mar y en los ríos, así de todo reptil de agua como de toda cosa viviente que está en las aguas, las tendréis en abominación.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, 'Os serán, pues, en abominación: de su carne no comeréis, y abominaréis sus cuerpos muertos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, 'Todo lo que no tuviere aletas y escamas en las aguas, tendréislo en abominación.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, 'Y de las aves, éstas tendréis en abominación; no se comerán, serán abominación: el águila, el quebrantahuesos, el esmerejón,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, 'El milano, y el buitre según su especie;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, 'Todo cuervo según su especie;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, 'El avestruz, y la lechuza, y el laro, y el gavilán según su especie,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, 'Y el buho, y el somormujo, y el ibis,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, 'Y el calamón, y el cisne, y el onocrótalo,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, 'Y el herodión, y el caradrión, según su especie, y la abubilla, y el murciélago.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, 'Todo reptil alado que anduviere sobre cuatro pies, tendréis en abominación.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, 'Empero esto comeréis de todo reptil alado que anda sobre cuatro pies, que tuviere piernas además de sus pies para saltar con ellas sobre la tierra;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, 'Estos comeréis de ellos: la langosta según su especie, y el langostín según su especie, y el aregol según su especie, y el haghab según su especie.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, 'Todo reptil alado que tenga cuatro pies, tendréis en abominación.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, 'Y por estas cosas seréis inmundos: cualquiera que tocare á sus cuerpos muertos, será inmundo hasta la tarde:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, 'Y cualquiera que llevare de sus cuerpos muertos, lavará sus vestidos, y será inmundo hasta la tarde.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, 'Todo animal de pezuña, pero que no tiene pezuña hendida, ni rumia, tendréis por inmundo: cualquiera que los tocare será inmundo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, 'Y de todos los animales que andan á cuatro pies, tendréis por inmundo cualquiera que ande sobre sus garras: cualquiera que tocare sus cuerpos muertos, será inmundo hasta la tarde.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, 'Y el que llevare sus cuerpos muertos, lavará sus vestidos, y será inmundo hasta la tarde: habéis de tenerlos por inmundos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, 'Y estos tendréis por inmundos de los reptiles que van arrastrando sobre la tierra: la comadreja, y el ratón, y la rana según su especie,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, 'Y el erizo, y el lagarto, y el caracol, y la babosa, y el topo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, 'Estos tendréis por inmundos de todos los reptiles: cualquiera que los tocare, cuando estuvieren muertos, será inmundo hasta la tarde.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, 'Y todo aquello sobre que cayere alguno de ellos después de muertos, será inmundo; así vaso de madera, como vestido, ó piel, ó saco, cualquier instrumento con que se hace obra, será metido en agua, y será inmundo hasta la tarde, y así será limpio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, 'Y toda vasija de barro dentro de la cual cayere alguno de ellos, todo lo que estuviere en ella será inmundo, y quebraréis la vasija:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, 'Toda vianda que se come, sobre la cual viniere el agua de tales vasijas, será inmunda: y toda bebida que se bebiere, será en todas esas vasijas inmunda:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, 'Y todo aquello sobre que cayere algo del cuerpo muerto de ellos, será inmundo: el horno ú hornillos se derribarán; son inmundos, y por inmundos los tendréis.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, 'Con todo, la fuente y la cisterna donde se recogen aguas, serán limpias: mas lo que hubiere tocado en sus cuerpos muertos será inmundo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, 'Y si cayere de sus cuerpos muertos sobre alguna simiente que se haya de sembrar, será limpia.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, 'Mas si se hubiere puesto agua en la simiente, y cayere de sus cuerpos muertos sobre ella, tendréisla por inmunda.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, 'Y si algún animal que tuviereis para comer se muriere, el que tocare su cuerpo muerto será inmundo hasta la tarde:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, 'Y el que comiere de su cuerpo muerto, lavará sus vestidos, y será inmundo hasta la tarde: asimismo el que sacare su cuerpo muerto, lavará sus vestidos, y será inmundo hasta la tarde.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, 'Y todo reptil que va arrastrando sobre la tierra, es abominación; no se comerá.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, 'Todo lo que anda sobre el pecho, y todo lo que anda sobre cuatro ó más pies, de todo reptil que anda arrastrando sobre la tierra, no lo comeréis, porque es abominación.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, 'No ensuciéis vuestras personas con ningún reptil que anda arrastrando, ni os contaminéis con ellos, ni seáis inmundos por ellos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, 'Pues que yo soy Jehová vuestro Dios, vosotros por tanto os santificaréis, y seréis santos, porque yo soy santo: así que no ensuciéis vuestras personas con ningún reptil que anduviere arrastrando sobre la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, 'Porque yo soy Jehová, que os hago subir de la tierra de Egipto para seros por Dios: seréis pues santos, porque yo soy santo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, 'Esta es la ley de los animales y de las aves, y de todo ser viviente que se mueve en las aguas, y de todo animal que anda arrastrando sobre la tierra;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, 'Para hacer diferencia entre inmundo y limpio, y entre los animales que se pueden comer y los animales que no se pueden comer.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, 'Y HABLÓ Jehová á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, 'Habla á los hijos de Israel, diciendo: La mujer cuando concibiere y pariere varón, será inmunda siete días; conforme á los días que está separada por su menstruo, será inmunda.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, 'Y al octavo día circuncidará la carne de su prepucio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, 'Mas ella permanecerá treinta y tres días en la sangre de su purgación: ninguna cosa santa tocará, ni vendrá al santuario, hasta que sean cumplidos los días de su purgación.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, 'Y si pariere hembra será inmunda dos semanas, conforme á su separación, y sesenta y seis días estará purificándose de su sangre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, 'Y cuando los días de su purgación fueren cumplidos, por hijo ó por hija, traerá un cordero de un año para holocausto, y un palomino ó una tórtola para expiación, á la puerta del tabernáculo del testimonio, al sacerdote:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, 'Y él ofrecerá delante de Jehová, y hará expiación por ella, y será limpia del flujo de su sangre. Esta es la ley de la que pariere varón ó hembra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, 'Y si no alcanzare su mano lo suficiente para un cordero, tomará entonces dos tórtolas ó dos palominos, uno para holocausto, y otro para expiación: y el sacerdote hará expiación por ella, y será limpia.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, 'Y HABLÓ Jehová á Moisés y á Aarón, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, 'Cuando el hombre tuviere en la piel de su carne hinchazón, ó postilla, ó mancha blanca, y hubiere en la piel de su carne como llaga de lepra, será traído á Aarón el sacerdote, ó á uno de los sacerdotes sus hijos:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, 'Y el sacerdote mirará la llaga en la piel de la carne: si el pelo en la llaga se ha vuelto blanco, y pareciere la llaga más hundida que la tez de la carne, llaga de lepra es; y el sacerdote le reconocerá, y le dará por inmundo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, 'Y si en la piel de su carne hubiere mancha blanca, pero no pareciere más hundida que la tez, ni su pelo se hubiere vuelto blanco, entonces el sacerdote encerrará al llagado por siete días;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, 'Y al séptimo día el sacerdote lo mirará; y si la llaga á su parecer se hubiere estancado, no habiéndose extendido en la piel, entonces el sacerdote le volverá á encerrar por otros siete días.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, 'Y al séptimo día el sacerdote le reconocerá de nuevo; y si parece haberse oscurecido la llaga, y que no ha cundido en la piel, entonces el sacerdote lo dará por limpio: era postilla; y lavará sus vestidos, y será limpio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, 'Mas si hubiere ido creciendo la postilla en la piel, después que fué mostrado al sacerdote para ser limpio, será visto otra vez del sacerdote:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, 'Y si reconociéndolo el sacerdote, ve que la postilla ha crecido en la piel, el sacerdote lo dará por inmundo: es lepra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, 'Cuando hubiere llaga de lepra en el hombre, será traído al sacerdote;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, 'Y el sacerdote mirará, y si pareciere tumor blanco en la piel, el cual haya mudado el color del pelo, y se descubre asimismo la carne viva,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, 'Lepra es envejecida en la piel de su carne; y le dará por inmundo el sacerdote, y no le encerrará, porque es inmundo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, 'Mas si brotare la lepra cundiendo por el cutis, y ella cubriere toda la piel del llagado desde su cabeza hasta sus pies, á toda vista de ojos del sacerdote;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, 'Entonces el sacerdote le reconocerá; y si la lepra hubiere cubierto toda su carne, dará por limpio al llagado: hase vuelto toda ella blanca; y él es limpio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, 'Mas el día que apareciere en él la carne viva, será inmundo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, 'Y el sacerdote mirará la carne viva, y lo dará por inmundo. Es inmunda la carne viva: es lepra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, 'Mas cuando la carne viva se mudare y volviere blanca, entonces vendrá al sacerdote;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, 'Y el sacerdote mirará, y si la llaga se hubiere vuelto blanca, el sacerdote dará por limpio al que tenía la llaga, y será limpio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, 'Y cuando en la carne, en su piel, hubiere apostema, y se sanare,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, 'Y sucediere en el lugar de la apostema tumor blanco, ó mancha blanca embermejecida, será mostrado al sacerdote:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, 'Y el sacerdote mirará; y si pareciere estar más baja que su piel, y su pelo se hubiere vuelto blanco, darálo el sacerdote por inmundo: es llaga de lepra que se originó en la apostema.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, 'Y si el sacerdote la considerare, y no pareciere en ella pelo blanco, ni estuviere más baja que la piel, sino oscura, entonces el sacerdote lo encerrará por siete días:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, 'Y si se fuere extendiendo por la piel, entonces el sacerdote lo dará por inmundo: es llaga.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, 'Empero si la mancha blanca se estuviere en su lugar, que no haya cundido, es la costra de la apostema; y el sacerdote lo dará por limpio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, 'Asimismo cuando la carne tuviere en su piel quemadura de fuego, y hubiere en lo sanado del fuego mancha blanquecina, bermejiza ó blanca,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, 'El sacerdote la mirará; y si el pelo se hubiere vuelto blanco en la mancha, y pareciere estar más hundida que la piel, es lepra que salió en la quemadura; y el sacerdote declarará al sujeto inmundo, por ser llaga de lepra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, 'Mas si el sacerdote la mirare, y no pareciere en la mancha pelo blanco, ni estuviere más baja que la tez, sino que está oscura, le encerrará el sacerdote por siete días;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, 'Y al séptimo día el sacerdote la reconocerá: si se hubiere ido extendiendo por la piel, el sacerdote lo dará por inmundo: es llaga de lepra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, 'Empero si la mancha se estuviere en su lugar, y no se hubiere extendido en la piel, sino que está oscura, hinchazón es de la quemadura: darálo el sacerdote por limpio; que señal de la quemadura es.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, 'Y al hombre ó mujer que le saliere llaga en la cabeza, ó en la barba,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, 'El sacerdote mirará la llaga; y si pareciere estar más profunda que la tez, y el pelo en ella fuera rubio y adelgazado, entonces el sacerdote lo dará por inmundo: es tiña, es lepra de la cabeza ó de la barba.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, 'Mas cuando el sacerdote hubiere mirado la llaga de la tiña, y no pareciere estar más profunda que la tez, ni fuere en ella pelo negro, el sacerdote encerrará al llagado de la tiña por siete días:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, 'Y al séptimo día el sacerdote mirará la llaga: y si la tiña no pareciere haberse extendido, ni hubiere en ella pelo rubio, ni pareciere la tiña más profunda que la tez,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, 'Entonces lo trasquilarán, mas no trasquilarán el lugar de la tiña: y encerrará el sacerdote al que tiene la tiña por otros siete días.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, 'Y al séptimo día mirará el sacerdote la tiña; y si la tiña no hubiere cundido en la piel, ni pareciere estar más profunda que la tez, el sacerdote lo dará por limpio; y lavará sus vestidos, y será limpio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, 'Empero si la tiña se hubiere ido extendiendo en la piel después de su purificación,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, 'Entonces el sacerdote la mirará; y si la tiña hubiere cundido en la piel, no busque el sacerdote el pelo rubio, es inmundo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, 'Mas si le pareciere que la tiña está detenida, y que ha salido en ella el pelo negro, la tiña está sanada; él está limpio, y por limpio lo dará el sacerdote.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, 'Asimismo el hombre ó mujer, cuando en la piel de su carne tuviere manchas, manchas blancas,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, 'El sacerdote mirará: y si en la piel de su carne parecieren manchas blancas algo oscurecidas, es empeine que brotó en la piel, está limpia la persona.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, 'Y el hombre, cuando se le pelare la cabeza, es calvo, mas limpio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, 'Y si á la parte de su rostro se le pelare la cabeza, es calvo por delante, pero limpio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, 'Mas cuando en la calva ó en la antecalva hubiere llaga blanca rojiza, lepra es que brota en su calva ó en su antecalva.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, 'Entonces el sacerdote lo mirará, y si pareciere la hinchazón de la llaga blanca rojiza en su calva ó en su antecalva, como el parecer de la lepra de la tez de la carne,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, 'Leproso es, es inmundo; el sacerdote lo dará luego por inmundo; en su cabeza tiene su llaga.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, 'Y el leproso en quien hubiere llaga, sus vestidos serán deshechos y su cabeza descubierta, y embozado pregonará: ¡Inmundo! ¡inmundo!');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, 'Todo el tiempo que la llaga estuviere en él, será inmundo; estará impuro: habitará solo; fuera del real será su morada.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, 'Y cuando en el vestido hubiere plaga de lepra, en vestido de lana, ó en vestido de lino;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, 'O en estambre ó en trama, de lino ó de lana, ó en piel, ó en cualquiera obra de piel;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, 'Y que la plaga sea verde, ó bermeja, en vestido ó en piel, ó en estambre ó en trama, ó en cualquiera obra de piel; plaga es de lepra, y se ha de mostrar al sacerdote.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, 'Y el sacerdote mirará la plaga, y encerrará la cosa plagada por siete días.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, 'Y al séptimo día mirará la plaga: y si hubiere cundido la plaga en el vestido, ó estambre, ó en la trama, ó en piel, ó en cualquiera obra que se hace de pieles, lepra roedora es la plaga; inmunda será.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, 'Será quemado el vestido, ó estambre ó trama, de lana ó de lino, ó cualquiera obra de pieles en que hubiere tal plaga; porque lepra roedora es: al fuego será quemada.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, 'Y si el sacerdote mirare, y no pareciere que la plaga se haya extendido en el vestido, ó estambre, ó en la trama, ó en cualquiera obra de pieles;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, 'Entonces el sacerdote mandará que laven donde está la plaga, y lo encerrará otra vez por siete días.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, 'Y el sacerdote mirará después que la plaga fuere lavada; y si pareciere que la plaga no ha mudado su aspecto, bien que no haya cundido la plaga, inmunda es; la quemarás al fuego; corrosión es penetrante, esté lo raído en la haz ó en el revés de aquella cosa.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, 'Mas si el sacerdote la viere, y pareciere que la plaga se ha oscurecido después que fué lavada, la cortará del vestido, ó de la piel, ó del estambre, ó de la trama.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, 'Y si apareciere más en el vestido, ó estambre, ó trama, ó en cualquiera cosa de pieles, reverdeciendo en ella, quemarás al fuego aquello donde estuviere la plaga.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, 'Empero el vestido, ó estambre, ó trama, ó cualquiera cosa de piel que lavares, y que se le quitare la plaga, lavarse ha segunda vez, y entonces será limpia.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, 'Esta es la ley de la plaga de la lepra del vestido de lana ó de lino, ó del estambre, ó de la trama, ó de cualquiera cosa de piel, para que sea dada por limpia ó por inmunda.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, 'Y HABLÓ Jehová á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, 'Esta será la ley del leproso cuando se limpiare: Será traído al sacerdote:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, 'Y el sacerdote saldrá fuera del real; y mirará el sacerdote, y viendo que está sana la plaga de la lepra del leproso,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, 'El sacerdote mandará luego que se tomen para el que se purifica dos avecillas vivas, limpias, y palo de cedro, y grana, é hisopo;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, 'Y mandará el sacerdote matar la una avecilla en un vaso de barro sobre aguas vivas;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, 'Después tomará la avecilla viva, y el palo de cedro, y la grana, y el hisopo, y lo mojará con la avecilla viva en la sangre de la avecilla muerta sobre las aguas vivas:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, 'Y rociará siete veces sobre el que se purifica de la lepra, y le dará por limpio; y soltará la avecilla viva sobre la haz del campo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, 'Y el que se purifica lavará sus vestidos, y raerá todos sus pelos, y se ha de lavar con agua, y será limpio: y después entrará en el real, y morará fuera de su tienda siete días.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, 'Y será, que al séptimo día raerá todos sus pelos, su cabeza, y su barba, y las cejas de sus ojos; finalmente, raerá todo su pelo, y lavará sus vestidos, y lavará su carne en aguas, y será limpio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, 'Y el día octavo tomará dos corderos sin defecto, y una cordera de un año sin tacha; y tres décimas de flor de harina para presente, amasada con aceite, y un log de aceite.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, 'Y el sacerdote que le purifica presentará con aquellas cosas al que se ha de limpiar delante de Jehová, á la puerta del tabernáculo del testimonio:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, 'Y tomará el sacerdote el un cordero, y ofrecerálo por la culpa, con el log de aceite, y lo mecerá como ofrenda agitada delante de Jehová:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, 'Y degollará el cordero en el lugar donde degüellan la víctima por el pecado y el holocausto, en el lugar del santuario: porque como la víctima por el pecado, así también la víctima por la culpa es del sacerdote: es cosa muy sagrada.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, 'Y tomará el sacerdote de la sangre de la víctima por la culpa, y pondrá el sacerdote sobre la ternilla de la oreja derecha del que se purifica, y sobre el pulgar de su mano derecha, y sobre el pulgar de su pie derecho.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, 'Asimismo tomará el sacerdote del log de aceite, y echará sobre la palma de su mano izquierda:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, 'Y mojará su dedo derecho en el aceite que tiene en su mano izquierda, y esparcirá del aceite con su dedo siete veces delante de Jehová:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, 'Y de lo que quedare del aceite que tiene en su mano, pondrá el sacerdote sobre la ternilla de la oreja derecha del que se purifica, y sobre el pulgar de su mano derecha, y sobre el pulgar de su pie derecho, sobre la sangre de la expiación por la culpa:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, 'Y lo que quedare del aceite que tiene en su mano, pondrá sobre la cabeza del que se purifica: y hará el sacerdote expiación por él delante de Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, 'Ofrecerá luego el sacerdote el sacrificio por el pecado, y hará expiación por el que se ha de purificar de su inmundicia, y después degollará el holocausto:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, 'Y hará subir el sacerdote el holocausto y el presente sobre el altar. Así hará el sacerdote expiación por él, y será limpio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, 'Mas si fuere pobre, que no alcanzare su mano á tanto, entonces tomará un cordero para ser ofrecido como ofrenda agitada por la culpa, para reconciliarse, y una décima de flor de harina amasada con aceite para presente, y un log de aceite;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, 'Y dos tórtolas, ó dos palominos, lo que alcanzare su mano: y el uno será para expiación por el pecado, y el otro para holocausto;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, 'Las cuales cosas traerá al octavo día de su purificación al sacerdote, á la puerta del tabernáculo del testimonio delante de Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, 'Y el sacerdote tomará el cordero de la expiación por la culpa, y el log de aceite, y mecerálo el sacerdote como ofrenda agitada delante de Jehová;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, 'Luego degollará el cordero de la culpa, y tomará el sacerdote de la sangre de la culpa, y pondrá sobre la ternilla de la oreja derecha del que se purifica, y sobre el pulgar de su mano derecha, y sobre el pulgar de su pie derecho.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, 'Y el sacerdote echará del aceite sobre la palma de su mano izquierda;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, 'Y con su dedo derecho rociará el sacerdote del aceite que tiene en su mano izquierda, siete veces delante de Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, 'También pondrá el sacerdote del aceite que tiene en su mano sobre la ternilla de la oreja derecha del que se purifica, y sobre el pulgar de su mano derecha, y sobre el pulgar de su pie derecho, en el lugar de la sangre de la culpa.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, 'Y lo que sobrare del aceite que el sacerdote tiene en su mano, pondrálo sobre la cabeza del que se purifica, para reconciliarlo delante de Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, 'Asimismo ofrecerá la una de las tórtolas, ó de los palominos, lo que alcanzare su mano:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, 'El uno de lo que alcanzare su mano, en expiación por el pecado, y el otro en holocausto, además del presente: y hará el sacerdote expiación por el que se ha de purificar, delante de Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, 'Esta es la ley del que hubiere tenido plaga de lepra, cuya mano no alcanzare lo prescrito para purificarse.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, 'Y habló Jehová á Moisés y á Aarón, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, 'Cuando hubieres entrado en la tierra de Canaán, la cual yo os doy en posesión, y pusiere yo plaga de lepra en alguna casa de la tierra de vuestra posesión,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, 'Vendrá aquél cuya fuere la casa, y dará aviso al sacerdote, diciendo: Como plaga ha aparecido en mi casa.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, 'Entonces mandará el sacerdote, y despejarán la casa antes que el sacerdote entre á mirar la plaga, porque no sea contaminado todo lo que estuviere en la casa: y después el sacerdote entrará á reconocer la casa:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, 'Y mirará la plaga: y si se vieren manchas en las paredes de la casa, cavernillas verdosas ó rojas, las cuales parecieren más hundidas que la pared,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, 'El sacerdote saldrá de la casa á la puerta de ella, y cerrará la casa por siete días.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, 'Y al séptimo día volverá el sacerdote, y mirará: y si la plaga hubiere crecido en las paredes de la casa,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, 'Entonces mandará el sacerdote, y arrancarán las piedras en que estuviere la plaga, y las echarán fuera de la ciudad, en lugar inmundo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, 'Y hará descostrar la casa por dentro alrededor, y derramarán el polvo que descostraren, fuera de la ciudad en lugar inmundo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, 'Y tomarán otras piedras, y las pondrán en lugar de las piedras quitadas; y tomarán otro barro, y encostrarán la casa.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, 'Y si la plaga volviere á reverdecer en aquella casa, después que hizo arrancar las piedras, y descostrar la casa, y después que fué encostrada,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, 'Entonces el sacerdote entrará y mirará; y si pareciere haberse extendido la plaga en la casa, lepra roedora está en la casa: inmunda es.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, 'Derribará, por tanto, la tal casa, sus piedras, y sus maderos, y toda la mezcla de la casa; y lo sacará fuera de la ciudad á lugar inmundo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, 'Y cualquiera que entrare en aquella casa todos los días que la mandó cerrar, será inmundo hasta la tarde.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, 'Y el que durmiere en aquella casa, lavará sus vestidos; también el que comiere en la casa, lavará sus vestidos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, 'Mas si entrare el sacerdote y mirare, y viere que la plaga no se ha extendido en la casa después que fué encostrada, el sacerdote dará la casa por limpia, porque la plaga ha sanado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, 'Entonces tomará para limpiar la casa dos avecillas, y palo de cedro, y grana, é hisopo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, 'Y degollará la una avecilla en una vasija de barro sobre aguas vivas:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, 'Y tomará el palo de cedro, y el hisopo, y la grana, y la avecilla viva, y mojarálo en la sangre de la avecilla muerta y en las aguas vivas, y rociará la casa siete veces:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, 'Y purificará la casa con la sangre de la avecilla, y con las aguas vivas, y con la avecilla viva, y el palo de cedro, y el hisopo, y la grana:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, 'Luego soltará la avecilla viva fuera de la ciudad sobre la haz del campo: así hará expiación por la casa, y será limpia.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, 'Esta es la ley acerca de toda plaga de lepra, y de tiña;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, 'Y de la lepra del vestido, y de la casa;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, 'Y acerca de la hinchazón, y de la postilla, y de la mancha blanca:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, 'Para enseñar cuándo es inmundo, y cuándo limpio. Aquesta es la ley tocante á la lepra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, 'Y HABLÓ Jehová á Moisés y á Aarón, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, 'Hablad á los hijos de Israel, y decidles: Cualquier varón, cuando su simiente manare de su carne, será inmundo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, 'Y esta será su inmundicia en su flujo; sea que su carne destiló por causa de su flujo, ó que su carne se obstruyó á causa de su flujo, él será inmundo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, 'Toda cama en que se acostare el que tuviere flujo, será inmunda; y toda cosa sobre que se sentare, inmunda será.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, 'Y cualquiera que tocare á su cama, lavará sus vestidos; lavaráse también á sí mismo con agua, y será inmundo hasta la tarde.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, 'Y el que se sentare sobre aquello en que se hubiere sentado el que tiene flujo, lavará sus vestidos, se lavará también á sí mismo con agua, y será inmundo hasta la tarde.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, 'Asimismo el que tocare la carne del que tiene flujo, lavará sus vestidos, y á sí mismo se lavará con agua, y será inmundo hasta la tarde.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, 'Y si el que tiene flujo escupiere sobre el limpio, éste lavará sus vestidos, y después de haberse lavado con agua, será inmundo hasta la tarde.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, 'Y todo aparejo sobre que cabalgare el que tuviere flujo, será inmundo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, 'Y cualquiera que tocare cualquiera cosa que haya estado debajo de él, será inmundo hasta la tarde; y el que la llevare, lavará sus vestidos, y después de lavarse con agua, será inmundo hasta la tarde.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, 'Y todo aquel á quien tocare el que tiene flujo, y no lavare con agua sus manos, lavará sus vestidos, y á sí mismo se lavará con agua, y será inmundo hasta la tarde.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, 'Y la vasija de barro en que tocare el que tiene flujo, será quebrada; y toda vasija de madera será lavada con agua.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, 'Y cuando se hubiere limpiado de su flujo el que tiene flujo, se ha de contar siete días desde su purificación, y lavará sus vestidos, y lavará su carne en aguas vivas, y será limpio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, 'Y el octavo día tomará dos tórtolas, ó dos palominos, y vendrá delante de Jehová á la puerta del tabernáculo del testimonio, y los dará al sacerdote:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, 'Y harálos el sacerdote, el uno ofrenda por el pecado, y el otro holocausto: y le purificará el sacerdote de su flujo delante de Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, 'Y el hombre, cuando de él saliere derramamiento de semen, lavará en aguas toda su carne, y será inmundo hasta la tarde.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, 'Y toda vestimenta, ó toda piel sobre la cual hubiere el derramamiento del semen, lavaráse con agua, y será inmunda hasta la tarde.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, 'Y la mujer con quien el varón tuviera ayuntamiento de semen, ambos se lavarán con agua, y serán inmundos hasta la tarde.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, 'Y cuando la mujer tuviere flujo de sangre, y su flujo fuere en su carne, siete días estará apartada; y cualquiera que tocare en ella, será inmundo hasta la tarde.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, 'Y todo aquello sobre que ella se acostare mientras su separación, será inmundo: también todo aquello sobre que se sentare, será inmundo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, 'Y cualquiera que tocare á su cama, lavará sus vestidos, y después de lavarse con agua, será inmundo hasta la tarde.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, 'También cualquiera que tocare cualquier mueble sobre que ella se hubiere sentado, lavará sus vestidos; lavaráse luego á sí mismo con agua, y será inmundo hasta la tarde.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, 'Y si estuviere sobre la cama, ó sobre la silla en que ella se hubiere sentado, el que tocare en ella será inmundo hasta la tarde.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, 'Y si alguno durmiere con ella, y su menstruo fuere sobre él, será inmundo por siete días; y toda cama sobre que durmiere, será inmunda.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, 'Y la mujer, cuando siguiere el flujo de su sangre por muchos días fuera del tiempo de su costumbre, ó cuando tuviere flujo de sangre más de su costumbre; todo el tiempo del flujo de su inmundicia, será inmunda como en los días de su costumbre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, 'Toda cama en que durmiere todo el tiempo de su flujo, le será como la cama de su costumbre; y todo mueble sobre que se sentare, será inmundo, como la inmundicia de su costumbre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, 'Cualquiera que tocare en esas cosas será inmundo; y lavará sus vestidos, y á sí mismo se lavará con agua, y será inmundo hasta la tarde.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, 'Y cuando fuere libre de su flujo, se ha de contar siete días, y después será limpia.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, 'Y el octavo día tomará consigo dos tórtolas, ó dos palominos, y los traerá al sacerdote, á la puerta del tabernáculo del testimonio:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, 'Y el sacerdote hará el uno ofrenda por el pecado, y el otro holocausto; y la purificará el sacerdote delante de Jehová del flujo de su inmundicia.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, 'Así apartaréis los hijos de Israel de sus inmundicias, á fin de que no mueran por sus inmundicias, ensuciando mi tabernáculo que está entre ellos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, 'Esta es la ley del que tiene flujo, y del que sale derramamiento de semen, viniendo á ser inmundo á causa de ello;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, 'Y de la que padece su costumbre, y acerca del que tuviere flujo, sea varón ó hembra, y del hombre que durmiere con mujer inmunda.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, 'Y HABLÓ Jehová á Moisés, después que murieron los dos hijos de Aarón, cuando se llegaron delante de Jehová, y murieron;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, 'Y Jehová dijo á Moisés: Di á Aarón tu hermano, que no en todo tiempo entre en el santuario del velo adentro, delante de la cubierta que está sobre el arca, para que no muera: porque yo apareceré en la nube sobre la cubierta.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, 'Con esto entrará Aarón en el santuario: con un becerro por expiación, y un carnero en holocausto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, 'La túnica santa de lino se vestirá, y sobre su carne tendrá pañetes de lino, y ceñiráse el cinto de lino; y con la mitra de lino se cubrirá: son las santas vestiduras: con ellas, después de lavar su carne con agua, se ha de vestir.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, 'Y de la congregación de los hijos de Israel tomará dos machos de cabrío para expiación, y un carnero para holocausto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, 'Y hará allegar Aarón el becerro de la expiación, que es suyo, y hará la reconciliación por sí y por su casa.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, 'Después tomará los dos machos de cabrío, y los presentará delante de Jehová á la puerta del tabernáculo del testimonio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, 'Y echará suertes Aarón sobre los dos machos de cabrío; la una suerte por Jehová, y la otra suerte por Azazel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, 'Y hará allegar Aarón el macho cabrío sobre el cual cayere la suerte por Jehová, y ofrecerálo en expiación.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, 'Mas el macho cabrío, sobre el cual cayere la suerte por Azazel, lo presentará vivo delante de Jehová, para hacer la reconciliación sobre él, para enviarlo á Azazel al desierto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, 'Y hará llegar Aarón el becerro que era suyo para expiación, y hará la reconciliación por sí y por su casa, y degollará en expiación el becerro que es suyo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, 'Después tomará el incensario lleno de brasas de fuego, del altar de delante de Jehová, y sus puños llenos del perfume aromático molido, y meterálo del velo adentro:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, 'Y pondrá el perfume sobre el fuego delante de Jehová, y la nube del perfume cubrirá la cubierta que está sobre el testimonio, y no morirá.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, 'Tomará luego de la sangre del becerro, y rociará con su dedo hacia la cubierta al lado oriental: hacia la cubierta esparcirá siete veces de aquella sangre con su dedo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, 'Después degollará en expiación el macho cabrío, que era del pueblo, y meterá la sangre de él del velo adentro; y hará de su sangre como hizo de la sangre del becerro, y esparcirá sobre la cubierta y delante de la cubierta:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, 'Y limpiará el santuario, de las inmundicias de los hijos de Israel, y de sus rebeliones, y de todos sus pecados: de la misma manera hará también al tabernáculo del testimonio, el cual reside entre ellos en medio de sus inmundicias.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, 'Y ningún hombre estará en el tabernáculo del testimonio cuando él entrare á hacer la reconciliación en el santuario, hasta que él salga, y haya hecho la reconciliación por sí, y por su casa, y por toda la congregación de Israel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, 'Y saldrá al altar que está delante de Jehová, y lo expiará; y tomará de la sangre del becerro, y de la sangre del macho cabrío, y pondrá sobre los cuernos del altar alrededor.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, 'Y esparcirá sobre él de la sangre con su dedo siete veces, y lo limpiará, y lo santificará de las inmundicias de los hijos de Israel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, 'Y cuando hubiere acabado de expiar el santuario, y el tabernáculo del testimonio, y el altar, hará llegar el macho cabrío vivo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, 'Y pondrá Aarón ambas manos suyas sobre la cabeza del macho cabrío vivo, y confesará sobre él todas las iniquidades de los hijos de Israel, y todas sus rebeliones, y todos sus pecados, poniéndolos así sobre la cabeza del macho cabrío, y lo enviará al desierto por mano de un hombre destinado para esto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, 'Y aquel macho cabrío llevará sobre sí todas las iniquidades de ellos á tierra inhabitada: y dejará ir el macho cabrío por el desierto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, 'Después vendrá Aarón al tabernáculo del testimonio, y se desnudará las vestimentas de lino, que había vestido para entrar en el santuario, y pondrálas allí.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, 'Lavará luego su carne con agua en el lugar del santuario, y después de ponerse sus vestidos saldrá, y hará su holocausto, y el holocausto del pueblo, y hará la reconciliación por sí y por el pueblo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, 'Y quemará el sebo de la expiación sobre el altar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, 'Y el que hubiere llevado el macho cabrío á Azazel, lavará sus vestidos, lavará también con agua su carne, y después entrará en el real.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, 'Y sacará fuera del real el becerro del pecado, y el macho cabrío de la culpa, la sangre de los cuales fué metida para hacer la expiación en el santuario; y quemarán en el fuego sus pellejos, y sus carnes, y su estiércol.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, 'Y el que los quemare, lavará sus vestidos, lavará también su carne con agua, y después entrará en el real.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, 'Y esto tendréis por estatuto perpetuo: En el mes séptimo, á los diez del mes, afligiréis vuestras almas, y ninguna obra haréis, ni el natural ni el extranjero que peregrina entre vosotros:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, 'Porque en este día se os reconciliará para limpiaros; y seréis limpios de todos vuestros pecados delante de Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, 'Sábado de reposo es para vosotros, y afligiréis vuestras almas, por estatuto perpetuo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, 'Y hará la reconciliación el sacerdote que fuere ungido, y cuya mano hubiere sido llena para ser sacerdote en lugar de su padre; y se vestirá las vestimentas de lino, las vestiduras sagradas:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, 'Y expiará el santuario santo, y el tabernáculo del testimonio; expiará también el altar, y á los sacerdotes, y á todo el pueblo de la congregación.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, 'Y esto tendréis por estatuto perpetuo, para expiar á los hijos de Israel de todos sus pecados una vez en el año. Y Moisés lo hizo como Jehová le mandó.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, 'Y HABLÓ Jehová á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, 'Habla á Aarón y á sus hijos, y á todos los hijos de Israel, y diles: Esto es lo que ha mandado Jehová, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, 'Cualquier varón de la casa de Israel que degollare buey, ó cordero, ó cabra, en el real, ó fuera del real,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, 'Y no lo trajere á la puerta del tabernáculo del testimonio, para ofrecer ofrenda á Jehová delante del tabernáculo de Jehová, sangre será imputada al tal varón: sangre derramó; cortado será el tal varón de entre su pueblo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, 'A fin de que traigan los hijos de Israel sus sacrificios, los que sacrifican sobre la haz del campo, para que los traigan á Jehová á la puerta del tabernáculo del testimonio al sacerdote, y sacrifiquen ellos sacrificios de paces á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, 'Y el sacerdote esparcirá la sangre sobre el altar de Jehová, á la puerta del tabernáculo del testimonio, y quemará el sebo en olor de suavidad á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, 'Y nunca más sacrificarán sus sacrificios á los demonios, tras de los cuales han fornicado: tendrán esto por estatuto perpetuo por sus edades.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, 'Les dirás también: Cualquier varón de la casa de Israel, ó de los extranjeros que peregrinan entre vosotros, que ofreciere holocausto ó sacrificio,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, 'Y no lo trajere á la puerta del tabernáculo del testimonio, para hacerlo á Jehová, el tal varón será igualmente cortado de sus pueblos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, 'Y cualquier varón de la casa de Israel, ó de los extranjeros que peregrinan entre ellos, que comiere alguna sangre, yo pondré mi rostro contra la persona que comiere sangre, y le cortaré de entre su pueblo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, 'Porque la vida de la carne en la sangre está: y yo os la he dado para expiar vuestras personas sobre el altar: por lo cual la misma sangre expiará la persona.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, 'Por tanto, he dicho á los hijos de Israel: Ninguna persona de vosotros comerá sangre, ni el extranjero que peregrina entre vosotros comerá sangre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, 'Y cualquier varón de los hijos de Israel, ó de los extranjeros que peregrinan entre ellos, que cogiere caza de animal ó de ave que sea de comer, derramará su sangre y cubrirála con tierra:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, 'Porque el alma de toda carne, su vida, está en su sangre: por tanto he dicho á los hijos de Israel: No comeréis la sangre de ninguna carne, porque la vida de toda carne es su sangre: cualquiera que la comiere será cortado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, 'Y cualquiera persona que comiere cosa mortecina, ó despedazada por fiera, así de los naturales como de los extranjeros, lavará sus vestidos y á sí mismo se lavará con agua, y será inmundo hasta la tarde; y se limpiará.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, 'Y si no los lavare, ni lavare su carne, llevará su iniquidad.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, 'Y HABLÓ Jehová á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, 'Habla á los hijos de Israel, y diles: Yo soy Jehová vuestro Dios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, 'No haréis como hacen en la tierra de Egipto, en la cual morasteis; ni haréis como hacen en la tierra de Canaán, á la cual yo os conduzco; ni andaréis en sus estatutos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, 'Mis derechos pondréis por obra, y mis estatutos guardaréis, andando en ellos: Yo Jehová vuestro Dios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, 'Por tanto mis estatutos y mis derechos guardaréis, los cuales haciendo el hombre, vivirá en ellos: Yo Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, 'Ningún varón se allegue á ninguna cercana de su carne, para descubrir su desnudez: Yo Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, 'La desnudez de tu padre, ó la desnudez de tu madre, no descubrirás: tu madre es, no descubrirás su desnudez.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, 'La desnudez de la mujer de tu padre no descubrirás; es la desnudez de tu padre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, 'La desnudez de tu hermana, hija de tu padre, ó hija de tu madre, nacida en casa ó nacida fuera, su desnudez no descubrirás.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, 'La desnudez de la hija de tu hijo, ó de la hija de tu hija, su desnudez no descubrirás, porque es la desnudez tuya.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, 'La desnudez de la hija de la mujer de tu padre, engendrada de tu padre, tu hermana es, su desnudez no descubrirás.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, 'La desnudez de la hermana de tu padre no descubrirás: es parienta de tu padre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, 'La desnudez de la hermana de tu madre no descubrirás: porque parienta de tu madre es.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, 'La desnudez del hermano de tu padre no descubrirás: no llegarás á su mujer: es mujer del hermano de tu padre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, 'La desnudez de tu nuera no descubrirás: mujer es de tu hijo; no descubrirás su desnudez.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, 'La desnudez de la mujer de tu hermano no descubrirás: es la desnudez de tu hermano.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, 'La desnudez de la mujer y de su hija no descubrirás: no tomarás la hija de su hijo, ni la hija de su hija, para descubrir su desnudez: son parientas, es maldad.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, 'No tomarás mujer juntamente con su hermana, para hacerla su rival, descubriendo su desnudez delante de ella en su vida.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, 'Y no llegarás á la mujer en el apartamiento de su inmundicia, para descubrir su desnudez.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, 'Además, no tendrás acto carnal con la mujer de tu prójimo, contaminándote en ella.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, 'Y no des de tu simiente para hacerla pasar por el fuego á Moloch; no contamines el nombre de tu Dios: Yo Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, 'No te echarás con varón como con mujer: es abominación.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, 'Ni con ningún animal tendrás ayuntamiento amancillándote con él; ni mujer alguna se pondrá delante de animal para ayuntarse con él: es confusión.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, 'En ninguna de estas cosas os amancillaréis; porque en todas estas cosas se han ensuciado las gentes que yo echo de delante de vosotros:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, 'Y la tierra fué contaminada; y yo visité su maldad sobre ella, y la tierra vomitó sus moradores.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, 'Guardad, pues, vosotros mis estatutos y mis derechos, y no hagáis ninguna de todas estas abominaciones: ni el natural ni el extranjero que peregrina entre vosotros.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, '(Porque todas estas abominaciones hicieron los hombres de la tierra, que fueron antes de vosotros, y la tierra fué contaminada:)');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, 'Y la tierra no os vomitará, por haberla contaminado, como vomitó á la gente que fué antes de vosotros.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, 'Porque cualquiera que hiciere alguna de todas estas abominaciones, las personas que las hicieren, serán cortadas de entre su pueblo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, 'Guardad, pues, mi ordenanza, no haciendo de las prácticas abominables que tuvieron lugar antes de vosotros, y no os ensuciéis en ellas: Yo Jehová vuestro Dios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, 'Y HABLÓ Jehová á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, 'Habla á toda la congregación de los hijos de Israel, y diles: Santos seréis, porque santo soy yo Jehová vuestro Dios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, 'Cada uno temerá á su madre y á su padre, y mis sábados guardaréis: Yo Jehová vuestro Dios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, 'No os volveréis á los ídolos, ni haréis para vosotros dioses de fundición: Yo Jehová vuestro Dios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, 'Y cuando sacrificareis sacrificio de paces á Jehová, de vuestra voluntad lo sacrificaréis.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, 'Será comido el día que lo sacrificareis, y el siguiente día: y lo que quedare para el tercer día, será quemado en el fuego.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, 'Y si se comiere el día tercero, será abominación; no será acepto:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, 'Y el que lo comiere, llevará su delito, por cuanto profanó lo santo de Jehová; y la tal persona será cortada de sus pueblos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, 'Cuando segareis la mies de vuestra tierra, no acabarás de segar el rincón de tu haza, ni espigarás tu tierra segada.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, 'Y no rebuscarás tu viña, ni recogerás los granos caídos de tu viña; para el pobre y para el extranjero los dejarás: Yo Jehová vuestro Dios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, 'No hurtaréis, y no engañaréis, ni mentiréis ninguno á su prójimo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, 'Y no juraréis en mi nombre con mentira, ni profanarás el nombre de tu Dios: Yo Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, 'No oprimirás á tu prójimo, ni le robarás. No se detendrá el trabajo del jornalero en tu casa hasta la mañana.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, 'No maldigas al sordo, y delante del ciego no pongas tropiezo, mas tendrás temor de tu Dios: Yo Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, 'No harás agravio en el juicio: no tendrás respeto al pobre, ni honrarás la cara del grande: con justicia juzgarás á tu prójimo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, 'No andarás chismeando en tus pueblos. No te pondrás contra la sangre de tu prójimo: Yo Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, 'No aborrecerás á tu hermano en tu corazón: ingenuamente reprenderás á tu prójimo, y no consentirás sobre él pecado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, 'No te vengarás, ni guardarás rencor á los hijos de tu pueblo: mas amarás á tu prójimo como á ti mismo: Yo Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, 'Mis estatutos guardaréis. A tu animal no harás ayuntar para misturas; tu haza no sembrarás con mistura de semillas, y no te pondrás vestidos con mezcla de diversas cosas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, 'Y cuando un hombre tuviere cópula con mujer, y ella fuere sierva desposada con alguno, y no estuviere rescatada, ni le hubiere sido dada libertad, ambos serán azotados: no morirán, por cuanto ella no es libre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, 'Y él traerá á Jehová, á la puerta del tabernáculo del testimonio, un carnero en expiación por su culpa.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, 'Y con el carnero de la expiación lo reconciliará el sacerdote delante de Jehová, por su pecado que cometió: y se le perdonará su pecado que ha cometido.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, 'Y cuando hubiereis entrado en la tierra, y plantareis todo árbol de comer, quitaréis su prepucio, lo primero de su fruto: tres años os será incircunciso: su fruto no se comerá.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, 'Y el cuarto año todo su fruto será santidad de loores á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, 'Mas al quinto año comeréis el fruto de él, para que os haga crecer su fruto: Yo Jehová vuestro Dios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, 'No comeréis cosa alguna con sangre. No seréis agoreros, ni adivinaréis.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, 'No cortaréis en redondo las extremidades de vuestras cabezas, ni dañarás la punta de tu barba.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, 'Y no haréis rasguños en vuestra carne por un muerto, ni imprimiréis en vosotros señal alguna: Yo Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, 'No contaminarás tu hija haciéndola fornicar: porque no se prostituya la tierra, y se hincha de maldad.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, 'Mis sábados guardaréis, y mi santuario tendréis en reverencia: Yo Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, 'No os volváis á los encantadores y á los adivinos: no los consultéis ensuciándoos con ellos: Yo Jehová vuestro Dios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, 'Delante de las canas te levantarás, y honrarás el rostro del anciano, y de tu Dios tendrás temor: Yo Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, 'Y cuando el extranjero morare contigo en vuestra tierra, no le oprimiréis.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, 'Como á un natural de vosotros tendréis al extranjero que peregrinare entre vosotros; y ámalo como á ti mismo; porque peregrinos fuisteis en la tierra de Egipto: Yo Jehová vuestro Dios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, 'No hagáis agravio en juicio, en medida de tierra, ni en peso, ni en otra medida.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, 'Balanzas justas, pesas justas, epha justo, é hin justo tendréis: Yo Jehová vuestro Dios, que os saqué de la tierra de Egipto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, 'Guardad pues todos mis estatutos, y todos mis derechos, y ponedlos por obra: Yo Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, 'Y HABLÓ Jehová á Moisés diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, 'Dirás asimismo á los hijos de Israel: Cualquier varón de los hijos de Israel, ó de los extranjeros que peregrinan en Israel, que diere de su simiente á Moloch, de seguro morirá: el pueblo de la tierra lo apedreará con piedras.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, 'Y yo pondré mi rostro contra el tal varón, y lo cortaré de entre su pueblo; por cuanto dió de su simiente á Moloch, contaminando mi santuario, y amancillando mi santo nombre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, 'Que si escondiere el pueblo de la tierra sus ojos de aquel varón que hubiere dado de su simiente á Moloch, para no matarle,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, 'Entonces yo pondré mi rostro contra aquel varón, y contra su familia, y le cortaré de entre su pueblo, con todos los que fornicaron en pos de él, prostituyéndose con Moloch.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, 'Y la persona que atendiere á encantadores ó adivinos, para prostituirse tras de ellos, yo pondré mi rostro contra la tal persona, y cortaréla de entre su pueblo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, 'Santificaos, pues, y sed santos, porque yo Jehová soy vuestro Dios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, 'Y guardad mis estatutos, y ponedlos por obra: Yo Jehová que os santifico.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, 'Porque varón que maldijere á su padre ó á su madre, de cierto morirá: á su padre ó á su madre maldijo; su sangre será sobre él.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, 'Y el hombre que adulterare con la mujer de otro, el que cometiere adulterio con la mujer de su prójimo, indefectiblemente se hará morir al adúltero y á la adúltera.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, 'Y cualquiera que se echare con la mujer de su padre, la desnudez de su padre descubrió: ambos han de ser muertos; su sangre será sobre ellos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, 'Y cualquiera que durmiere con su nuera, ambos han de morir: hicieron confusión; su sangre será sobre ellos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, 'Y cualquiera que tuviere ayuntamiento con varón como con mujer, abominación hicieron: entrambos han de ser muertos; sobre ellos será su sangre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, 'Y el que tomare mujer y á la madre de ella, comete vileza: quemarán en fuego á él y á ellas, porque no haya vileza entre vosotros.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, 'Y cualquiera que tuviere cópula con bestia, ha de ser muerto; y mataréis á la bestia.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, 'Y la mujer que se allegare á algún animal, para tener ayuntamiento con él, á la mujer y al animal matarás: morirán infaliblemente; será su sangre sobre ellos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, 'Y cualquiera que tomare á su hermana, hija de su padre ó hija de su madre, y viere su desnudez, y ella viere la suya, cosa es execrable; por tanto serán muertos á ojos de los hijos de su pueblo: descubrió la desnudez de su hermana; su pecado llevará.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, 'Y cualquiera que durmiere con mujer menstruosa, y descubriere su desnudez, su fuente descubrió, y ella descubrió la fuente de su sangre: ambos serán cortados de entre su pueblo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, 'La desnudez de la hermana de tu madre, ó de la hermana de tu padre, no descubrirás: por cuanto descubrió su parienta, su iniquidad llevarán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, 'Y cualquiera que durmiere con la mujer del hermano de su padre, la desnudez del hermano de su padre descubrió; su pecado llevarán; morirán sin hijos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, 'Y el que tomare la mujer de su hermano, es suciedad; la desnudez de su hermano descubrió; sin hijos serán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, 'Guardad, pues, todos mis estatutos y todos mis derechos, y ponedlos por obra: y no os vomitará la tierra, en la cual yo os introduzco para que habitéis en ella.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, 'Y no andéis en las prácticas de la gente que yo echaré de delante de vosotros: porque ellos hicieron todas estas cosas, y los tuve en abominación.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, 'Empero á vosotros os he dicho: Vosotros poseeréis la tierra de ellos, y yo os la daré para que la poseáis por heredad, tierra que fluye leche y miel: Yo Jehová vuestro Dios, que os he apartado de los pueblos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, 'Por tanto, vosotros haréis diferencia entre animal limpio é inmundo, y entre ave inmunda y limpia: y no ensuciéis vuestras personas en los animales, ni en las aves, ni en ninguna cosa que va arrastrando por la tierra, las cuales os he apartado por inmundas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, 'Habéis, pues, de serme santos, porque yo Jehová soy santo, y os he apartado de los pueblos, para que seáis míos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, 'Y el hombre ó la mujer en quienes hubiere espíritu pithónico ó de adivinación, han de ser muertos: los apedrearán con piedras; su sangre sobre ellos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, 'Y JEHOVÁ dijo á Moisés: Habla á los sacerdotes hijos de Aarón, y diles que no se contaminen por un muerto en sus pueblos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, 'Mas por su pariente cercano á sí, por su madre, ó por su padre, ó por su hijo, ó por su hermano,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, 'O por su hermana virgen, á él cercana, la cual no haya tenido marido, por ella se contaminará.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, 'No se contaminará, porque es príncipe en sus pueblos, haciéndose inmundo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, 'No harán calva en su cabeza, ni raerán la punta de su barba, ni en su carne harán rasguños.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, 'Santos serán á su Dios, y no profanarán el nombre de su Dios; porque los fuegos de Jehová y el pan de su Dios ofrecen: por tanto serán santos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, 'Mujer ramera ó infame no tomarán: ni tomarán mujer repudiada de su marido: porque es santo á su Dios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, 'Lo santificarás por tanto, pues el pan de tu Dios ofrece: santo será para ti, porque santo soy yo Jehová vuestro santificador.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, 'Y la hija del varón sacerdote, si comenzare á fornicar, á su padre amancilla: quemada será al fuego.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, 'Y el sumo sacerdote entre sus hermanos, sobre cuya cabeza fué derramado el aceite de la unción, y que hinchió su mano para vestir las vestimentas, no descubrirá su cabeza, ni romperá sus vestidos:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, 'Ni entrará donde haya alguna persona muerta, ni por su padre, ó por su madre se contaminará.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, 'Ni saldrá del santuario, ni contaminará el santuario de su Dios; porque la corona del aceite de la unción de su Dios está sobre él: Yo Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, 'Y tomará él mujer con su virginidad.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, 'Viuda, ó repudiada, ó infame, ó ramera, éstas no tomará: mas tomará virgen de sus pueblos por mujer.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, 'Y no amancillará su simiente en sus pueblos; porque yo Jehová soy el que los santifico.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, 'Y Jehová habló á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, 'Habla á Aarón, y dile: El varón de tu simiente en sus generaciones, en el cual hubiere falta, no se allegará para ofrecer el pan de su Dios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, 'Porque ningún varón en el cual hubiere falta, se allegará: varón ciego, ó cojo, ó falto, ó sobrado,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, 'O varón en el cual hubiere quebradura de pie ó rotura de mano,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, 'O corcovado, ó lagañoso, ó que tuviere nube en el ojo, ó que tenga sarna, ó empeine, ó compañón relajado;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, 'Ningún varón de la simiente de Aarón sacerdote, en el cual hubiere falta, se allegará para ofrecer las ofrendas encendidas de Jehová. Hay falta en él; no se allegará á ofrecer el pan de su Dios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, 'El pan de su Dios, de lo muy santo y las cosas santificadas, comerá.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, 'Empero no entrará del velo adentro, ni se allegará al altar, por cuanto hay falta en él: y no profanará mi santuario, porque yo Jehová soy el que los santifico.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, 'Y Moisés habló esto á Aarón, y á sus hijos, y á todos los hijos de Israel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, 'Y HABLÓ Jehová á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, 'Di á Aarón y á sus hijos, que se abstengan de las santificaciones de los hijos de Israel, y que no profanen mi santo nombre en lo que ellos me santifican: Yo Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, 'Diles: Todo varón de toda vuestra simiente en vuestras generaciones que llegare á las cosas sagradas, que los hijos de Israel consagran á Jehová, teniendo inmundicia sobre sí, de delante de mí será cortada su alma: Yo Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, 'Cualquier varón de la simiente de Aarón que fuere leproso, ó padeciere flujo, no comerá de las cosas sagradas hasta que esté limpio: y el que tocare cualquiera cosa inmunda de mortecino, ó el varón del cual hubiere salido derramamiento de semen;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, 'O el varón que hubiere tocado cualquier reptil, por el cual será inmundo, ú hombre por el cual venga á ser inmundo, conforme á cualquiera inmundicia suya;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, 'La persona que lo tocare, será inmunda hasta la tarde, y no comerá de las cosas sagradas antes que haya lavado su carne con agua.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, 'Y cuando el sol se pusiere, será limpio; y después comerá las cosas sagradas, porque su pan es.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, 'Mortecino ni despedazado por fiera no comerá, para contaminarse en ello: Yo Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, 'Guarden, pues, mi ordenanza, y no lleven pecado por ello, no sea que así mueran cuando la profanaren: Yo Jehová que los santifico.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, 'Ningún extraño comerá cosa sagrada; el huésped del sacerdote, ni el jornalero, no comerá cosa sagrada.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, 'Mas el sacerdote, cuando comprare persona de su dinero, ésta comerá de ella, y el nacido en su casa: éstos comerán de su pan.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, 'Empero la hija del sacerdote, cuando se casare con varón extraño, ella no comerá de la ofrenda de las cosas sagradas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, 'Pero si la hija del sacerdote fuere viuda, ó repudiada, y no tuviere prole, y se hubiere vuelto á la casa de su padre, como en su mocedad, comerá del pan de su padre; mas ningún extraño coma de él.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, 'Y el que por yerro comiere cosa sagrada, añadirá á ella su quinto, y darálo al sacerdote con la cosa sagrada.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, 'No profanarán, pues, las cosas santas de los hijos de Israel, las cuales apartan para Jehová:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, 'Y no les harán llevar la iniquidad del pecado, comiendo las cosas santas de ellos: porque yo Jehová soy el que los santifico.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, 'Y habló Jehová á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, 'Habla á Aarón y á sus hijos, y á todos los hijos de Israel, y diles: Cualquier varón de la casa de Israel, ó de los extranjeros en Israel, que ofreciere su ofrenda por todos sus votos, y por todas sus voluntarias oblaciones que ofrecieren á Jehová en holocausto;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, 'De vuestra voluntad ofreceréis macho sin defecto de entre las vacas, de entre los corderos, ó de entre las cabras.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, 'Ninguna cosa en que haya falta ofreceréis, porque no será acepto por vosotros.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, 'Asimismo, cuando alguno ofreciere sacrificio de paces á Jehová para presentar voto, ú ofreciendo voluntariamente, sea de vacas ó de ovejas, sin tacha será acepto; no ha de haber en él falta.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, 'Ciego, ó perniquebrado, ó mutilado, ó verrugoso, ó sarnoso, ó roñoso, no ofreceréis éstos á Jehová, ni de ellos pondréis ofrenda encendida sobre el altar de Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, 'Buey ó carnero que tenga de más ó de menos, podrás ofrecer por ofrenda voluntaria; mas por voto no será acepto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, 'Herido ó magullado, rompido ó cortado, no ofreceréis á Jehová, ni en vuestra tierra lo haréis.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, 'Y de mano de hijo de extranjero no ofreceréis el pan de vuestro Dios de todas estas cosas; porque su corrupción está en ellas: hay en ellas falta, no se os aceptarán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, 'Y habló Jehová á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, 'El buey, ó el cordero, ó la cabra, cuando naciere, siete días estará mamando de su madre: mas desde el octavo día en adelante será acepto para ofrenda de sacrificio encendido á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, 'Y sea buey ó carnero, no degollaréis en un día á él y á su hijo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, 'Y cuando sacrificareis sacrificio de hacimiento de gracias á Jehová, de vuestra voluntad lo sacrificaréis.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, 'En el mismo día se comerá; no dejaréis de él para otro día: Yo Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, 'Guardad pues mis mandamientos, y ejecutadlos: Yo Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, 'Y no amancilléis mi santo nombre, y yo me santificaré en medio de los hijos de Israel: Yo Jehová que os santifico;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, 'Que os saqué de la tierra de Egipto, para ser vuestro Dios: Yo Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, 'Y HABLÓ Jehová á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, 'Habla á los hijos de Israel, y diles: Las solemnidades de Jehová, las cuales proclamaréis santas convocaciones, aquestas serán mis solemnidades.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, 'Seis días se trabajará, y el séptimo día sábado de reposo será, convocación santa: ninguna obra haréis; sábado es de Jehová en todas vuestras habitaciones.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, 'Estas son las solemnidades de Jehová, las convocaciones santas, á las cuales convocaréis en sus tiempos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, 'En el mes primero, á los catorce del mes, entre las dos tardes, pascua es de Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, 'Y á los quince días de este mes es la solemnidad de los ázimos á Jehová: siete días comeréis ázimos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, 'El primer día tendréis santa convocación: ninguna obra servil haréis.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, 'Y ofreceréis á Jehová siete días ofrenda encendida: el séptimo día será santa convocación; ninguna obra servil haréis.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, 'Y habló Jehová á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, 'Habla á los hijos de Israel, y diles: Cuando hubiereis entrado en la tierra que yo os doy, y segareis su mies, traeréis al sacerdote un omer por primicia de los primeros frutos de vuestra siega;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, 'El cual mecerá el omer delante de Jehová, para que seáis aceptos: el siguiente día del sábado lo mecerá el sacerdote.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, 'Y el día que ofrezcáis el omer, ofreceréis un cordero de un año, sin defecto, en holocausto á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, 'Y su presente será dos décimas de flor de harina amasada con aceite, ofrenda encendida á Jehová en olor suavísimo; y su libación de vino, la cuarta parte de un hin.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, 'Y no comeréis pan, ni grano tostado, ni espiga fresca, hasta este mismo día, hasta que hayáis ofrecido la ofrenda de vuestro Dios; estatuto perpetuo es por vuestras edades en todas vuestras habitaciones.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, 'Y os habéis de contar desde el siguiente día del sábado, desde el día en que ofrecisteis el omer de la ofrenda mecida; siete semanas cumplidas serán:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, 'Hasta el siguiente día del sábado séptimo contaréis cincuenta días; entonces ofreceréis nuevo presente á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, 'De vuestras habitaciones traeréis dos panes para ofrenda mecida, que serán de dos décimas de flor de harina, cocidos con levadura, por primicias á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, 'Y ofreceréis con el pan siete corderos de un año sin defecto, y un becerro de la vacada y dos carneros: serán holocausto á Jehová, con su presente y sus libaciones; ofrenda encendida de suave olor á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, 'Ofreceréis además un macho de cabrío por expiación; y dos corderos de un año en sacrificio de paces.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, 'Y el sacerdote los mecerá en ofrenda agitada delante de Jehová, con el pan de las primicias, y los dos corderos: serán cosa sagrada de Jehová para el sacerdote.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, 'Y convocaréis en este mismo día; os será santa convocación: ninguna obra servil haréis: estatuto perpetuo en todas vuestras habitaciones por vuestras edades.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, 'Y cuando segareis la mies de vuestra tierra, no acabarás de segar el rincón de tu haza, ni espigarás tu siega; para el pobre, y para el extranjero la dejarás: Yo Jehová vuestro Dios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, 'Y habló Jehová á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, 'Habla á los hijos de Israel, y diles: En el mes séptimo, al primero del mes tendréis sábado, una conmemoración al son de trompetas, y una santa convocación.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, 'Ninguna obra servil haréis; y ofreceréis ofrenda encendida á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, 'Y habló Jehová á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, 'Empero á los diez de este mes séptimo será el día de las expiaciones: tendréis santa convocación, y afligiréis vuestras almas, y ofreceréis ofrenda encendida á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, 'Ninguna obra haréis en este mismo día; porque es día de expiaciones, para reconciliaros delante de Jehová vuestro Dios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, 'Porque toda persona que no se afligiere en este mismo día, será cortada de sus pueblos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, 'Y cualquiera persona que hiciere obra alguna en este mismo día, yo destruiré la tal persona de entre su pueblo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, 'Ninguna obra haréis: estatuto perpetuo es por vuestras edades en todas vuestras habitaciones.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, 'Sábado de reposo será á vosotros, y afligiréis vuestras almas, comenzando á los nueve del mes en la tarde: de tarde á tarde holgaréis vuestro sábado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, 'Y habló Jehová á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, 'Habla á los hijos de Israel, y diles: A los quince días de este mes séptimo será la solemnidad de las cabañas á Jehová por siete días.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, 'El primer día habrá santa convocación: ninguna obra servil haréis.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, 'Siete días ofreceréis ofrenda encendida á Jehová: el octavo día tendréis santa convocación, y ofreceréis ofrenda encendida á Jehová: es fiesta: ninguna obra servil haréis.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, 'Estas son las solemnidades de Jehová, á las que convocaréis santas reuniones, para ofrecer ofrenda encendida á Jehová, holocausto y presente, sacrificio y libaciones, cada cosa en su tiempo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, 'Además de los sábados de Jehová y además de vuestros dones, y á más de todos vuestros votos, y además de todas vuestras ofrendas voluntarias, que daréis á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, 'Empero á los quince del mes séptimo, cuando hubiereis allegado el fruto de la tierra, haréis fiesta á Jehová por siete días: el primer día será sábado; sábado será también el octavo día.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, 'Y tomaréis el primer día gajos con fruto de árbol hermoso, ramos de palmas, y ramas de árboles espesos, y sauces de los arroyos; y os regocijaréis delante de Jehová vuestro Dios por siete días.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, 'Y le haréis fiesta á Jehová por siete días cada un año; será estatuto perpetuo por vuestras edades; en el mes séptimo la haréis.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, 'En cabañas habitaréis siete días: todo natural de Israel habitará en cabañas;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, 'Para que sepan vuestros descendientes que en cabañas hice yo habitar á los hijos de Israel, cuando los saqué de la tierra de Egipto: Yo Jehová vuestro Dios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, 'Así habló Moisés á los hijos de Israel sobre las solemnidades de Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, 'Y HABLÓ Jehová á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, 'Manda á los hijos de Israel que te traigan aceite de olivas claro, molido, para la luminaria, para hacer arder las lámparas de continuo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, 'Fuera del velo del testimonio, en el tabernáculo del testimonio, las aderezará Aarón desde la tarde hasta la mañana delante de Jehová, de continuo: estatuto perpetuo por vuestras edades.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, 'Sobre el candelero limpio pondrá siempre en orden las lámparas delante de Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, 'Y tomarás flor de harina, y cocerás de ella doce tortas: cada torta será de dos décimas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, 'Y has de ponerlas en dos órdenes, seis en cada orden, sobre la mesa limpia delante de Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, 'Pondrás también sobre cada orden incienso limpio, y será para el pan por perfume, ofrenda encendida á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, 'Cada día de sábado lo pondrá de continuo en orden delante de Jehová, de los hijos de Israel por pacto sempiterno.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, 'Y será de Aarón y de sus hijos, los cuales lo comerán en el lugar santo; porque es cosa muy santa para él, de las ofrendas encendidas á Jehová, por fuero perpetuo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, 'En aquella sazón el hijo de una mujer Israelita, el cual era hijo de un Egipcio, salió entre los hijos de Israel; y el hijo de la Israelita y un hombre de Israel riñeron en el real:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, 'Y el hijo de la mujer Israelita pronunció el Nombre, y maldijo: entonces le llevaron á Moisés. Y su madre se llamaba Selomith, hija de Dribi, de la tribu de Dan.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, 'Y pusiéronlo en la cárcel, hasta que les fuese declarado por palabra de Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, 'Y Jehová habló á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, 'Saca al blasfemo fuera del real, y todos los que le oyeron pongan sus manos sobre la cabeza de él, y apedréelo toda la congregación.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, 'Y á los hijos de Israel hablarás, diciendo: Cualquiera que maldijere á su Dios, llevará su iniquidad.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, 'Y el que blasfemare el nombre de Jehová, ha de ser muerto: toda la congregación lo apedreará: así el extranjero como el natural, si blasfemare el Nombre, que muera.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, 'Asimismo el hombre que hiere de muerte á cualquiera persona, que sufra la muerte.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, 'Y el que hiere á algún animal, ha de restituirlo: animal por animal.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, 'Y el que causare lesión en su prójimo, según hizo, así le sea hecho:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, 'Rotura por rotura, ojo por ojo, diente por diente: según la lesión que habrá hecho á otro, tal se hará á él.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, 'El que hiere algún animal, ha de restituirlo; mas el que hiere de muerte á un hombre, que muera.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, 'Un mismo derecho tendréis: como el extranjero, así será el natural: porque yo soy Jehová vuestro Dios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, 'Y habló Moisés á los hijos de Israel, y ellos sacaron al blasfemo fuera del real, y apedreáronlo con piedras. Y los hijos de Israel hicieron según que Jehová había mandado á Moisés.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, 'Y JEHOVÁ habló á Moisés en el monte de Sinaí, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, 'Habla á los hijos de Israel, y diles: Cuando hubiereis entrado en la tierra que yo os doy, la tierra hará sábado á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, 'Seis años sembrarás tu tierra, y seis años podarás tu viña, y cogerás sus frutos;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, 'Y el séptimo año la tierra tendrá sábado de holganza, sábado á Jehová: no sembrarás tu tierra, ni podarás tu viña.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, 'Lo que de suyo se naciere en tu tierra segada, no lo segarás; y las uvas de tu viñedo no vendimiarás: año de holganza será á la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, 'Mas el sábado de la tierra os será para comer á ti, y á tu siervo, y á tu sierva, y á tu criado, y á tu extranjero que morare contigo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, 'Y á tu animal, y á la bestia que hubiere en tu tierra, será todo el fruto de ella para comer.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, 'Y te has de contar siete semanas de años, siete veces siete años; de modo que los días de las siete semanas de años vendrán á serte cuarenta y nueve años.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, 'Entonces harás pasar la trompeta de jubilación en el mes séptimo á los diez del mes; el día de la expiación haréis pasar la trompeta por toda vuestra tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, 'Y santificaréis el año cincuenta, y pregonaréis libertad en la tierra á todos sus moradores: éste os será jubileo; y volveréis cada uno á su posesión, y cada cual volverá á su familia.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, 'El año de los cincuenta años os será jubileo: no sembraréis, ni segaréis lo que naciere de suyo en la tierra, ni vendimiaréis sus viñedos:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, 'Porque es jubileo: santo será á vosotros; el producto de la tierra comeréis.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, 'En este año de jubileo volveréis cada uno á su posesión.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, 'Y cuando vendiereis algo á vuestro prójimo, ó comprareis de mano de vuestro prójimo, no engañe ninguno á su hermano:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, 'Conforme al número de los años después del jubileo comprarás de tu prójimo; conforme al número de los años de los frutos te venderá él á ti.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, 'Conforme á la multitud de los años aumentarás el precio, y conforme á la disminución de los años disminuirás el precio; porque según el número de los rendimientos te ha de vender él.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, 'Y no engañe ninguno á su prójimo; mas tendrás temor de tu Dios: porque yo soy Jehová vuestro Dios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, 'Ejecutad, pues, mis estatutos, y guardad mis derechos, y ponedlos por obra, y habitaréis en la tierra seguros;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, 'Y la tierra dará su fruto, y comeréis hasta hartura, y habitaréis en ella con seguridad.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, 'Y si dijereis: ¿Qué comeremos el séptimo año? he aquí no hemos de sembrar, ni hemos de coger nuestros frutos:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, 'Entonces yo os enviaré mi bendición el sexto año, y hará fruto por tres años.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, 'Y sembraréis el año octavo, y comeréis del fruto añejo; hasta el año noveno, hasta que venga su fruto comeréis del añejo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, 'Y la tierra no se venderá rematadamente, porque la tierra mía es; que vosotros peregrinos y extranjeros sois para conmigo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, 'Por tanto, en toda la tierra de vuestra posesión, otorgaréis redención á la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, 'Cuando tu hermano empobreciere, y vendiere algo de su posesión, vendrá el rescatador, su cercano, y rescatará lo que su hermano hubiere vendido.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, 'Y cuando el hombre no tuviere rescatador, si alcanzare su mano, y hallare lo que basta para su rescate;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, 'Entonces contará los años de su venta, y pagará lo que quedare al varón á quien vendió, y volverá á su posesión.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, 'Mas si no alcanzare su mano lo que basta para que vuelva á él, lo que vendió estará en poder del que lo compró hasta el año del jubileo; y al jubileo saldrá, y él volverá á su posesión.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, 'Y el varón que vendiere casa de morada en ciudad cercada, tendrá facultad de redimirla hasta acabarse el año de su venta: un año será el término de poderse redimir.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, 'Y si no fuere redimida dentro de un año entero, la casa que estuviere en la ciudad murada quedará para siempre por de aquel que la compró, y para sus descendientes: no saldrá en el jubileo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, 'Mas las casas de las aldeas que no tienen muro alrededor, serán estimadas como una haza de tierra: tendrán redención, y saldrán en el jubileo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, 'Pero en cuanto á las ciudades de los Levitas, siempre podrán redimir los Levitas las casas de las ciudades que poseyeren.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, 'Y el que comprare de los Levitas, saldrá de la casa vendida, ó de la ciudad de su posesión, en el jubileo: por cuanto las casas de las ciudades de los Levitas es la posesión de ellos entre los hijos de Israel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, 'Mas la tierra del ejido de sus ciudades no se venderá, porque es perpetua posesión de ellos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, 'Y cuando tu hermano empobreciere, y se acogiere á ti, tú lo ampararás: como peregrino y extranjero vivirá contigo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, 'No tomarás usura de él, ni aumento; mas tendrás temor de tu Dios, y tu hermano vivirá contigo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, 'No le darás tu dinero á usura, ni tu vitualla á ganancia:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, 'Yo Jehová vuestro Dios, que os saqué de la tierra de Egipto, para daros la tierra de Canaán, para ser vuestro Dios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, 'Y cuando tu hermano empobreciere, estando contigo, y se vendiere á ti, no le harás servir como siervo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, 'Como criado, como extranjero estará contigo; hasta el año del jubileo te servirá.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, 'Entonces saldrá de contigo, él y sus hijos consigo, y volverá á su familia, y á la posesión de sus padres se restituirá.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, 'Porque son mis siervos, los cuales saqué yo de la tierra de Egipto: no serán vendidos á manera de siervos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, 'No te enseñorearás de él con dureza, mas tendrás temor de tu Dios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, 'Así tu siervo como tu sierva que tuvieres, serán de las gentes que están en vuestro alrededor: de ellos compraréis siervos y siervas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, 'También compraréis de los hijos de los forasteros que viven entre vosotros, y de los que del linaje de ellos son nacidos en vuestra tierra, que están con vosotros; los cuales tendréis por posesión:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, 'Y los poseeréis por juro de heredad para vuestros hijos después de vosotros, como posesión hereditaria; para siempre os serviréis de ellos; empero en vuestros hermanos los hijos de Israel, no os enseñorearéis cada uno sobre su hermano con dureza.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, 'Y si el peregrino ó extranjero que está contigo, adquiriese medios, y tu hermano que está con él empobreciere, y se vendiere al peregrino ó extranjero que está contigo, ó á la raza de la familia del extranjero;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, 'Después que se hubiere vendido, podrá ser rescatado: uno de sus hermanos lo rescatará;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, 'O su tío, ó el hijo de su tío lo rescatará, ó el cercano de su carne, de su linaje, lo rescatará; ó si sus medios alcanzaren, él mismo se redimirá.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, 'Y contará con el que lo compró, desde el año que se vendió á él hasta el año del jubileo: y ha de apreciarse el dinero de su venta conforme al número de los años, y se hará con él conforme al tiempo de un criado asalariado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, 'Si aun fueren muchos años, conforme á ellos volverá para su rescate del dinero por el cual se vendió.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, 'Y si quedare poco tiempo hasta el año del jubileo, entonces contará con él, y devolverá su rescate conforme á sus años.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, 'Como con tomado á salario anualmente hará con él: no se enseñoreará en él con aspereza delante de tus ojos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, 'Mas si no se redimiere en esos años, en el año del jubileo saldrá, él, y sus hijos con él.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, 'Porque mis siervos son los hijos de Israel; son siervos míos, á los cuales saqué de la tierra de Egipto: Yo Jehová vuestro Dios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, 'NO haréis para vosotros ídolos, ni escultura, ni os levantaréis estatua, ni pondréis en vuestra tierra piedra pintada para inclinaros á ella: porque yo soy Jehová vuestro Dios.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, 'Guardad mis sábados, y tened en reverencia mi santuario: Yo Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, 'Si anduviereis en mis decretos, y guardareis mis mandamientos, y los pusiereis por obra;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, 'Yo daré vuestra lluvia en su tiempo, y la tierra rendirá sus producciones, y el árbol del campo dará su fruto;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, 'Y la trilla os alcanzará á la vendimia, y la vendimia alcanzará á la sementera, y comeréis vuestro pan en hartura, y habitaréis seguros en vuestra tierra:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, 'Y yo daré paz en la tierra, y dormiréis, y no habrá quien os espante: y haré quitar las malas bestias de vuestra tierra, y no pasará por vuestro país la espada:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, 'Y perseguiréis á vuestros enemigos, y caerán á cuchillo delante de vosotros:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, 'Y cinco de vosotros perseguirán á ciento, y ciento de vosotros perseguirán á diez mil, y vuestros enemigos caerán á cuchillo delante de vosotros.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, 'Porque yo me volveré á vosotros, y os haré crecer, y os multiplicaré, y afirmaré mi pacto con vosotros:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, 'Y comeréis lo añejo de mucho tiempo, y sacaréis fuera lo añejo á causa de lo nuevo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, 'Y pondré mi morada en medio de vosotros, y mi alma no os abominará:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, 'Y andaré entre vosotros, y yo seré vuestro Dios, y vosotros seréis mi pueblo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, 'Yo Jehová vuestro Dios, que os saqué de la tierra de Egipto, para que no fueseis sus siervos; y rompí las coyundas de vuestro yugo, y os he hecho andar el rostro alto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, 'Empero si no me oyereis, ni hiciereis todos estos mis mandamientos,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, 'Y si abominareis mis decretos, y vuestra alma menospreciare mis derechos, no ejecutando todos mis mandamientos, é invalidando mi pacto;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, 'Yo también haré con vosotros esto: enviaré sobre vosotros terror, extenuación y calentura, que consuman los ojos y atormenten el alma: y sembraréis en balde vuestra simiente, porque vuestros enemigos la comerán:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, 'Y pondré mi ira sobre vosotros, y seréis heridos delante de vuestros enemigos; y los que os aborrecen se enseñorearán de vosotros, y huiréis sin que haya quien os persiga.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, 'Y si aun con esas cosas no me oyereis, yo tornaré á castigaros siete veces más por vuestros pecados.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, 'Y quebrantaré la soberbia de vuestra fortaleza, y tornaré vuestro cielo como hierro, y vuestra tierra como metal:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, 'Y vuestra fuerza se consumirá en vano; que vuestra tierra no dará su esquilmo, y los árboles de la tierra no darán su fruto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, 'Y si anduviereis conmigo en oposición, y no me quisiereis oir, yo añadiré sobre vosotros siete veces más plagas según vuestros pecados.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, 'Enviaré también contra vosotros bestias fieras que os arrebaten los hijos, y destruyan vuestros animales, y os apoquen, y vuestros caminos sean desiertos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, 'Y si con estas cosas no fuereis corregidos, sino que anduviereis conmigo en oposición,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, 'Yo también procederé con vosotros en oposición, y os heriré aun siete veces por vuestros pecados:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, 'Y traeré sobre vosotros espada vengadora, en vindicación del pacto; y os recogeréis á vuestras ciudades; mas yo enviaré pestilencia entre vosotros, y seréis entregados en mano del enemigo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, 'Cuando yo os quebrantare el arrimo del pan, cocerán diez mujeres vuestro pan en un horno, y os devolverán vuestro pan por peso; y comeréis, y no os hartaréis.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, 'Y si con esto no me oyereis, mas procediereis conmigo en oposición,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, 'Yo procederé con vosotros en contra y con ira, y os castigaré aun siete veces por vuestros pecados.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, 'Y comeréis las carnes de vuestros hijos, y comeréis las carnes de vuestras hijas:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, 'Y destruiré vuestros altos, y talaré vuestras imágenes, y pondré vuestros cuerpos muertos sobre los cuerpos muertos de vuestros ídolos, y mi alma os abominará:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, 'Y pondré vuestras ciudades en desierto, y asolaré vuestros santuarios, y no oleré la fragancia de vuestro suave perfume.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, 'Yo asolaré también la tierra, y se pasmarán de ella vuestros enemigos que en ella moran:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, 'Y á vosotros os esparciré por las gentes, y desenvainaré espada en pos de vosotros: y vuestra tierra estará asolada, y yermas vuestras ciudades.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, 'Entonces la tierra holgará sus sábados todos los días que estuviere asolada, y vosotros en la tierra de vuestros enemigos: la tierra descansará entonces y gozará sus sábados.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, 'Todo el tiempo que estará asolada, holgará lo que no holgó en vuestros sábados mientras habitabais en ella.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, 'Y á los que quedaren de vosotros infundiré en sus corazones tal cobardía, en la tierra de sus enemigos, que el sonido de una hoja movida los perseguirá, y huirán como de cuchillo, y caerán sin que nadie los persiga:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, 'Y tropezarán los unos en los otros, como si huyeran delante de cuchillo, aunque nadie los persiga; y no podréis resistir delante de vuestros enemigos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, 'Y pereceréis entre las gentes, y la tierra de vuestros enemigos os consumirá.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, 'Y los que quedaren de vosotros decaerán en las tierras de vuestros enemigos por su iniquidad; y por la iniquidad de sus padres decaerán con ellos:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, 'Y confesarán su iniquidad, y la iniquidad de sus padres, por su prevaricación con que prevaricaron contra mí: y también porque anduvieron conmigo en oposición,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, 'Yo también habré andado con ellos en contra, y los habré metido en la tierra de sus enemigos: y entonces se humillará su corazón incircunciso, y reconocerán su pecado;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, 'Y yo me acordaré de mi pacto con Jacob, y asimismo de mi pacto con Isaac, y también de mi pacto con Abraham me acordaré; y haré memoria de la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, 'Que la tierra estará desamparada de ellos, y holgará sus sábados, estando yerma á causa de ellos; mas entretanto se someterán al castigo de sus iniquidades: por cuanto menospreciaron mis derechos, y tuvo el alma de ellos fastidio de mis estatutos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, 'Y aun con todo esto, estando ellos en tierra de sus enemigos, yo no los desecharé, ni los abominaré para consumirlos, invalidando mi pacto con ellos: porque yo Jehová soy su Dios:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, 'Antes me acordaré de ellos por el pacto antiguo, cuando los saqué de la tierra de Egipto á los ojos de las gentes, para ser su Dios: Yo Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 46, 'Estos son los decretos, derechos y leyes que estableció Jehová entre sí y los hijos de Israel en el monte de Sinaí por mano de Moisés.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, 'Y HABLÓ Jehová á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, 'Habla á los hijos de Israel, y diles: Cuando alguno hiciere especial voto á Jehová, según la estimación de las personas que se hayan de redimir, así será tu estimación:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, 'En cuanto al varón de veinte años hasta sesenta, tu estimación será cincuenta siclos de plata, según el siclo del santuario.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, 'Y si fuere hembra, la estimación será treinta siclos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, 'Y si fuere de cinco años hasta veinte, tu estimación será respecto al varón veinte siclos, y á la hembra diez siclos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, 'Y si fuere de un mes hasta cinco años, tu estimación será en orden al varón, cinco siclos de plata; y por la hembra será tu estimación tres siclos de plata.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, 'Mas si fuere de sesenta años arriba, por el varón tu estimación será quince siclos, y por la hembra diez siclos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, 'Pero si fuere más pobre que tu estimación, entonces comparecerá ante el sacerdote, y el sacerdote le pondrá tasa: conforme á la facultad del votante le impondrá tasa el sacerdote.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, 'Y si fuere animal de que se ofrece ofrenda á Jehová, todo lo que se diere de él á Jehová será santo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, 'No será mudado ni trocado, bueno por malo, ni malo por bueno: y si se permutare un animal por otro, él y el dado por él en cambio serán sagrados.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, 'Y si fuere algún animal inmundo, de que no se ofrece ofrenda á Jehová, entonces el animal será puesto delante del sacerdote:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, 'Y el sacerdote lo apreciará, sea bueno ó sea malo; conforme á la estimación del sacerdote, así será.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, 'Y si lo hubieren de redimir, añadirán su quinto sobre tu valuación.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, 'Y cuando alguno santificare su casa consagrándola á Jehová, la apreciará el sacerdote, sea buena ó sea mala: según la apreciare el sacerdote, así quedará.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, 'Mas si el santificante redimiere su casa, añadirá á tu valuación el quinto del dinero de ella, y será suya.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, 'Y si alguno santificare de la tierra de su posesión á Jehová, tu estimación será conforme á su sembradura: un omer de sembradura de cebada se apreciará en cincuenta siclos de plata.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, 'Y si santificare su tierra desde el año del jubileo, conforme á tu estimación quedará.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, 'Mas si después del jubileo santificare su tierra, entonces el sacerdote hará la cuenta del dinero conforme á los años que quedaren hasta el año del jubileo, y se rebajará de tu estimación.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, 'Y si el que santificó la tierra quisiere redimirla, añadirá á tu estimación el quinto del dinero de ella, y quedaráse para él.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, 'Mas si él no redimiere la tierra, y la tierra se vendiere á otro, no la redimirá más;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, 'Sino que cuando saliere en el jubileo, la tierra será santa á Jehová, como tierra consagrada: la posesión de ella será del sacerdote.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, 'Y si santificare alguno á Jehová la tierra que él compró, que no era de la tierra de su herencia,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, 'Entonces el sacerdote calculará con él la suma de tu estimación hasta el año del jubileo, y aquel día dará tu señalado precio, cosa consagrada á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, 'En el año del jubileo, volverá la tierra á aquél de quien él la compró, cuya es la herencia de la tierra.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, 'Y todo lo que apreciares será conforme al siclo del santuario: el siclo tiene veinte óbolos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, 'Empero el primogénito de los animales, que por la primogenitura es de Jehová, nadie lo santificará; sea buey ú oveja, de Jehová es.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, 'Mas si fuere de los animales inmundos, lo redimirán conforme á tu estimación, y añadirán sobre ella su quinto: y si no lo redimieren, se venderá conforme á tu estimación.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, 'Pero ninguna cosa consagrada, que alguno hubiere santificado á Jehová de todo lo que tuviere, de hombres y animales, y de las tierras de su posesión, no se venderá, ni se redimirá: todo lo consagrado será cosa santísima á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, 'Cualquier anatema (cosa consagrada) de hombres que se consagrare, no será redimido: indefectiblemente ha de ser muerto.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, 'Y todas las décimas de la tierra, así de la simiente de la tierra como del fruto de los árboles, de Jehová son: es cosa consagrada á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, 'Y si alguno quisiere redimir algo de sus décimas, añadirá su quinto á ello.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, 'Y toda décima de vacas ó de ovejas, de todo lo que pasa bajo la vara, la décima será consagrada á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, 'No mirará si es bueno ó malo, ni lo trocará: y si lo trocare, ello y su trueque serán cosas sagradas; no se redimirá.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, 'Estos son los mandamientos que ordenó Jehová á Moisés, para los hijos de Israel, en el monte de Sinaí.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, 'Y HABLÓ Jehová á Moisés en el desierto de Sinaí, en el tabernáculo del testimonio, en el primero del mes segundo, en el segundo año de su salida de la tierra de Egipto, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, 'Tomad el encabezamiento de toda la congregación de los hijos de Israel por sus familias, por las casas de sus padres, con la cuenta de los nombres, todos los varones por sus cabezas:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, 'De veinte años arriba, todos los que pueden salir á la guerra en Israel, los contaréis tú y Aarón por sus cuadrillas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, 'Y estará con vosotros un varón de cada tribu, cada uno cabeza de la casa de sus padres.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, 'Y estos son los nombres de los varones que estarán con vosotros: De la tribu de Rubén, Elisur hijo de Sedeur.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, 'De Simeón, Selumiel hijo de Zurisaddai.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, 'De Judá, Naasón hijo de Aminadab.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, 'De Issachâr, Nathanael hijo de Suar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, 'De Zabulón, Eliab hijo de Helón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, 'De los hijos de José: de Ephraim, Elisama hijo de Ammiud; de Manasés, Gamaliel hijo de Pedasur.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, 'De Benjamín, Abidán hijo de Gedeón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, 'De Dan, Ahiezer hijo de Ammisaddai.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, 'De Aser, Phegiel hijo de Ocrán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, 'De Gad, Eliasaph hijo de Dehuel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, 'De Nephtalí, Ahira hijo de Enán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, 'Estos eran los nombrados de la congregación, príncipes de las tribus de sus padres, capitanes de los millares de Israel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, 'Tomó pues Moisés y Aarón á estos varones que fueron declarados por sus nombres:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, 'Y juntaron toda la congregación en el primero del mes segundo, y fueron reunidos sus linajes, por las casas de sus padres, según la cuenta de los nombres, de veinte años arriba, por sus cabezas,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, 'Como Jehová lo había mandado á Moisés; y contólos en el desierto de Sinaí.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, 'Y los hijos de Rubén, primogénito de Israel, por sus generaciones, por sus familias, por las casas de sus padres, conforme á la cuenta de los nombres por sus cabezas, todos los varones de veinte años arriba, todos los que podían salir á la guerra;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'Los contados de ellos, de la tribu de Rubén, fueron cuarenta y seis mil y quinientos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, 'De los hijos de Simeón, por sus generaciones, por sus familias, por las casas de sus padres, los contados de ellos conforme á la cuenta de los nombres por sus cabezas, todos los varones de veinte años arriba, todos los que podían salir á la guerra;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'Los contados de ellos, de la tribu de Simeón, cincuenta y nueve mil y trescientos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, 'De los hijos de Gad, por sus generaciones, por sus familias, por las casas de sus padres, conforme á la cuenta de los nombres, de veinte años arriba, todos los que podían salir á la guerra;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'Los contados de ellos, de la tribu de Gad, cuarenta y cinco mil seiscientos y cincuenta.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, 'De los hijos de Judá, por sus generaciones, por sus familias, por las casas de sus padres, conforme á la cuenta de los nombres, de veinte años arriba, todos los que podían salir á la guerra;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'Los contados de ellos, de la tribu de Judá, setenta y cuatro mil y seiscientos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, 'De los hijos de Issachâr, por sus generaciones, por sus familias, por las casas de sus padres, conforme á la cuenta de los nombres, de veinte años arriba, todos los que podían salir á la guerra;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'Los contados de ellos, de la tribu de Issachâr, cincuenta y cuatro mil y cuatrocientos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, 'De los hijos de Zabulón, por sus generaciones, por sus familias, por las casas de sus padres, conforme á la cuenta de sus nombres, de veinte años arriba, todos los que podían salir á la guerra;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'Los contados de ellos, de la tribu de Zabulón, cincuenta y siete mil y cuatrocientos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, 'De los hijos de José: de los hijos de Ephraim, por sus generaciones, por sus familias, por las casas de sus padres, conforme á la cuenta de los nombres, de veinte años arriba, todos los que podían salir á la guerra;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'Los contados de ellos, de la tribu de Ephraim, cuarenta mil y quinientos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, 'De los hijos de Manasés, por sus generaciones, por sus familias, por las casas de sus padres, conforme á la cuenta de los nombres, de veinte años arriba, todos los que podían salir á la guerra;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'Los contados de ellos, de la tribu de Manasés, treinta y dos mil y doscientos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, 'De los hijos de Benjamín, por sus generaciones, por sus familias, por las casas de sus padres, conforme á la cuenta de los nombres, de veinte años arriba, todos los que podían salir á la guerra;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'Los contados de ellos, de la tribu de Benjamín, treinta y cinco mil y cuatrocientos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, 'De los hijos de Dan, por sus generaciones, por sus familias, por las casas de sus padres, conforme á la cuenta de los nombres, de veinte años arriba, todos los que podían salir á la guerra;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'Los contados de ellos, de la tribu de Dan, sesenta y dos mil y setecientos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, 'De los hijos de Aser, por sus generaciones, por sus familias, por las casas de sus padres, conforme á la cuenta de los nombres, de veinte años arriba, todos los que podían salir á la guerra;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'Los contados de ellos, de la tribu de Aser, cuarenta y un mil y quinientos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, 'De los hijos de Nephtalí, por sus generaciones, por sus familias, por las casas de sus padres, conforme á la cuenta de los nombres, de veinte años arriba, todos los que podían salir á la guerra;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'Los contados de ellos, de la tribu de Nephtalí, cincuenta y tres mil y cuatrocientos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, 'Estos fueron los contados, los cuales contaron Moisés y Aarón, con los príncipes de Israel, que eran doce, uno por cada casa de sus padres.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, 'Y fueron todos los contados de los hijos de Israel por las casas de sus padres, de veinte años arriba, todos los que podían salir á la guerra en Israel;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, 'Fueron todos los contados seiscientos tres mil quinientos y cincuenta.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, 'Pero los Levitas no fueron contados entre ellos según la tribu de sus padres.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, 'Porque habló Jehová á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, 'Solamente no contarás la tribu de Leví, ni tomarás la cuenta de ellos entre los hijos de Israel:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, 'Mas tú pondrás á los Levitas en el tabernáculo del testimonio, y sobre todos sus vasos, y sobre todas las cosas que le pertenecen: ellos llevarán el tabernáculo y todos sus vasos, y ellos servirán en él, y asentarán sus tiendas alrededor del tabernáculo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, 'Y cuando el tabernáculo partiere, los Levitas lo desarmarán; y cuando el tabernáculo parare, los Levitas lo armarán: y el extraño que se llegare, morirá.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, 'Y los hijos de Israel asentarán sus tiendas cada uno en su escuadrón, y cada uno junto á su bandera, por sus cuadrillas;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, 'Mas los Levitas asentarán las suyas alrededor del tabernáculo del testimonio, y no habrá ira sobre la congregación de los hijos de Israel: y los Levitas tendrán la guarda del tabernáculo del testimonio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, 'E hicieron los hijos de Israel conforme á todas las cosas que mandó Jehová á Moisés; así lo hicieron.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, 'Y HABLÓ Jehová á Moisés y á Aarón, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, 'Los hijos de Israel acamparán cada uno junto á su bandera, según las enseñas de las casas de sus padres; alrededor del tabernáculo del testimonio acamparán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, 'Estos acamparán al levante, al oriente: la bandera del ejército de Judá, por sus escuadrones; y el jefe de los hijos de Judá, Naasón hijo de Aminadab:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, 'Su hueste, con los contados de ellos, setenta y cuatro mil y seiscientos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, 'Junto á él acamparán los de la tribu de Issachâr: y el jefe de los hijos de Issachâr, Nathanael hijo de Suar;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, 'Y su hueste, con sus contados, cincuenta y cuatro mil y cuatrocientos:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, 'Y la tribu de Zabulón: y el jefe de los hijos de Zabulón, Eliab hijo de Helón;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, 'Y su hueste, con sus contados, cincuenta y siete mil y cuatrocientos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, 'Todos los contados en el ejército de Judá, ciento ochenta y seis mil y cuatrocientos, por sus escuadrones, irán delante.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, 'La bandera del ejército de Rubén al mediodía, por sus escuadrones: y el jefe de los hijos de Rubén, Elisur hijo de Sedeur;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, 'Y su hueste, sus contados, cuarenta y seis mil y quinientos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, 'Y acamparán junto á él los de la tribu de Simeón: y el jefe de los hijos de Simeón, Selumiel hijo de Zurisaddai;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, 'Y su hueste, con los contados de ellos, cincuenta y nueve mil y trescientos:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, 'Y la tribu de Gad: y el jefe de los hijos de Gad, Eliasaph hijo de Rehuel;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, 'Y su hueste, con los contados de ellos, cuarenta y cinco mil seiscientos y cincuenta.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, 'Todos los contados en el ejército de Rubén, ciento cincuenta y un mil cuatrocientos y cincuenta, por sus escuadrones, irán los segundos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, 'Luego irá el tabernáculo del testimonio, el campo de los Levitas en medio de los ejércitos: de la manera que asientan el campo, así caminarán, cada uno en su lugar, junto á sus banderas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, 'La bandera del ejército de Ephraim por sus escuadrones, al occidente: y el jefe de los hijos de Ephraim, Elisama hijo de Ammiud;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, 'Y su hueste, con los contados de ellos, cuarenta mil y quinientos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, 'Junto á él estará la tribu de Manasés; y el jefe de los hijos de Manasés, Gamaliel hijo de Pedasur;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, 'Y su hueste, con los contados de ellos, treinta y dos mil y doscientos:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, 'Y la tribu de Benjamín: y el jefe de los hijos de Benjamín, Abidán hijo de Gedeón;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, 'Y su hueste, con los contados de ellos, treinta y cinco mil y cuatrocientos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, 'Todos los contados en el ejército de Ephraim, ciento ocho mil y ciento, por sus escuadrones, irán los terceros.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, 'La bandera del ejército de Dan estará al aquilón, por sus escuadrones: y el jefe de los hijos de Dan, Ahiezer hijo de Amisaddai;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, 'Y su hueste, con los contados de ellos, sesenta y dos mil y setecientos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, 'Junto á él acamparán los de la tribu de Aser: y el jefe de los hijos de Aser, Phegiel hijo de Ocrán;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, 'Y su hueste, con los contados de ellos, cuarenta y un mil y quinientos:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, 'Y la tribu de Nephtalí: y el jefe de los hijos de Nephtalí, Ahira hijo de Enán;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, 'Y su hueste, con los contados de ellos, cincuenta y tres mil y cuatrocientos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, 'Todos los contados en el ejército de Dan, ciento cincuenta y siete mil y seiscientos: irán los postreros tras sus banderas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, 'Estos son los contados de los hijos de Israel, por las casas de sus padres: todos los contados por ejércitos, por sus escuadrones, seiscientos tres mil quinientos y cincuenta.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, 'Mas los Levitas no fueron contados entre los hijos de Israel; como Jehová lo mandó á Moisés.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, 'E hicieron los hijos de Israel conforme á todas las cosas que Jehová mandó á Moisés; así asentaron el campo por sus banderas, y así marcharon cada uno por sus familias, según las casas de sus padres.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, 'Y ESTAS son las generaciones de Aarón y de Moisés, desde que Jehová habló á Moisés en el monte de Sinaí.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, 'Y estos son los nombres de los hijos de Aarón: Nadab el primogénito, y Abiú, Eleazar, é Ithamar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, 'Estos son los nombres de los hijos de Aarón, sacerdotes ungidos; cuyas manos él hinchió para administrar el sacerdocio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, 'Mas Nadab y Abiú murieron delante de Jehová, cuando ofrecieron fuego extraño delante de Jehová, en el desierto de Sinaí: y no tuvieron hijos: y Eleazar é Ithamar ejercieron el sacerdocio delante de Aarón su padre.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, 'Y Jehová habló á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, 'Haz llegar á la tribu de Leví, y hazla estar delante del sacerdote Aarón, para que le ministren;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, 'Y desempeñen su cargo, y el cargo de toda la congregación delante del tabernáculo del testimonio, para servir en el ministerio del tabernáculo;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, 'Y guarden todas las alhajas del tabernáculo del testimonio, y lo encargado á ellos de los hijos de Israel, y ministren en el servicio del tabernáculo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, 'Y darás los Levitas á Aarón y á sus hijos: le son enteramente dados de entre los hijos de Israel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, 'Y constituirás á Aarón y á sus hijos, para que ejerzan su sacerdocio: y el extraño que se llegare, morirá.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, 'Y habló Jehová á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, 'Y he aquí yo he tomado los Levitas de entre los hijos de Israel en lugar de todos los primogénitos que abren la matriz entre los hijos de Israel; serán pues míos los Levitas:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, 'Porque mío es todo primogénito; desde el día que yo maté todos los primogénitos en la tierra de Egipto, yo santifiqué á mí todos los primogénitos en Israel, así de hombres como de animales: míos serán: Yo Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, 'Y Jehová habló á Moisés en el desierto de Sinaí, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, 'Cuenta los hijos de Leví por las casas de sus padres, por sus familias: contarás todos los varones de un mes arriba.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, 'Y Moisés los contó conforme á la palabra de Jehová, como le fué mandado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, 'Y los hijos de Leví fueron estos por sus nombres: Gersón, y Coath, y Merari.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, 'Y los nombres de los hijos de Gersón, por sus familias, estos: Libni, y Simei.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, 'Y los hijos de Coath, por sus familias: Amram, é Izhar, y Hebrón, y Uzziel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, 'Y los hijos de Merari, por sus familias: Mahali, y Musi. Estas, las familias de Leví, por las casas de sus padres.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, 'De Gersón, la familia de Libni y la de Simei: estas son las familias de Gersón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, 'Los contados de ellos conforme á la cuenta de todos los varones de un mes arriba, los contados de ellos, siete mil y quinientos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, 'Las familias de Gersón asentarán sus tiendas á espaldas del tabernáculo, al occidente;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, 'Y el jefe de la casa del padre de los Gersonitas, Eliasaph hijo de Lael.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, 'A cargo de los hijos de Gersón, en el tabernáculo del testimonio, estará el tabernáculo, y la tienda, y su cubierta, y el pabellón de la puerta del tabernáculo del testimonio,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, 'Y las cortinas del atrio, y el pabellón de la puerta del atrio, que está junto al tabernáculo y junto al altar alrededor; asimismo sus cuerdas para todo su servicio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, 'Y de Coath, la familia Amramítica, y la familia Izeharítica, y la familia Hebronítica, y la familia Ozielítica: estas son las familias Coathitas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, 'Por la cuenta de todos los varones de un mes arriba, eran ocho mil y seiscientos, que tenían la guarda del santuario.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, 'Las familias de los hijos de Coath acamparán al lado del tabernáculo, al mediodía;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, 'Y el jefe de la casa del padre de las familias de Coath, Elisaphán hijo de Uzziel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, 'Y á cargo de ellos estará el arca, y la mesa, y el candelero, y los altares, y los vasos del santuario con que ministran, y el velo, con todo su servicio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, 'Y el principal de los jefes de los Levitas será Eleazar, hijo de Aarón el sacerdote, prepósito de los que tienen la guarda del santuario.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, 'De Merari, la familia Mahalítica, y la familia Musítica: estas son las familias de Merari.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, 'Y los contados de ellos conforme á la cuenta de todos los varones de un mes arriba, fueron seis mil y doscientos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, 'Y el jefe de la casa del padre de las familias de Merari, Suriel hijo de Abihail: acamparán al lado del tabernáculo, al aquilón.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, 'Y á cargo de los hijos de Merari estará la custodia de las tablas del tabernáculo, y sus barras, y sus columnas, y sus basas, y todos sus enseres, con todo su servicio:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, 'Y las columnas en derredor del atrio, y sus basas, y sus estacas, y sus cuerdas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, 'Y los que acamparán delante del tabernáculo al oriente, delante del tabernáculo del testimonio al levante, serán Moisés, y Aarón y sus hijos, teniendo la guarda del santuario en lugar de los hijos de Israel: y el extraño que se acercare, morirá.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, 'Todos los contados de los Levitas, que Moisés y Aarón conforme á la palabra de Jehová contaron por sus familias, todos los varones de un mes arriba, fueron veinte y dos mil.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, 'Y Jehová dijo á Moisés: Cuenta todos los primogénitos varones de los hijos de Israel de un mes arriba, y toma la cuenta de los nombres de ellos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, 'Y tomarás los Levitas para mí, yo Jehová, en lugar de todos los primogénitos de los hijos de Israel: y los animales de los Levitas en lugar de todos los primogénitos de los animales de los hijos de Israel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, 'Y contó Moisés, como Jehová le mandó, todos los primogénitos de los hijos de Israel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, 'Y todos los primogénitos varones, conforme á la cuenta de los nombres, de un mes arriba, los contados de ellos fueron veinte y dos mil doscientos setenta y tres.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, 'Y habló Jehová á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, 'Toma los Levitas en lugar de todos los primogénitos de los hijos de Israel, y los animales de los Levitas en lugar de sus animales; y los Levitas serán míos: Yo Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, 'Y por los rescates de los doscientos y setenta y tres, que sobrepujan á los Levitas los primogénitos de los hijos de Israel,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, 'Tomarás cinco siclos por cabeza; conforme al siclo del santuario tomarás: el siclo tiene veinte óbolos:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, 'Y darás á Aarón y á sus hijos el dinero por los rescates de los que de ellos sobran.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, 'Tomó, pues, Moisés el dinero del rescate de los que resultaron de más de los redimidos por los Levitas:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, 'Y recibió de los primogénitos de los hijos de Israel en dinero, mil trescientos sesenta y cinco siclos, conforme al siclo del santuario.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, 'Y Moisés dió el dinero de los rescates á Aarón y á sus hijos, conforme al dicho de Jehová, según que Jehová había mandado á Moisés.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, 'Y HABLÓ Jehová á Moisés y á Aarón, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, 'Toma la cuenta de los hijos de Coath de entre los hijos de Leví, por sus familias, por las casas de sus padres,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, 'De edad de treinta años arriba hasta cincuenta años, todos los que entran en compañía, para hacer servicio en el tabernáculo del testimonio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, 'Este será el oficio de los hijos de Coath en el tabernáculo del testimonio, en el lugar santísimo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, 'Cuando se hubiere de mudar el campo, vendrán Aarón y sus hijos, y desarmarán el velo de la tienda, y cubrirán con él el arca del testimonio:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, 'Y pondrán sobre ella la cubierta de pieles de tejones, y extenderán encima el paño todo de cárdeno, y le pondrán sus varas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, 'Y sobre la mesa de la proposición extenderán el paño cárdeno, y pondrán sobre ella las escudillas, y las cucharas, y las copas, y los tazones para libar: y el pan continuo estará sobre ella.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, 'Y extenderán sobre ella el paño de carmesí colorado, y lo cubrirán con la cubierta de pieles de tejones; y le pondrán sus varas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, 'Y tomarán un paño cárdeno, y cubrirán el candelero de la luminaria; y sus candilejas, y sus despabiladeras, y sus platillos, y todos sus vasos del aceite con que se sirve;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, 'Y lo pondrán con todos sus vasos en una cubierta de pieles de tejones, y lo colocarán sobre unas parihuelas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, 'Y sobre el altar de oro extenderán el paño cárdeno, y le cubrirán con la cubierta de pieles de tejones, y le pondrán sus varales.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, 'Y tomarán todos los vasos del servicio, de que hacen uso en el santuario, y los pondrán en un paño cárdeno, y los cubrirán con una cubierta de pieles de tejones, y los colocarán sobre unas parihuelas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, 'Y quitarán la ceniza del altar, y extenderán sobre él un paño de púrpura:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, 'Y pondrán sobre él todos sus instrumentos de que se sirve: las paletas, los garfios, los braseros, y los tazones, todos los vasos del altar; y extenderán sobre él la cubierta de pieles de tejones, y le pondrán además las varas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, 'Y en acabando Aarón y sus hijos de cubrir el santuario y todos los vasos del santuario, cuando el campo se hubiere de mudar, vendrán después de ello los hijos de Coath para conducir: mas no tocarán cosa santa, que morirán. Estas serán las cargas de los hijos de Coath en el tabernáculo del testimonio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, 'Empero al cargo de Eleazar, hijo de Aarón el sacerdote, estará el aceite de la luminaria, y el perfume aromático, y el presente continuo, y el aceite de la unción; el cargo de todo el tabernáculo, y de todo lo que está en él, en el santuario, y en sus vasos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, 'Y habló Jehová á Moisés y á Aarón, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, 'No cortaréis la tribu de las familias de Coath de entre los Levitas;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, 'Mas esto haréis con ellos, para que vivan, y no mueran cuando llegaren al lugar santísimo: Aarón y sus hijos vendrán y los pondrán á cada uno en su oficio, y en su cargo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, 'No entrarán para ver, cuando cubrieren las cosas santas; que morirán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, 'Y habló Jehová á Moisés diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, 'Toma también la cuenta de los hijos de Gersón por las casas de sus padres, por sus familias.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, 'De edad de treinta años arriba hasta cincuenta años los contarás; todos los que entran en compañía, para hacer servicio en el tabernáculo del testimonio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, 'Este será el oficio de las familias de Gersón, para ministrar y para llevar:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, 'Llevarán las cortinas del tabernáculo, y el tabernáculo del testimonio, su cubierta, y la cubierta de pieles de tejones que está sobre él encima, y el pabellón de la puerta del tabernáculo del testimonio,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, 'Y las cortinas del atrio, y el pabellón de la puerta del atrio, que está cerca del tabernáculo y cerca del altar alrededor, y sus cuerdas, y todos los instrumentos de su servicio, y todo lo que será hecho para ellos: así servirán.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, 'Según la orden de Aarón y de sus hijos será todo el ministerio de los hijos de Gersón en todos sus cargos, y en todo su servicio: y les encomendaréis en guarda todos sus cargos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, 'Este es el servicio de las familias de los hijos de Gersón en el tabernáculo del testimonio: y el cargo de ellos estará bajo la mano de Ithamar, hijo de Aarón el sacerdote.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, 'Contarás los hijos de Merari por sus familias, por las casas de sus padres.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, 'Desde el de edad de treinta años arriba hasta el de cincuenta años, los contarás; todos los que entran en compañía, para hacer servicio en el tabernáculo del testimonio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, 'Y este será el deber de su cargo para todo su servicio en el tabernáculo del testimonio: las tablas del tabernáculo, y sus barras, y sus columnas, y sus basas,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, 'Y las columnas del atrio alrededor, y sus basas, y sus estacas, y sus cuerdas con todos sus instrumentos, y todo su servicio; y contaréis por sus nombres todos los vasos de la guarda de su cargo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, 'Este será el servicio de las familias de los hijos de Merari para todo su ministerio en el tabernáculo del testimonio, bajo la mano de Ithamar, hijo de Aarón el sacerdote.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, 'Moisés, pues, y Aarón, y los jefes de la congregación, contaron los hijos de Coath por sus familias, y por las casas de sus padres,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, 'Desde el de edad de treinta años arriba hasta el de edad de cincuenta años; todos los que entran en compañía, para ministrar en el tabernáculo del testimonio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, 'Y fueron los contados de ellos por sus familias, dos mil setecientos y cincuenta.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, 'Estos fueron los contados de las familias de Coath, todos los que ministran en el tabernáculo del testimonio, los cuales contaron Moisés y Aarón, como lo mandó Jehová por mano de Moisés.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, 'Y los contados de los hijos de Gersón, por sus familias, y por las casas de sus padres,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, 'Desde el de edad de treinta años arriba hasta el de edad de cincuenta años, todos los que entran en compañía, para ministrar en el tabernáculo del testimonio;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'Los contados de ellos por sus familias, por las casas de sus padres, fueron dos mil seiscientos y treinta.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, 'Estos son los contados de las familias de los hijos de Gersón, todos los que ministran en el tabernáculo del testimonio, los cuales contaron Moisés y Aarón por mandato de Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, 'Y los contados de las familias de los hijos de Merari, por sus familias, por las casas de sus padres,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, 'Desde el de edad de treinta años arriba hasta el de edad de cincuenta años, todos los que entran en compañía, para ministrar en el tabernáculo del testimonio:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'Los contados de ellos, por sus familias, fueron tres mil y doscientos.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, 'Estos fueron los contados de las familias de los hijos de Merari, los cuales contaron Moisés y Aarón, según lo mandó Jehová por mano de Moisés.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, 'Todos los contados de los Levitas, que Moisés y Aarón y los jefes de Israel contaron por sus familias, y por las casas de sus padres,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, 'Desde el de edad de treinta años arriba hasta el de edad de cincuenta años, todos los que entraban para ministrar en el servicio, y tener cargo de obra en el tabernáculo del testimonio;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, 'Los contados de ellos fueron ocho mil quinientos y ochenta,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, 'Como lo mandó Jehová por mano de Moisés fueron contados, cada uno según su oficio, y según su cargo; los cuales contó él, como le fué mandado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, 'Y JEHOVÁ habló á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, 'Manda á los hijos de Israel que echen del campo á todo leproso, y á todos los que padecen flujo de semen, y á todo contaminado sobre muerto:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, 'Así hombres como mujeres echaréis, fuera del campo los echaréis; porque no contaminen el campo de aquellos entre los cuales yo habito.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, 'E hiciéronlo así los hijos de Israel, que los echaron fuera del campo: como Jehová dijo á Moisés, así lo hicieron los hijos de Israel.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, 'Además habló Jehová á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, 'Habla á los hijos de Israel: El hombre ó la mujer que cometiere alguno de todos los pecados de los hombres, haciendo prevaricación contra Jehová, y delinquiere aquella persona;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, 'Confesarán su pecado que cometieron, y compensarán su ofensa enteramente, y añadirán su quinto sobre ello, y lo darán á aquel contra quien pecaron.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, 'Y si aquel hombre no tuviere pariente al cual sea resarcida la ofensa, daráse la indemnización del agravio á Jehová, al sacerdote, á más del carnero de las expiaciones, con el cual hará expiación por él.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, 'Y toda ofrenda de todas las cosas santas que los hijos de Israel presentaren al sacerdote, suya será.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, 'Y lo santificado de cualquiera será suyo: asimismo lo que cualquiera diere al sacerdote, suyo será.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, 'Y Jehová habló á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, 'Habla á los hijos de Israel, y diles: Cuando la mujer de alguno se desmandare, é hiciere traición contra él,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, 'Que alguno se hubiere echado con ella en carnal ayuntamiento, y su marido no lo hubiese visto por haberse ella contaminado ocultamente, ni hubiere testigo contra ella, ni ella hubiere sido cogida en el acto;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, 'Si viniere sobre él espíritu de celo, y tuviere celos de su mujer, habiéndose ella contaminado; ó viniere sobre él espíritu de celo, y tuviere celos de su mujer, no habiéndose ella contaminado;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, 'Entonces el marido traerá su mujer al sacerdote, y traerá su ofrenda con ella, la décima de un epha de harina de cebada; no echará sobre ella aceite, ni pondrá sobre ella incienso: porque es presente de celos, presente de recordación, que trae en memoria pecado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, 'Y el sacerdote la hará acercar, y la hará poner delante de Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, 'Luego tomará el sacerdote del agua santa en un vaso de barro: tomará también el sacerdote del polvo que hubiere en el suelo del tabernáculo, y echarálo en el agua.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, 'Y hará el sacerdote estar en pie á la mujer delante de Jehová, y descubrirá la cabeza de la mujer, y pondrá sobre sus manos el presente de la recordación, que es el presente de celos: y el sacerdote tendrá en la mano las aguas amargas que acarrean maldición.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, 'Y el sacerdote la conjurará, y le dirá: Si ninguno hubiere dormido contigo, y si no te has apartado de tu marido á inmundicia, libre seas de estas aguas amargas que traen maldición:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, 'Mas si te has descarriado de tu marido, y te has amancillado, y alguno hubiere tenido coito contigo, fuera de tu marido:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, '(El sacerdote conjurará á la mujer con juramento de maldición, y dirá á la mujer): Jehová te dé en maldición y en conjuración en medio de tu pueblo, haciendo Jehová á tu muslo que caiga, y á tu vientre que se te hinche;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, 'Y estas aguas que dan maldición entren en tus entrañas, y hagan hinchar tu vientre y caer tu muslo. Y la mujer dirá: Amén, amén.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, 'Y el sacerdote escribirá estas maldiciones en un libro, y las borrará con las aguas amargas:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, 'Y dará á beber á la mujer las aguas amargas que traen maldición; y las aguas que obran maldición entrarán en ella por amargas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, 'Después tomará el sacerdote de la mano de la mujer el presente de los celos, y mecerálo delante de Jehová, y lo ofrecerá delante del altar:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, 'Y tomará el sacerdote un puñado del presente, en memoria de ella, y lo quemará sobre el altar, y después dará á beber las aguas á la mujer.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, 'Darále pues á beber las aguas; y será, que si fuere inmunda y hubiere hecho traición contra su marido, las aguas que obran maldición entrarán en ella en amargura, y su vientre se hinchará, y caerá su muslo; y la mujer será por maldición en medio de su pueblo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, 'Mas si la mujer no fuere inmunda, sino que estuviere limpia, ella será libre, y será fecunda.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, 'Esta es la ley de los celos, cuando la mujer hiciere traición á su marido, y se amancillare;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, 'O del marido, sobre el cual pasare espíritu de celo, y tuviere celos de su mujer: presentarála entonces delante de Jehová, y el sacerdote ejecutará en ella toda esta ley.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, 'Y aquel varón será libre de iniquidad, y la mujer llevará su pecado.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, 'Y HABLÓ Jehová á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, 'Habla á los hijos de Israel, y diles: El hombre, ó la mujer, cuando se apartare haciendo voto de Nazareo, para dedicarse á Jehová,');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, 'Se abstendrá de vino y de sidra; vinagre de vino, ni vinagre de sidra no beberá, ni beberá algún licor de uvas, ni tampoco comerá uvas frescas ni secas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, 'Todo el tiempo de su nazareato, de todo lo que se hace de vid de vino, desde los granillos hasta el hollejo, no comerá.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, 'Todo el tiempo del voto de su nazareato no pasará navaja sobre su cabeza, hasta que sean cumplidos los días de su apartamiento á Jehová: santo será; dejará crecer las guedejas del cabello de su cabeza.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, 'Todo el tiempo que se apartare á Jehová, no entrará á persona muerta.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, 'Por su padre, ni por su madre, por su hermano, ni por su hermana, no se contaminará con ellos cuando murieren; porque consagración de su Dios tiene sobre su cabeza.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, 'Todo el tiempo de su nazareato, será santo á Jehová.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, 'Y si alguno muriere muy de repente junto á él, contaminará la cabeza de su nazareato; por tanto el día de su purificación raerá su cabeza; al séptimo día la raerá.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, 'Y el día octavo traerá dos tórtolas ó dos palominos al sacerdote, á la puerta del tabernáculo del testimonio;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, 'Y el sacerdote hará el uno en expiación, y el otro en holocausto: y expiarálo de lo que pecó sobre el muerto, y santificará su cabeza en aquel día.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, 'Y consagrará á Jehová los días de su nazareato, y traerá un cordero de un año en expiación por la culpa; y los días primeros serán anulados, por cuanto fué contaminado su nazareato.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, 'Esta es, pues, la ley del Nazareo el día que se cumpliere el tiempo de su nazareato: Vendrá á la puerta del tabernáculo del testimonio;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, 'Y ofrecerá su ofrenda á Jehová, un cordero de un año sin tacha en holocausto, y una cordera de un año sin defecto en expiación, y un carnero sin defecto por sacrificio de paces:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, 'Además un canastillo de cenceñas, tortas de flor de harina amasadas con aceite, y hojaldres cenceñas untadas con aceite, y su presente, y sus libaciones.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, 'Y el sacerdote lo ofrecerá delante de Jehová, y hará su expiación y su holocausto:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, 'Y ofrecerá el carnero en sacrificio de paces á Jehová, con el canastillo de las cenceñas; ofrecerá asimismo el sacerdote su presente, y sus libaciones.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, 'Entonces el Nazareo raerá á la puerta del tabernáculo del testimonio la cabeza de su nazareato, y tomará los cabellos de la cabeza de su nazareato, y los pondrá sobre el fuego que está debajo del sacrificio de las paces.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, 'Después tomará el sacerdote la espaldilla cocida del carnero, y una torta sin levadura del canastillo, y una hojaldre sin levadura, y pondrálas sobre las manos del Nazareo, después que fuere raído su nazareato:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, 'Y el sacerdote mecerá aquello, ofrenda agitada delante de Jehová; lo cual será cosa santa del sacerdote, á más del pecho mecido y de la espaldilla separada: y después podrá beber vino el Nazareo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, 'Esta es la ley del Nazareo que hiciere voto de su ofrenda á Jehová por su nazareato, á más de lo que su mano alcanzare: según el voto que hiciere, así hará, conforme á la ley de su nazareato.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, 'Y Jehová habló á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, 'Habla á Aarón y á sus hijos, y diles: Así bendeciréis á los hijos de Israel, diciéndoles:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, 'Jehová te bendiga, y te guarde:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, 'Haga resplandecer Jehová su rostro sobre ti, y haya de ti misericordia:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, 'Jehová alce á ti su rostro, y ponga en ti paz.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, 'Y pondrán mi nombre sobre los hijos de Israel, y yo los bendeciré.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, 'Y ACONTECIÓ, que cuando Moisés hubo acabado de levantar el tabernáculo, y ungídolo y santificádolo, con todos sus vasos; y asimismo ungido y santificado el altar, con todos sus vasos;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, 'Entonces los príncipes de Israel, las cabezas de las casas de sus padres, los cuales eran los príncipes de las tribus, que estaban sobre los contados, ofrecieron;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, 'Y trajeron sus ofrendas delante de Jehová, seis carros cubiertos, y doce bueyes; por cada dos príncipes un carro, y cada uno un buey; lo cual ofrecieron delante del tabernáculo.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, 'Y Jehová habló á Moisés, diciendo:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, 'Tómalo de ellos, y será para el servicio del tabernáculo del testimonio: y lo darás á los Levitas, á cada uno conforme á su ministerio.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, 'Entonces Moisés recibió los carros y los bueyes, y diólos á los Levitas.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, 'Dos carros y cuatro bueyes, dió á los hijos de Gersón, conforme á su ministerio;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, 'Y á los hijos de Merari dió los cuatro carros y ocho bueyes, conforme á su ministerio, bajo la mano de Ithamar, hijo de Aarón el sacerdote.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, 'Y á los hijos de Coath no dió; porque llevaban sobre sí en los hombros el servicio del santuario.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, 'Y ofrecieron los príncipes á la dedicación del altar el día que fué ungido, ofrecieron los príncipes su ofrenda delante del altar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, 'Y Jehová dijo á Moisés: Ofrecerán su ofrenda, un príncipe un día, y otro príncipe otro día, á la dedicación del altar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, 'Y el que ofreció su ofrenda el primer día fué Naasón hijo de Aminadab, de la tribu de Judá.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, 'Y fué su ofrenda un plato de plata de peso de ciento y treinta siclos, y un jarro de plata de setenta siclos, al siclo del santuario; ambos llenos de flor de harina amasada con aceite para presente;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, 'Una cuchara de oro de diez siclos, llena de perfume;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, 'Un becerro, un carnero, un cordero de un año para holocausto;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, 'Un macho cabrío para expiación;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, 'Y para sacrificio de paces, dos bueyes, cinco carneros, cinco machos de cabrío, cinco corderos de un año. Esta fué la ofrenda de Naasón, hijo de Aminadab.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, 'El segundo día ofreció Nathanael hijo de Suar, príncipe de Issachâr.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, 'Ofreció por su ofrenda un plato de plata de ciento y treinta siclos de peso, un jarro de plata de setenta siclos, al siclo del santuario; ambos llenos de flor de harina amasada con aceite para presente;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 20, 'Una cuchara de oro de diez siclos, llena de perfume;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 21, 'Un becerro, un carnero, un cordero de un año para holocausto;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 22, 'Un macho cabrío para expiación;');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 23, 'Y para sacrificio de paces, dos bueyes, cinco carneros, cinco machos de cabrío, cinco corderos de un año. Esta fué la ofrenda de Nathanael, hijo de Suar.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 24, 'El tercer día, Eliab hijo de Helón, príncipe de los hijos de Zabulón:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 25, 'Y su ofrenda, un plato de plata de ciento y treinta siclos de peso, un jarro de plata de setenta siclos, al siclo del santuario; ambos llenos de flor de harina amasada con aceite para presente;');
