INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 30, 'El cuarto día, Elisur hijo de Sedeur, príncipe de los hijos de Rubén:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 31, 'Y su ofrenda, un plato de plata de ciento y treinta siclos de peso, un jarro de plata de setenta siclos, al siclo del santuario; ambos llenos de flor de harina amasada con aceite para presente;');
