INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 36, 'El quinto día, Selumiel hijo de Zurisaddai, príncipe de los hijos de Simeón:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 37, 'Y su ofrenda, un plato de plata de ciento y treinta siclos de peso, un jarro de plata de setenta siclos, al siclo del santuario; ambos llenos de flor de harina amasada con aceite para presente;');
