INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 59, 'Y para sacrificio de paces, dos bueyes, cinco carneros, cinco machos de cabrío, cinco corderos de un año. Esta fué la ofrenda de Gamaliel, hijo de Pedasur.');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 60, 'El noveno día, el príncipe de los hijos de Benjamín, Abidán hijo de Gedeón:');
INSERT INTO `SpaRV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 61, 'Y su ofrenda, un plato de plata de ciento y treinta siclos de peso, un jarro de plata de setenta siclos, al siclo del santuario; ambos llenos de flor de harina amasada con aceite para presente;');
